    fn backupTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        plan: backups_api.TableBackupPlan,
    ) !?[]backups_api.ShardSnapshot {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        const db = try self.activeDb();
        if (plan.format == .portable) {
            return try exportPortableBackupShard(alloc, db, plan.backup_root, plan.backup_id, 0, plan.io);
        }

        const snapshot_token = try std.fmt.allocPrint(alloc, "{s}-local", .{plan.backup_id});
        defer alloc.free(snapshot_token);
        _ = try db.snapshot(snapshot_token);

        const snapshot_root = try std.fmt.allocPrint(alloc, "{s}.snapshots/{s}", .{ db.core.path, snapshot_token });
        defer alloc.free(snapshot_root);
        const dest_root = try backups_api.shardSnapshotPath(alloc, plan.backup_root, plan.backup_id, 0);
        defer alloc.free(dest_root);
        try backups_api.copyDirectoryRecursiveUsingIo(alloc, plan.io, snapshot_root, dest_root);

        const rel_path = try backups_api.shardSnapshotRelPath(alloc, plan.backup_id, 0);
        errdefer alloc.free(rel_path);
        const byte_range = db.getRange();
        const shards = try alloc.alloc(backups_api.ShardSnapshot, 1);
        shards[0] = .{
            .group_id = 0,
            .start_key = try alloc.dupe(u8, byte_range.start),
            .end_key = if (byte_range.end.len > 0) try alloc.dupe(u8, byte_range.end) else null,
            .snapshot_path = rel_path,
        };
        errdefer shards[0].deinit(alloc);
        try backups_api.populateShardArtifactIntegrity(alloc, plan.io, .native, dest_root, &shards[0]);
        return shards;
    }

    fn restoreTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        plan: backups_api.TableRestorePlan,
    ) !?void {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        try backups_api.validateRestorableManifestLayout(plan.manifest);
        try backups_api.validateRestoreManifest(alloc, plan.manifest, plan.manifest.backup_id);
        if (plan.reconcile_only) return error.RestoreIdentityMismatch;
        const db = try self.activeDb();

        const shard = &plan.manifest.shards[0];
        const snapshot_root = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ plan.backup_root, shard.snapshot_path });
        defer alloc.free(snapshot_root);
        try backups_api.verifyShardArtifactIntegrity(
            alloc,
            plan.io,
            plan.manifest.format,
            snapshot_root,
            shard,
        );

        const db_path = try alloc.dupe(u8, db.core.path);
        defer alloc.free(db_path);
        const primary_backend = db.primary_backend;
        var owned_backend_runtime = db.owned_backend_runtime;
        db.owned_backend_runtime = null;
        errdefer if (owned_backend_runtime) |*runtime| runtime.deinit();
        const backend_runtime = if (owned_backend_runtime) |*runtime|
            runtime.runtime
        else
            db.backend_runtime;
        const identity_namespace = db.core.identity_namespace;

        db.close();
        const recovery_open_options: db_mod.OpenOptions = .{
            .primary_backend = primary_backend,
            .backend_runtime = backend_runtime,
            .identity_namespace = identity_namespace,
        };
        // A restore publishes the snapshot's document-identity generation. The
        // pre-restore namespace is valid only when reopening the old generation
        // after a failed publication attempt.
        const restored_open_options: db_mod.OpenOptions = .{
            .primary_backend = primary_backend,
            .backend_runtime = backend_runtime,
        };
        const publication_outcome = restoreBoundTableGeneration(
            alloc,
            snapshot_root,
            db_path,
            plan.manifest.format,
            restored_open_options,
            plan.io,
        ) catch |restore_err| {
            self.db.* = db_mod.DB.open(alloc, db_path, recovery_open_options) catch |reopen_err| {
                std.log.err("bound restore recovery failed phase=reopen restore_class={s} reopen_class={s}", .{
                    @errorName(restore_err),
                    @errorName(reopen_err),
                });
                return reopen_err;
            };
            self.db.owned_backend_runtime = owned_backend_runtime;
            owned_backend_runtime = null;
            return restore_err;
        };
        self.db.* = db_mod.DB.open(alloc, db_path, restored_open_options) catch |reopen_err| {
            std.log.err("bound restore recovery failed phase=published_reopen class={s}", .{@errorName(reopen_err)});
            return reopen_err;
        };
        self.db.owned_backend_runtime = owned_backend_runtime;
        owned_backend_runtime = null;
        if (publication_outcome == .durability_uncertain) return error.GenerationDurabilityUncertain;
    }

    fn restoreBoundTableGeneration(
        alloc: std.mem.Allocator,
        snapshot_root: []const u8,
        live_path: []const u8,
        format: backups_api.BackupFormat,
        open_options: db_mod.OpenOptions,
        shared_io: ?std.Io,
    ) !db_mod.generation_lifecycle.PublicationOutcome {
        var transition = try db_mod.generation_lifecycle.beginProcessExclusiveWithRuntime(live_path, open_options.backend_runtime);
        defer transition.deinit();
        var staged = try transition.beginStaging();
        defer staged.deinit();

        switch (format) {
            .portable => {
                var staged_open_options = open_options;
                staged_open_options.staged_generation = &staged;
                var restored = try db_mod.DB.open(alloc, staged.path(), staged_open_options);
                defer restored.close();
                try importPortableBackupFile(alloc, restored.core.store, snapshot_root, shared_io);
                _ = try restored.rebuildDenseIndexesForTargetCoverage(alloc);
                _ = try restored.rebuildSparseIndexesForTargetCoverage(alloc);
                try restored.rebuildGraphIndexesForTargetCoverage(alloc);
                try restored.syncIndexes(true);
            },
            .native => try db_mod.DB.restoreSnapshotToStagedGeneration(
                &staged,
                alloc,
                snapshot_root,
                staged.path(),
                open_options,
            ),
        }
        return try staged.publish();
    }

    fn commitTransaction(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
    ) !?distributed_txn.CommitOutcome {
        return try commitTransactionWithCancellation(ptr, alloc, tables, sync_level, .none);
    }

    fn commitTransactionWithCancellation(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        const txn_id = nextTxnId();
        return try commitBoundTransaction(ptr, alloc, txn_id, nextTxnTimestamp(), tables, sync_level, false, cancellation);
    }

    fn commitBatch(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
    ) !?distributed_txn.CommitOutcome {
        return try commitBatchWithCancellation(ptr, alloc, tables, sync_level, .none);
    }

    fn commitBatchWithCancellation(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        if (tables.len == 1 and tables[0].predicates.len == 0) {
            const table = tables[0];
            const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
            if (!std.mem.eql(u8, self.table_name, table.table_name)) return null;
            const db = try self.activeDb();
            const req: db_mod.types.BatchRequest = .{
                .writes = transactionWritesAsBatchWrites(table.writes),
                .deletes = table.deletes,
                .transforms = table.transforms,
                .sync_level = sync_level,
            };
            try validateTableBatchAgainstLocalSchema(alloc, db, req.writes, req.deletes, req.transforms);
            db.batchWithVisibilityCancellation(req, cancellation) catch |err| switch (err) {
                error.IntentConflict, error.VersionConflict => return .{ .conflict = boundConflict(table, err) },
                else => return err,
            };
            return .{ .committed = .{ .participant_count = 1 } };
        }
        const txn_id = nextTxnId();
        return try commitBoundTransaction(ptr, alloc, txn_id, nextTxnTimestamp(), tables, sync_level, false, cancellation);
    }

    fn commitTransactionWithId(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
    ) !?distributed_txn.CommitOutcome {
        return try commitTransactionWithIdAndCancellation(ptr, alloc, txn_id, begin_timestamp, tables, sync_level, .none);
    }

    fn commitTransactionWithIdAndCancellation(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        return try commitBoundTransaction(ptr, alloc, txn_id, begin_timestamp, tables, sync_level, true, cancellation);
    }

    fn acknowledgeTransactionCommit(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        _: u64,
        coordinator_table_name: []const u8,
    ) !?void {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, coordinator_table_name)) return null;
        const participant = try distributed_txn.participantIdForGroup(alloc, coordinator_table_name, 0);
        defer alloc.free(participant);
        try (try self.activeDb()).markTransactionParticipantResolved(txn_id, participant);
        return {};
    }

    fn commitBoundTransaction(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        retain_terminal: bool,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (tables.len != 1) return error.UnsupportedOperation;
        const table = tables[0];
        if (!std.mem.eql(u8, self.table_name, table.table_name)) return null;

        const db = try self.activeDb();
        try validateTransactionAgainstLocalSchema(alloc, db, table.writes, table.deletes, table.transforms);
        const commit_version = begin_timestamp + 1;
        const local_participant = try distributed_txn.participantIdForGroup(alloc, table.table_name, 0);
        defer alloc.free(local_participant);
        const participants = [_][]const u8{local_participant};

        _ = db.beginTransactionWithIdAndParticipantsCreatedAtRoleAndRetention(
            txn_id,
            begin_timestamp,
            platform_time.realtimeNs(),
            &participants,
            true,
            retain_terminal,
        ) catch |err| switch (err) {
            error.DecisionConflict => switch (try db.getTransactionStatus(txn_id)) {
                .committed => {
                    db.resolveTransactionIntentsWithSyncLevelAndCancellation(txn_id, .committed, commit_version, sync_level, cancellation) catch |barrier_err| {
                        const durable_status = db.getTransactionStatus(txn_id) catch return barrier_err;
                        if (durable_status != .committed) return barrier_err;
                        var propagation_pending = false;
                        if (!retain_terminal) {
                            db.markTransactionParticipantResolved(txn_id, local_participant) catch {
                                propagation_pending = true;
                            };
                        }
                        return .{ .committed = .{
                            .participant_count = 1,
                            .coordinator_group_id = if (retain_terminal) 0 else null,
                            .coordinator_table_name = if (retain_terminal) table.table_name else null,
                            .propagation_pending = propagation_pending,
                            .visibility_pending = true,
                            .visibility_retry_pending = barrier_err != error.EnrichmentWorkerFailed,
                            .visibility_repair_required = barrier_err == error.EnrichmentWorkerFailed,
                        } };
                    };
                    var propagation_pending = false;
                    if (!retain_terminal) {
                        db.markTransactionParticipantResolved(txn_id, local_participant) catch {
                            propagation_pending = true;
                        };
                    }
                    return .{ .committed = .{
                        .participant_count = 1,
                        .coordinator_group_id = if (retain_terminal) 0 else null,
                        .coordinator_table_name = if (retain_terminal) table.table_name else null,
                        .propagation_pending = propagation_pending,
                    } };
                },
                .aborted => {
                    db.markTransactionParticipantResolved(txn_id, local_participant) catch |ack_err| {
                        std.log.warn("bound transaction abort acknowledgement retry deferred txn_id={x} err={s}", .{
                            txn_id,
                            @errorName(ack_err),
                        });
                    };
                    return .{ .conflict = boundConflict(table, error.DecisionConflict) };
                },
                .pending => return error.TransactionBeginFailed,
            },
            else => return err,
        };
        db.writeTransaction(txn_id, .{
            .writes = table.writes,
            .deletes = table.deletes,
            .transforms = table.transforms,
            .predicates = table.predicates,
        }) catch |err| {
            // A begun local transaction must reach a terminal state on every
            // rejected write. In particular, graph transform validation is
            // performed by DB.writeTransaction after begin, so returning the
            // validation error without aborting would strand its transaction.
            db.resolveTransactionIntents(txn_id, .aborted, commit_version) catch |abort_err| {
                std.log.err("failed to abort rejected bound transaction write_err={s} abort_err={s}", .{
                    @errorName(err),
                    @errorName(abort_err),
                });
                return abort_err;
            };
            db.markTransactionParticipantResolved(txn_id, local_participant) catch |ack_err| {
                // The abort is already durable; recovery can finish this
                // idempotent cleanup without changing the client result.
                std.log.warn("bound transaction abort acknowledgement deferred txn_id={x} err={s}", .{
                    txn_id,
                    @errorName(ack_err),
                });
            };
            switch (err) {
                error.VersionConflict, error.IntentConflict => return .{ .conflict = boundConflict(table, err) },
                error.InvalidBatchRequest,
                error.InvalidArgument,
                error.InvalidGraphEdges,
                error.UnsupportedTransformOperation,
                => return error.InvalidBatchRequest,
                else => return err,
            }
        };
        db.resolveTransactionIntentsWithSyncLevelAndCancellation(txn_id, .committed, commit_version, sync_level, cancellation) catch |err| {
            const durable_status = db.getTransactionStatus(txn_id) catch return err;
            if (durable_status == .committed) {
                std.log.warn("bound transaction acknowledged after durable commit barrier failure txn_id={x} err={s}", .{
                    txn_id,
                    @errorName(err),
                });
                var propagation_pending = false;
                if (!retain_terminal) {
                    db.markTransactionParticipantResolved(txn_id, local_participant) catch {
                        propagation_pending = true;
                    };
                }
                return .{ .committed = .{
                    .participant_count = 1,
                    .coordinator_group_id = if (retain_terminal) 0 else null,
                    .coordinator_table_name = if (retain_terminal) table.table_name else null,
                    .propagation_pending = propagation_pending,
                    .visibility_pending = true,
                    .visibility_retry_pending = err != error.EnrichmentWorkerFailed,
                    .visibility_repair_required = err == error.EnrichmentWorkerFailed,
                } };
            }
            return err;
        };
        var propagation_pending = false;
        if (!retain_terminal) {
            db.markTransactionParticipantResolved(txn_id, local_participant) catch {
                propagation_pending = true;
            };
        }
        return .{ .committed = .{
            .participant_count = 1,
            .coordinator_group_id = if (retain_terminal) 0 else null,
            .coordinator_table_name = if (retain_terminal) table.table_name else null,
            .propagation_pending = propagation_pending,
        } };
    }

    fn createIndex(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
        index_json: []const u8,
    ) !?void {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        const db = try self.activeDb();
        const schema_json = try loadLocalTableSchemaJson(alloc, db);
        defer if (schema_json) |value| alloc.free(value);
        const expanded_index_json = try tables_api.expandSchemaDerivedAlgebraicIndexAlloc(alloc, table_name, index_json, tables_api.effectiveSchemaJson(schema_json));
        defer alloc.free(expanded_index_json);
        const cfg = try parseIndexConfig(alloc, index_name, expanded_index_json);
        defer {
            alloc.free(cfg.name);
            alloc.free(cfg.config_json);
        }
        try db.addIndex(cfg);
    }

    fn putArtifactEnrichment(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        artifact_name: []const u8,
        enrichment_json: []const u8,
    ) !?void {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        var parsed = try std.json.parseFromSlice(db_mod.types.EnrichmentConfig, alloc, enrichment_json, .{
            .allocate = .alloc_always,
            .ignore_unknown_fields = true,
        });
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.name, artifact_name)) return error.InvalidEnrichmentConfig;
        _ = try (try self.activeDb()).upsertEnrichment(parsed.value);
    }

    fn deleteArtifactEnrichment(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        artifact_name: []const u8,
    ) !?void {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        _ = try deleteArtifactEnrichmentFromDbByName(alloc, try self.activeDb(), artifact_name);
    }

    fn dropIndex(
        ptr: *anyopaque,
        _: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
    ) !?void {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        _ = try (try self.activeDb()).deleteIndex(index_name);
    }

    fn batchGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        _: u64,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
    ) !?void {
        return try batch(ptr, alloc, table_name, req);
    }

    fn txnBeginGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        topology_epoch: u64,
        retain_terminal: bool,
        participants: []const []const u8,
    ) !?void {
        return try txnBeginGroupLocalWithPreDecisionContext(ptr, alloc, group_id, table_name, txn_id, begin_timestamp, topology_epoch, retain_terminal, participants, .{});
    }

    fn txnBeginGroupLocalWithPreDecisionContext(
        ptr: *anyopaque,
        _: std.mem.Allocator,
        _: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        _: u64,
        retain_terminal: bool,
        participants: []const []const u8,
        context: distributed_txn.PreDecisionContext,
    ) !?void {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        try ensurePreDecisionContextActive(context);
        _ = try (try self.activeDb()).beginTransactionWithIdAndParticipantsCreatedAtRoleAndRetention(
            txn_id,
            begin_timestamp,
            platform_time.realtimeNs(),
            participants,
            true,
            retain_terminal,
        );
    }

    fn txnPrepareGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        topology_epoch: u64,
        req: db_mod.types.TransactionIntentRequest,
    ) !?void {
        return try txnPrepareGroupLocalWithPreDecisionContext(ptr, alloc, group_id, table_name, txn_id, topology_epoch, req, .{});
    }

    fn txnPrepareGroupLocalWithPreDecisionContext(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        _: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        _: u64,
        req: db_mod.types.TransactionIntentRequest,
        context: distributed_txn.PreDecisionContext,
    ) !?void {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        try ensurePreDecisionContextActive(context);
        const db = try self.activeDb();
        try validateTransactionAgainstLocalSchema(alloc, db, req.writes, req.deletes, req.transforms);
        try ensurePreDecisionContextActive(context);
        try db.writeTransaction(txn_id, req);
    }

    fn txnResolveGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        status: db_mod.types.TxnStatus,
        commit_version: u64,
        topology_epoch: u64,
        sync_level: db_mod.types.SyncLevel,
    ) !?void {
        return try txnResolveGroupLocalWithCancellation(ptr, alloc, group_id, table_name, txn_id, status, commit_version, topology_epoch, sync_level, .none);
    }

    fn txnResolveGroupLocalWithCancellation(
        ptr: *anyopaque,
        _: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        status: db_mod.types.TxnStatus,
        commit_version: u64,
        _: u64,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?void {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        const db = try self.activeDb();
        try db.resolveTransactionIntentsWithSyncLevelAndCancellation(txn_id, status, commit_version, sync_level, cancellation);
        const participant = try distributed_txn.participantIdForGroup(db.alloc, table_name, group_id);
        defer db.alloc.free(participant);
        db.markTransactionParticipantResolved(txn_id, participant) catch |err| switch (err) {
            transactions_mod.TxnError.TxnNotFound => if (status != .aborted) return err,
            else => return err,
        };
    }

    fn txnStatusGroupLocal(
        ptr: *anyopaque,
        _: std.mem.Allocator,
        _: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
    ) !?db_mod.types.TxnStatus {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        return try (try self.activeDb()).getTransactionStatus(txn_id);
    }

    fn txnAcknowledgeGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        participant: []const u8,
    ) !?void {
        const self: *BoundTableWriteSource = @ptrCast(@alignCast(ptr));
        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        _ = group_id;
        _ = alloc;
        try (try self.activeDb()).markTransactionParticipantResolved(txn_id, participant);
    }
};

pub const ProvisionedTableWriteSource = struct {
    pub const StartupCatchUpResult = struct {
        had_debt: bool = false,
        cleared_debt: bool = false,
        terminal_degraded: bool = false,
        busy: bool = false,
        made_progress: bool = false,
        quarantined: bool = false,
        quarantine_retry_scheduled: bool = false,
        retry_at_ms: u64 = 0,
        index_repair_pending: bool = false,
        // Durable repair debt exists, but operator-controlled automation is
        // paused. This is parked status debt, never runnable scheduler work.
        index_repair_paused: bool = false,
        index_repair_attempted: bool = false,
        index_repair_repaired: bool = false,
        index_repair_degraded: bool = false,
        index_repair_disk_wait: bool = false,
        index_repair_retry_at_ms: u64 = 0,
    };

    pub const LocalChangeKind = enum {
        data,
        index_repair,
        structural,
        /// A DB worker observed lifecycle progress. The runtime owner must
        /// publish from outside every DB/index executor.
        runtime_status,
        /// An in-place schema/index reconciliation published fresh runtime
        /// state without replacing the shard root generation.
        runtime_reconciled,
    };

    pub const LocalChangeHook = struct {
        ptr: *anyopaque,
        on_change: *const fn (ptr: *anyopaque, table_name: []const u8, kind: LocalChangeKind) void,
    };

    pub const LocalIndexRepairDebtAction = enum {
        enqueue,
        /// The caller has released every structural and DB lease that could
        /// conflict with repair, so the runtime may admit the queued work
        /// immediately instead of waiting for its control-loop poll.
        enqueue_runnable,
        /// Destructive lifecycle removal after the group path and its durable
        /// repair state are no longer authoritative. Ordinary repair clear
        /// edges enqueue an aggregate audit instead.
        remove,
        cancel,
        clear_cancel,
    };

    pub const LocalIndexRepairDebtHook = struct {
        ptr: *anyopaque,
        on_change: *const fn (
            ptr: *anyopaque,
            table_name: []const u8,
            group_id: u64,
            action: LocalIndexRepairDebtAction,
        ) void,
    };

    /// Durable and live recovery proof for a staged local replica retirement.
    /// The catalog distinguishes an aborted removal from a committed one;
    /// live ownership then fences filesystem deletion until runtime teardown.
    pub const ReplicaRetirementOwnership = struct {
        pub const State = enum {
            retained,
            retiring,
            retired,
        };

        ptr: *anyopaque,
        classify: *const fn (ptr: *anyopaque, group_id: u64) anyerror!State,

        fn state(self: @This(), group_id: u64) !State {
            return try self.classify(self.ptr, group_id);
        }
    };

    pub const PreparedReplicaRetirements = struct {
        alloc: std.mem.Allocator,
        intents: []PersistedReplicaRetirementIntent,

        pub fn deinit(self: *@This()) void {
            for (self.intents) |intent| self.alloc.free(intent.path);
            self.alloc.free(self.intents);
            self.* = undefined;
        }
    };

    const StructuralReconcileRequest = struct {
        table_name: []u8,
        index_name: ?[]u8 = null,
        plan: ?StructuralReconcilePlan = null,
        failure_count: u32 = 0,
        pending_count: u32 = 0,
        attempt_count: u32 = 0,
        prepared: bool = false,
        not_before_ms: u64 = 0,
        deferred_repair_group_ids: std.ArrayListUnmanaged(u64) = .empty,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            alloc.free(self.table_name);
            if (self.index_name) |name| alloc.free(name);
            if (self.plan) |*plan| plan.deinit(alloc);
            self.deferred_repair_group_ids.deinit(alloc);
            self.* = undefined;
        }

        fn deferRepairDebt(self: *@This(), alloc: std.mem.Allocator, group_id: u64) !void {
            for (self.deferred_repair_group_ids.items) |deferred_group_id| {
                if (deferred_group_id == group_id) return;
            }
            try self.deferred_repair_group_ids.append(alloc, group_id);
        }

        fn publishDeferredRepairDebt(self: *@This(), owner: *ProvisionedTableWriteSource) void {
            for (self.deferred_repair_group_ids.items) |group_id| {
                owner.notifyLocalIndexRepairDebt(self.table_name, group_id, .enqueue_runnable);
            }
            self.deferred_repair_group_ids.clearRetainingCapacity();
        }

        fn handoffDeferredRepairDebt(self: *@This(), owner: *ProvisionedTableWriteSource) void {
            // Each shard acquires handoff authority before its structural
            // operation releases. The table reservation can therefore be
            // released without creating a clear-edge gap, even when repair of
            // an earlier shard completed while later shards reconciled.
            owner.releaseStructuralReconcileStatus(self.table_name);
            self.publishDeferredRepairDebt(owner);
        }

        fn sameTarget(self: @This(), table_name: []const u8, index_name: ?[]const u8) bool {
            if (!std.mem.eql(u8, self.table_name, table_name)) return false;
            if (self.index_name == null or index_name == null) return self.index_name == null and index_name == null;
            return std.mem.eql(u8, self.index_name.?, index_name.?);
        }

        fn covers(self: @This(), table_name: []const u8, index_name: ?[]const u8) bool {
            if (!std.mem.eql(u8, self.table_name, table_name)) return false;
            if (self.index_name == null) return true;
            if (index_name == null) return false;
            return std.mem.eql(u8, self.index_name.?, index_name.?);
        }

        fn reservesWriteAdmission(self: @This()) bool {
            // Whole-table/schema reconciliation can change the contract seen
            // by a write and therefore retains the exclusive reservation.
            // Index-targeted work runs only after request-time managed
            // admission has installed the index writer in every local group.
            return self.index_name == null;
        }
    };

    const StructuralReconcileGroup = struct {
        range: metadata_table_manager.RangeRecord,
        identity_namespace: doc_identity.Namespace,

        fn clone(alloc: std.mem.Allocator, table_id: u64, range: metadata_table_manager.RangeRecord) !@This() {
            var owned_range = try metadata_table_manager.cloneRange(alloc, range);
            owned_range.table_id = table_id;
            return .{
                .range = owned_range,
                .identity_namespace = tableIdentityNamespaceForRangeId(table_id, range),
            };
        }

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            metadata_table_manager.freeRange(alloc, self.range);
            self.* = undefined;
        }
    };

    const StructuralReconcilePlan = struct {
        metadata_group_id: u64,
        metadata_incarnation: ?metadata_api.MetadataClusterIncarnation,
        table_id: u64,
        indexes_json: []u8,
        schema_json: []u8,
        topology: metadata_api.CatalogTableTopology,
        groups: []StructuralReconcileGroup,
        pending_group_indexes: std.ArrayListUnmanaged(usize),
        cursor: usize = 0,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            for (self.groups) |*group| group.deinit(alloc);
            alloc.free(self.groups);
            alloc.free(self.indexes_json);
            alloc.free(self.schema_json);
            self.pending_group_indexes.deinit(alloc);
            self.* = undefined;
        }

        fn currentGroup(self: *@This()) ?*StructuralReconcileGroup {
            if (self.pending_group_indexes.items.len == 0) return null;
            if (self.cursor >= self.pending_group_indexes.items.len) self.cursor = 0;
            return &self.groups[self.pending_group_indexes.items[self.cursor]];
        }

        fn markCurrentComplete(self: *@This()) void {
            std.debug.assert(self.pending_group_indexes.items.len != 0);
            _ = self.pending_group_indexes.swapRemove(self.cursor);
            if (self.cursor >= self.pending_group_indexes.items.len) self.cursor = 0;
        }

        fn markCurrentBusy(self: *@This()) void {
            if (self.pending_group_indexes.items.len == 0) return;
            self.cursor = (self.cursor + 1) % self.pending_group_indexes.items.len;
        }
    };

    const StructuralReconcileOutcome = enum {
        complete,
        yielded,
        blocked,
        discarded,
    };

    const StructuralReconcileGroupOutcome = enum {
        complete,
        busy,
        repair_pending,
        publication_pending,
    };

    const StructuralRuntimeObservation = struct {
        status: runtime_status.LocalTableRuntimeStatus,
        opened_root_generation: u64,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            self.status.deinit(alloc);
            self.* = undefined;
        }
    };

    const structural_reconcile_retry_min_ms: u64 = 25;
    const structural_reconcile_retry_max_ms: u64 = 2_000;
    const structural_reconcile_pending_delay_ms: u64 = 100;
    const structural_reconcile_groups_per_quantum: usize = 4;

    fn structuralReconcileRetryDelayMs(failure_count: u32) u64 {
        const exponent: u6 = @intCast(@min(failure_count -| 1, 7));
        return @min(
            structural_reconcile_retry_max_ms,
            structural_reconcile_retry_min_ms * (@as(u64, 1) << exponent),
        );
    }

    fn structuralReconcileRequeueAtMs(outcome: StructuralReconcileOutcome, now_ms: u64) u64 {
        return switch (outcome) {
            .yielded => now_ms,
            .blocked => now_ms +| structural_reconcile_pending_delay_ms,
            .complete, .discarded => unreachable,
        };
    }

    replica_root_dir: []const u8,
    catalog: table_catalog.CatalogSource,
    local_db_mutex: SourceStateMutex = .{},
    table_activity_threaded: Io.Threaded,
    table_activity_mutex: Io.Mutex = .init,
    table_activity_ready: Io.Condition = .init,
    write_coalesce_mutex: Io.Mutex = .init,
    write_coalesce_ready: Io.Condition = .init,
    write_coalesce_queues: std.ArrayListUnmanaged(WriteCoalesceQueue) = .empty,
    read_cache: ?*table_reads.ProvisionedTableReadCache = null,
    write_cache: ?*ProvisionedTableWriteCache = null,
    startup_write_cache: ?*ProvisionedTableWriteCache = null,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime = null,
    // Hosted storage shares a process-wide cache whose mutex must fence both
    // foreground opens and persistent dropped-table recovery jobs.
    dropped_table_cleanup_outer_mutex: ?*std.atomic.Mutex = null,
    dropped_table_delete_owner_id: u64 = 0,
    dropped_table_recovery_started: std.atomic.Value(bool) = .init(false),
    dropped_table_recovery_scheduled: std.atomic.Value(bool) = .init(false),
    // Every wake increments an epoch. The active scanner releases ownership
    // only after observing the same epoch before and after clearing the
    // scheduled bit, closing the classic coalesced-work lost-wakeup race.
    dropped_table_recovery_requested: std.atomic.Value(u64) = .init(0),
    dropped_table_recovery_retry_scheduled: std.atomic.Value(bool) = .init(false),
    dropped_table_recovery_retry_failures: std.atomic.Value(u32) = .init(0),
    replica_retirement_ownership_mutex: std.atomic.Mutex = .unlocked,
    replica_retirement_ownership: ?ReplicaRetirementOwnership = null,
    // Serializes journal publication/recovery and tracks in-flight plans so a
    // scanner cannot classify a just-prepared record before its catalog CAS.
    replica_retirement_intent_mutex: std.atomic.Mutex = .unlocked,
    active_replica_retirement_intents: std.AutoHashMapUnmanaged(u64, usize) = .empty,
    // Protected by table_activity_mutex. A retirement is rare topology work;
    // this set fences new group activity while current leases drain.
    retiring_replica_groups: std.AutoHashMapUnmanaged(u64, void) = .empty,
    restore_repair_work_group: Io.Group = .init,
    restore_repair_shutdown: std.atomic.Value(bool) = .init(false),
    restore_repair_completion_mutex: Io.Mutex = .init,
    restore_repair_completion_group: Io.Group = .init,
    restore_repair_completion_scheduled: std.atomic.Value(bool) = .init(false),
    restore_repair_completions: std.ArrayListUnmanaged([]u8) = .empty,
    structural_reconcile_mutex: Io.Mutex = .init,
    structural_reconcile_scheduled: std.atomic.Value(bool) = .init(false),
    structural_reconcile_tables: std.ArrayListUnmanaged(StructuralReconcileRequest) = .empty,
    runtime_status_cache: ?*runtime_status.TableRuntimeSnapshotCache = null,
    local_change_hook: ?LocalChangeHook = null,
    local_index_repair_debt_hook: ?LocalIndexRepairDebtHook = null,
    raft_batcher: ?RaftBatcher = null,
    local_write_owner: ?*ProvisionedTableWriteSource = null,
    seed_create_table_writers: bool = true,
    group_visible_root_generation: ?table_reads.GroupVisibleRootGenerationSource = null,
    antfly_provider: ?managed_embedder.AntflyProvider = null,
    inference_api_url: ?[]const u8 = null,
    secret_store: ?*common_secrets.FileStore = null,
    destination_authorizer: ?stored_destination_authorization.Authorizer = null,
    restore_open_options: backups_api.OpenOptions = .{},
    remote_content: ?*const scraping.RemoteContentConfig = null,
    resolution_candidate_source: ?db_mod.CandidateSource = null,
    entity_sink: ?db_mod.EntitySink = null,
    promotion_leadership_source: ?ProvisionedTableWriteCache.PromotionLeadershipSource = null,
    ha_write_gate: ?db_mod.HAWriteGate = null,
    ha_async_mirror: ?db_mod.HAAsyncEffectMirror = null,
    dirty_write_tables_mutex: std.atomic.Mutex = .unlocked,
    dirty_write_table_count: std.atomic.Value(u32) = .init(0),
    dirty_write_tables: std.StringHashMapUnmanaged(void) = .empty,
    startup_catch_up_active: std.atomic.Value(bool) = .init(false),
    startup_catch_up_backoff_mutex: std.atomic.Mutex = .unlocked,
    startup_catch_up_backoff_epoch: std.atomic.Value(u64) = .init(1),
    startup_catch_up_backoff_alloc: std.mem.Allocator = std.heap.page_allocator,
    quiesced: bool = false,
    startup_catch_up_backoffs: std.AutoHashMapUnmanaged(u64, StartupCatchUpBackoff) = .empty,
    active_table_activities: std.ArrayListUnmanaged(TableActivity) = .empty,
    // Protected by table_activity_mutex. Repair handoff publications capture
    // this node-local generation before observing status and may retire only
    // that exact edge, including across activity-entry prune/recreate (ABA).
    next_repair_handoff_generation: u64 = 1,

    const TableActivity = struct {
        // Owned by active_table_activities; entries must be created via activityEntryLocked.
        table_name: []const u8,
        group_id: ?u64 = null,
        table_request_active: usize = 0,
        read_request_active: usize = 0,
        // Status observes immutable published state and may coexist with
        // ordinary group maintenance. Track it separately so it neither
        // starves that maintenance nor gets mistaken for a data read that
        // must drain before mutation. Root replacement still waits for both.
        status_request_active: usize = 0,
        // Reserved before structural work drains live status, reads, and
        // writes. New status calls use the published snapshot while reserved,
        // so continuous polling cannot extend the drain.
        structural_waiters: usize = 0,
        operation_active: bool = false,
        // Reserved before an exclusive group operation waits for admitted
        // readers to drain. Without this reservation, newly arriving reads
        // can repeatedly overtake a committed Raft apply and starve the
        // state-machine thread indefinitely.
        operation_waiters: usize = 0,
        // Reserved before a transition waits so newly arriving writers cannot
        // repeatedly win the idle handoff and starve structural progress.
        transition_waiters: usize = 0,
        // A schema/index backfill mutates only its unpublished target index.
        // Reads routed to the retained read-schema generation may therefore
        // share the resident DB while that operation is active. Ordinary
        // writes, restores, and generation changes remain read-exclusive.
        operation_allows_reads: bool = false,
        structural_active: bool = false,
        structural_reconcile_active: bool = false,
        structural_reconcile_queued: usize = 0,
        structural_reconcile_waiters: usize = 0,
        // Index-targeted reconciliation deliberately does not reserve write
        // admission, but status must remain snapshot-only until every queued
        // quantum has finished. Otherwise a gap between quanta can expose an
        // already-ready snapshot immediately before the worker appends more
        // replay work.
        structural_reconcile_status_pending: usize = 0,
        // Each affected shard acquires status authority before its compatible
        // structural operation releases. This does not reserve write
        // admission; it only makes cached status non-authoritative until the
        // repaired generation publishes its final visibility boundary.
        repair_handoff_status_pending: usize = 0,
        repair_handoff_clear_observed: bool = false,
        repair_handoff_generation: u64 = 0,
        // Managed index creation can synchronously append durable replay work
        // while leaving its execution to the resident asynchronous owner. Keep
        // status fail-closed across that handoff until the owner publishes a
        // consistent post-append observation carrying the real replay target.
        publication_handoffs: std.ArrayListUnmanaged(PublicationHandoff) = .empty,
        restore_preparations: usize = 0,
        generation_preparation_active: bool = false,

        fn structuralReconcileReserved(self: TableActivity) bool {
            return self.structural_reconcile_active or
                self.structural_reconcile_queued > 0 or
                self.structural_reconcile_waiters > 0;
        }

        fn deinit(self: *TableActivity) void {
            for (self.publication_handoffs.items) |*handoff| handoff.deinit();
            self.publication_handoffs.deinit(std.heap.page_allocator);
            std.heap.page_allocator.free(self.table_name);
            self.* = undefined;
        }
    };

    const PublicationHandoff = struct {
        index_name: []u8,
        coverage_generation: u64,
        coverage_config_hash: u64,
        producer_target_sequence: u64,
        requires_blocking: bool,

        fn deinit(self: *PublicationHandoff) void {
            std.heap.page_allocator.free(self.index_name);
            self.* = undefined;
        }
    };

    const PublicationHandoffTarget = struct {
        index_name: []const u8,
        coverage_generation: u64,
        coverage_config_hash: u64,
        producer_target_sequence: u64,
        requires_blocking: bool,
    };

    const StatusRequestAdmission = enum {
        live,
        snapshot_only,
    };

    const StartupCatchUpBackoff = struct {
        consecutive_no_progress: u8 = 0,
        retry_at_ms: u64 = 0,
    };

    const WriteCoalesceQueue = struct {
        table_name: []u8,
        group_id: u64,
        draining: bool = false,
        entries: std.ArrayListUnmanaged(*WriteCoalesceEntry) = .empty,
    };

    const WriteCoalesceEntry = struct {
        group: GroupBatch = .{ .group_id = 0 },
        sync_level: db_mod.types.SyncLevel = .write,
        timestamp_ns: u64 = 0,
        done: bool = false,
        err: ?anyerror = null,
    };

    /// Serializes source configuration with every cache container it can
    /// mutate. The order matches request-time cache opens: cache-open locks by
    /// address, then the source lock, then cache lifecycle locks by address.
    const WriteCacheTransitionLocks = struct {
        source: *ProvisionedTableWriteSource,
        first: ?*ProvisionedTableWriteCache,
        second: ?*ProvisionedTableWriteCache,
        state_locked: bool = true,
        open_locked: bool = true,

        fn init(
            owner: *ProvisionedTableWriteSource,
            include_write: bool,
            include_startup: bool,
        ) WriteCacheTransitionLocks {
            var first: ?*ProvisionedTableWriteCache = if (include_write) owner.write_cache else null;
            var second: ?*ProvisionedTableWriteCache = if (include_startup) owner.startup_write_cache else null;
            if (first == second) second = null;
            if (first == null) {
                first = second;
                second = null;
            } else if (second != null and @intFromPtr(first.?) > @intFromPtr(second.?)) {
                const swap = first;
                first = second;
                second = swap;
            }

            if (first) |cache| lockAtomic(&cache.open_mutex);
            if (second) |cache| lockAtomic(&cache.open_mutex);
            lockAtomic(&owner.local_db_mutex);
            if (first) |cache| lockAtomic(&cache.entry_lifecycle_mutex);
            if (second) |cache| lockAtomic(&cache.entry_lifecycle_mutex);
            return .{ .source = owner, .first = first, .second = second };
        }

        fn reserveClearCapacity(self: *WriteCacheTransitionLocks) !void {
            if (self.first) |cache| try cache.reserveClearCapacityAssumeLifecycleLocked();
            if (self.second) |cache| try cache.reserveClearCapacityAssumeLifecycleLocked();
        }

        fn assertClearCapacity(self: *const WriteCacheTransitionLocks) void {
            const assertCache = struct {
                fn run(cache: *const ProvisionedTableWriteCache) void {
                    std.debug.assert(cache.retired_entries.capacity - cache.retired_entries.items.len >= cache.entries.items.len);
                    std.debug.assert(cache.closing_entries.capacity - cache.closing_entries.items.len >= cache.entries.items.len);
                }
            }.run;
            if (self.first) |cache| assertCache(cache);
            if (self.second) |cache| assertCache(cache);
        }

        fn clearCaches(self: *WriteCacheTransitionLocks, notify_evictions: bool) void {
            if (self.first) |cache| {
                if (notify_evictions) cache.notifyTableEvictions();
                cache.clearAssumeLifecycleLocked();
            }
            if (self.second) |cache| {
                if (notify_evictions) cache.notifyTableEvictions();
                cache.clearAssumeLifecycleLocked();
            }
        }

        fn releaseStateLocks(self: *WriteCacheTransitionLocks) void {
            if (!self.state_locked) return;
            if (self.second) |cache| cache.entry_lifecycle_mutex.unlock();
            if (self.first) |cache| cache.entry_lifecycle_mutex.unlock();
            self.source.local_db_mutex.unlock();
            self.state_locked = false;
        }

        fn drainAndRelease(self: *WriteCacheTransitionLocks) void {
            self.releaseStateLocks();
            if (self.first) |cache| cache.drainPendingClosesAssumeOpenMutexHeld();
            if (self.second) |cache| cache.drainPendingClosesAssumeOpenMutexHeld();
            self.releaseOpenLocks();
        }

        fn releaseOpenLocks(self: *WriteCacheTransitionLocks) void {
            if (!self.open_locked) return;
            if (self.second) |cache| cache.open_mutex.unlock();
            if (self.first) |cache| cache.open_mutex.unlock();
            self.open_locked = false;
        }

        fn deinit(self: *WriteCacheTransitionLocks) void {
            self.releaseStateLocks();
            self.releaseOpenLocks();
        }
    };

    /// Reclaim an idle lifetime-descriptor owner from either cache while no
    /// cache-open lock is held by the caller. Cross-cache reclamation is rare,
    /// so use the full transition lock order here: both cache-open locks by
    /// address, source state, then both lifecycle locks by address. This keeps
    /// descriptor pressure from introducing a lock inversion with cache
    /// rebinding, HA transitions, or startup-cache adoption.
    fn reclaimInactiveEntryAcrossWriteCachesForDescriptorPressure(
        self: *ProvisionedTableWriteSource,
        opening_cache: *ProvisionedTableWriteCache,
        excluded_group_id: u64,
        excluded_table_name: []const u8,
    ) !bool {
        var locks = WriteCacheTransitionLocks.init(self, true, true);
        defer locks.deinit();

        // Read bindings only after the transition helper owns source state, and
        // touch only caches whose lifecycle locks it now holds.
        const write_cache = self.write_cache;
        const startup_cache = self.startup_write_cache;
        const opening_is_write = write_cache != null and write_cache.? == opening_cache;
        const opening_is_startup = startup_cache != null and startup_cache.? == opening_cache;
        if (!opening_is_write and !opening_is_startup) return false;

        const other_cache: ?*ProvisionedTableWriteCache = if (opening_is_write)
            if (startup_cache != opening_cache) startup_cache else null
        else if (write_cache != opening_cache)
            write_cache
        else
            null;
        if (other_cache == null) return false;

        // Prefer the other cache because the opening cache was checked
        // immediately before entering this coordinated slow path. Recheck the
        // opening cache only if its state changed while its lock was dropped.
        var evicted = try other_cache.?.evictOneInactiveEntryForDescriptorPressureAssumeLifecycleLocked(
            // The same group may have an idle stale-generation startup owner;
            // only the opening cache must protect its target entry.
            null,
            excluded_table_name,
        );
        if (!evicted) {
            evicted = try opening_cache.evictOneInactiveEntryForDescriptorPressureAssumeLifecycleLocked(
                excluded_group_id,
                excluded_table_name,
            );
        }
        if (!evicted) return false;

        // DB.close releases persistent lock permits. Keep both open locks until
        // every queued victim is closed, then let the caller reacquire its cache
        // and revalidate the prepared-open state before retrying disk I/O.
        locks.drainAndRelease();
        return true;
    }

    pub fn init(replica_root_dir: []const u8, catalog: table_catalog.CatalogSource) ProvisionedTableWriteSource {
        return .{
            .replica_root_dir = replica_root_dir,
            .catalog = catalog,
            .table_activity_threaded = threaded_io_limits.initService(std.heap.page_allocator),
        };
    }

    pub fn bindWriteCaches(
        self: *ProvisionedTableWriteSource,
        write_cache: ?*ProvisionedTableWriteCache,
        startup_write_cache: ?*ProvisionedTableWriteCache,
    ) void {
        const state_mutex = self.local_db_mutex.atomicMutex();
        if (write_cache) |cache| cache.bindStateMutex(state_mutex);
        if (startup_write_cache) |cache| cache.bindStateMutex(state_mutex);
        self.write_cache = write_cache;
        self.startup_write_cache = startup_write_cache;
        const hook = ProvisionedTableWriteCache.TableEvictionHook{
            .ptr = self,
            .on_evict = onWriteCacheTableEvicted,
        };
        if (write_cache) |cache| cache.table_eviction_hook = hook;
        if (startup_write_cache) |cache| cache.table_eviction_hook = hook;
    }

    /// Bind every source that can mutate one storage owner's writer caches to
    /// the same state lock. The source keeps an embedded fallback lock for
    /// standalone use, while provisioned storage makes shared-cache
    /// serialization an explicit ownership invariant.
    pub fn bindWriteCachesWithStateMutex(
        self: *ProvisionedTableWriteSource,
        write_cache: ?*ProvisionedTableWriteCache,
        startup_write_cache: ?*ProvisionedTableWriteCache,
        state_mutex: *std.atomic.Mutex,
    ) void {
        self.local_db_mutex.bind(state_mutex);
        self.bindWriteCaches(write_cache, startup_write_cache);
    }

    fn onWriteCacheTableEvicted(
        ptr: *anyopaque,
        evicting_cache: *ProvisionedTableWriteCache,
        table_name: []const u8,
    ) void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.local_write_owner) |owner| {
            return onWriteCacheTableEvicted(owner, evicting_cache, table_name);
        }
        // The table-wide read epoch makes every mutation visible even when a
        // retired entry still has a draining lease. A later mutation on that
        // lease re-marks the table through its visibility hook.
        self.invalidateReadCache(table_name);

        const sibling_owns_table = if (self.write_cache != null and self.write_cache.? != evicting_cache and self.write_cache.?.hasTableStateLocked(table_name))
            true
        else if (self.startup_write_cache != null and self.startup_write_cache.? != evicting_cache and self.startup_write_cache.?.hasTableStateLocked(table_name))
            true
        else
            false;
        if (sibling_owns_table) return;

        // No cached owner can provide a fresher status after this retirement.
        // Remove cached observations instead of letting them masquerade as
        // fresh, and let the next status request recover from durable storage.
        self.invalidateRuntimeStatusCache(table_name);
        self.clearDirtyWriteTable(table_name);
    }

