    pub fn withHAWriteGate(
        self: *ProvisionedTableWriteSource,
        gate: ?db_mod.HAWriteGate,
    ) !*ProvisionedTableWriteSource {
        var locks = WriteCacheTransitionLocks.init(self, true, true);
        defer locks.deinit();
        const changed = !ProvisionedTableWriteCache.haWriteGatesEqual(self.ha_write_gate, gate);
        if (!changed) return self;
        try locks.reserveClearCapacity();
        self.ha_write_gate = gate;
        if (locks.first) |cache| cache.ha_write_gate = gate;
        if (locks.second) |cache| cache.ha_write_gate = gate;
        locks.clearCaches(false);
        self.resetCachedVisibilityAfterOwnershipChange();
        locks.drainAndRelease();
        return self;
    }

    /// Reserves every queue slot an ownership change can consume without
    /// publishing configuration. Promotion uses this before consuming the
    /// standby, so even a manually assembled cache that predates the normal
    /// entry-install invariant fails before any irreversible HA mutation.
    pub fn prepareHAConfigTransition(self: *ProvisionedTableWriteSource) !void {
        var locks = WriteCacheTransitionLocks.init(self, true, true);
        defer locks.deinit();
        try locks.reserveClearCapacity();
    }

    pub fn withHAMirror(
        self: *ProvisionedTableWriteSource,
        mirror: ?db_mod.HAAsyncEffectMirror,
    ) !*ProvisionedTableWriteSource {
        var locks = WriteCacheTransitionLocks.init(self, true, true);
        defer locks.deinit();
        const changed = !ProvisionedTableWriteCache.haAsyncMirrorsEqual(self.ha_async_mirror, mirror);
        if (!changed) return self;
        try locks.reserveClearCapacity();
        self.ha_async_mirror = mirror;
        if (locks.first) |cache| cache.ha_async_mirror = mirror;
        if (locks.second) |cache| cache.ha_async_mirror = mirror;
        locks.clearCaches(false);
        self.resetCachedVisibilityAfterOwnershipChange();
        locks.drainAndRelease();
        return self;
    }

    /// Publishes a mirror after `prepareHAConfigTransition` has succeeded.
    /// Entry installation preserves the retirement-capacity invariant while
    /// the preflight lock is released, so this path cannot allocate after an
    /// irreversible HA ownership handoff.
    pub fn withPreparedHAMirror(
        self: *ProvisionedTableWriteSource,
        mirror: ?db_mod.HAAsyncEffectMirror,
    ) *ProvisionedTableWriteSource {
        var locks = WriteCacheTransitionLocks.init(self, true, true);
        defer locks.deinit();
        const changed = !ProvisionedTableWriteCache.haAsyncMirrorsEqual(self.ha_async_mirror, mirror);
        if (!changed) return self;
        locks.assertClearCapacity();
        self.ha_async_mirror = mirror;
        if (locks.first) |cache| cache.ha_async_mirror = mirror;
        if (locks.second) |cache| cache.ha_async_mirror = mirror;
        locks.clearCaches(false);
        self.resetCachedVisibilityAfterOwnershipChange();
        locks.drainAndRelease();
        return self;
    }

    fn resetCachedVisibilityAfterOwnershipChange(self: *ProvisionedTableWriteSource) void {
        // A role/mirror transition retires every local writer authority at
        // once. Invalidate both observation planes only after the caches have
        // drained so no pre-transition status can be served as current.
        if (self.read_cache) |cache| cache.clear();
        if (self.runtime_status_cache) |cache| cache.clear();
        self.clearAllDirtyWriteTables();
    }

    fn syncRuntimeHooksToCaches(self: *ProvisionedTableWriteSource) void {
        if (self.write_cache) |cache| self.syncRuntimeHooksToCache(cache);
        if (self.startup_write_cache) |cache| {
            if (self.write_cache != cache) self.syncRuntimeHooksToCache(cache);
        }
    }

    fn syncRuntimeHooksToCache(
        self: *ProvisionedTableWriteSource,
        cache: *ProvisionedTableWriteCache,
    ) void {
        lockAtomic(&cache.open_mutex);
        defer cache.open_mutex.unlock();
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        cache.setRuntimeHooksLocked(
            self.resolution_candidate_source,
            self.entity_sink,
            self.promotion_leadership_source,
        );
    }

    fn applyRuntimeHooksToUncachedDb(
        self: *ProvisionedTableWriteSource,
        db: *db_mod.DB,
        table_name: []const u8,
        group_id: u64,
        owner_state: *ProvisionedTableWriteCache.PromotionOwnerState,
    ) void {
        db.setResolutionCandidateSource(self.resolution_candidate_source);
        db.setEntitySink(self.entity_sink);
        owner_state.* = .{
            .group_id = group_id,
            .leadership_source = self.promotion_leadership_source,
        };
        db.setPromotionOwner(owner_state.owner());
        // Cold repair owners must report the same durable pending/clear edges
        // as resident writers. DB.close() clears this hook with a callback
        // barrier before table_name leaves the caller's scope.
        db.setQueryVisibilityHook(self.managedDerivedVisibilityHook(table_name, group_id, db));
    }

    pub fn withRaftBatcher(self: *ProvisionedTableWriteSource, batcher: ?RaftBatcher) *ProvisionedTableWriteSource {
        self.raft_batcher = batcher;
        return self;
    }

    fn transactionRecoveryConfig(self: *ProvisionedTableWriteSource) db_mod.transaction_runtime.Config {
        const backend_runtime = self.backend_runtime orelse return .{};
        if (backend_runtime.io() == null or self.quiesced) return .{};
        const replicated = self.raft_batcher != null;
        return .{
            .enabled = true,
            .lease_owned = !replicated,
            .owner_id = "provisioned-2pc",
            .interval_ms = 5_000,
            .cutoff_ns = 5 * std.time.ns_per_min,
            .resolver_ctx = self,
            .resolve_participant_fn = resolveRecoveryParticipant,
            .replicated_metadata = replicated,
            .owns_recovery_fn = if (replicated) ownsRecovery else null,
            .acknowledge_participant_fn = if (replicated) acknowledgeRecoveryParticipant else null,
            .cleanup_transaction_fn = if (replicated) cleanupRecoveryTransaction else null,
        };
    }

    fn ownsRecovery(ptr: *anyopaque, owner_participant: []const u8) bool {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const ref = distributed_txn.parseParticipantRef(owner_participant) orelse return false;
        const leadership = self.promotion_leadership_source orelse return true;
        return leadership.isLocalLeader(ref.group_id);
    }

    fn resolveRecoveryParticipant(
        ptr: *anyopaque,
        txn_id: db_mod.types.TxnId,
        participant: []const u8,
        status: db_mod.types.TxnStatus,
        commit_version: u64,
    ) !void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const ref = distributed_txn.parseParticipantRef(participant) orelse return error.InvalidParticipant;
        if (self.quiesced) return error.Canceled;
        const alloc = std.heap.page_allocator;
        if (self.raft_batcher) |batcher| {
            try batcher.batchGroup(alloc, ref.group_id, ref.table_name, .{
                // Recovery acknowledges immediately after this returns. Wait
                // for Raft apply so a leader change cannot discard a merely
                // proposed resolution after the coordinator forgets it.
                .sync_level = .write,
                .transaction = .{ .resolve = .{
                    .txn_id = txn_id,
                    .status = status,
                    .commit_version = commit_version,
                } },
            });
            return;
        }
        _ = (try self.source().txnResolveGroupLocal(
            alloc,
            ref.group_id,
            ref.table_name,
            txn_id,
            status,
            commit_version,
            0,
            .write,
        )) orelse return error.UnknownGroup;
    }

    fn acknowledgeRecoveryParticipant(
        ptr: *anyopaque,
        txn_id: db_mod.types.TxnId,
        owner_participant: []const u8,
        participant: []const u8,
    ) !void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const owner = distributed_txn.parseParticipantRef(owner_participant) orelse return error.InvalidParticipant;
        const batcher = self.raft_batcher orelse return error.UnsupportedOperation;
        try batcher.batchGroup(std.heap.page_allocator, owner.group_id, owner.table_name, .{
            .sync_level = .write,
            .transaction = .{ .acknowledge = .{
                .txn_id = txn_id,
                .participant = participant,
            } },
        });
    }

    fn cleanupRecoveryTransaction(
        ptr: *anyopaque,
        txn_id: db_mod.types.TxnId,
        owner_participant: []const u8,
        cutoff_timestamp: u64,
        retained_cutoff_timestamp: u64,
    ) !void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const owner = distributed_txn.parseParticipantRef(owner_participant) orelse return error.InvalidParticipant;
        const batcher = self.raft_batcher orelse return error.UnsupportedOperation;
        try batcher.batchGroup(std.heap.page_allocator, owner.group_id, owner.table_name, .{
            .sync_level = .write,
            .transaction = .{ .cleanup = .{
                .txn_id = txn_id,
                .cutoff_timestamp = cutoff_timestamp,
                .retained_cutoff_timestamp = retained_cutoff_timestamp,
            } },
        });
    }

    pub fn withLocalWriteOwner(self: *ProvisionedTableWriteSource, owner: ?*ProvisionedTableWriteSource) *ProvisionedTableWriteSource {
        self.local_write_owner = if (owner == self) null else owner;
        return self;
    }

    pub fn withReplicaRetirementOwnership(
        self: *ProvisionedTableWriteSource,
        ownership: ?ReplicaRetirementOwnership,
    ) *ProvisionedTableWriteSource {
        lockAtomic(&self.replica_retirement_ownership_mutex);
        self.replica_retirement_ownership = ownership;
        self.replica_retirement_ownership_mutex.unlock();
        // The general cleanup worker can race source construction and scan
        // before the live Raft host is attached. Scan synchronously when the
        // fail-closed proof becomes available; merely scheduling could coalesce
        // with the proof-less scan and strand an intent until another event.
        if (ownership != null) {
            const retry_required = self.recoverReplicaRetirementIntents(std.heap.page_allocator) catch |err| blk: {
                std.log.warn("replica-retirement ownership attachment recovery deferred root={s} err={s}", .{
                    self.replica_root_dir,
                    @errorName(err),
                });
                break :blk true;
            };
            if (retry_required) self.scheduleDroppedTableRecoveryRetry();
        }
        return self;
    }

    fn replicaRetirementOwnershipSnapshot(self: *ProvisionedTableWriteSource) ?ReplicaRetirementOwnership {
        lockAtomic(&self.replica_retirement_ownership_mutex);
        defer self.replica_retirement_ownership_mutex.unlock();
        return self.replica_retirement_ownership;
    }

    pub fn withCreateTableWriterSeeding(self: *ProvisionedTableWriteSource, enabled: bool) *ProvisionedTableWriteSource {
        self.seed_create_table_writers = enabled;
        return self;
    }

    fn localWriteOwnerSource(self: *ProvisionedTableWriteSource) ?TableWriteSource {
        const owner = self.local_write_owner orelse return null;
        return owner.source();
    }

    /// Stop every source-owned worker before an attached storage owner begins
    /// closing cached DBs. This is deliberately separate from `deinit`: cache
    /// pointers are borrowed, so a standalone source must remain safe to
    /// destroy after its optional cache owner has already gone away.
    pub fn quiesce(self: *ProvisionedTableWriteSource) void {
        if (self.quiesced) return;
        self.closeDroppedTableDeletes();
        const io = self.table_activity_threaded.io();
        self.restore_repair_shutdown.store(true, .release);
        self.restore_repair_work_group.cancel(io);
        self.restore_repair_completion_group.await(io) catch {};
        self.freeRestoreRepairCompletions();
        self.freeStructuralReconcileTables();
        self.freeWriteCoalesceQueues();
        lockAtomic(&self.startup_catch_up_backoff_mutex);
        self.startup_catch_up_backoffs.deinit(self.startup_catch_up_backoff_alloc);
        self.startup_catch_up_backoffs = .empty;
        self.startup_catch_up_backoff_mutex.unlock();
        self.table_activity_mutex.lockUncancelable(io);
        for (self.active_table_activities.items) |*entry| entry.deinit();
        self.active_table_activities.deinit(std.heap.page_allocator);
        self.active_table_activities = .empty;
        self.retiring_replica_groups.deinit(std.heap.page_allocator);
        self.retiring_replica_groups = .empty;
        self.table_activity_mutex.unlock(io);
        lockAtomic(&self.replica_retirement_intent_mutex);
        self.active_replica_retirement_intents.deinit(std.heap.page_allocator);
        self.active_replica_retirement_intents = .empty;
        self.replica_retirement_intent_mutex.unlock();
        self.quiesced = true;
    }

    pub fn deinit(self: *ProvisionedTableWriteSource) void {
        self.quiesce();
        lockAtomic(&self.dirty_write_tables_mutex);
        self.clearAllDirtyWriteTablesLocked();
        self.dirty_write_tables.deinit(std.heap.page_allocator);
        self.dirty_write_tables = .empty;
        self.dirty_write_tables_mutex.unlock();
        self.table_activity_threaded.deinit();
        self.* = undefined;
    }

    pub fn localDbMutex(self: *ProvisionedTableWriteSource) *std.atomic.Mutex {
        return self.local_db_mutex.atomicMutex();
    }

    fn freeWriteCoalesceQueues(self: *ProvisionedTableWriteSource) void {
        const io = self.table_activity_threaded.io();
        const alloc = std.heap.page_allocator;
        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        for (self.write_coalesce_queues.items) |*queue| {
            alloc.free(queue.table_name);
            queue.entries.deinit(alloc);
        }
        self.write_coalesce_queues.deinit(alloc);
        self.write_coalesce_queues = .empty;
    }

    fn findWriteCoalesceQueueLocked(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
    ) ?usize {
        for (self.write_coalesce_queues.items, 0..) |queue, index| {
            if (queue.group_id == group_id and std.mem.eql(u8, queue.table_name, table_name)) return index;
        }
        return null;
    }

    fn pruneWriteCoalesceQueueLocked(self: *ProvisionedTableWriteSource, index: usize) void {
        const alloc = std.heap.page_allocator;
        const queue = &self.write_coalesce_queues.items[index];
        if (queue.draining or queue.entries.items.len > 0) return;
        alloc.free(queue.table_name);
        queue.entries.deinit(alloc);
        _ = self.write_coalesce_queues.orderedRemove(index);
    }

    fn writeCoalesceQueueLocked(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
    ) !*WriteCoalesceQueue {
        if (self.findWriteCoalesceQueueLocked(table_name, group_id)) |index| return &self.write_coalesce_queues.items[index];
        const alloc = std.heap.page_allocator;
        const owned_table_name = try alloc.dupe(u8, table_name);
        errdefer alloc.free(owned_table_name);
        try self.write_coalesce_queues.append(alloc, .{
            .table_name = owned_table_name,
            .group_id = group_id,
        });
        return &self.write_coalesce_queues.items[self.write_coalesce_queues.items.len - 1];
    }

    fn visibleRootGeneration(self: *const ProvisionedTableWriteSource, group_id: u64) u64 {
        return if (self.group_visible_root_generation) |generation_source| generation_source.visibleRootGenerationForGroup(group_id) else table_reads.backend_current_root_generation;
    }

    /// Activation fence for long-running owner-side repair work. This is
    /// intentionally narrower than exposing the generation source itself.
    pub fn visibleRootGenerationForRepair(self: *const ProvisionedTableWriteSource, group_id: u64) u64 {
        if (self.local_write_owner) |owner| return owner.visibleRootGenerationForRepair(group_id);
        return self.visibleRootGeneration(group_id);
    }

    /// Leader-side admission for writes that have not yet entered Raft. Once a
    /// batch is committed it must apply on every replica, so replicated apply
    /// deliberately bypasses this gate. The resource check keeps the ordinary
    /// proposal path allocation-free and avoids touching the writer cache until
    /// the node is actually under hard replay/backlog pressure.
    pub fn preflightDenseRepairWriteAdmission(
        self: *ProvisionedTableWriteSource,
        group_id: u64,
        table_name: []const u8,
    ) !void {
        if (self.local_write_owner) |owner| return owner.preflightDenseRepairWriteAdmission(group_id, table_name);

        const write_manager = if (self.write_cache) |cache| cache.resource_manager else null;
        const startup_manager = if (self.startup_write_cache) |cache| cache.resource_manager else null;
        const write_cache_hard = if (write_manager) |manager| manager.denseRepairReplayPressureIsHard() else false;
        const startup_cache_hard = if (startup_manager) |manager|
            if (write_manager != null and manager == write_manager.?)
                write_cache_hard
            else
                manager.denseRepairReplayPressureIsHard()
        else
            false;
        if (!write_cache_hard and !startup_cache_hard) return;

        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        if (write_cache_hard) {
            if (self.write_cache.?.groupDenseRepairWriteBackpressuredLocked(group_id, table_name)) {
                return error.DenseRepairBackpressure;
            }
        }
        if (startup_cache_hard) {
            if (self.startup_write_cache.?.groupDenseRepairWriteBackpressuredLocked(group_id, table_name)) {
                return error.DenseRepairBackpressure;
            }
        }
    }

    fn droppedTableDeleteOwnerId(self: *ProvisionedTableWriteSource, runtime: *db_mod.background_runtime.BackendRuntime) !u64 {
        if (self.dropped_table_delete_owner_id == 0) {
            self.dropped_table_delete_owner_id = try runtime.allocOwnerId();
        }
        return self.dropped_table_delete_owner_id;
    }

    fn drainDroppedTableDeletes(self: *ProvisionedTableWriteSource) void {
        if (self.dropped_table_delete_owner_id == 0) return;
        if (self.backend_runtime) |runtime| {
            runtime.durable_jobs.drainOwner(self.dropped_table_delete_owner_id);
        }
    }

    fn closeDroppedTableDeletes(self: *ProvisionedTableWriteSource) void {
        if (self.dropped_table_delete_owner_id == 0) return;
        if (self.backend_runtime) |runtime| {
            runtime.durable_jobs.closeOwner(self.dropped_table_delete_owner_id);
        }
    }

    fn removeDroppedTableRepairIntent(path: []const u8) !void {
        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        std.Io.Dir.cwd().deleteFile(io, path) catch |err| switch (err) {
            error.FileNotFound => return,
            else => return err,
        };
        try fs_paths.syncDirPortable(io, std.fs.path.dirname(path) orelse ".");
    }

    fn recoverDroppedTableTrash(self: *ProvisionedTableWriteSource, alloc: std.mem.Allocator) !bool {
        var retry_required = false;
        const trash_dir_path = try droppedTableTrashDirPath(alloc, self.replica_root_dir);
        defer alloc.free(trash_dir_path);
        var io_impl = std.Io.Threaded.init(alloc, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        var dir = std.Io.Dir.cwd().openDir(io, trash_dir_path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => return err,
        };
        defer dir.close(io);
        var iterator = dir.iterate();
        while (try iterator.next(io)) |entry| {
            if (entry.kind != .directory) continue;
            const path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ trash_dir_path, entry.name });
            if (self.scheduleDroppedGroupDelete(path) catch false) {
                alloc.free(path);
            } else {
                defer alloc.free(path);
                DroppedTableDeleteWork.deletePath(path) catch |delete_err| {
                    std.log.warn("dropped-table trash recovery deferred path={s} err={s}", .{ path, @errorName(delete_err) });
                    retry_required = true;
                };
            }
        }
        return retry_required;
    }

    fn recoverDroppedTableRepairIntents(self: *ProvisionedTableWriteSource, alloc: std.mem.Allocator) !bool {
        var retry_required = false;
        const repair_dir_path = try droppedTableRepairDirPath(alloc, self.replica_root_dir);
        defer alloc.free(repair_dir_path);
        var io_impl = std.Io.Threaded.init(alloc, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        var dir = std.Io.Dir.cwd().openDir(io, repair_dir_path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => return err,
        };
        defer dir.close(io);
        var iterator = dir.iterate();
        while (try iterator.next(io)) |entry| {
            if (entry.kind != .file or !std.mem.endsWith(u8, entry.name, ".bin")) continue;
            const path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ repair_dir_path, entry.name });
            defer alloc.free(path);
            var intent = loadDroppedTableRepairIntent(alloc, io, path) catch |err| {
                std.log.err("invalid dropped-table repair intent retained path={s} err={s}", .{ path, @errorName(err) });
                continue;
            };
            defer intent.deinit(alloc);
            self.executeDroppedTableCleanup(alloc, intent.table_name, .{
                .table_id = intent.table_id,
                .expected_transition_generation = intent.expected_transition_generation,
                .group_ids = intent.group_ids,
            }, true) catch |err| {
                std.log.warn("dropped-table repair deferred table={s} path={s} err={s}", .{ intent.table_name, path, @errorName(err) });
                retry_required = true;
                continue;
            };
            removeDroppedTableRepairIntent(path) catch |err| {
                std.log.warn("completed dropped-table repair intent retained path={s} err={s}", .{ path, @errorName(err) });
                retry_required = true;
            };
        }
        return retry_required;
    }

    fn executeReplicaRetirementCleanup(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
    ) !void {
        try self.beginReplicaRetirementActivity(group_id);
        defer self.endReplicaRetirementActivity(group_id);

        var read_cache_exclusive = try self.beginReadCacheGroupExclusive(group_id);
        defer if (read_cache_exclusive) |*exclusive| exclusive.deinit();

        lockAtomic(&self.local_db_mutex);
        var local_db_mutex_held = true;
        errdefer {
            if (local_db_mutex_held) self.local_db_mutex.unlock();
            self.drainWriteCachePendingClosesForGroup(group_id);
        }
        if (self.write_cache) |cache| try cache.invalidateGroup(group_id);
        if (self.startup_write_cache) |cache| {
            if (self.write_cache == null or cache != self.write_cache.?) {
                try cache.invalidateGroup(group_id);
            }
        }
        self.local_db_mutex.unlock();
        local_db_mutex_held = false;
        self.drainWriteCachePendingClosesForGroup(group_id);

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        self.invalidateSharedPathCaches(path);
        if (try moveRetiredReplicaPathToTrash(alloc, self.replica_root_dir, group_id)) |trash_path| {
            try self.deleteDroppedGroupPath(alloc, trash_path);
        }
    }

    fn recoverReplicaRetirementIntents(self: *ProvisionedTableWriteSource, alloc: std.mem.Allocator) !bool {
        var retry_required = false;
        const ownership = self.replicaRetirementOwnershipSnapshot() orelse return false;
        lockAtomic(&self.replica_retirement_intent_mutex);
        defer self.replica_retirement_intent_mutex.unlock();
        const dir_path = try replicaRetirementDirPath(alloc, self.replica_root_dir);
        defer alloc.free(dir_path);
        var io_impl = std.Io.Threaded.init(alloc, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        var dir = std.Io.Dir.cwd().openDir(io, dir_path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => return err,
        };
        defer dir.close(io);
        var iterator = dir.iterate();
        while (try iterator.next(io)) |entry| {
            if (entry.kind != .file or !std.mem.endsWith(u8, entry.name, ".bin")) continue;
            const path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ dir_path, entry.name });
            defer alloc.free(path);
            const intent = loadReplicaRetirementIntent(alloc, io, path) catch |err| {
                std.log.err("invalid replica-retirement intent retained path={s} err={s}", .{ path, @errorName(err) });
                continue;
            };
            const group_id = intent.group_id;
            if (self.active_replica_retirement_intents.contains(group_id)) continue;
            const state = ownership.state(group_id) catch |err| {
                std.log.warn("replica-retirement ownership classification deferred group_id={d} path={s} err={s}", .{ group_id, path, @errorName(err) });
                retry_required = true;
                continue;
            };
            // A retained catalog record proves that the removal CAS never
            // committed. Retire only the orphaned journal, never the replica.
            if (state == .retained) {
                removeDroppedTableRepairIntent(path) catch |err| {
                    std.log.warn("aborted replica-retirement intent retained group_id={d} path={s} err={s}", .{ group_id, path, @errorName(err) });
                    retry_required = true;
                };
                continue;
            }
            // Promotion repairs the crash window between the atomic catalog
            // commit and journal phase update. V1 records are upgraded here.
            if (intent.phase != .committed or intent.legacy) {
                writeReplicaRetirementIntent(alloc, io, dir_path, path, group_id, .committed, true) catch |err| {
                    std.log.warn("replica-retirement commit marker deferred group_id={d} path={s} err={s}", .{ group_id, path, @errorName(err) });
                    retry_required = true;
                    continue;
                };
            }
            if (state == .retiring) {
                retry_required = true;
                continue;
            }
            self.executeReplicaRetirementCleanup(alloc, group_id) catch |err| {
                std.log.warn("replica retirement deferred group_id={d} path={s} err={s}", .{ group_id, path, @errorName(err) });
                retry_required = true;
                continue;
            };
            removeDroppedTableRepairIntent(path) catch |err| {
                std.log.warn("completed replica-retirement intent retained group_id={d} path={s} err={s}", .{ group_id, path, @errorName(err) });
                retry_required = true;
            };
        }
        return retry_required;
    }

    pub fn prepareReplicaRetirements(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_ids: []const u64,
    ) !PreparedReplicaRetirements {
        lockAtomic(&self.replica_retirement_intent_mutex);
        defer self.replica_retirement_intent_mutex.unlock();
        try self.active_replica_retirement_intents.ensureUnusedCapacity(
            std.heap.page_allocator,
            std.math.cast(u32, group_ids.len) orelse return error.ReplicaRetirementBatchTooLarge,
        );
        const intents = try alloc.alloc(PersistedReplicaRetirementIntent, group_ids.len);
        var initialized: usize = 0;
        errdefer {
            for (intents[0..initialized]) |intent| {
                const active = self.active_replica_retirement_intents.getPtr(intent.group_id) orelse unreachable;
                std.debug.assert(active.* > 0);
                active.* -= 1;
                if (active.* == 0) {
                    _ = self.active_replica_retirement_intents.remove(intent.group_id);
                    if (intent.created) removeDroppedTableRepairIntent(intent.path) catch {};
                }
                alloc.free(intent.path);
            }
            alloc.free(intents);
        }
        const dir_path = try replicaRetirementDirPath(alloc, self.replica_root_dir);
        defer alloc.free(dir_path);
        var io_impl = std.Io.Threaded.init(alloc, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        try fs_paths.createDirPathPortable(io, dir_path);
        var directory_dirty = false;
        for (group_ids, intents) |group_id, *intent| {
            intent.* = try persistReplicaRetirementIntentWithIo(
                alloc,
                io,
                dir_path,
                self.replica_root_dir,
                group_id,
                false,
            );
            directory_dirty = directory_dirty or intent.created;
            const active = self.active_replica_retirement_intents.getOrPutAssumeCapacity(group_id);
            if (!active.found_existing) active.value_ptr.* = 0;
            active.value_ptr.* += 1;
            initialized += 1;
        }
        // Every file was synced before rename. One directory barrier makes the
        // complete removal batch durable without paying one fsync per entry.
        if (directory_dirty) try fs_paths.syncDirPortable(io, dir_path);
        return .{ .alloc = alloc, .intents = intents };
    }

    pub fn cancelPreparedReplicaRetirements(
        self: *ProvisionedTableWriteSource,
        prepared: *const PreparedReplicaRetirements,
    ) void {
        var recovery_required = false;
        lockAtomic(&self.replica_retirement_intent_mutex);
        for (prepared.intents) |intent| {
            const active = self.active_replica_retirement_intents.getPtr(intent.group_id) orelse continue;
            std.debug.assert(active.* > 0);
            active.* -= 1;
            if (active.* != 0) continue;
            _ = self.active_replica_retirement_intents.remove(intent.group_id);
            // A pre-existing record may belong to an earlier committed
            // retirement. This failed preparation did not create it and must
            // not cancel its recovery ownership.
            if (!intent.created) {
                recovery_required = true;
                continue;
            }
            removeDroppedTableRepairIntent(intent.path) catch |err| {
                std.log.warn("uncommitted replica-retirement intent retained path={s} err={s}", .{ intent.path, @errorName(err) });
                recovery_required = true;
            };
        }
        self.replica_retirement_intent_mutex.unlock();
        if (recovery_required and self.backend_runtime != null) self.scheduleDroppedTableRecovery();
    }

    pub fn completePreparedReplicaRetirements(
        self: *ProvisionedTableWriteSource,
        group_ids: []const u64,
        prepared: *const PreparedReplicaRetirements,
    ) !void {
        if (group_ids.len != prepared.intents.len) return error.InvalidReplicaRetirementBatch;
        var first_error: ?anyerror = null;

        // Publish the committed phase before releasing the in-process fence.
        // If a phase write fails, catalog classification still repairs it on
        // the next scan without ever guessing whether the CAS committed.
        lockAtomic(&self.replica_retirement_intent_mutex);
        const dir_path = replicaRetirementDirPath(prepared.alloc, self.replica_root_dir) catch |err| blk: {
            first_error = err;
            break :blk null;
        };
        defer if (dir_path) |path| prepared.alloc.free(path);
        var io_impl = std.Io.Threaded.init(prepared.alloc, .{});
        defer io_impl.deinit();
        var directory_dirty = false;
        for (group_ids, prepared.intents) |group_id, intent| {
            if (dir_path) |path| {
                const wrote = wrote: {
                    writeReplicaRetirementIntent(
                        prepared.alloc,
                        io_impl.io(),
                        path,
                        intent.path,
                        group_id,
                        .committed,
                        false,
                    ) catch |err| {
                        first_error = first_error orelse err;
                        break :wrote false;
                    };
                    break :wrote true;
                };
                directory_dirty = directory_dirty or wrote;
            }
            if (self.active_replica_retirement_intents.getPtr(group_id)) |active| {
                std.debug.assert(active.* > 0);
                active.* -= 1;
                if (active.* == 0) _ = self.active_replica_retirement_intents.remove(group_id);
            }
        }
        if (directory_dirty) {
            if (dir_path) |path| fs_paths.syncDirPortable(io_impl.io(), path) catch |err| {
                first_error = first_error orelse err;
            };
        }
        self.replica_retirement_intent_mutex.unlock();

        const ownership = self.replicaRetirementOwnershipSnapshot() orelse {
            if (self.backend_runtime != null) self.scheduleDroppedTableRecovery();
            return first_error orelse error.ReplicaRetirementOwnershipUnavailable;
        };
        for (group_ids, prepared.intents) |group_id, intent| {
            const state = ownership.state(group_id) catch |err| {
                first_error = first_error orelse err;
                continue;
            };
            if (state == .retained) {
                // The caller promises this method only after a durable catalog
                // commit. Treat a retained record as an inconclusive proof.
                first_error = first_error orelse error.ReplicaRetirementOwnershipInconclusive;
                continue;
            }
            if (state == .retiring) {
                first_error = first_error orelse error.ReplicaRetirementOwnershipInconclusive;
                continue;
            }
            self.executeReplicaRetirementCleanup(prepared.alloc, group_id) catch |err| {
                first_error = first_error orelse err;
                continue;
            };
            removeDroppedTableRepairIntent(intent.path) catch |err| {
                first_error = first_error orelse err;
            };
        }
        if (first_error) |err| {
            if (self.backend_runtime != null) self.scheduleDroppedTableRecovery();
            return err;
        }
    }

    pub fn requestReplicaRetirementRecovery(self: *ProvisionedTableWriteSource) void {
        self.scheduleDroppedTableRecovery();
    }

    /// Start the one-time recovery scan only after this source has reached a
    /// stable owner address. `source()` is also used to publish short-lived
    /// adapters (for example by metadata CDC workers), so it must remain a
    /// side-effect-free ABI conversion and must never enqueue work that
    /// captures the adapter's backing pointer.
    pub fn startDroppedTableRecovery(self: *ProvisionedTableWriteSource) void {
        if (self.local_write_owner) |owner| return owner.startDroppedTableRecovery();
        if (!self.dropped_table_recovery_started.swap(true, .acq_rel)) {
            self.scheduleDroppedTableRecovery();
        }
    }

    fn runDroppedTableRecovery(self: *ProvisionedTableWriteSource) bool {
        const alloc = std.heap.page_allocator;
        var retry_required = self.recoverDroppedTableRepairIntents(alloc) catch |err| blk: {
            std.log.warn("dropped-table intent recovery scan deferred root={s} err={s}", .{ self.replica_root_dir, @errorName(err) });
            break :blk true;
        };
        retry_required = (self.recoverDroppedTableTrash(alloc) catch |err| blk: {
            std.log.warn("dropped-table trash recovery scan deferred root={s} err={s}", .{ self.replica_root_dir, @errorName(err) });
            break :blk true;
        }) or retry_required;
        retry_required = (self.recoverReplicaRetirementIntents(alloc) catch |err| blk: {
            std.log.warn("replica-retirement recovery scan deferred root={s} err={s}", .{ self.replica_root_dir, @errorName(err) });
            break :blk true;
        }) or retry_required;
        if (builtin.is_test) {
            if (test_dropped_table_recovery_pass_hook) |hook| hook.run(hook.ptr);
        }
        return retry_required;
    }

    fn drainDroppedTableRecoveryRequests(self: *ProvisionedTableWriteSource) void {
        while (true) {
            const observed_epoch = self.dropped_table_recovery_requested.load(.acquire);
            const retry_required = self.runDroppedTableRecovery();
            if (self.dropped_table_recovery_requested.load(.acquire) != observed_epoch)
                continue;

            self.dropped_table_recovery_scheduled.store(false, .release);
            if (self.dropped_table_recovery_requested.load(.acquire) == observed_epoch) {
                if (retry_required) {
                    self.scheduleDroppedTableRecoveryRetry();
                } else {
                    self.dropped_table_recovery_retry_failures.store(0, .release);
                }
                return;
            }
            // A requester can race between the equality check and ownership
            // release. It either installed a successor or left the lane for
            // this worker to reclaim; both cases have exactly one owner.
            if (self.dropped_table_recovery_scheduled.swap(true, .acq_rel))
                return;
        }
    }

    fn scheduleDroppedTableRecoveryRetry(self: *ProvisionedTableWriteSource) void {
        if (self.quiesced) return;
        if (self.dropped_table_recovery_retry_scheduled.swap(true, .acq_rel)) return;
        const runtime = self.backend_runtime orelse {
            self.dropped_table_recovery_retry_scheduled.store(false, .release);
            return;
        };
        // Manual runtimes execute durable submissions recursively on the
        // caller's stack. A persistent filesystem failure must remain as
        // durable trash for the next explicit poll/reopen instead of turning
        // the retry chain into unbounded recursion.
        if (runtime.durable_jobs.executesInline()) {
            self.dropped_table_recovery_retry_scheduled.store(false, .release);
            return;
        }
        const RetryWork = struct {
            source: *ProvisionedTableWriteSource,

            fn run(ptr: *anyopaque) !void {
                const work: *@This() = @ptrCast(@alignCast(ptr));
                const failure = work.source.dropped_table_recovery_retry_failures.fetchAdd(1, .acq_rel);
                const shift: u5 = @intCast(@min(failure, 4));
                const delay_ms: u64 = @as(u64, 100) << shift;
                var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
                defer io_impl.deinit();
                io_impl.io().sleep(.fromNanoseconds(delay_ms * std.time.ns_per_ms), .awake) catch {};
                work.source.dropped_table_recovery_retry_scheduled.store(false, .release);
                work.source.scheduleDroppedTableRecovery();
            }

            fn deinit(ptr: *anyopaque) void {
                const work: *@This() = @ptrCast(@alignCast(ptr));
                std.heap.page_allocator.destroy(work);
            }
        };
        const work = std.heap.page_allocator.create(RetryWork) catch {
            self.dropped_table_recovery_retry_scheduled.store(false, .release);
            return;
        };
        work.* = .{ .source = self };
        runtime.durable_jobs.submit(.{
            .owner_id = self.droppedTableDeleteOwnerId(runtime) catch {
                std.heap.page_allocator.destroy(work);
                self.dropped_table_recovery_retry_scheduled.store(false, .release);
                return;
            },
            .class = .cleanup,
            .ptr = work,
            .run = RetryWork.run,
            .deinit = RetryWork.deinit,
        }) catch {
            std.heap.page_allocator.destroy(work);
            self.dropped_table_recovery_retry_scheduled.store(false, .release);
        };
    }

    fn scheduleDroppedTableRecovery(self: *ProvisionedTableWriteSource) void {
        if (self.quiesced) return;
        _ = self.dropped_table_recovery_requested.fetchAdd(1, .release);
        if (self.dropped_table_recovery_scheduled.swap(true, .acq_rel)) return;
        const runtime = self.backend_runtime orelse {
            self.drainDroppedTableRecoveryRequests();
            return;
        };
        const Work = struct {
            source: *ProvisionedTableWriteSource,

            fn run(ptr: *anyopaque) !void {
                const work: *@This() = @ptrCast(@alignCast(ptr));
                work.source.drainDroppedTableRecoveryRequests();
            }

            fn deinit(ptr: *anyopaque) void {
                const work: *@This() = @ptrCast(@alignCast(ptr));
                std.heap.page_allocator.destroy(work);
            }
        };
        const work = std.heap.page_allocator.create(Work) catch {
            self.dropped_table_recovery_scheduled.store(false, .release);
            return;
        };
        work.* = .{ .source = self };
        runtime.durable_jobs.submit(.{
            .owner_id = self.droppedTableDeleteOwnerId(runtime) catch {
                std.heap.page_allocator.destroy(work);
                self.dropped_table_recovery_scheduled.store(false, .release);
                return;
            },
            .class = .cleanup,
            .ptr = work,
            .run = Work.run,
            .deinit = Work.deinit,
        }) catch {
            std.heap.page_allocator.destroy(work);
            self.dropped_table_recovery_scheduled.store(false, .release);
        };
    }

    fn scheduleDroppedGroupDelete(self: *ProvisionedTableWriteSource, path: []const u8) !bool {
        const runtime = self.backend_runtime orelse return false;
        const work = try std.heap.page_allocator.create(DroppedTableDeleteWork);
        errdefer std.heap.page_allocator.destroy(work);
        const owned_path = try std.heap.page_allocator.dupe(u8, path);
        errdefer std.heap.page_allocator.free(owned_path);
        work.* = .{ .path = owned_path, .recovery_source = self };
        try runtime.durable_jobs.submit(.{
            .owner_id = try self.droppedTableDeleteOwnerId(runtime),
            .class = .cleanup,
            .ptr = work,
            .run = DroppedTableDeleteWork.run,
            .deinit = DroppedTableDeleteWork.deinit,
        });
        return true;
    }

    fn deleteDroppedGroupPath(self: *ProvisionedTableWriteSource, alloc: std.mem.Allocator, path: []u8) !void {
        defer alloc.free(path);
        if (self.scheduleDroppedGroupDelete(path) catch false) return;
        try DroppedTableDeleteWork.deletePath(path);
    }

    fn findTableActivityLocked(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: ?u64) ?usize {
        for (self.active_table_activities.items, 0..) |entry, i| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.group_id != group_id) continue;
            return i;
        }
        return null;
    }

    fn replicaRetirementConflictsLocked(self: *ProvisionedTableWriteSource, group_id: u64) bool {
        for (self.active_table_activities.items) |entry| {
            if (entry.group_id == null) {
                if (entry.structural_active or
                    entry.structural_waiters > 0 or
                    entry.structural_reconcile_active or
                    entry.restore_preparations > 0)
                {
                    return true;
                }
                continue;
            }
            if (entry.group_id.? != group_id) continue;
            if (entry.operation_active or entry.generation_preparation_active) return true;
        }
        return false;
    }

    fn beginReplicaRetirementActivity(self: *ProvisionedTableWriteSource, group_id: u64) !void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        while (self.retiring_replica_groups.contains(group_id)) {
            self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
        }
        try self.retiring_replica_groups.put(std.heap.page_allocator, group_id, {});
        while (self.replicaRetirementConflictsLocked(group_id)) {
            self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
        }
    }

    fn endReplicaRetirementActivity(self: *ProvisionedTableWriteSource, group_id: u64) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        _ = self.retiring_replica_groups.remove(group_id);
        self.table_activity_ready.broadcast(io);
    }

    fn activityEntryLocked(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: ?u64) *TableActivity {
        if (self.findTableActivityLocked(table_name, group_id)) |index| return &self.active_table_activities.items[index];
        const index = self.active_table_activities.items.len;
        const owned_table_name = std.heap.page_allocator.dupe(u8, table_name) catch {
            @panic("failed to allocate table activity name");
        };
        self.active_table_activities.append(std.heap.page_allocator, .{ .table_name = owned_table_name, .group_id = group_id }) catch {
            std.heap.page_allocator.free(owned_table_name);
            @panic("failed to allocate table activity entry");
        };
        return &self.active_table_activities.items[index];
    }

    fn pruneTableActivityLocked(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: ?u64) void {
        const index = self.findTableActivityLocked(table_name, group_id) orelse return;
        const entry = self.active_table_activities.items[index];
        if (entry.table_request_active > 0 or entry.read_request_active > 0 or entry.status_request_active > 0 or entry.structural_waiters > 0 or entry.operation_active or entry.operation_waiters > 0 or entry.transition_waiters > 0 or entry.structural_active or entry.structural_reconcile_active or entry.structural_reconcile_queued > 0 or entry.structural_reconcile_waiters > 0 or entry.structural_reconcile_status_pending > 0 or entry.repair_handoff_status_pending > 0 or entry.publication_handoffs.items.len > 0 or entry.restore_preparations > 0 or entry.generation_preparation_active) return;
        var removed = self.active_table_activities.swapRemove(index);
        removed.deinit();
        if (self.active_table_activities.items.len == 0) {
            self.active_table_activities.deinit(std.heap.page_allocator);
            self.active_table_activities = .empty;
        }
    }

    fn hasAnyActiveGroupOperationLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        for (self.active_table_activities.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.group_id == null) continue;
            if (entry.operation_active or entry.operation_waiters > 0) return true;
        }
        return false;
    }

    fn hasAnyExecutingGroupOperationLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        for (self.active_table_activities.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.group_id != null and entry.operation_active) return true;
        }
        return false;
    }

    fn structuralDrainPendingLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        return self.hasAnyExecutingGroupOperationLocked(table_name);
    }

    fn hasAnyReadBlockingGroupOperationLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        for (self.active_table_activities.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.group_id == null) continue;
            if (entry.operation_waiters > 0 or entry.transition_waiters > 0 or (entry.operation_active and !entry.operation_allows_reads)) return true;
        }
        return false;
    }

    fn hasAnyGenerationPreparationLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        for (self.active_table_activities.items) |entry| {
            if (entry.group_id != null and entry.generation_preparation_active and std.mem.eql(u8, entry.table_name, table_name)) return true;
        }
        return false;
    }

    fn waitForNoStructuralActivityLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        while (true) {
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.structural_reconcile_queued > 0 or entry.structural_reconcile_waiters > 0 or entry.restore_preparations > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            return;
        }
    }

    fn beginTableRequestLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        while (true) {
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.structural_reconcile_queued > 0 or entry.structural_reconcile_waiters > 0 or entry.restore_preparations > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            const entry = self.activityEntryLocked(table_name, null);
            entry.table_request_active += 1;
            return;
        }
    }

    fn tryBeginTableRequestLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        if (self.findTableActivityLocked(table_name, null)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.structural_reconcile_queued > 0 or entry.structural_reconcile_waiters > 0 or entry.restore_preparations > 0) return false;
        }
        const entry = self.activityEntryLocked(table_name, null);
        entry.table_request_active += 1;
        return true;
    }

    fn endTableRequestLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        const index = self.findTableActivityLocked(table_name, null) orelse {
            self.table_activity_ready.broadcast(io);
            return;
        };
        if (self.active_table_activities.items[index].table_request_active == 0) {
            self.table_activity_ready.broadcast(io);
            return;
        }
        self.active_table_activities.items[index].table_request_active -= 1;
        self.pruneTableActivityLocked(table_name, null);
        self.table_activity_ready.broadcast(io);
    }

    fn beginStructuralReconcileActivity(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        self.activityEntryLocked(table_name, null).structural_reconcile_waiters += 1;
        while (true) {
            if (self.hasAnyGenerationPreparationLocked(table_name)) {
                self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                continue;
            }
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.restore_preparations > 0 or entry.table_request_active > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            const entry = self.activityEntryLocked(table_name, null);
            std.debug.assert(entry.structural_reconcile_waiters > 0);
            entry.structural_reconcile_waiters -= 1;
            entry.structural_reconcile_active = true;
            return;
        }
    }

    fn reserveStructuralReconcileActivity(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        self.activityEntryLocked(table_name, null).structural_reconcile_queued += 1;
    }

    fn reserveStructuralReconcileStatus(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        self.activityEntryLocked(table_name, null).structural_reconcile_status_pending += 1;
    }

    fn releaseStructuralReconcileStatus(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, null) orelse return;
        const entry = &self.active_table_activities.items[index];
        std.debug.assert(entry.structural_reconcile_status_pending > 0);
        entry.structural_reconcile_status_pending -= 1;
        self.pruneTableActivityLocked(table_name, null);
        self.table_activity_ready.broadcast(io);
    }

    fn ensureStructuralRepairHandoffStatus(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
    ) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const table_index = self.findTableActivityLocked(table_name, null) orelse return;
        std.debug.assert(self.active_table_activities.items[table_index].structural_reconcile_status_pending > 0);
        const group_entry = self.activityEntryLocked(table_name, group_id);
        // Repair debt is group-wide. One post-clear publication settles every
        // structural request that observed the same outstanding generation,
        // so coalescing here is both sufficient and allocation-free.
        if (group_entry.repair_handoff_status_pending == 0) {
            group_entry.repair_handoff_status_pending = 1;
            group_entry.repair_handoff_clear_observed = false;
            group_entry.repair_handoff_generation = self.nextRepairHandoffGenerationLocked();
        }
    }

    fn ensureStructuralPublicationHandoffStatus(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        target: PublicationHandoffTarget,
    ) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const table_index = self.findTableActivityLocked(table_name, null) orelse return;
        std.debug.assert(self.active_table_activities.items[table_index].structural_reconcile_status_pending > 0);
        const entry = self.activityEntryLocked(table_name, group_id);
        for (entry.publication_handoffs.items) |*handoff| {
            if (!std.mem.eql(u8, handoff.index_name, target.index_name)) continue;
            if (handoff.coverage_generation == target.coverage_generation and
                handoff.coverage_config_hash == target.coverage_config_hash)
            {
                handoff.producer_target_sequence = @max(handoff.producer_target_sequence, target.producer_target_sequence);
                handoff.requires_blocking = handoff.requires_blocking or target.requires_blocking;
                return;
            }
            // A later incarnation for the same public name supersedes the old
            // create. Its own handoff protects the only status users can now
            // observe, so retaining the obsolete target would strand polling.
            handoff.deinit();
            handoff.* = .{
                .index_name = std.heap.page_allocator.dupe(u8, target.index_name) catch @panic("failed to allocate publication handoff index name"),
                .coverage_generation = target.coverage_generation,
                .coverage_config_hash = target.coverage_config_hash,
                .producer_target_sequence = target.producer_target_sequence,
                .requires_blocking = target.requires_blocking,
            };
            return;
        }
        const owned_name = std.heap.page_allocator.dupe(u8, target.index_name) catch @panic("failed to allocate publication handoff index name");
        entry.publication_handoffs.append(std.heap.page_allocator, .{
            .index_name = owned_name,
            .coverage_generation = target.coverage_generation,
            .coverage_config_hash = target.coverage_config_hash,
            .producer_target_sequence = target.producer_target_sequence,
            .requires_blocking = target.requires_blocking,
        }) catch {
            std.heap.page_allocator.free(owned_name);
            @panic("failed to allocate publication handoff");
        };
    }

    fn retireDroppedTablePublicationAuthority(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);

        // The successful drop owns the table-wide structural fence, so no new
        // reconcile can install publication authority while this allocation-free
        // cleanup retires every old group incarnation. Those deleted DBs can no
        // longer publish the edge that would otherwise release status polling.
        const table_index = self.findTableActivityLocked(table_name, null) orelse unreachable;
        std.debug.assert(self.active_table_activities.items[table_index].structural_active);
        var index: usize = 0;
        while (index < self.active_table_activities.items.len) {
            const entry = &self.active_table_activities.items[index];
            if (!std.mem.eql(u8, entry.table_name, table_name) or
                (entry.repair_handoff_status_pending == 0 and entry.publication_handoffs.items.len == 0))
            {
                index += 1;
                continue;
            }

            const group_id = entry.group_id;
            entry.repair_handoff_status_pending = 0;
            entry.repair_handoff_clear_observed = false;
            entry.repair_handoff_generation = 0;
            for (entry.publication_handoffs.items) |*handoff| handoff.deinit();
            entry.publication_handoffs.deinit(std.heap.page_allocator);
            entry.publication_handoffs = .empty;

            const previous_len = self.active_table_activities.items.len;
            self.pruneTableActivityLocked(table_name, group_id);
            // swapRemove puts an unvisited entry at this index. Revisit it when
            // pruning succeeded; otherwise advance past the still-active entry.
            if (self.active_table_activities.items.len == previous_len) index += 1;
        }
    }

    fn settlePublicationHandoffStatusBestEffort(
        self: *ProvisionedTableWriteSource,
        snapshot_cache: *runtime_status.TableRuntimeSnapshotCache,
        table_name: []const u8,
        group_id: u64,
        blocking: bool,
    ) bool {
        // This runs after ordinary status publications too. Preserve the hot
        // path's allocation profile by cloning a cached status only when an
        // actual create handoff is waiting for that observation.
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        const pending = if (self.findTableActivityLocked(table_name, group_id)) |index|
            self.active_table_activities.items[index].publication_handoffs.items.len != 0
        else
            false;
        self.table_activity_mutex.unlock(io);
        if (!pending) return false;

        var status = (snapshot_cache.snapshotGroupStatus(snapshot_cache.alloc, table_name, group_id) catch return false) orelse return false;
        defer status.deinit(snapshot_cache.alloc);

        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, group_id) orelse return false;
        const entry = &self.active_table_activities.items[index];
        var settled = false;
        var handoff_index: usize = 0;
        while (handoff_index < entry.publication_handoffs.items.len) {
            const handoff = entry.publication_handoffs.items[handoff_index];
            const current = for (status.stats.indexes) |item| {
                if (std.mem.eql(u8, item.name, handoff.index_name)) break item;
            } else null;
            const complete = if (current) |item| blk: {
                // Absence or replacement settles the obsolete target on any
                // authoritative publication: its old dense worker may already
                // be gone and therefore cannot emit another blocking edge.
                if (item.coverage_generation != handoff.coverage_generation or
                    item.coverage_config_hash != handoff.coverage_config_hash)
                {
                    break :blk true;
                }
                // Only the same dense incarnation needs the stronger
                // post-watermark publication boundary.
                if (handoff.requires_blocking and !blocking) break :blk false;
                break :blk status.stats.enrichment.applied_sequence >= handoff.producer_target_sequence and
                    item.replay_applied_sequence >= item.replay_target_sequence and
                    !item.replay_catch_up_required and
                    !item.catch_up_active and
                    !item.backfill_active;
            } else true;
            if (!complete) {
                handoff_index += 1;
                continue;
            }
            var removed = entry.publication_handoffs.swapRemove(handoff_index);
            removed.deinit();
            settled = true;
        }
        if (!settled) return false;
        self.pruneTableActivityLocked(table_name, group_id);
        self.table_activity_ready.broadcast(io);
        return true;
    }

    const RepairHandoffPublicationToken = struct {
        generation: u64,
    };

    fn nextRepairHandoffGenerationLocked(self: *ProvisionedTableWriteSource) u64 {
        const generation = self.next_repair_handoff_generation;
        self.next_repair_handoff_generation +%= 1;
        if (self.next_repair_handoff_generation == 0) self.next_repair_handoff_generation = 1;
        return generation;
    }

    fn captureRepairHandoffPublicationTokenBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        require_clear: bool,
    ) ?RepairHandoffPublicationToken {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, group_id) orelse return null;
        const entry = self.active_table_activities.items[index];
        if (entry.repair_handoff_status_pending == 0) return null;
        if (require_clear and !entry.repair_handoff_clear_observed) return null;
        std.debug.assert(entry.repair_handoff_generation != 0);
        return .{ .generation = entry.repair_handoff_generation };
    }

    fn settleRepairHandoffStatusIfUnchangedBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        token: RepairHandoffPublicationToken,
    ) bool {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, group_id) orelse return false;
        const entry = &self.active_table_activities.items[index];
        if (entry.repair_handoff_status_pending == 0 or
            !entry.repair_handoff_clear_observed or
            entry.repair_handoff_generation != token.generation)
        {
            return false;
        }
        // One group-wide consistent publication covers all coalesced
        // structural handoffs that preceded the observed durable clear.
        entry.repair_handoff_status_pending = 0;
        entry.repair_handoff_clear_observed = false;
        entry.repair_handoff_generation = 0;
        self.pruneTableActivityLocked(table_name, group_id);
        self.table_activity_ready.broadcast(io);
        return true;
    }

    fn settleTerminalRepairHandoffStatusIfUnchangedBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        token: RepairHandoffPublicationToken,
    ) bool {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, group_id) orelse return false;
        const entry = &self.active_table_activities.items[index];
        if (entry.repair_handoff_status_pending == 0 or
            entry.repair_handoff_generation != token.generation)
        {
            return false;
        }
        // A terminal intent deliberately remains durable, so no aggregate
        // repair-clear edge is guaranteed to follow it. Its authoritative
        // terminal snapshot is the fail-closed completion proof for exactly
        // the status handoff generation captured before observation. A later
        // clear or pending callback advances the generation and remains owned
        // by its newer scheduler wake.
        entry.repair_handoff_status_pending = 0;
        entry.repair_handoff_clear_observed = false;
        entry.repair_handoff_generation = 0;
        self.pruneTableActivityLocked(table_name, group_id);
        self.table_activity_ready.broadcast(io);
        return true;
    }

    fn retainRepairRouteForPendingHandoffBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        result: *StartupCatchUpResult,
    ) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, group_id) orelse return;
        const entry = self.active_table_activities.items[index];
        if (entry.repair_handoff_status_pending == 0 or !entry.repair_handoff_clear_observed) return;
        // Pending callbacks invalidate an owner audit, but clear callbacks are
        // deliberately not settlement evidence: DB hooks can overlap and
        // therefore arrive out of durable commit order. Only publication debt
        // created by the aggregate owner's post-operation audit may borrow the
        // repair route. This includes paused durable repair: the next pass
        // performs no repair work, but remains the only exact owner that can
        // retry a fenced authoritative status publication.
        result.index_repair_pending = true;
    }

    fn finishRepairHandoffPublicationAttemptBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        result: *StartupCatchUpResult,
    ) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, group_id) orelse return;
        const entry = &self.active_table_activities.items[index];
        if (entry.repair_handoff_status_pending == 0) return;

        // The caller still owns group mutation admission here. If publication
        // did not settle the handoff, retain its exact scheduler route but do
        // not let a generic publisher borrow this audit after that ownership
        // is released. The next pass must reacquire the group operation and
        // repeat the durable audit before becoming publishable.
        result.index_repair_pending = true;
        if (!entry.repair_handoff_clear_observed) return;
        entry.repair_handoff_clear_observed = false;
        entry.repair_handoff_generation = self.nextRepairHandoffGenerationLocked();
    }

    fn markRepairHandoffOwnerAuditCompleteBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
    ) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, group_id) orelse return;
        const entry = &self.active_table_activities.items[index];
        if (entry.repair_handoff_status_pending == 0) return;
        // This transition is reserved for the aggregate scheduler owner after
        // its durable repair-state read under the group operation lease. A DB
        // clear callback may only enqueue that audit: callback invocations copy
        // their hook under a mutex and can complete in the opposite order from
        // their durable mutations.
        entry.repair_handoff_clear_observed = true;
        entry.repair_handoff_generation = self.nextRepairHandoffGenerationLocked();
    }

    fn invalidateRepairHandoffOwnerAuditBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
    ) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, group_id) orelse return;
        const entry = &self.active_table_activities.items[index];
        if (entry.repair_handoff_status_pending == 0 or !entry.repair_handoff_clear_observed) return;
        // Every admitted aggregate pass must earn publication authority from
        // a fresh durable audit. In particular, a prior fenced publication
        // may have left a clear-eligible handoff behind while this pass drops
        // its operation lease for a corpus-sized repair scan.
        entry.repair_handoff_clear_observed = false;
        entry.repair_handoff_generation = self.nextRepairHandoffGenerationLocked();
    }

    fn markRepairHandoffPendingBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
    ) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        if (self.findTableActivityLocked(table_name, group_id)) |index| {
            const entry = &self.active_table_activities.items[index];
            if (entry.repair_handoff_status_pending > 0) {
                entry.repair_handoff_clear_observed = false;
                entry.repair_handoff_generation = self.nextRepairHandoffGenerationLocked();
                return;
            }
        }
        // An unrelated shard can discover repair debt while another index's
        // structural request owns the table status fence. Give that exact edge
        // its own shard authority before it becomes scheduler-visible; the
        // table reservation will release independently at request handoff.
        const table_index = self.findTableActivityLocked(table_name, null) orelse return;
        if (self.active_table_activities.items[table_index].structural_reconcile_status_pending == 0) return;
        const entry = self.activityEntryLocked(table_name, group_id);
        entry.repair_handoff_status_pending = 1;
        entry.repair_handoff_clear_observed = false;
        entry.repair_handoff_generation = self.nextRepairHandoffGenerationLocked();
    }

    fn cancelStructuralReconcileReservation(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, null) orelse return;
        const entry = &self.active_table_activities.items[index];
        std.debug.assert(entry.structural_reconcile_queued > 0);
        entry.structural_reconcile_queued -= 1;
        self.pruneTableActivityLocked(table_name, null);
        self.table_activity_ready.broadcast(io);
    }

    fn beginReservedStructuralReconcileActivity(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        while (true) {
            const index = self.findTableActivityLocked(table_name, null) orelse unreachable;
            const entry = self.active_table_activities.items[index];
            std.debug.assert(entry.structural_reconcile_queued > 0);
            if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.restore_preparations > 0 or entry.table_request_active > 0 or self.hasAnyGenerationPreparationLocked(table_name)) {
                self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                continue;
            }
            const mutable_entry = &self.active_table_activities.items[index];
            mutable_entry.structural_reconcile_queued -= 1;
            mutable_entry.structural_reconcile_active = true;
            return;
        }
    }

    fn endStructuralReconcileActivity(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, null) orelse unreachable;
        std.debug.assert(self.active_table_activities.items[index].structural_reconcile_active);
        self.active_table_activities.items[index].structural_reconcile_active = false;
        self.pruneTableActivityLocked(table_name, null);
        self.table_activity_ready.broadcast(io);
    }

    fn beginReadRequestLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        while (true) {
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.structural_active or entry.structural_waiters > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            if (self.hasAnyReadBlockingGroupOperationLocked(table_name)) {
                self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                continue;
            }
            const entry = self.activityEntryLocked(table_name, null);
            entry.read_request_active += 1;
            return;
        }
    }

    fn endStatusRequestLocked(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        admission: StatusRequestAdmission,
    ) void {
        if (admission == .snapshot_only) return;
        const io = self.table_activity_threaded.io();
        const index = self.findTableActivityLocked(table_name, null) orelse {
            self.table_activity_ready.broadcast(io);
            return;
        };
        if (self.active_table_activities.items[index].status_request_active == 0) {
            self.table_activity_ready.broadcast(io);
            return;
        }
        self.active_table_activities.items[index].status_request_active -= 1;
        self.pruneTableActivityLocked(table_name, null);
        self.table_activity_ready.broadcast(io);
    }

    fn statusUsesPublishedSnapshotLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        if (self.findTableActivityLocked(table_name, null)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.structural_active or entry.structural_waiters > 0 or entry.structuralReconcileReserved() or entry.structural_reconcile_status_pending > 0) return true;
        }
        for (self.active_table_activities.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.repair_handoff_status_pending > 0 or entry.publication_handoffs.items.len > 0) return true;
        }
        return self.hasAnyReadBlockingGroupOperationLocked(table_name);
    }

    fn beginStatusRequestLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) StatusRequestAdmission {
        const io = self.table_activity_threaded.io();
        while (true) {
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                // Status is served from an immutable published snapshot while
                // structural work is active. It is observational and must not
                // make schema metadata projection or a long index backfill an
                // availability fence. Restore preparation is different: it
                // may replace the complete root and has no stable snapshot
                // contract until the lifecycle reservation completes.
                if (entry.restore_preparations > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            if (self.statusUsesPublishedSnapshotLocked(table_name)) return .snapshot_only;
            const entry = self.activityEntryLocked(table_name, null);
            entry.status_request_active += 1;
            return .live;
        }
    }

    fn endReadRequestLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        const index = self.findTableActivityLocked(table_name, null) orelse {
            self.table_activity_ready.broadcast(io);
            return;
        };
        if (self.active_table_activities.items[index].read_request_active == 0) {
            self.table_activity_ready.broadcast(io);
            return;
        }
        self.active_table_activities.items[index].read_request_active -= 1;
        self.pruneTableActivityLocked(table_name, null);
        self.table_activity_ready.broadcast(io);
    }

    fn beginGroupOperationLocked(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) void {
        const io = self.table_activity_threaded.io();
        while (self.retiring_replica_groups.contains(group_id)) {
            self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
        }
        self.activityEntryLocked(table_name, group_id).operation_waiters += 1;
        while (true) {
            if (self.retiring_replica_groups.contains(group_id)) {
                self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                continue;
            }
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.structural_active or entry.restore_preparations > 0 or entry.read_request_active > 0 or entry.status_request_active > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            if (self.findTableActivityLocked(table_name, group_id)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.operation_active or entry.transition_waiters > 0 or entry.generation_preparation_active) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            const entry = self.activityEntryLocked(table_name, group_id);
            std.debug.assert(entry.operation_waiters > 0);
            entry.operation_waiters -= 1;
            entry.operation_active = true;
            entry.operation_allows_reads = false;
            return;
        }
    }

    fn cancelGroupOperationWaiterLocked(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) void {
        const io = self.table_activity_threaded.io();
        const index = self.findTableActivityLocked(table_name, group_id) orelse unreachable;
        std.debug.assert(self.active_table_activities.items[index].operation_waiters > 0);
        self.active_table_activities.items[index].operation_waiters -= 1;
        self.pruneTableActivityLocked(table_name, group_id);
        self.table_activity_ready.broadcast(io);
    }

    fn tryBeginGroupOperationLocked(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) bool {
        const io = self.table_activity_threaded.io();
        if (self.retiring_replica_groups.contains(group_id)) return false;
        if (self.findTableActivityLocked(table_name, null)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.structural_active or entry.restore_preparations > 0 or entry.read_request_active > 0) return false;
        }
        if (self.findTableActivityLocked(table_name, group_id)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.operation_active or entry.operation_waiters > 0 or entry.transition_waiters > 0 or entry.generation_preparation_active) return false;
        }
        self.activityEntryLocked(table_name, group_id).operation_waiters += 1;
        while (true) {
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.structural_active or entry.restore_preparations > 0 or entry.read_request_active > 0) {
                    self.cancelGroupOperationWaiterLocked(table_name, group_id);
                    return false;
                }
                if (entry.status_request_active > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            const index = self.findTableActivityLocked(table_name, group_id) orelse unreachable;
            const entry = &self.active_table_activities.items[index];
            if (entry.operation_active or entry.operation_waiters > 1 or entry.transition_waiters > 0 or entry.generation_preparation_active) {
                self.cancelGroupOperationWaiterLocked(table_name, group_id);
                return false;
            }
            std.debug.assert(entry.operation_waiters == 1);
            entry.operation_waiters = 0;
            entry.operation_active = true;
            entry.operation_allows_reads = false;
            return true;
        }
    }

    fn tryBeginReadCompatibleGroupOperationLocked(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) bool {
        if (self.retiring_replica_groups.contains(group_id)) return false;
        if (self.findTableActivityLocked(table_name, null)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.structural_active or entry.restore_preparations > 0) return false;
        }
        if (self.findTableActivityLocked(table_name, group_id)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.operation_active or entry.operation_waiters > 0 or entry.transition_waiters > 0 or entry.generation_preparation_active) return false;
        }
        const entry = self.activityEntryLocked(table_name, group_id);
        entry.operation_active = true;
        entry.operation_allows_reads = true;
        return true;
    }

    fn beginReplicatedApplyOperationLocked(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) void {
        const io = self.table_activity_threaded.io();
        while (!self.tryBeginReadCompatibleGroupOperationLocked(table_name, group_id)) {
            self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
        }
    }

    fn beginGroupTransitionOperationLocked(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) void {
        const io = self.table_activity_threaded.io();
        while (self.retiring_replica_groups.contains(group_id)) {
            self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
        }
        self.activityEntryLocked(table_name, group_id).transition_waiters += 1;
        while (true) {
            if (self.retiring_replica_groups.contains(group_id)) {
                self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                continue;
            }
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.structural_active or entry.restore_preparations > 0 or entry.read_request_active > 0 or entry.status_request_active > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            if (self.findTableActivityLocked(table_name, group_id)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.operation_active or entry.generation_preparation_active) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            const entry = self.activityEntryLocked(table_name, group_id);
            std.debug.assert(entry.transition_waiters > 0);
            entry.transition_waiters -= 1;
            entry.operation_active = true;
            entry.operation_allows_reads = false;
            return;
        }
    }

    fn endGroupOperationLocked(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) void {
        const io = self.table_activity_threaded.io();
        const index = self.findTableActivityLocked(table_name, group_id) orelse unreachable;
        std.debug.assert(self.active_table_activities.items[index].operation_active);
        self.active_table_activities.items[index].operation_active = false;
        self.active_table_activities.items[index].operation_allows_reads = false;
        self.pruneTableActivityLocked(table_name, group_id);
        self.table_activity_ready.broadcast(io);
    }

    fn beginGroupGenerationPreparation(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        while (true) {
            if (self.retiring_replica_groups.contains(group_id)) {
                self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                continue;
            }
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.structural_reconcile_queued > 0 or entry.structural_reconcile_waiters > 0 or entry.restore_preparations > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            if (self.findTableActivityLocked(table_name, group_id)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.operation_active or entry.generation_preparation_active) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            self.activityEntryLocked(table_name, group_id).generation_preparation_active = true;
            return;
        }
    }

    fn endGroupGenerationPreparation(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        const index = self.findTableActivityLocked(table_name, group_id) orelse unreachable;
        std.debug.assert(self.active_table_activities.items[index].generation_preparation_active);
        self.active_table_activities.items[index].generation_preparation_active = false;
        self.pruneTableActivityLocked(table_name, group_id);
        self.table_activity_ready.broadcast(io);
    }

    fn tryBeginStructuralTableActivityLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        const io = self.table_activity_threaded.io();
        if (self.retiring_replica_groups.count() != 0) return false;
        if (self.findTableActivityLocked(table_name, null)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.structural_reconcile_queued > 0 or entry.structural_reconcile_waiters > 0 or entry.restore_preparations > 0 or entry.table_request_active > 0 or entry.read_request_active > 0) return false;
        }
        if (self.hasAnyGenerationPreparationLocked(table_name)) return false;
        if (self.hasAnyActiveGroupOperationLocked(table_name)) return false;
        const entry = self.activityEntryLocked(table_name, null);
        entry.structural_active = true;
        while (true) {
            const index = self.findTableActivityLocked(table_name, null) orelse unreachable;
            if (self.active_table_activities.items[index].status_request_active == 0) break;
            self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
        }
        return true;
    }

    fn beginStructuralTableActivityLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        // Reserve before draining foreground activity. This closes admission
        // to new reads/writes and routes new status calls to the immutable
        // snapshot, while already-admitted table requests may finish their
        // group work without a lock cycle.
        while (true) {
            if (self.retiring_replica_groups.count() != 0) {
                self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                continue;
            }
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.structural_reconcile_queued > 0 or entry.structural_reconcile_waiters > 0 or entry.restore_preparations > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            self.activityEntryLocked(table_name, null).structural_waiters = 1;
            break;
        }
        while (true) {
            const index = self.findTableActivityLocked(table_name, null) orelse unreachable;
            const entry = self.active_table_activities.items[index];
            if (entry.table_request_active > 0 or entry.read_request_active > 0 or entry.status_request_active > 0 or self.hasAnyGenerationPreparationLocked(table_name)) {
                self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                continue;
            }
            break;
        }
        {
            const index = self.findTableActivityLocked(table_name, null) orelse unreachable;
            const entry = &self.active_table_activities.items[index];
            std.debug.assert(entry.structural_waiters == 1);
            entry.structural_waiters = 0;
            entry.structural_active = true;
        }
        // structural_active parks queued group operations. Drain only work
        // that entered before this fence; including parked waiters here would
        // create a cycle because they cannot enter until structural work ends.
        while (self.structuralDrainPendingLocked(table_name)) {
            self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
        }
    }

    fn endStructuralTableActivityLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        const index = self.findTableActivityLocked(table_name, null) orelse unreachable;
        self.active_table_activities.items[index].structural_active = false;
        self.pruneTableActivityLocked(table_name, null);
        self.table_activity_ready.broadcast(io);
    }

    fn beginRestoreLifecycleActivityLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        while (true) {
            if (self.findTableActivityLocked(table_name, null)) |index| {
                const entry = self.active_table_activities.items[index];
                if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.structural_reconcile_queued > 0 or entry.structural_reconcile_waiters > 0 or entry.restore_preparations > 0 or entry.table_request_active > 0) {
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                    continue;
                }
            }
            if (self.hasAnyGenerationPreparationLocked(table_name) or self.hasAnyActiveGroupOperationLocked(table_name)) {
                self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                continue;
            }
            const entry = self.activityEntryLocked(table_name, null);
            entry.restore_preparations += 1;
            return;
        }
    }

    fn endRestoreLifecycleActivityLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        const index = self.findTableActivityLocked(table_name, null) orelse {
            self.table_activity_ready.broadcast(io);
            return;
        };
        if (self.active_table_activities.items[index].restore_preparations > 0) {
            self.active_table_activities.items[index].restore_preparations -= 1;
        }
        self.pruneTableActivityLocked(table_name, null);
        self.table_activity_ready.broadcast(io);
    }

    fn beginRestoreLifecycleActivity(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        self.beginRestoreLifecycleActivityLocked(table_name);
    }

    fn endRestoreLifecycleActivity(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        self.endRestoreLifecycleActivityLocked(table_name);
    }

