        self.beginStructuralTableActivity(table_name);
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
    }

    fn beginLocalStructuralCachedDbMutationFromPreparation(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        self.beginStructuralTableActivityFromRestorePreparation(table_name);
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
    }

    fn finishLocalStructuralCachedDbMutation(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();
        self.endStructuralTableActivity(table_name);
    }

    fn abortLocalStructuralCachedDbMutation(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        // The catalog is the durable structural authority. A multi-group
        // mutation may have committed to an earlier DB before a later DB
        // fails, so retire every cache-visible handle first, then hand the
        // table to the bounded reconciler. This avoids expensive rollback
        // writes and guarantees convergence without waiting for a foreground
        // read to reopen each group.
        lockAtomic(&self.local_db_mutex);
        self.invalidateWriteCache(table_name);
        self.invalidateReadCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();
        self.endStructuralTableActivity(table_name);
        self.enqueueTableStructuralReconcile(table_name) catch |err| {
            std.log.err("failed to enqueue structural recovery after cached mutation failure table={s} err={s}", .{
                table_name,
                @errorName(err),
            });
        };
    }

    fn abortLocalStructuralMutationUnlocked(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        lockAtomic(&self.local_db_mutex);
        self.invalidateWriteCache(table_name);
        self.invalidateReadCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();
        self.endStructuralTableActivity(table_name);
    }

    fn abortLocalStructuralMutationUnlockedForGroups(self: *ProvisionedTableWriteSource, table_name: []const u8, group_ids: []const u64) void {
        lockAtomic(&self.local_db_mutex);
        self.invalidateWriteCache(table_name);
        self.invalidateReadCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingClosesForGroups(table_name, group_ids);
        self.endStructuralTableActivity(table_name);
    }

    fn beginLocalTableGenerationTransition(self: *ProvisionedTableWriteSource, table_name: []const u8) !LocalTableGenerationTransition {
        self.beginStructuralTableActivity(table_name);
        errdefer self.endStructuralTableActivity(table_name);

        var read_cache_exclusive = try self.beginReadCacheExclusive(table_name);
        errdefer {
            if (read_cache_exclusive) |*exclusive| exclusive.deinit();
        }

        lockAtomic(&self.local_db_mutex);
        self.invalidateWriteCache(table_name);
        self.invalidateReadCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();

        return .{
            .source = self,
            .table_name = table_name,
            .read_cache_exclusive = read_cache_exclusive,
        };
    }

    fn beginLocalTableGenerationTransitionFromPreparation(self: *ProvisionedTableWriteSource, table_name: []const u8) !LocalTableGenerationTransition {
        self.beginStructuralTableActivityFromRestorePreparation(table_name);
        errdefer self.endStructuralTableActivity(table_name);

        var read_cache_exclusive = try self.beginReadCacheExclusive(table_name);
        errdefer if (read_cache_exclusive) |*exclusive| exclusive.deinit();

        lockAtomic(&self.local_db_mutex);
        self.invalidateWriteCache(table_name);
        self.invalidateReadCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();

        return .{
            .source = self,
            .table_name = table_name,
            .read_cache_exclusive = read_cache_exclusive,
        };
    }

    fn beginStructuralTableActivityFromRestorePreparation(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        if (self.findTableActivityLocked(table_name, null)) |index| {
            const entry = &self.active_table_activities.items[index];
            if (entry.restore_preparations > 0) {
                entry.restore_preparations -= 1;
                std.debug.assert(!entry.structural_active and entry.structural_waiters == 0 and !entry.structural_reconcile_active and entry.structural_reconcile_queued == 0 and entry.structural_reconcile_waiters == 0 and entry.table_request_active == 0);
                entry.structural_active = true;
                while (true) {
                    const current_index = self.findTableActivityLocked(table_name, null) orelse unreachable;
                    const current = self.active_table_activities.items[current_index];
                    if (current.read_request_active == 0 and current.status_request_active == 0 and !self.structuralDrainPendingLocked(table_name)) break;
                    self.table_activity_ready.waitUncancelable(io, &self.table_activity_mutex);
                }
                self.table_activity_mutex.unlock(io);
            } else {
                self.table_activity_mutex.unlock(io);
                self.beginStructuralTableActivity(table_name);
            }
        } else {
            self.table_activity_mutex.unlock(io);
            self.beginStructuralTableActivity(table_name);
        }
    }

    fn finishLocalTableGenerationTransitionMutation(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        lockAtomic(&self.local_db_mutex);
        self.invalidateWriteCache(table_name);
        self.invalidateReadCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();
        self.endStructuralTableActivity(table_name);
    }

    fn abortLocalTableGenerationTransitionMutation(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.invalidateWriteCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();
        self.endStructuralTableActivity(table_name);
    }

    fn beginLocalGroupGenerationTransitionFromPreparation(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
    ) !LocalGroupGenerationTransition {
        var read_cache_exclusive = try self.beginReadCacheGroupExclusive(group_id);
        errdefer if (read_cache_exclusive) |*exclusive| exclusive.deinit();

        lockAtomic(&self.local_db_mutex);
        errdefer self.local_db_mutex.unlock();
        if (self.write_cache) |cache| try cache.invalidateGroupTable(group_id, table_name);
        if (self.startup_write_cache) |cache| try cache.invalidateGroupTable(group_id, table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingClosesForGroups(table_name, &.{group_id});
        return .{
            .source = self,
            .table_name = table_name,
            .group_id = group_id,
            .read_cache_exclusive = read_cache_exclusive,
        };
    }

    const LocalGroupGenerationTransition = struct {
        source: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        read_cache_exclusive: ?table_reads.ProvisionedTableReadCache.ExclusiveGroupAccess = null,
        preparation_open: bool = true,

        fn finishMutation(self: *@This()) void {
            std.debug.assert(self.preparation_open);
            self.source.invalidateRuntimeStatusCache(self.table_name);
            self.source.endGroupGenerationPreparation(self.table_name, self.group_id);
            self.preparation_open = false;
        }

        fn abort(self: *@This()) void {
            if (self.preparation_open) {
                self.source.endGroupGenerationPreparation(self.table_name, self.group_id);
                self.preparation_open = false;
            }
            self.releaseReadExclusive();
        }

        fn deinit(self: *@This()) void {
            if (self.preparation_open) {
                self.source.endGroupGenerationPreparation(self.table_name, self.group_id);
                self.preparation_open = false;
            }
            self.releaseReadExclusive();
        }

        fn releaseReadExclusive(self: *@This()) void {
            if (self.read_cache_exclusive) |*exclusive| {
                exclusive.deinit();
                self.read_cache_exclusive = null;
            }
        }
    };

    const LocalTableGenerationTransition = struct {
        source: *ProvisionedTableWriteSource,
        table_name: []const u8,
        read_cache_exclusive: ?table_reads.ProvisionedTableReadCache.ExclusiveTableAccess = null,
        mutation_open: bool = true,

        fn finishMutation(self: *@This()) void {
            std.debug.assert(self.mutation_open);
            self.source.finishLocalTableGenerationTransitionMutation(self.table_name);
            self.mutation_open = false;
        }

        fn beginShardStorageTransition(self: *@This(), path: []const u8) !db_mod.generation_lifecycle.ExclusiveTransition {
            if (!self.mutation_open) return error.InvalidGenerationTransition;
            return try db_mod.generation_lifecycle.beginProcessExclusiveWithRuntime(path, self.source.backend_runtime);
        }

        fn abort(self: *@This()) void {
            if (self.mutation_open) {
                self.source.abortLocalTableGenerationTransitionMutation(self.table_name);
                self.mutation_open = false;
            }
            self.releaseReadExclusive();
        }

        fn deinit(self: *@This()) void {
            if (self.mutation_open) {
                self.source.abortLocalTableGenerationTransitionMutation(self.table_name);
                self.mutation_open = false;
            }
            self.releaseReadExclusive();
        }

        fn releaseReadExclusive(self: *@This()) void {
            if (self.read_cache_exclusive) |*exclusive| {
                exclusive.deinit();
                self.read_cache_exclusive = null;
            }
        }
    };

    fn abortLocalStructuralMutation(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        self.invalidateReadCache(table_name);
        self.invalidateWriteCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();
        self.endStructuralTableActivity(table_name);
    }

    fn getOrOpenCachedDbModeAlreadyLocked(
        self: *ProvisionedTableWriteSource,
        cache: *ProvisionedTableWriteCache,
        path: []const u8,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
        mode: ManagedDbOpenMode,
    ) !ProvisionedTableWriteCache.CachedDb {
        const deadline_ns = platform_time.monotonicNs() +| replicated_apply_writer_open_timeout_ns;
        while (true) {
            const open_result: anyerror!ProvisionedTableWriteCache.CachedDb = if (consumeTestWriterOpenPersistentDescriptorFailure())
                error.PersistentDescriptorAdmissionExhausted
            else
                cache.getOrOpenLockedMode(path, self.catalog, group_id, lsm_root_generation, table_name, mode);
            const cached = open_result catch |err| switch (err) {
                error.LsmRootWriterAlreadyOpen => {
                    const cache_pending = cache.hasPendingCloseForGroupTableLocked(group_id, table_name);
                    const startup_cache = self.startup_write_cache;
                    const startup_pending = if (startup_cache) |startup|
                        startup != cache and startup.hasPendingCloseForGroupTableLocked(group_id, table_name)
                    else
                        false;
                    if (!cache_pending and !startup_pending) return err;
                    self.local_db_mutex.unlock();
                    cache.drainPendingClosesForGroupTable(group_id, table_name);
                    if (startup_cache) |startup| {
                        if (startup != cache) startup.drainPendingClosesForGroupTable(group_id, table_name);
                    }
                    if (platform_time.monotonicNs() >= deadline_ns) {
                        lockAtomic(&self.local_db_mutex);
                        return err;
                    }
                    sleepNs(replicated_apply_writer_open_retry_ns);
                    lockAtomic(&self.local_db_mutex);
                    continue;
                },
                error.PersistentDescriptorAdmissionExhausted => {
                    var evicted_cache: ?*ProvisionedTableWriteCache = null;
                    if (try cache.evictOneInactiveEntryForDescriptorPressureLocked(group_id, table_name)) {
                        evicted_cache = cache;
                    } else if (self.startup_write_cache) |startup| {
                        if (startup != cache and
                            try startup.evictOneInactiveEntryForDescriptorPressureLocked(group_id, table_name))
                        {
                            evicted_cache = startup;
                        }
                    }
                    const victim_cache = evicted_cache orelse return err;
                    self.local_db_mutex.unlock();
                    // DB.close synchronously releases persistent lock permits;
                    // retry only after the selected victim is fully closed.
                    victim_cache.drainPendingCloses();
                    lockAtomic(&self.local_db_mutex);
                    continue;
                },
                else => return err,
            };
            return cached;
        }
    }

    fn getOrOpenCachedDbForLocalMutationAlreadyLocked(
        self: *ProvisionedTableWriteSource,
        cache: *ProvisionedTableWriteCache,
        path: []const u8,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
        allow_bulk_session: bool,
    ) !ProvisionedTableWriteCache.CachedDb {
        if (self.startup_write_cache) |startup_cache| {
            if (startup_cache != cache and
                (startup_cache.hasForegroundStateForGroupTableLocked(group_id, table_name) or
                    startup_cache.hasPendingCloseForGroupTableLocked(group_id, table_name)))
            {
                startup_cache.invalidateTable(table_name);
                self.local_db_mutex.unlock();
                startup_cache.drainPendingClosesForGroupTable(group_id, table_name);
                lockAtomic(&self.local_db_mutex);
            }
        }
        if (try self.leaseLiveEntryForLocalMutationLocked(cache, group_id, table_name, allow_bulk_session)) |cached| {
            return cached;
        }
        return try self.getOrOpenCachedDbModeAlreadyLocked(cache, path, group_id, lsm_root_generation, table_name, .default_async);
    }

    fn leaseLiveEntryForLocalMutationLocked(
        self: *ProvisionedTableWriteSource,
        cache: *ProvisionedTableWriteCache,
        group_id: u64,
        table_name: []const u8,
        allow_bulk_session: bool,
    ) !?ProvisionedTableWriteCache.CachedDb {
        if (cache.leaseLiveEntryForLocalMutationLocked(group_id, table_name, allow_bulk_session)) |cached| {
            return cached;
        }
        if (allow_bulk_session) return null;

        for (cache.entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (!cache.entryHAWriteGateCurrent(entry)) continue;
            if (entry.auto_bulk_ingest_finishing) return error.LsmRootWriterAlreadyOpen;
            if (entry.auto_bulk_ingest_session_open) {
                try self.finishEntryAutoBulkIngestForForegroundVisibility(cache, entry);
                return cache.leaseEntryLocked(entry);
            }
            if (entry.bulk_ingest_session_open) return error.LsmRootWriterAlreadyOpen;
        }
        return null;
    }

    fn preemptStartupWriteCacheForLocalMutation(
        self: *ProvisionedTableWriteSource,
        group_id: u64,
        table_name: []const u8,
    ) void {
        const startup_cache = self.startup_write_cache orelse return;
        var should_drain = false;
        lockAtomic(&self.local_db_mutex);
        if (startup_cache.hasForegroundStateForGroupTableLocked(group_id, table_name) or
            startup_cache.hasPendingCloseForGroupTableLocked(group_id, table_name))
        {
            startup_cache.invalidateTable(table_name);
            should_drain = true;
        }
        self.local_db_mutex.unlock();
        if (should_drain) startup_cache.drainPendingClosesForGroupTable(group_id, table_name);
    }

    fn getOrOpenCachedDbForLocalMutation(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        cache: *ProvisionedTableWriteCache,
        path: []const u8,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
        allow_bulk_session: bool,
    ) !ProvisionedTableWriteCache.CachedDb {
        return try self.getOrOpenCachedDbForLocalMutationWithOptions(
            alloc,
            cache,
            path,
            group_id,
            lsm_root_generation,
            table_name,
            allow_bulk_session,
            .{},
        );
    }

    fn getOrOpenCachedDbForLocalMutationWithOptions(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        cache: *ProvisionedTableWriteCache,
        path: []const u8,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
        allow_bulk_session: bool,
        managed_open_options: ManagedDbOpenOptions,
    ) !ProvisionedTableWriteCache.CachedDb {
        if (cache.backend_runtime == null) cache.backend_runtime = self.backend_runtime;
        cache.antfly_provider = self.antfly_provider;
        cache.inference_api_url = self.inference_api_url;
        cache.secret_store = self.secret_store;
        cache.remote_content = self.remote_content;
        self.syncRuntimeHooksToCache(cache);

        const start_ns = platform_time.monotonicNs();
        const deadline_ns = start_ns +| replicated_apply_writer_open_timeout_ns;
        var logged_wait = false;
        while (true) {
            self.preemptStartupWriteCacheForLocalMutation(group_id, table_name);
            lockAtomic(&self.local_db_mutex);
            const maybe_cached = self.leaseLiveEntryForLocalMutationLocked(cache, group_id, table_name, allow_bulk_session) catch |err| {
                self.local_db_mutex.unlock();
                return err;
            };
            if (maybe_cached) |cached| {
                self.local_db_mutex.unlock();
                return cached;
            }
            self.local_db_mutex.unlock();
            return self.getOrOpenCachedDbModeAtGeneration(alloc, cache, path, group_id, lsm_root_generation, table_name, .default_async, null, null, null, managed_open_options) catch |err| {
                if (!isTransientWriterOpenConflict(err)) return err;
                if (!managed_open_options.retry_transient_writer_open) return err;
                const now_ns = platform_time.monotonicNs();
                if (now_ns >= deadline_ns) {
                    std.log.err("local mutation writer wait timed out table={s} group_id={} wait_ms={} err={s}", .{
                        table_name,
                        group_id,
                        @divTrunc(now_ns -| start_ns, std.time.ns_per_ms),
                        @errorName(err),
                    });
                    return err;
                }
                if (!logged_wait) {
                    logged_wait = true;
                    std.log.warn("local mutation waiting for writer table={s} group_id={} err={s}", .{
                        table_name,
                        group_id,
                        @errorName(err),
                    });
                }
                sleepNs(replicated_apply_writer_open_retry_ns);
                continue;
            };
        }
    }

    fn getOrOpenCachedDbMode(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        cache: *ProvisionedTableWriteCache,
        path: []const u8,
        group_id: u64,
        table_name: []const u8,
        mode: ManagedDbOpenMode,
        finish_expired_auto_bulk_now_ns: ?u64,
        ensure_auto_bulk_now_ns: ?u64,
    ) !ProvisionedTableWriteCache.CachedDb {
        return try self.getOrOpenCachedDbModeWithMetadata(
            alloc,
            cache,
            path,
            group_id,
            table_name,
            mode,
            finish_expired_auto_bulk_now_ns,
            ensure_auto_bulk_now_ns,
            null,
        );
    }

    fn getOrOpenCachedDbModeWithMetadata(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        cache: *ProvisionedTableWriteCache,
        path: []const u8,
        group_id: u64,
        table_name: []const u8,
        mode: ManagedDbOpenMode,
        finish_expired_auto_bulk_now_ns: ?u64,
        ensure_auto_bulk_now_ns: ?u64,
        preloaded_metadata: ?StartupCatchUpMetadata,
    ) !ProvisionedTableWriteCache.CachedDb {
        return try self.getOrOpenCachedDbModeAtGeneration(
            alloc,
            cache,
            path,
            group_id,
            self.visibleRootGeneration(group_id),
            table_name,
            mode,
            finish_expired_auto_bulk_now_ns,
            ensure_auto_bulk_now_ns,
            preloaded_metadata,
            .{},
        );
    }

    fn getOrOpenCachedDbModeAtGeneration(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        cache: *ProvisionedTableWriteCache,
        path: []const u8,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
        mode: ManagedDbOpenMode,
        finish_expired_auto_bulk_now_ns: ?u64,
        ensure_auto_bulk_now_ns: ?u64,
        preloaded_metadata: ?StartupCatchUpMetadata,
        managed_open_options: ManagedDbOpenOptions,
    ) !ProvisionedTableWriteCache.CachedDb {
        _ = alloc;
        const local_persisted_metadata = if (preloaded_metadata) |metadata|
            metadata.metadata_source == .local_persisted
        else
            false;
        if (cache.backend_runtime == null) cache.backend_runtime = self.backend_runtime;
        cache.antfly_provider = self.antfly_provider;
        cache.inference_api_url = self.inference_api_url;
        cache.remote_content = self.remote_content;
        self.syncRuntimeHooksToCache(cache);
        const identity_namespace = if (preloaded_metadata) |metadata|
            metadata.identity_namespace
        else
            try loadTableIdentityNamespaceForGroup(cache.alloc, self.catalog, table_name, group_id);
        const identity_validation = if (preloaded_metadata) |metadata|
            metadata.identity_validation
        else
            StartupCatchUpMetadata.IdentityValidation.exact;
        const expected_identity_namespace = if (identity_validation == .exact)
            identity_namespace
        else
            null;
        // Structural reconciliation already owns table admission and updates
        // the resident writer's schema/producers in place. Let that owner
        // acquire an existing metadata-mismatched entry without retiring it;
        // a cold miss still opens from the supplied desired metadata below.
        const cache_match_metadata = if (managed_open_options.reuse_cached_writer_for_metadata_reconcile)
            null
        else
            preloaded_metadata;
        if (mode == .status_only) {
            while (true) {
                lockAtomic(&self.local_db_mutex);
                if (finish_expired_auto_bulk_now_ns) |now_ns| {
                    _ = cache.finishExpiredAutoBulkIngestLocked(now_ns) catch |err| {
                        self.local_db_mutex.unlock();
                        return err;
                    };
                }
                var cached = self.getOrOpenCachedDbModeAlreadyLocked(cache, path, group_id, lsm_root_generation, table_name, .status_only) catch |err| {
                    self.local_db_mutex.unlock();
                    return err;
                };
                self.local_db_mutex.unlock();
                errdefer cached.deinit(cache.alloc);
                try validateProvisionedDbIdentityNamespaceWithPolicy(
                    identity_namespace,
                    identity_validation,
                    cached.db,
                );
                return cached;
            }
        }

        var prepared_open: ?ProvisionedTableWriteCache.PreparedOpen = null;
        defer if (prepared_open) |*prepared| prepared.deinit(cache.alloc);

        while (true) {
            lockAtomic(&self.local_db_mutex);
            if (finish_expired_auto_bulk_now_ns) |now_ns| {
                _ = cache.finishExpiredAutoBulkIngestLocked(now_ns) catch |err| {
                    self.local_db_mutex.unlock();
                    if (!isTransientReplayVisibilityError(err)) return err;
                    std.log.warn("auto bulk ingest expired finish deferred table={s} group_id={} err={s}", .{
                        table_name,
                        group_id,
                        @errorName(err),
                    });
                    continue;
                };
            }
            const open_state = cache.getOrPrepareOpenLocked(
                group_id,
                lsm_root_generation,
                table_name,
                expected_identity_namespace,
                cache_match_metadata,
            ) catch |err| {
                self.local_db_mutex.unlock();
                return err;
            };
            switch (open_state) {
                .cached => |cached_value| {
                    var cached = cached_value;
                    if (ensure_auto_bulk_now_ns) |now_ns| {
                        cache.ensureAutoBulkIngestLocked(group_id, table_name, now_ns) catch |err| {
                            self.local_db_mutex.unlock();
                            cached.deinit(cache.alloc);
                            return err;
                        };
                    }
                    self.local_db_mutex.unlock();
                    errdefer cached.deinit(cache.alloc);
                    try validateProvisionedDbIdentityNamespaceWithPolicy(
                        identity_namespace,
                        identity_validation,
                        cached.db,
                    );
                    if (mode == .default or mode == .default_async) {
                        cached.db.setQueryVisibilityHook(self.managedDerivedVisibilityHook(cached.entry.?.table_name, group_id, cached.db));
                    }
                    return cached;
                },
                .prepared => |prepared| {
                    self.local_db_mutex.unlock();
                    prepared_open = prepared;
                    break;
                },
                .pending_close => {
                    self.local_db_mutex.unlock();
                    cache.drainPendingClosesForGroupTable(group_id, table_name);
                    continue;
                },
            }
        }

        lockAtomic(&cache.open_mutex);
        var cache_open_locked = true;
        defer if (cache_open_locked) cache.open_mutex.unlock();

        prepared_open_retry: while (true) {
            while (true) {
                lockAtomic(&self.local_db_mutex);
                const open_state = cache.getOrPrepareOpenLocked(
                    group_id,
                    lsm_root_generation,
                    table_name,
                    expected_identity_namespace,
                    cache_match_metadata,
                ) catch |err| {
                    self.local_db_mutex.unlock();
                    return err;
                };
                switch (open_state) {
                    .cached => |cached_value| {
                        var cached = cached_value;
                        if (ensure_auto_bulk_now_ns) |now_ns| {
                            cache.ensureAutoBulkIngestLocked(group_id, table_name, now_ns) catch |err| {
                                self.local_db_mutex.unlock();
                                cached.deinit(cache.alloc);
                                return err;
                            };
                        }
                        self.local_db_mutex.unlock();
                        errdefer cached.deinit(cache.alloc);
                        try validateProvisionedDbIdentityNamespaceWithPolicy(
                            identity_namespace,
                            identity_validation,
                            cached.db,
                        );
                        prepared_open.?.deinit(cache.alloc);
                        prepared_open = null;
                        if (mode == .default or mode == .default_async) {
                            cached.db.setQueryVisibilityHook(self.managedDerivedVisibilityHook(cached.entry.?.table_name, group_id, cached.db));
                        }
                        return cached;
                    },
                    .prepared => |prepared| {
                        self.local_db_mutex.unlock();
                        prepared_open.?.deinit(cache.alloc);
                        prepared_open = prepared;
                        break;
                    },
                    .pending_close => {
                        self.local_db_mutex.unlock();
                        cache.drainPendingClosesForGroupTableAssumeOpenMutexHeld(group_id, table_name);
                        continue;
                    },
                }
            }

            if (preloaded_metadata) |metadata| {
                if (metadata.metadata_source == .supplied) {
                    if (metadata.indexes_json) |value| {
                        prepared_open.?.indexes_json = try cache.alloc.dupe(u8, value);
                    }
                    if (metadata.schema_json) |value| {
                        prepared_open.?.schema_json = try cache.alloc.dupe(u8, value);
                    }
                }
            } else if (try loadTableManagedMetadata(cache.alloc, self.catalog, table_name)) |metadata| {
                prepared_open.?.indexes_json = metadata.indexes_json;
                prepared_open.?.schema_json = metadata.schema_json;
            }

            const effective_ha_mirror = haMirrorForManagedDbOpenMode(mode, self.ha_async_mirror);
            var effective_open_options = managed_open_options;
            effective_open_options.drain_resolver_backfill = false;
            effective_open_options.source_table = table_name;
            effective_open_options.destination_authorizer = self.destination_authorizer;
            effective_open_options.schema_json_before_index_load = prepared_open.?.schema_json;
            effective_open_options.inference_api_url = self.inference_api_url;
            effective_open_options.ha_write_gate = self.ha_write_gate;
            effective_open_options.ha_async_effect_mirror = effective_ha_mirror;
            effective_open_options.ha_async_batch_mirror = effective_ha_mirror;
            effective_open_options.ha_async_metadata_mirror = effective_ha_mirror;
            effective_open_options.identity_validation = identity_validation;
            effective_open_options.transaction_recovery = if (mode == .startup_catch_up or mode == .restore_repair or mode == .query_readonly or mode == .status_only)
                .{}
            else
                self.transactionRecoveryConfig();
            var retry_prepared_open = false;
            var opened: ?db_mod.DB = while (true) {
                const open_result: anyerror!db_mod.DB = if (consumeTestWriterOpenPersistentDescriptorFailure())
                    error.PersistentDescriptorAdmissionExhausted
                else if (prepared_open.?.indexes_json) |value|
                    openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
                        cache.alloc,
                        path,
                        value,
                        cache.lsm_cache,
                        cache.hbc_cache,
                        lsm_root_generation,
                        cache.resource_manager,
                        mode,
                        cache.backend_runtime,
                        self.antfly_provider,
                        self.secret_store,
                        cache.remote_content,
                        identity_namespace,
                        effective_open_options,
                    )
                else
                    db_mod.DB.open(cache.alloc, path, .{
                        .lsm_cache = cache.lsm_cache,
                        .hbc_cache = cache.hbc_cache,
                        .lsm_root_generation = lsm_root_generation,
                        .resource_manager = cache.resource_manager,
                        .backend_runtime = cache.backend_runtime,
                        .primary_backend = if (local_persisted_metadata) existingPrimaryBackend() else (db_mod.OpenOptions{}).primary_backend,
                        .identity_namespace = identity_namespace,
                        .prefer_existing_identity_namespace = identity_namespace != null,
                        .ha_write_gate = self.ha_write_gate,
                        .ha_async_effect_mirror = effective_ha_mirror,
                        .ha_async_batch_mirror = effective_ha_mirror,
                        .ha_async_metadata_mirror = effective_ha_mirror,
                        .open_mode = switch (mode) {
                            .default => .writer,
                            .default_async, .writer_no_replay => .writer_no_replay,
                            .startup_catch_up, .restore_repair => .writer_no_replay,
                            .query_readonly => .query_readonly,
                            .status_only => .status_only,
                        },
                        .index_open_parallelism = if (mode == .default_async or mode == .writer_no_replay) 1 else null,
                        .start_index_workers = if (mode == .startup_catch_up or mode == .restore_repair or mode == .query_readonly) false else true,
                        .start_optional_runtimes = mode != .startup_catch_up and mode != .restore_repair and mode != .query_readonly,
                        .ttl_cleanup = if (mode == .startup_catch_up or mode == .restore_repair or mode == .query_readonly) .{ .enabled = false } else .{},
                        .transaction_recovery = if (mode == .startup_catch_up or mode == .restore_repair or mode == .query_readonly or mode == .status_only)
                            .{}
                        else
                            self.transactionRecoveryConfig(),
                        .text_merge = if (mode == .startup_catch_up or mode == .restore_repair or mode == .query_readonly) .{ .enabled = false } else .{},
                    });

                const opened_value = open_result catch |err| switch (err) {
                    error.PersistentDescriptorAdmissionExhausted => {
                        lockAtomic(&self.local_db_mutex);
                        const evicted = cache.evictOneInactiveEntryForDescriptorPressureLocked(group_id, table_name) catch |evict_err| {
                            self.local_db_mutex.unlock();
                            return evict_err;
                        };
                        self.local_db_mutex.unlock();
                        if (!evicted) {
                            // The process pool is shared by the serving and startup
                            // caches. Drop the currently-held open lock before the
                            // coordinated slow path acquires both caches in address
                            // order, then revalidate this prepared open after the
                            // victim has synchronously released its lifetime FDs.
                            cache.open_mutex.unlock();
                            cache_open_locked = false;
                            const cross_cache_evicted = self.reclaimInactiveEntryAcrossWriteCachesForDescriptorPressure(
                                cache,
                                group_id,
                                table_name,
                            ) catch |reclaim_err| {
                                lockAtomic(&cache.open_mutex);
                                cache_open_locked = true;
                                return reclaim_err;
                            };
                            lockAtomic(&cache.open_mutex);
                            cache_open_locked = true;
                            if (!cross_cache_evicted) return err;
                            retry_prepared_open = true;
                            break null;
                        }

                        // This path already owns cache.open_mutex. Close the
                        // selected DB synchronously so its lifetime lock permits
                        // are released before retrying the physical open.
                        cache.drainPendingClosesAssumeOpenMutexHeld();
                        continue;
                    },
                    else => return err,
                };
                break opened_value;
            };
            if (retry_prepared_open) continue :prepared_open_retry;
            defer if (opened) |*db| db.close();
            if (local_persisted_metadata and prepared_open.?.schema_json == null) {
                prepared_open.?.schema_json = (try loadLocalTableSchemaJson(cache.alloc, &opened.?)) orelse
                    return error.MissingLocalTableManifest;
            }
            try validateProvisionedDbIdentityNamespaceWithPolicy(
                identity_namespace,
                identity_validation,
                &opened.?,
            );

            var cached = blk: {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                try cache.reserveRetiredEntriesCapacityLocked(1);
                const adopted = try cache.adoptPreparedOpenLocked(&opened, group_id, lsm_root_generation, table_name, mode, &prepared_open.?);
                if (mode == .default or mode == .default_async) {
                    adopted.db.setQueryVisibilityHook(self.managedDerivedVisibilityHook(adopted.entry.?.table_name, group_id, adopted.db));
                }
                if (ensure_auto_bulk_now_ns) |now_ns| try cache.ensureAutoBulkIngestLocked(group_id, table_name, now_ns);
                break :blk adopted;
            };
            errdefer {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                cache.retireFailedOpenLocked(&cached);
            }
            // .default_async opens run on the raft apply thread
            // (applyReplicatedBatchGroupLocal). Draining resolver backfill there
            // blocks the raft loop on the promotion pipeline, whose cross-shard
            // entity upserts need raft applies that are queued behind this very
            // open — observed as a full apply wedge (batch writes timing out
            // cluster-wide) in the multinode autograph e2e. The promotion and
            // resolution workers started by this open drain the same backlog
            // asynchronously instead.
            if (managedDbOpenModeDrainsResolverBackfill(mode)) {
                try cached.db.drainResolverBackfill();
            }
            // DB.open starts and resumes derived workers before the cache can
            // attach its provisioned visibility hook. A short persisted replay
            // tail can therefore finish during open and miss the post-watermark
            // callback entirely. Seed the status cache once after hook attachment;
            // later watermark advances continue to publish through the hook.
            if (mode == .default or mode == .default_async) {
                _ = self.publishManagedRuntimeStatusBestEffort(table_name, group_id, cached.db);
            }
            return cached;
        }
    }

    fn getOrOpenCachedDbModeForReplicatedApply(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        cache: *ProvisionedTableWriteCache,
        path: []const u8,
        group_id: u64,
        table_name: []const u8,
    ) !ProvisionedTableWriteCache.CachedDb {
        const start_ns = platform_time.monotonicNs();
        const deadline_ns = start_ns +| replicated_apply_writer_open_timeout_ns;
        var logged_wait = false;
        while (true) {
            return self.getOrOpenCachedDbMode(
                alloc,
                cache,
                path,
                group_id,
                table_name,
                .default_async,
                null,
                null,
            ) catch |err| {
                if (!isTransientWriterOpenConflict(err)) return err;
                const now_ns = platform_time.monotonicNs();
                if (now_ns >= deadline_ns) {
                    std.log.err("raft apply local writer wait timed out table={s} group_id={} wait_ms={} err={s}", .{
                        table_name,
                        group_id,
                        @divTrunc(now_ns -| start_ns, std.time.ns_per_ms),
                        @errorName(err),
                    });
                    return err;
                }
                if (!logged_wait) {
                    logged_wait = true;
                    std.log.warn("raft apply waiting for local writer table={s} group_id={} err={s}", .{
                        table_name,
                        group_id,
                        @errorName(err),
                    });
                }
                sleepNs(replicated_apply_writer_open_retry_ns);
                continue;
            };
        }
    }

    pub fn setLocalChangeHook(self: *ProvisionedTableWriteSource, hook: ?LocalChangeHook) void {
        self.local_change_hook = hook;
    }

    pub fn setLocalIndexRepairDebtHook(self: *ProvisionedTableWriteSource, hook: ?LocalIndexRepairDebtHook) void {
        self.local_index_repair_debt_hook = hook;
    }

    fn invalidateReadCache(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        if (self.read_cache) |cache| cache.invalidateTable(table_name);
    }

    fn beginReadCacheExclusive(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
    ) !?table_reads.ProvisionedTableReadCache.ExclusiveTableAccess {
        const cache = self.read_cache orelse return null;
        return try cache.beginExclusiveTableAccess(table_name);
    }

    fn beginReadCacheGroupExclusive(
        self: *ProvisionedTableWriteSource,
        group_id: u64,
    ) !?table_reads.ProvisionedTableReadCache.ExclusiveGroupAccess {
        const cache = self.read_cache orelse return null;
        return try cache.beginExclusiveGroupAccess(group_id);
    }

    fn invalidateWriteCacheForTable(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        lockAtomic(&self.local_db_mutex);
        if (self.write_cache) |cache| cache.invalidateTable(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();
    }

    fn invalidateRuntimeStatusCache(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        if (self.runtime_status_cache) |snapshot_cache| snapshot_cache.invalidateTable(table_name);
    }

    fn invalidateSharedPathCaches(self: *ProvisionedTableWriteSource, path: []const u8) void {
        var write_lsm_cache: ?*lsm_backend.Cache = null;
        var startup_lsm_cache: ?*lsm_backend.Cache = null;
        var write_hbc_cache: ?*hbc_mod.Cache = null;
        var startup_hbc_cache: ?*hbc_mod.Cache = null;
        const read_lsm_cache = if (self.read_cache) |cache| cache.lsm_cache else null;
        const read_hbc_cache = if (self.read_cache) |cache| cache.hbc_cache else null;
        lockAtomic(&self.local_db_mutex);
        if (self.write_cache) |cache| {
            write_lsm_cache = cache.lsm_cache;
            write_hbc_cache = cache.hbc_cache;
        }
        if (self.startup_write_cache) |cache| {
            startup_lsm_cache = cache.lsm_cache;
            startup_hbc_cache = cache.hbc_cache;
        }
        self.local_db_mutex.unlock();

        if (write_lsm_cache) |cache| cache.invalidatePrefix(path);
        if (startup_lsm_cache) |cache| {
            if (write_lsm_cache == null or write_lsm_cache.? != cache) {
                cache.invalidatePrefix(path);
            }
        }
        if (read_lsm_cache) |cache| {
            if ((write_lsm_cache == null or write_lsm_cache.? != cache) and
                (startup_lsm_cache == null or startup_lsm_cache.? != cache))
            {
                cache.invalidatePrefix(path);
            }
        }
        if (write_hbc_cache) |cache| cache.invalidatePath(path);
        if (startup_hbc_cache) |cache| {
            if (write_hbc_cache == null or write_hbc_cache.? != cache) {
                cache.invalidatePath(path);
            }
        }
        if (read_hbc_cache) |cache| {
            if ((write_hbc_cache == null or write_hbc_cache.? != cache) and
                (startup_hbc_cache == null or startup_hbc_cache.? != cache))
            {
                cache.invalidatePath(path);
            }
        }
    }

    fn managedDerivedVisibilityHook(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        db: *db_mod.DB,
    ) db_mod.QueryVisibilityHook {
        return .{
            .ptr = self,
            .table_name = table_name,
            .group_id = group_id,
            .db = db,
            .on_change = onManagedDerivedVisibilityChanged,
        };
    }

    fn publishManagedRuntimeStatusBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        db: *db_mod.DB,
    ) bool {
        const snapshot_cache = self.runtime_status_cache orelse return false;
        publishRuntimeStatusSnapshot(self, snapshot_cache.alloc, table_name, group_id, db) catch |err| {
            if (err == error.WriterLocked) {
                std.log.debug("managed runtime status publish deferred table={s} group_id={} err={s}", .{
                    table_name,
                    group_id,
                    @errorName(err),
                });
            } else {
                std.log.warn("managed runtime status publish failed table={s} group_id={} err={s}", .{
                    table_name,
                    group_id,
                    @errorName(err),
                });
            }
            return false;
        };
        return true;
    }

    fn overlayCachedManagedRuntimeStatusBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        db: *db_mod.DB,
    ) bool {
        const snapshot_cache = self.runtime_status_cache orelse return false;
        const publication_token = snapshot_cache.capturePublicationToken(table_name) catch |err| {
            std.log.warn("managed runtime status token capture failed table={s} group_id={} err={s}", .{
                table_name,
                group_id,
                @errorName(err),
            });
            return false;
        };
        var status = (snapshot_cache.snapshotGroupStatus(snapshot_cache.alloc, table_name, group_id) catch |err| {
            std.log.warn("managed runtime status cached snapshot lookup failed table={s} group_id={} err={s}", .{
                table_name,
                group_id,
                @errorName(err),
            });
            return false;
        }) orelse return false;
        defer status.deinit(snapshot_cache.alloc);

        db.overlayRuntimeStatusBestEffort(snapshot_cache.alloc, &status.stats);
        _ = snapshot_cache.publishGroup(publication_token, table_name, status) catch |err| {
            std.log.warn("managed runtime status overlay publish failed table={s} group_id={} err={s}", .{
                table_name,
                group_id,
                @errorName(err),
            });
            return false;
        };
        return true;
    }

    fn onManagedDerivedVisibilityChanged(
        ptr: *anyopaque,
        table_name: []const u8,
        group_id: u64,
        db: ?*db_mod.DB,
        change: db_mod.QueryVisibilityChange,
    ) void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        // Cached owners release repair handoff authority only after a fresh
        // post-clear observation is successfully published. Sources without a
        // status cache have no publication plane to wait for: their next live
        // status request is itself authoritative.
        defer if (self.runtime_status_cache == null) switch (change) {
            .status, .publish, .publish_consistent, .publish_blocking => if (self.captureRepairHandoffPublicationTokenBestEffort(table_name, group_id, true)) |token| {
                _ = self.settleRepairHandoffStatusIfUnchangedBestEffort(table_name, group_id, token);
            },
            else => {},
        };
        switch (change) {
            .index_repair_pending => {
                // Query DBs snapshot repair admission at open. Retire readers
                // on both edges so a newly detected repair fails closed and a
                // completed repair cannot leave an old reader quarantined.
                self.invalidateReadCache(table_name);
                self.invalidateRuntimeStatusCache(table_name);
                self.markRepairHandoffPendingBestEffort(table_name, group_id);
                // Preserve every exact debt edge even while structural
                // reconciliation owns the table status fence. Plain enqueue
                // only updates the deduplicated exact-debt queue; the structural
                // owner upgrades its affected groups to runnable after it has
                // transferred status authority and released admission.
                self.notifyLocalIndexRepairDebt(table_name, group_id, .enqueue);
                self.notifyLocalChange(table_name, .data);
                return;
            },
            .index_repair_cleared => {
                self.invalidateReadCache(table_name);
                self.invalidateRuntimeStatusCache(table_name);
                // Visibility callbacks can overlap after copying their hook.
                // A clear edge is therefore an audit trigger, never settlement
                // evidence: an older clear can finish after a newer durable
                // pending edge whose callback is still running. Keep the group
                // queued; only the aggregate owner may classify durable repair
                // state and authorize status publication. Explicit drop remains
                // the destructive remove path.
                self.notifyLocalIndexRepairDebt(table_name, group_id, .enqueue);
                self.notifyLocalChange(table_name, .data);
                return;
            },
            .status => {
                if (self.deferManagedRuntimeStatusPublication(table_name, false)) return;
                if (db) |managed_db| {
                    if (self.publishManagedRuntimeStatusBestEffort(table_name, group_id, managed_db)) {
                        self.notifyLocalChange(table_name, .data);
                        return;
                    }
                }
                self.markWriteCacheDirty(table_name);
                self.notifyLocalChange(table_name, .data);
                return;
            },
            .publish => {
                if (self.deferManagedRuntimeStatusPublication(table_name, true)) return;
                if (db) |managed_db| {
                    if (self.publishManagedRuntimeStatusBestEffort(table_name, group_id, managed_db)) {
                        self.invalidateReadCache(table_name);
                        self.clearDirtyWriteTable(table_name);
                        self.notifyLocalChange(table_name, .data);
                        return;
                    }
                }
                self.markWriteCacheDirty(table_name);
            },
            .publish_consistent => {
                if (self.deferManagedRuntimeStatusPublication(table_name, true)) return;
                if (db) |managed_db| {
                    if (self.runtime_status_cache) |snapshot_cache| {
                        var published = true;
                        publishRuntimeStatusSnapshotConsistentIfAvailable(self, snapshot_cache.alloc, table_name, group_id, managed_db) catch |err| {
                            published = false;
                            if (err != error.WriterLocked) {
                                std.log.warn("managed runtime status publish failed table={s} group_id={} err={s}", .{
                                    table_name,
                                    group_id,
                                    @errorName(err),
                                });
                            }
                        };
                        if (published) _ = self.settlePublicationHandoffStatusBestEffort(snapshot_cache, table_name, group_id, false);
                        self.invalidateReadCache(table_name);
                        self.markWriteCacheDirty(table_name);
                        self.notifyLocalChange(table_name, .data);
                        return;
                    }
                }
                self.markWriteCacheDirty(table_name);
            },
            .publish_blocking => {
                if (self.deferManagedRuntimeStatusPublication(table_name, true)) return;
                if (db) |managed_db| {
                    if (self.runtime_status_cache) |snapshot_cache| {
                        publishRuntimeStatusSnapshotConsistent(self, snapshot_cache.alloc, table_name, group_id, managed_db) catch |err| {
                            std.log.warn("managed runtime status blocking publish failed table={s} group_id={} err={s}", .{
                                table_name,
                                group_id,
                                @errorName(err),
                            });
                            self.invalidateRuntimeStatusCache(table_name);
                            self.markWriteCacheDirty(table_name);
                            self.invalidateReadCache(table_name);
                            self.notifyLocalChange(table_name, .data);
                            return;
                        };
                        _ = self.settlePublicationHandoffStatusBestEffort(snapshot_cache, table_name, group_id, true);
                        self.invalidateReadCache(table_name);
                        self.clearDirtyWriteTable(table_name);
                        self.notifyLocalChange(table_name, .data);
                        return;
                    }
                }
                self.invalidateRuntimeStatusCache(table_name);
                self.markWriteCacheDirty(table_name);
            },
            .invalidate => if (self.deferManagedRuntimeStatusPublication(table_name, true)) return,
        }
        self.invalidateReadCache(table_name);
        self.notifyLocalChange(table_name, .data);
    }

    fn deferManagedRuntimeStatusPublication(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        invalidate_reads: bool,
    ) bool {
        // Query-visibility hooks run on DB/index workers. Sampling whole-DB
        // status here can form a cross-executor cycle when two indexes finish
        // together. A configured runtime owner is the serialization boundary:
        // the hook only records debt and asks that owner to sample later.
        if (self.local_change_hook == null) return false;
        self.markWriteCacheDirty(table_name);
        if (invalidate_reads) self.invalidateReadCache(table_name);
        self.notifyLocalChange(table_name, .runtime_status);
        return true;
    }

    fn invalidateWriteCache(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        _ = self.publishWriteCacheStatusBeforeInvalidate(table_name);
        self.detachWriteCacheVisibilityHooksBeforeInvalidate(table_name);
        if (self.write_cache) |cache| cache.invalidateTable(table_name);
        if (self.startup_write_cache) |cache| cache.invalidateTable(table_name);
        self.clearDirtyWriteTable(table_name);
    }

    fn publishWriteCacheStatusBeforeInvalidate(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        if (self.runtime_status_cache == null) return true;
        var published = true;
        published = self.publishCacheStatusBeforeInvalidate(table_name, self.write_cache) and published;
        published = self.publishCacheStatusBeforeInvalidate(table_name, self.startup_write_cache) and published;
        return published;
    }

    fn detachWriteCacheVisibilityHooksBeforeInvalidate(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        self.detachCacheVisibilityHooksBeforeInvalidate(table_name, self.write_cache);
        self.detachCacheVisibilityHooksBeforeInvalidate(table_name, self.startup_write_cache);
    }

    fn detachCacheVisibilityHooksBeforeInvalidate(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        maybe_cache: ?*ProvisionedTableWriteCache,
    ) void {
        const cache = maybe_cache orelse return;
        for (cache.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.lsm_root_generation != self.visibleRootGeneration(entry.group_id)) continue;
            entry.db.setQueryVisibilityHook(null);
        }
    }

    fn publishCacheStatusBeforeInvalidate(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        maybe_cache: ?*ProvisionedTableWriteCache,
    ) bool {
        const cache = maybe_cache orelse return true;
        var published = true;
        for (cache.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.lsm_root_generation != self.visibleRootGeneration(entry.group_id)) continue;
            self.finishEntryAutoBulkIngestForForegroundVisibility(cache, entry) catch |err| {
                if (!isTransientReplayVisibilityError(err)) {
                    std.log.warn("managed writer auto bulk finish before status publish failed table={s} group_id={} err={s}", .{
                        entry.table_name,
                        entry.group_id,
                        @errorName(err),
                    });
                }
                published = false;
                continue;
            };
            published = self.publishManagedRuntimeStatusBestEffort(entry.table_name, entry.group_id, &entry.db) and published;
        }
        return published;
    }

    fn finishEntryAutoBulkIngestForForegroundVisibility(
        self: *ProvisionedTableWriteSource,
        cache: *ProvisionedTableWriteCache,
        entry: *ProvisionedTableWriteCache.Entry,
    ) !void {
        if (!entry.auto_bulk_ingest_session_open) return;
        if (entry.auto_bulk_ingest_finishing) return error.AutoBulkIngestBusy;
        try entry.db.finishPrimaryStoreAutoBulkIngestSessionWithOptions(auto_bulk_ingest_finish_options);
        entry.bulk_ingest_session_open = false;
        entry.auto_bulk_ingest_session_open = false;
        entry.auto_bulk_ingest_ops = 0;
        entry.auto_bulk_ingest_started_ns = 0;
        entry.auto_bulk_ingest_last_ns = 0;
        entry.auto_bulk_ingest_finish_requested = false;
        cache.removeInactiveBulkIngestSessionLocked(entry.table_name);
        _ = self;
    }

    pub fn pruneStaleWriteCacheLocked(self: *ProvisionedTableWriteSource) void {
        const pruneCache = struct {
            fn run(write_source: *ProvisionedTableWriteSource, cache: *ProvisionedTableWriteCache) void {
                var i: usize = 0;
                while (i < cache.entries.items.len) {
                    const entry = cache.entries.items[i];
                    const current_generation = write_source.visibleRootGeneration(entry.group_id);
                    if (entry.lsm_root_generation == current_generation) {
                        i += 1;
                        continue;
                    }
                    if (cache.adoptSeededEntryGenerationLocked(entry, current_generation)) {
                        i += 1;
                        continue;
                    }
                    if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) {
                        i += 1;
                        continue;
                    }
                    if (cache.retireInactiveEntryAtIndexForCloseLocked(i) catch false) continue;
                    i += 1;
                }

                var session_index: usize = 0;
                while (session_index < cache.active_bulk_ingest_sessions.items.len) {
                    const session = &cache.active_bulk_ingest_sessions.items[session_index];
                    const table_name = session.table_name;
                    for (cache.entries.items) |entry| {
                        if (std.mem.eql(u8, entry.table_name, table_name)) break;
                    } else {
                        if (session.state != .active) {
                            session_index += 1;
                            continue;
                        }
                        var removed = cache.active_bulk_ingest_sessions.orderedRemove(session_index);
                        removed.deinit(cache.alloc);
                        continue;
                    }
                    session_index += 1;
                }
            }
        }.run;

        if (self.write_cache) |cache| pruneCache(self, cache);
        if (self.startup_write_cache) |cache| pruneCache(self, cache);
    }

    /// Reconciles provisioned DB state without holding `local_db_mutex` across
    /// DB work. Resolver catch-up can acquire a resident DB lease while
    /// reconciling indexes, so carrying the cache mutex into that work creates
    /// a lock inversion (`local_db_mutex` -> resolver catch-up mutex ->
    /// `local_db_mutex`). Cache entries are pinned by a lease instead; the
    /// mutex only protects cache admission and metadata publication.
    pub fn reconcileReplicaRootTablesWithWriteCache(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        metadata_group_id: u64,
        hosted_group_ids: []const u64,
        tables: []const metadata_table_manager.TableRecord,
        ranges: []const metadata_table_manager.RangeRecord,
        backend_runtime: ?*db_mod.background_runtime.BackendRuntime,
    ) !metadata_table_provisioner.ProvisionSummary {
        const cache = self.write_cache orelse return try metadata_table_provisioner.reconcileReplicaRootWithOptions(
            alloc,
            self.replica_root_dir,
            metadata_group_id,
            hosted_group_ids,
            tables,
            ranges,
            .{
                .backend_runtime = backend_runtime,
                .restore_open_options = self.restore_open_options,
                .destination_authorizer = self.destination_authorizer,
            },
        );

        {
            lockAtomic(&self.local_db_mutex);
            defer self.local_db_mutex.unlock();
            if (cache.backend_runtime == null) cache.backend_runtime = backend_runtime orelse self.backend_runtime;
            cache.antfly_provider = self.antfly_provider;
            cache.inference_api_url = self.inference_api_url;
            cache.secret_store = self.secret_store;
            cache.remote_content = self.remote_content;
        }

        var summary: metadata_table_provisioner.ProvisionSummary = .{};
        for (hosted_group_ids) |group_id| {
            if (group_id == metadata_group_id) continue;
            const range = findRangeRecord(ranges, group_id) orelse continue;
            const table = findTableRecord(tables, range.table_id) orelse continue;
            summary.groups_considered += 1;

            const path = try metadata_table_provisioner.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);

            var io_impl = std.Io.Threaded.init(alloc, .{});
            defer io_impl.deinit();
            try fs_paths.createDirPathPortable(io_impl.io(), path);
            try metadata_table_provisioner.applyRestoreIntentIfNeededWithOptions(
                alloc,
                path,
                group_id,
                table,
                range,
                self.restore_open_options,
            );

            const lsm_root_generation = self.visibleRootGeneration(group_id);
            const identity_namespace = doc_identity.Namespace{
                .table_id = table.table_id,
                .shard_id = metadata_table_manager.rangeDocIdentityShardId(range),
                .range_id = metadata_table_manager.rangeDocIdentityRangeId(range),
            };
            var admitted_new_cache_entry = false;
            var cached = blk: {
                lockAtomic(&self.local_db_mutex);
                const existing = cache.snapshotLeaseOrAdoptSeededLocked(
                    group_id,
                    lsm_root_generation,
                    table.name,
                );
                self.local_db_mutex.unlock();
                if (existing) |value| break :blk value;

                const metadata: StartupCatchUpMetadata = .{
                    .indexes_json = table.indexes_json,
                    .schema_json = table.schema_json,
                    .identity_namespace = identity_namespace,
                };
                const opened = try self.getOrOpenCachedDbModeAtGeneration(
                    alloc,
                    cache,
                    path,
                    group_id,
                    lsm_root_generation,
                    table.name,
                    .default,
                    null,
                    null,
                    metadata,
                    .{},
                );
                admitted_new_cache_entry = true;
                summary.dbs_opened += 1;
                break :blk opened;
            };
            defer cached.deinit(alloc);

            try validateProvisionedDbIdentityNamespaceExpected(identity_namespace, cached.db);
            try applyLocalTableSchemaJson(alloc, cached.db, table.schema_json);
            // The open helper performs initial desired-state reconciliation,
            // but intentionally returns only the DB. Reconcile once more at
            // this cache-admission boundary so a staged same-name retirement
            // cannot lose its pending retry signal. This pass is idempotent;
            // if cleanup already completed it admits the replacement now.
            const index_summary = try metadata_table_provisioner.reconcileDbIndexes(alloc, cached.db, table.indexes_json);
            summary.merge(index_summary);
            if (index_summary.indexes_pending != 0 and !admitted_new_cache_entry) {
                // A newly admitted managed DB publishes the pending edge via
                // its installed visibility hook. An existing lease may have
                // observed the edge before this owner began reconciliation,
                // so retain the idempotent aggregate-debt audit for that path.
                self.notifyLocalIndexRepairDebt(table.name, group_id, .enqueue);
            }
            {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                try cache.replaceTableMetadataLocked(table.name, table.indexes_json, table.schema_json);
                try cache.replaceEntrySchemaLocked(cached.entry.?, table.schema_json);
            }
        }
        return summary;
    }

    pub fn transferAdoptableWriteCacheEntriesTo(
        self: *ProvisionedTableWriteSource,
        dest: *ProvisionedTableWriteSource,
        table_name: []const u8,
    ) !usize {
        if (self == dest) return 0;
        const source_cache = self.write_cache orelse return 0;
        const dest_cache = dest.write_cache orelse return 0;
        if (source_cache == dest_cache) return 0;

        const self_mutex = self.localDbMutex();
        const dest_mutex = dest.localDbMutex();
        if (self_mutex == dest_mutex) {
            lockAtomic(self_mutex);
            defer self_mutex.unlock();
            return try source_cache.transferAdoptableEntriesForTableLocked(
                dest_cache,
                table_name,
                dest.groupVisibleRootGenerationSource(),
            );
        }
        if (@intFromPtr(self_mutex) < @intFromPtr(dest_mutex)) {
            lockAtomic(self_mutex);
            defer self_mutex.unlock();
            lockAtomic(dest_mutex);
            defer dest_mutex.unlock();
        } else {
            lockAtomic(dest_mutex);
            defer dest_mutex.unlock();
            lockAtomic(self_mutex);
            defer self_mutex.unlock();
        }
        return try source_cache.transferAdoptableEntriesForTableLocked(dest_cache, table_name, dest.groupVisibleRootGenerationSource());
    }

    pub fn clearStartupWriteCache(self: *ProvisionedTableWriteSource) !void {
        var locks = WriteCacheTransitionLocks.init(self, false, true);
        defer locks.deinit();
        try locks.reserveClearCapacity();
        locks.clearCaches(true);
        locks.drainAndRelease();
    }

    pub fn clearWriteCache(self: *ProvisionedTableWriteSource) !void {
        var locks = WriteCacheTransitionLocks.init(self, true, true);
        defer locks.deinit();
        try locks.reserveClearCapacity();
        locks.clearCaches(true);
        self.clearAllDirtyWriteTables();
        locks.drainAndRelease();
    }

    pub fn warmTableGroup(self: *ProvisionedTableWriteSource, alloc: std.mem.Allocator, group_id: u64, table_name: []const u8) !void {
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);

        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);

        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default, null, null);
            defer cached.deinit(alloc);
            return;
        }

        var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
        db.close();
    }

    pub fn leaseCachedGroupWriter(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
    ) !?ProvisionedTableWriteCache.CachedDb {
        const cache = self.write_cache orelse return null;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        return try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
    }

    /// Opens a managed writer from a table contract captured by the caller.
    /// Transition callbacks use this path to avoid a lock inversion with the
    /// metadata control loop that is synchronously waiting for them.
    pub fn leaseCachedGroupWriterWithMetadata(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        metadata: StartupCatchUpMetadata,
    ) !?ProvisionedTableWriteCache.CachedDb {
        if (metadata.metadata_source != .supplied)
            return error.InvalidTransitionMetadataSource;
        if (metadata.identity_namespace == null)
            return error.DocIdentityNamespaceUnavailable;
        const cache = self.write_cache orelse return null;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        return try self.getOrOpenCachedDbModeAtGeneration(
            alloc,
            cache,
            path,
            group_id,
            self.visibleRootGeneration(group_id),
            table_name,
            .default_async,
            null,
            null,
            metadata,
            .{},
        );
    }

    /// Opens a transition destination before it is published in the catalog.
    /// The caller supplies the identity namespace inherited from the source
    /// range; ordinary catalog-derived opens cannot discover it yet.
    pub fn leaseCachedTransitionGroupWriter(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        identity_namespace: doc_identity.Namespace,
    ) !?ProvisionedTableWriteCache.CachedDb {
        return try self.leaseCachedTransitionGroupWriterWithOptions(
            alloc,
            group_id,
            table_name,
            identity_namespace,
            .{},
        );
    }

    fn leaseCachedTransitionGroupWriterWithOptions(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        identity_namespace: doc_identity.Namespace,
        managed_open_options: ManagedDbOpenOptions,
    ) !?ProvisionedTableWriteCache.CachedDb {
        const cache = self.write_cache orelse return null;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);

        const loaded_metadata = (try loadTableManagedMetadata(cache.alloc, self.catalog, table_name)) orelse return null;
        defer {
            if (loaded_metadata.indexes_json) |value| cache.alloc.free(value);
            if (loaded_metadata.schema_json) |value| cache.alloc.free(value);
        }
        return try self.getOrOpenCachedDbModeAtGeneration(
            alloc,
            cache,
            path,
            group_id,
            self.visibleRootGeneration(group_id),
            table_name,
            .default_async,
            null,
            null,
            .{
                .indexes_json = loaded_metadata.indexes_json,
                .schema_json = loaded_metadata.schema_json,
                .identity_namespace = identity_namespace,
            },
            managed_open_options,
        );
    }

    /// Opens a transition destination from a caller-pinned table contract.
    /// Metadata control loops may synchronously wait for this open, so their
    /// shard callbacks must not re-enter the catalog over HTTP.
    pub fn leaseCachedTransitionGroupWriterWithMetadata(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        indexes_json: ?[]const u8,
        schema_json: ?[]const u8,
        identity_namespace: doc_identity.Namespace,
    ) !?ProvisionedTableWriteCache.CachedDb {
        return try self.leaseCachedGroupWriterWithMetadata(
            alloc,
            group_id,
            table_name,
            .{
                .indexes_json = indexes_json,
                .schema_json = schema_json,
                .identity_namespace = identity_namespace,
            },
        );
    }

    fn openGroupWriterWithMetadata(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        path: []const u8,
        group_id: u64,
        metadata: StartupCatchUpMetadata,
    ) !db_mod.DB {
        const identity_namespace = metadata.identity_namespace orelse
            return error.DocIdentityNamespaceUnavailable;
        const lsm_root_generation = self.visibleRootGeneration(group_id);
        const effective_ha_mirror = haMirrorForManagedDbOpenMode(.default, self.ha_async_mirror);
        var db = if (metadata.indexes_json) |indexes_json|
            try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
                alloc,
                path,
                indexes_json,
                null,
                null,
                lsm_root_generation,
                null,
                .default,
                self.backend_runtime,
                self.antfly_provider,
                self.secret_store,
                self.remote_content,
                identity_namespace,
                .{
                    .inference_api_url = self.inference_api_url,
                    .schema_json_before_index_load = metadata.schema_json,
                    .ha_write_gate = self.ha_write_gate,
                    .ha_async_effect_mirror = effective_ha_mirror,
                    .ha_async_batch_mirror = effective_ha_mirror,
                    .ha_async_metadata_mirror = effective_ha_mirror,
                    .identity_validation = metadata.identity_validation,
                },
            )
        else
            try db_mod.DB.open(alloc, path, .{
                .lsm_root_generation = lsm_root_generation,
                .backend_runtime = self.backend_runtime,
                .secret_store = self.secret_store,
                .remote_content = self.remote_content,
                .identity_namespace = identity_namespace,
                .prefer_existing_identity_namespace = true,
                .ha_write_gate = self.ha_write_gate,
                .ha_async_effect_mirror = effective_ha_mirror,
                .ha_async_batch_mirror = effective_ha_mirror,
                .ha_async_metadata_mirror = effective_ha_mirror,
            });
        errdefer db.close();
        try validateProvisionedDbIdentityNamespaceWithPolicy(
            identity_namespace,
            metadata.identity_validation,
            &db,
        );
        return db;
    }

    /// Leases a destination generation from its durable local manifest. Raft
    /// apply must not call the remote catalog: metadata reconciliation can be
    /// synchronously waiting for this exact apply to complete.
    pub fn leasePreparedTransitionGroupWriter(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        identity_namespace: doc_identity.Namespace,
    ) !?ProvisionedTableWriteCache.CachedDb {
        const cache = self.write_cache orelse return null;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        return try self.getOrOpenCachedDbModeAtGeneration(
            alloc,
            cache,
            path,
            group_id,
            self.visibleRootGeneration(group_id),
            table_name,
            .default_async,
            null,
            null,
            .{
                .identity_namespace = identity_namespace,
                .metadata_source = .local_persisted,
            },
            .{
                .reconcile_for_replicated_apply = true,
                .retry_transient_writer_open = false,
            },
        );
    }

    pub fn findMedianKeyForGroup(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        lsm_root_generation: u64,
    ) !?[]u8 {
        var snapshot = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&snapshot);

        const range = metadata_mod.findAdminRange(&snapshot, group_id) orelse return error.UnknownGroup;
        const table = metadata_mod.findAdminTable(&snapshot, range.table_id) orelse return error.TableNotFound;
        return try self.findMedianKeyForTableGroup(alloc, group_id, lsm_root_generation, table.name);
    }

    pub fn findMedianKeyForTableGroup(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
    ) !?[]u8 {
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);

        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);

        // Startup catch-up and Raft apply intentionally use separate caches,
        // but there may only be one writer for an LSM root. Prefer the writer
        // that already owns the root; opening through the other cache would
        // turn a healthy split into LsmRootWriterAlreadyOpen and eventually
        // surface to metadata as GroupLeaderUnavailable.
        var existing: ?ProvisionedTableWriteCache.CachedDb = null;
        lockAtomic(&self.local_db_mutex);
        if (self.write_cache) |cache| {
            existing = cache.snapshotLeaseLocked(group_id, lsm_root_generation, table_name);
        }
        if (existing == null) {
            if (self.startup_write_cache) |cache| {
                existing = cache.snapshotLeaseLocked(group_id, lsm_root_generation, table_name);
            }
        }
        self.local_db_mutex.unlock();
        if (existing) |leased| {
            var cached = leased;
            defer cached.deinit(alloc);
            if (cached.entry) |entry| {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                try self.finishEntryAutoBulkIngestForForegroundVisibility(cached.cache.?, entry);
            }
            return cached.db.findMedianKey(alloc) catch |err| switch (err) {
                error.NotFound => null,
                else => err,
            };
        }

        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbModeAtGeneration(alloc, cache, path, group_id, lsm_root_generation, table_name, .default_async, null, null, null, .{});
            defer cached.deinit(alloc);
            if (cached.entry) |entry| {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                try self.finishEntryAutoBulkIngestForForegroundVisibility(cache, entry);
            }
            const median = cached.db.findMedianKey(alloc) catch |err| switch (err) {
                error.NotFound => return null,
                else => return err,
            };
            return median;
        }

        var db = try openManagedDbForTableGroupWithCacheAndRuntime(alloc, path, self.catalog, table_name, group_id, null, null, lsm_root_generation, null, self.backend_runtime);
        defer db.close();
        const median = db.findMedianKey(alloc) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        return median;
    }

    pub fn catchUpTableGroupBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
    ) !StartupCatchUpResult {
        return try self.catchUpTableGroupBestEffortWithIndexesJson(alloc, group_id, table_name, null);
    }

    pub fn catchUpTableGroupBestEffortWithIndexesJson(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        cached_indexes_json: ?[]const u8,
    ) !StartupCatchUpResult {
        return try self.catchUpTableGroupBestEffortWithMetadata(alloc, group_id, table_name, .{
            .indexes_json = cached_indexes_json,
        });
    }

    pub fn catchUpTableGroupBestEffortWithMetadata(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        metadata: StartupCatchUpMetadata,
    ) !StartupCatchUpResult {
        if (self.local_write_owner) |owner| {
            return try owner.catchUpTableGroupBestEffortWithMetadata(alloc, group_id, table_name, metadata);
        }
        const busy_result = StartupCatchUpResult{
            .had_debt = metadata.advance_index_repairs,
            .busy = true,
            // Repair scheduling is edge-triggered. Contention must retain the
            // exact queue entry; otherwise one collision with structural
            // reconciliation is misreported as completed durable debt.
            .index_repair_pending = metadata.advance_index_repairs,
        };
        const backoff_epoch = self.startup_catch_up_backoff_epoch.load(.acquire);
        const now_ms = startupCatchUpMonotonicMs();
        if (!metadata.advance_index_repairs) {
            if (self.startupCatchUpRetryAt(group_id, now_ms)) |retry_at_ms| {
                return .{
                    .had_debt = true,
                    .quarantined = true,
                    .retry_at_ms = retry_at_ms,
                };
            }
        }
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const lsm_root_generation = self.visibleRootGeneration(group_id);

        // Fence any publisher that captured an older clear audit before this
        // pass attempts admission. Doing this before the fallible operation
        // and cache leases also makes a busy return retain publication debt
        // without leaving the old audit available to an unlocked publisher.
        self.invalidateRepairHandoffOwnerAuditBestEffort(table_name, group_id);
        if (!self.tryBeginStartupCatchUpGroupOperation(table_name, group_id, metadata.advance_index_repairs)) return busy_result;
        if (!self.local_db_mutex.tryLock()) {
            self.endGroupOperation(table_name, group_id);
            return busy_result;
        }
        var live_repair_guard: ?ProvisionedTableWriteCache.CachedDb = if (metadata.advance_index_repairs) repair_cache: {
            const cache = self.write_cache orelse break :repair_cache null;
            break :repair_cache cache.leaseLiveEntryForLocalMutationLocked(group_id, table_name, false);
        } else null;
        var use_live_repair_cache = live_repair_guard != null;
        if (metadata.advance_index_repairs and !use_live_repair_cache) {
            // Read-compatible admission is valid only while repair leases the
            // live writer and mutates its unpublished candidate generation.
            // A cold owner can also recover a restore, replay derived state,
            // or rebuild artifacts, so release the optimistic reservation and
            // reacquire the ordinary read-exclusive lifecycle fence. Recheck
            // the cache under that fence; a writer may have appeared during
            // the handoff, but retaining the stronger guard for one bounded
            // pass is safe and avoids another fairness-sensitive transition.
            self.local_db_mutex.unlock();
            self.endGroupOperation(table_name, group_id);
            if (!self.tryBeginGroupOperation(table_name, group_id)) return busy_result;
            if (!self.local_db_mutex.tryLock()) {
                self.endGroupOperation(table_name, group_id);
                return busy_result;
            }
            live_repair_guard = repair_cache: {
                const cache = self.write_cache orelse break :repair_cache null;
                break :repair_cache cache.leaseLiveEntryForLocalMutationLocked(group_id, table_name, false);
            };
            use_live_repair_cache = live_repair_guard != null;
        }
        if (!use_live_repair_cache and self.hasDirtyWriteTableWithLocalDbLocked(table_name)) {
            self.local_db_mutex.unlock();
            self.endGroupOperation(table_name, group_id);
            return busy_result;
        }
        if (!use_live_repair_cache) if (self.write_cache) |cache| {
            if (cache.hasForegroundStateForGroupTableLocked(group_id, table_name)) {
                self.local_db_mutex.unlock();
                self.endGroupOperation(table_name, group_id);
                return busy_result;
            }
        };
        self.local_db_mutex.unlock();
        defer if (live_repair_guard) |*guard| guard.deinit(alloc);
        var group_operation_active = true;
        var preserve_startup_cache = false;
        errdefer {
            var failed_result = StartupCatchUpResult{ .had_debt = true };
            self.updateStartupCatchUpBackoff(group_id, startupCatchUpMonotonicMs(), backoff_epoch, &failed_result);
        }
        defer {
            if (!use_live_repair_cache and !preserve_startup_cache) self.clearStartupWriteCache() catch |err| {
                std.log.warn("startup writer cache retirement deferred table={s} group_id={} err={s}", .{
                    table_name,
                    group_id,
                    @errorName(err),
                });
            };
            if (group_operation_active) self.endGroupOperation(table_name, group_id);
        }
        self.startup_catch_up_active.store(true, .monotonic);
        defer self.startup_catch_up_active.store(false, .monotonic);

        const owned_indexes_json = if (metadata.indexes_json == null) try loadTableIndexesJson(alloc, self.catalog, table_name) else null;
        defer if (owned_indexes_json) |value| alloc.free(value);
        const indexes_json = metadata.indexes_json orelse owned_indexes_json;
        const identity_namespace = if (metadata.identity_namespace) |namespace|
            namespace
        else if (metadata.indexes_json == null)
            try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id)
        else
            null;
        var configured_indexes_storage: ?StartupConfiguredIndexes = null;
        if (indexes_json) |value| configured_indexes_storage = try parseStartupConfiguredIndexes(alloc, value);
        defer if (configured_indexes_storage) |*summary| summary.deinit(alloc);
        const configured_indexes = if (configured_indexes_storage) |*summary| summary else null;
        if (live_repair_guard) |guard| {
            // The direct lease transfer below intentionally bypasses generic
            // cache-open pruning: that path cannot retire an entry while this
            // guard is proving its lifetime. Preserve the same correctness
            // fences explicitly before mutating the authoritative writer.
            try validateProvisionedDbIdentityNamespaceWithPolicy(
                identity_namespace,
                metadata.identity_validation,
                guard.db,
            );
            if (!ProvisionedTableWriteCache.entryManagedConfigMatches(guard.entry.?, indexes_json)) {
                // Repair never reconciles desired table structure. Preserve
                // the durable repair queue entry, but explicitly hand stale
                // writer metadata to the coalesced structural owner instead
                // of spinning this bounded worker on the same mismatch.
                if (!self.structuralStatusSnapshotOnlyBestEffort(table_name)) {
                    self.enqueueTableStructuralReconcile(table_name) catch |err| {
                        std.log.warn("managed index repair structural handoff failed table={s} group_id={} err={s}", .{
                            table_name,
                            group_id,
                            @errorName(err),
                        });
                    };
                }
                return busy_result;
            }
        }
        const opening_db_startup = startupCatchUpStatsForPath(path, .opening_db, configured_indexes) catch db_mod.types.StartupCatchUpStats{
            .active = true,
            .phase = .opening_db,
        };
        // An opening attempt does not own runtime truth until it has leased the
        // generation. Publishing before the open lets a normal WriterLocked
        // return overwrite a healthy writer observation indefinitely.
        const source_io = self.table_activity_threaded.io();
        if (!use_live_repair_cache) {
            _ = db_mod.DB.recoverIncompleteRestoreImportIfNeededWithIo(alloc, source_io, path, .{}) catch |err| {
                if (err == error.LsmRootWriterAlreadyOpen) return busy_result;
                std.log.warn("managed startup restore recovery failed phase=import class={s}", .{@errorName(err)});
                return err;
            };
        }
        const restore_repair_needed = if (live_repair_guard) |guard|
            guard.db.restoreRuntimeRepairNeeded() catch |err| {
                std.log.warn("managed startup restore recovery failed phase=live_repair_probe class={s}", .{@errorName(err)});
                return err;
            }
        else
            db_mod.DB.restoreRuntimeRepairNeededForPathWithIo(alloc, source_io, path) catch |err| {
                if (err == error.LsmRootWriterAlreadyOpen) return busy_result;
                std.log.warn("managed startup restore recovery failed phase=repair_probe class={s}", .{@errorName(err)});
                return err;
            };
        const startup_open_mode: ManagedDbOpenMode = if (restore_repair_needed) .restore_repair else .startup_catch_up;
        // A provisioned writer is the generation owner. Index repair leases
        // that owner instead of opening a second DB over the same path; cold
        // startup recovery retains its dedicated short-lived cache.
        const startup_cache = if (use_live_repair_cache) null else self.startup_write_cache;
        var cached_db: ?ProvisionedTableWriteCache.CachedDb = null;
        defer if (cached_db) |*cached| cached.deinit(alloc);
        var uncached_db: ?db_mod.DB = null;
        var uncached_promotion_owner_state: ProvisionedTableWriteCache.PromotionOwnerState = .{};
        const db = db_blk: {
            if (live_repair_guard) |guard| break :db_blk guard.db;
            if (startup_cache) |cache| {
                cached_db = self.getOrOpenCachedDbModeWithMetadata(alloc, cache, path, group_id, table_name, startup_open_mode, null, null, .{
                    .indexes_json = indexes_json,
                    .schema_json = metadata.schema_json,
                    .identity_namespace = identity_namespace,
                }) catch |err| {
                    if (err == error.LsmRootWriterAlreadyOpen) return busy_result;
                    if (isTerminalStartupCatchUpOpenFailure(err)) {
                        const terminal_status_published = try publishTerminalStartupCatchUpRuntimeStatus(self, alloc, table_name, group_id, opening_db_startup, configured_indexes, err);
                        return .{
                            .had_debt = true,
                            .terminal_degraded = true,
                            .index_repair_pending = !terminal_status_published,
                        };
                    }
                    return err;
                };
                break :db_blk cached_db.?.db;
            }

            const effective_ha_mirror = haMirrorForManagedDbOpenMode(startup_open_mode, self.ha_async_mirror);
            uncached_db = if (indexes_json) |value|
                openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
                    alloc,
                    path,
                    value,
                    null,
                    null,
                    lsm_root_generation,
                    null,
                    startup_open_mode,
                    self.backend_runtime,
                    self.antfly_provider,
                    self.secret_store,
                    self.remote_content,
                    identity_namespace,
                    .{
                        .drain_resolver_backfill = false,
                        .schema_json_before_index_load = metadata.schema_json,
                        .inference_api_url = self.inference_api_url,
                        .ha_write_gate = self.ha_write_gate,
                        .ha_async_effect_mirror = effective_ha_mirror,
                        .ha_async_batch_mirror = effective_ha_mirror,
                        .ha_async_metadata_mirror = effective_ha_mirror,
                    },
                ) catch |err| {
                    if (err == error.LsmRootWriterAlreadyOpen) return busy_result;
                    if (isTerminalStartupCatchUpOpenFailure(err)) {
                        const terminal_status_published = try publishTerminalStartupCatchUpRuntimeStatus(self, alloc, table_name, group_id, opening_db_startup, configured_indexes, err);
                        return .{
                            .had_debt = true,
                            .terminal_degraded = true,
                            .index_repair_pending = !terminal_status_published,
                        };
                    }
                    return err;
                }
            else
                db_mod.DB.open(alloc, path, .{
                    .open_mode = .writer_no_replay,
                    .lsm_root_generation = lsm_root_generation,
                    .backend_runtime = self.backend_runtime,
                    .start_index_workers = false,
                    .start_optional_runtimes = false,
                    .ttl_cleanup = .{ .enabled = false },
                    .transaction_recovery = .{ .enabled = false },
                    .text_merge = .{ .enabled = false },
                    .identity_namespace = identity_namespace,
                    .prefer_existing_identity_namespace = identity_namespace != null,
                    .ha_write_gate = self.ha_write_gate,
                    .ha_async_effect_mirror = effective_ha_mirror,
                    .ha_async_batch_mirror = effective_ha_mirror,
                    .ha_async_metadata_mirror = effective_ha_mirror,
                }) catch |err| {
                    if (err == error.LsmRootWriterAlreadyOpen) return busy_result;
                    if (isTerminalStartupCatchUpOpenFailure(err)) {
                        const terminal_status_published = try publishTerminalStartupCatchUpRuntimeStatus(self, alloc, table_name, group_id, opening_db_startup, configured_indexes, err);
                        return .{
                            .had_debt = true,
                            .terminal_degraded = true,
                            .index_repair_pending = !terminal_status_published,
                        };
                    }
                    return err;
                };
            errdefer if (uncached_db) |*owned| owned.close();
            try validateProvisionedDbIdentityNamespaceExpected(identity_namespace, &uncached_db.?);
            self.applyRuntimeHooksToUncachedDb(&uncached_db.?, table_name, group_id, &uncached_promotion_owner_state);
            try uncached_db.?.drainResolverBackfill();
            break :db_blk &uncached_db.?;
        };
        defer if (uncached_db) |*owned| owned.close();
        _ = try db.runDueLsmObsoleteReclaimUntilIdle(startup_obsolete_reclaim_max_steps);
        var startup_status_active = true;
        defer if (startup_status_active) {
            // Every post-acquisition exit retires the transient startup marker
            // while the generation lease is still alive.
            publishStartupCatchUpRuntimeStatusSnapshot(
                self,
                alloc,
                table_name,
                group_id,
                .{},
                db,
                configured_indexes,
            ) catch {};
        };
        try finishManagedMaintenanceStatusPublication(publishStartupCatchUpRuntimeStatusSnapshot(
            self,
            alloc,
            table_name,
            group_id,
            startupCatchUpStatsForPhase(.opening_db, db),
            db,
            configured_indexes,
        ));
        var live_broad_recovery = false;
        if (metadata.advance_index_repairs and use_live_repair_cache) {
            live_broad_recovery = try managedDbHasBroadCatchUpDebt(alloc, db);
            if (live_broad_recovery) {
                // Broad recovery must exclude readers, but the live repair
                // admission above deliberately allows them. Drop that guard
                // and reacquire the ordinary lifecycle owner while retaining
                // the DB lease so its root cannot be retired in the handoff.
                self.endGroupOperation(table_name, group_id);
                group_operation_active = false;
                if (!self.tryBeginGroupOperation(table_name, group_id)) return busy_result;
                group_operation_active = true;
            } else {
                // The repair lease keeps the authoritative DB/root alive,
                // while the activation callback fences leadership and root
                // generation. Releasing the broad lifecycle guard prevents a
                // multi-minute corpus scan from head-of-line blocking
                // unrelated group work.
                self.endGroupOperation(table_name, group_id);
                group_operation_active = false;
            }
        }
        var restore_index_prerequisite = false;
        var result = catchUpManagedDb(
            self,
            alloc,
            group_id,
            table_name,
            db,
            metadata.advance_index_repairs,
            if (use_live_repair_cache) .live_writer else .isolated,
            if (live_broad_recovery)
                .broad_debt_only
            else if (metadata.advance_index_repairs and use_live_repair_cache)
                .index_repair_only
            else
                .all_debt,
            metadata.index_repair_options,
        ) catch |err| result_blk: {
            if (live_broad_recovery and err == error.RestoreIndexAvailabilityIncomplete) {
                restore_index_prerequisite = true;
                break :result_blk StartupCatchUpResult{
                    .had_debt = true,
                    .made_progress = true,
                    .index_repair_pending = true,
                };
            }
            return err;
        };
        if (live_broad_recovery and !result.terminal_degraded) {
            if (restore_index_prerequisite) {
                // Restore's final availability proof depends on repairing the
                // unavailable generation. Release broad exclusivity before
                // that corpus-sized candidate build, then retain this exact
                // route so the next quantum can finish restore proof.
                self.endGroupOperation(table_name, group_id);
                group_operation_active = false;
                const repair_result = try catchUpManagedDb(
                    self,
                    alloc,
                    group_id,
                    table_name,
                    db,
                    true,
                    .live_writer,
                    .index_repair_prerequisite,
                    metadata.index_repair_options,
                );
                mergeLiveIndexRepairResult(&result, repair_result);
                if (!result.terminal_degraded and !result.index_repair_paused) {
                    result.busy = true;
                    result.index_repair_pending = true;
                }
            } else if (try managedDbHasBroadCatchUpDebt(alloc, db)) {
                // Keep the exact route alive even if its original index intent
                // completed concurrently. With a resident writer this same
                // owner is the only path that can continue broad recovery.
                result.cleared_debt = false;
                result.busy = true;
                result.index_repair_pending = true;
            } else {
                // The exclusive phase is complete. Release it before entering
                // the corpus-sized index quantum, then combine only durable
                // progress facts from the broad phase with the authoritative
                // repair outcome.
                self.endGroupOperation(table_name, group_id);
                group_operation_active = false;
                const repair_result = try catchUpManagedDb(
                    self,
                    alloc,
                    group_id,
                    table_name,
                    db,
                    true,
                    .live_writer,
                    .index_repair_only,
                    metadata.index_repair_options,
                );
                mergeLiveIndexRepairResult(&result, repair_result);
            }
        }
        // The live repair quantum deliberately releases mutation ownership
        // while scanning its candidate corpus. Reacquire exact group
        // ownership before trusting durable repair state, and retain it until
        // that state has been published and its handoff settled. This orders
        // the audit by durable commits rather than by visibility-hook callback
        // arrival, since a concurrent operator repair cannot enter this
        // boundary.
        if (!group_operation_active) {
            if (!self.tryBeginReadCompatibleGroupOperation(table_name, group_id)) {
                result.had_debt = true;
                result.busy = true;
                result.index_repair_pending = true;
                self.retainRepairRouteForPendingHandoffBestEffort(table_name, group_id, &result);
                self.updateStartupCatchUpBackoff(group_id, startupCatchUpMonotonicMs(), backoff_epoch, &result);
                preserve_startup_cache = shouldPreserveStartupWriteCache(result);
                return result;
            }
            group_operation_active = true;
        }

        const final_repair_summary = try db.indexRepairIntentSummary(alloc);
        const final_index_load_failure = try managedDbHasIndexLoadFailure(alloc, db);
        const final_restore_repair_needed = try db.restoreRuntimeRepairNeeded();
        const final_broad_debt = metadata.advance_index_repairs and try managedDbHasBroadCatchUpDebt(alloc, db);
        result.index_repair_paused = false;
        result.terminal_degraded = false;
        if (final_restore_repair_needed and final_index_load_failure) {
            // Restore cannot prove projection availability while any required
            // generation is unavailable. Preserve the original fail-closed
            // precedence even if that generation also has a runnable intent.
            result.had_debt = true;
            result.terminal_degraded = true;
            result.index_repair_pending = !try publishTerminalStartupRuntimeStatusSnapshot(self, alloc, table_name, group_id, db);
            startup_status_active = false;
        } else if (final_repair_summary.runnable != 0) {
            result.had_debt = true;
            result.index_repair_pending = true;
        } else if (final_repair_summary.terminal != 0 or final_index_load_failure) {
            result.had_debt = true;
            result.terminal_degraded = true;
            result.index_repair_pending = !try publishTerminalStartupRuntimeStatusSnapshot(self, alloc, table_name, group_id, db);
            startup_status_active = false;
        } else if (final_broad_debt) {
            result.had_debt = true;
            result.index_repair_pending = true;
        } else {
            result.index_repair_pending = false;
            result.index_repair_paused = final_repair_summary.paused != 0;
            if (result.index_repair_paused) result.had_debt = true;
            self.markRepairHandoffOwnerAuditCompleteBestEffort(table_name, group_id);
        }
        self.retireReadersAfterIndexRepairCompletion(table_name, result);
        if (result.terminal_degraded) {
            // The terminal observation was published from the final durable
            // audit above. Do not relabel it as a fresh live-writer snapshot.
            startup_status_active = false;
        } else if (result.index_repair_attempted or result.index_repair_repaired) {
            // Repair completion changes durable lifecycle fields that the
            // bounded best-effort overlay intentionally does not reload. Take
            // one authoritative snapshot at that boundary so a removed repair
            // intent cannot remain operator-visible in the cached status.
            try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhaseMode(
                self,
                alloc,
                table_name,
                group_id,
                .idle,
                .consistent,
                db,
            ));
            startup_status_active = false;
        } else {
            try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(self, alloc, table_name, group_id, .idle, db));
            startup_status_active = false;
        }
        // A fenced status observation cannot carry its clear authorization
        // beyond the operation lease. Retain the exact route, revoke that
        // authorization, and require the next pass to audit again.
        self.finishRepairHandoffPublicationAttemptBestEffort(table_name, group_id, &result);
        self.updateStartupCatchUpBackoff(group_id, startupCatchUpMonotonicMs(), backoff_epoch, &result);
        preserve_startup_cache = shouldPreserveStartupWriteCache(result);
        return result;
    }

    fn shouldPreserveStartupWriteCache(result: StartupCatchUpResult) bool {
        // A delegated repair is an ownership transfer, not a zero-progress
        // retry. Retaining this writer would prevent the durable repair owner
        // and structural reconciler from opening the shard.
        return result.had_debt and !result.cleared_debt and
            !result.terminal_degraded and !result.busy and !result.made_progress and
            !result.index_repair_pending;
    }

    fn retireReadersAfterIndexRepairCompletion(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        result: StartupCatchUpResult,
    ) void {
        if (!result.index_repair_repaired and !result.cleared_debt) return;
        // The isolated startup/repair owner is deliberately short-lived and
        // may not carry the cached writer's visibility hook. Retire readers
        // before publishing clean status so readiness can never race ahead of
        // the query generation that observes that proof.
        self.invalidateReadCache(table_name);
    }

    fn startupCatchUpRetryAt(self: *ProvisionedTableWriteSource, group_id: u64, now_ms: u64) ?u64 {
        lockAtomic(&self.startup_catch_up_backoff_mutex);
        defer self.startup_catch_up_backoff_mutex.unlock();
        const state = self.startup_catch_up_backoffs.get(group_id) orelse return null;
        if (state.retry_at_ms == 0 or now_ms >= state.retry_at_ms) return null;
        return state.retry_at_ms;
    }

    pub fn clearStartupCatchUpBackoffs(self: *ProvisionedTableWriteSource) void {
        lockAtomic(&self.startup_catch_up_backoff_mutex);
        defer self.startup_catch_up_backoff_mutex.unlock();
        _ = self.startup_catch_up_backoff_epoch.fetchAdd(1, .release);
        self.startup_catch_up_backoffs.deinit(self.startup_catch_up_backoff_alloc);
        self.startup_catch_up_backoffs = .empty;
    }

    fn updateStartupCatchUpBackoff(
        self: *ProvisionedTableWriteSource,
        group_id: u64,
        now_ms: u64,
        expected_epoch: u64,
        result: *StartupCatchUpResult,
    ) void {
        lockAtomic(&self.startup_catch_up_backoff_mutex);
        defer self.startup_catch_up_backoff_mutex.unlock();
        if (self.startup_catch_up_backoff_epoch.load(.acquire) != expected_epoch) return;
        if (result.busy) return;
        // Durable generation repair has its own owner, queue, and retry
        // policy. Once catch-up has handed that debt off, retaining a startup
        // backoff would make two schedulers compete for the same DB and can
        // falsely quarantine healthy, progressing repair work.
        if (!result.had_debt or result.cleared_debt or result.made_progress or result.index_repair_pending or result.index_repair_paused) {
            _ = self.startup_catch_up_backoffs.remove(group_id);
            return;
        }

        const entry = self.startup_catch_up_backoffs.getOrPut(self.startup_catch_up_backoff_alloc, group_id) catch |err| {
            // Allocation pressure must not disable the anti-spin invariant.
            // The scheduler consumes this result and parks the whole catch-up
            // pass even though no per-group state could be stored.
            result.quarantined = true;
            result.quarantine_retry_scheduled = true;
            result.retry_at_ms = now_ms +| startup_catch_up_quarantine_base_ms;
            std.log.warn("startup catch-up backoff allocation failed group={} retry_at_ms={} err={s}", .{
                group_id,
                result.retry_at_ms,
                @errorName(err),
            });
            return;
        };
        if (!entry.found_existing) entry.value_ptr.* = .{};
        entry.value_ptr.consecutive_no_progress +|= 1;
        if (entry.value_ptr.consecutive_no_progress < startup_catch_up_no_progress_threshold) return;

        const exponent = @min(
            entry.value_ptr.consecutive_no_progress - startup_catch_up_no_progress_threshold,
            8,
        );
        const delay_ms = @min(
            startup_catch_up_quarantine_base_ms << @intCast(exponent),
            startup_catch_up_quarantine_max_ms,
        );
        entry.value_ptr.retry_at_ms = now_ms +| delay_ms;
        result.quarantined = true;
        result.quarantine_retry_scheduled = true;
        result.retry_at_ms = entry.value_ptr.retry_at_ms;
    }

    pub const LsmMaintenanceRoundResult = struct {
        progressed: bool = false,
        group_id: ?u64 = null,
    };

    pub fn runLsmMaintenanceRound(self: *ProvisionedTableWriteSource) !bool {
        return (try self.runLsmMaintenanceRoundDetailed()).progressed;
    }

    pub fn runLsmMaintenanceRoundDetailed(self: *ProvisionedTableWriteSource) !LsmMaintenanceRoundResult {
        var primary_only = false;
        var leased = blk: {
            lockAtomic(&self.local_db_mutex);
            defer self.local_db_mutex.unlock();
            const cache = self.write_cache orelse return .{};
            if (cache.leaseLsmMaintenanceDueLocked()) |lease| break :blk lease;
            if (cache.leasePrimaryLsmMaintenanceDueLocked()) |lease| {
                primary_only = true;
                break :blk lease;
            }
            if (cache.maxLsmMaintenanceScoreLocked() != 0) {
                if (cache.leaseLsmMaintenanceRoundLocked()) |lease| break :blk lease;
            }
            // Dense replay can suppress index-LSM maintenance while the
            // primary store independently accumulates debt. The blocking
            // maintenance lane must retain the same primary-only fallback as
            // the best-effort lane, otherwise a forced fair turn still does
            // no work under sustained public ingestion.
            if (cache.maxPrimaryLsmMaintenanceScoreLocked() == 0) return .{};
            primary_only = true;
            break :blk cache.leasePrimaryLsmMaintenanceRoundLocked() orelse return .{};
        };
        defer {
            const release_alloc = if (leased.cache) |cache| cache.alloc else std.heap.page_allocator;
            leased.deinit(release_alloc);
        }
        const maintenance_table_name = if (leased.entry) |entry| entry.table_name else null;
        const progressed = if (primary_only)
            try leased.db.runPrimaryLsmMaintenanceStep()
        else
            try leased.db.runLsmMaintenanceStep();
        if (maintenance_table_name) |table_name| {
            const should_invalidate_read_cache = progressed or blk: {
                const stats = leased.db.trySnapshotLsmMaintenanceStats() orelse break :blk false;
                break :blk stats.obsolete_paths_pinned_by_versions != 0;
            };
            if (should_invalidate_read_cache) self.invalidateReadCache(table_name);
        }
        return .{
            .progressed = progressed,
            .group_id = if (leased.entry) |entry| entry.group_id else null,
        };
    }

    pub fn runLsmMaintenanceRoundBestEffort(self: *ProvisionedTableWriteSource) !bool {
        return (try self.runLsmMaintenanceRoundBestEffortDetailed()).progressed;
    }

    pub fn runLsmMaintenanceRoundBestEffortDetailed(self: *ProvisionedTableWriteSource) !LsmMaintenanceRoundResult {
        if (!self.local_db_mutex.tryLock()) return .{};
        var primary_only = false;
        var leased = blk: {
            defer self.local_db_mutex.unlock();
            const cache = self.write_cache orelse return .{};
            if (cache.leaseLsmMaintenanceDueLocked()) |lease| break :blk lease;
            if (cache.leasePrimaryLsmMaintenanceDueLocked()) |lease| {
                primary_only = true;
                break :blk lease;
            }
            if (cache.maxLsmMaintenanceScoreLocked() != 0) {
                if (cache.leaseLsmMaintenanceRoundBestEffortLocked()) |lease| break :blk lease;
            }
            if (cache.maxPrimaryLsmMaintenanceScoreLocked() == 0) return .{};
            primary_only = true;
            break :blk cache.leasePrimaryLsmMaintenanceRoundBestEffortLocked() orelse return .{};
        };
        defer {
            const release_alloc = if (leased.cache) |cache| cache.alloc else std.heap.page_allocator;
            leased.deinit(release_alloc);
        }
        const maintenance_table_name = if (leased.entry) |entry| entry.table_name else null;
        const progressed = if (primary_only)
            try leased.db.runPrimaryLsmMaintenanceStepBestEffort()
        else
            try leased.db.runLsmMaintenanceStepBestEffort();
        if (maintenance_table_name) |table_name| {
            const should_invalidate_read_cache = progressed or blk: {
                const stats = leased.db.trySnapshotLsmMaintenanceStats() orelse break :blk false;
                break :blk stats.obsolete_paths_pinned_by_versions != 0;
            };
            if (should_invalidate_read_cache) self.invalidateReadCache(table_name);
        }
        return .{
            .progressed = progressed,
            .group_id = if (leased.entry) |entry| entry.group_id else null,
        };
    }

    pub fn runDensePostingMaintenanceRoundBestEffort(self: *ProvisionedTableWriteSource) !usize {
        if (!self.local_db_mutex.tryLock()) return 0;
        var leases = std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb).empty;
        var lease_alloc: std.mem.Allocator = std.heap.page_allocator;
        {
            defer self.local_db_mutex.unlock();
            const cache = self.write_cache orelse return 0;
            lease_alloc = cache.alloc;
            for (cache.entries.items) |entry| {
                if (entry.bulk_ingest_session_open) continue;
                if (entry.db.hasActiveDenseBulkWork()) continue;
                try leases.append(lease_alloc, cache.leaseEntryLocked(entry));
            }
        }
        defer {
            for (leases.items) |*lease| lease.deinit(lease_alloc);
            leases.deinit(lease_alloc);
        }
        var total_steps: usize = 0;
        for (leases.items) |lease| {
            total_steps += lease.db.runDensePostingMaintenanceForIdle() catch |err| blk: {
                std.log.warn("dense posting maintenance round failed: {}", .{err});
                break :blk 0;
            };
        }
        return total_steps;
    }

    pub fn finishExpiredAutoBulkIngestBestEffort(self: *ProvisionedTableWriteSource) bool {
        return self.tryFinishExpiredAutoBulkIngest() orelse false;
    }

    pub fn tryFinishExpiredAutoBulkIngestAndPublishStatus(self: *ProvisionedTableWriteSource, alloc: std.mem.Allocator) ?bool {
        var leases = std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb).empty;
        defer {
            for (leases.items) |*lease| {
                const release_alloc = if (lease.cache) |cache| cache.alloc else std.heap.page_allocator;
                lease.deinit(release_alloc);
            }
            leases.deinit(alloc);
        }

        if (!self.local_db_mutex.tryLock()) return null;
        const finished = self.finishExpiredAutoBulkIngestLockedCollectingStatusLeases(alloc, &leases);
        self.local_db_mutex.unlock();

        self.publishRuntimeStatusLeaseSnapshots(alloc, leases.items);
        return finished;
    }

    pub fn tryFinishExpiredAutoBulkIngest(self: *ProvisionedTableWriteSource) ?bool {
        if (!self.local_db_mutex.tryLock()) return null;
        defer self.local_db_mutex.unlock();

        return self.finishExpiredAutoBulkIngestLocked();
    }

    pub fn finishExpiredAutoBulkIngest(self: *ProvisionedTableWriteSource) bool {
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();

        return self.finishExpiredAutoBulkIngestLocked();
    }

    /// Publishes any primary-store bulk window before a lifecycle operation
    /// snapshots the group's authoritative DB. This runs through the cache
    /// owner so both DB state and cache session bookkeeping transition
    /// atomically with respect to writer admission.
    pub fn finishManagedWriterAutoBulkForTransition(
        self: *ProvisionedTableWriteSource,
        group_id: u64,
        table_name: []const u8,
    ) !void {
        const FinishLease = struct {
            cached: ProvisionedTableWriteCache.CachedDb,
            finished: bool = false,
        };
        var leases = std.ArrayListUnmanaged(FinishLease).empty;
        defer {
            for (leases.items) |*item| {
                const alloc = item.cached.cache.?.alloc;
                item.cached.deinit(alloc);
            }
            leases.deinit(std.heap.page_allocator);
        }

        lockAtomic(&self.local_db_mutex);
        var state_locked = true;
        defer if (state_locked) self.local_db_mutex.unlock();

        const caches = [_]?*ProvisionedTableWriteCache{
            self.write_cache,
            if (self.startup_write_cache != self.write_cache)
                self.startup_write_cache
            else
                null,
        };
        var matching_entries: usize = 0;
        for (caches) |maybe_cache| {
            const cache = maybe_cache orelse continue;
            // An explicit table-scoped session may have adopted an automatic
            // session. It owns publication until its matching finish/abort.
            if (cache.findActiveBulkIngestSession(table_name) != null)
                return error.AutoBulkIngestBusy;
            for (cache.entries.items) |entry| {
                if (entry.group_id != group_id or
                    !std.mem.eql(u8, entry.table_name, table_name))
                {
                    continue;
                }
                if (entry.auto_bulk_ingest_finishing)
                    return error.AutoBulkIngestBusy;
                if (!entry.auto_bulk_ingest_session_open) continue;
                if (cache.entryActiveLeasesLocked(entry) != 0)
                    return error.AutoBulkIngestBusy;
                matching_entries += 1;
            }
        }
        try leases.ensureTotalCapacity(std.heap.page_allocator, matching_entries);
        for (caches) |maybe_cache| {
            const cache = maybe_cache orelse continue;
            for (cache.entries.items) |entry| {
                if (entry.group_id != group_id or
                    !std.mem.eql(u8, entry.table_name, table_name) or
                    !entry.auto_bulk_ingest_session_open)
                {
                    continue;
                }
                entry.auto_bulk_ingest_finishing = true;
                leases.appendAssumeCapacity(.{
                    .cached = cache.leaseEntryLocked(entry),
                });
            }
        }
        self.local_db_mutex.unlock();
        state_locked = false;

        var first_err: ?anyerror = null;
        for (leases.items) |*item| {
            item.cached.db.finishPrimaryStoreAutoBulkIngestSessionWithOptions(
                auto_bulk_ingest_finish_options,
            ) catch |err| {
                if (first_err == null) first_err = err;
                continue;
            };
            item.finished = true;
        }

        lockAtomic(&self.local_db_mutex);
        state_locked = true;
        for (leases.items) |*item| {
            const entry = item.cached.entry orelse continue;
            if (item.finished) {
                ProvisionedTableWriteCache.clearEntryBulkIngestState(entry);
            } else {
                entry.auto_bulk_ingest_finishing = false;
            }
        }
        for (caches) |maybe_cache| {
            const cache = maybe_cache orelse continue;
            cache.removeInactiveBulkIngestSessionLocked(table_name);
        }
        if (first_err) |err| return err;
    }

    fn finishExpiredAutoBulkIngestLocked(self: *ProvisionedTableWriteSource) bool {
        return self.finishExpiredAutoBulkIngestLockedCollectingStatusLeases(std.heap.page_allocator, null);
    }

    fn finishExpiredAutoBulkIngestLockedCollectingStatusLeases(
        self: *ProvisionedTableWriteSource,
        lease_alloc: std.mem.Allocator,
        finished_leases: ?*std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb),
    ) bool {
        const now_ns = platform_time.monotonicNs();
        var finished_any = false;
        if (self.write_cache) |cache| {
            finished_any = (cache.finishExpiredAutoBulkIngestLockedWithStatusLeases(now_ns, lease_alloc, finished_leases) catch |err| {
                if (!isTransientReplayVisibilityError(err)) {
                    std.log.warn("auto bulk ingest background finish failed err={s}", .{@errorName(err)});
                }
                return false;
            }) or finished_any;
        }
        if (self.startup_write_cache) |cache| {
            finished_any = (cache.finishExpiredAutoBulkIngestLockedWithStatusLeases(now_ns, lease_alloc, finished_leases) catch |err| {
                if (!isTransientReplayVisibilityError(err)) {
                    std.log.warn("startup auto bulk ingest background finish failed err={s}", .{@errorName(err)});
                }
                return finished_any;
            }) or finished_any;
        }
        return finished_any;
    }

    pub fn publishCachedWriterRuntimeStatusesBestEffort(self: *ProvisionedTableWriteSource, alloc: std.mem.Allocator) void {
        var leases = std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb).empty;
        defer {
            for (leases.items) |*lease| {
                const release_alloc = if (lease.cache) |cache| cache.alloc else std.heap.page_allocator;
                lease.deinit(release_alloc);
            }
            leases.deinit(alloc);
        }

        if (!self.local_db_mutex.tryLock()) return;
        self.collectAllRuntimeStatusLeasesFromCacheLocked(alloc, self.write_cache, &leases) catch {
            self.local_db_mutex.unlock();
            return;
        };
        self.collectAllRuntimeStatusLeasesFromCacheLocked(alloc, self.startup_write_cache, &leases) catch {
            self.local_db_mutex.unlock();
            return;
        };
        self.local_db_mutex.unlock();

        self.publishRuntimeStatusLeaseSnapshots(alloc, leases.items);
    }

    fn publishDirtyWriteCacheRuntimeStatusesBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) void {
        if (!self.isWriteCacheDirtyForTable(table_name)) return;
        self.publishWriteCacheRuntimeStatusesForTableBestEffort(alloc, table_name);
    }

    fn publishWriteCacheRuntimeStatusesForTableBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) void {
        // Status is derived observability state. Never queue it behind a
        // structural transition: callers can already hold a table request or
        // group operation, and re-entering writer-preferring admission while a
        // reconcile waits would deadlock both sides. The dirty bit keeps a
        // skipped publication retryable by the background status publisher.
        if (!self.tryBeginTableRequest(table_name)) return;
        defer self.endTableRequest(table_name);

        var leases = std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb).empty;
        defer {
            for (leases.items) |*lease| {
                const release_alloc = if (lease.cache) |cache| cache.alloc else std.heap.page_allocator;
                lease.deinit(release_alloc);
            }
            leases.deinit(alloc);
        }

        lockAtomic(&self.local_db_mutex);
        const has_leases = self.collectRuntimeStatusLeasesFromWriteCacheLocked(alloc, table_name, &leases) catch {
            self.local_db_mutex.unlock();
            self.drainWriteCachePendingCloses();
            return;
        };
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();
        if (!has_leases) return;

        self.publishRuntimeStatusLeaseSnapshots(alloc, leases.items);
    }

    fn publishRuntimeStatusLeaseSnapshots(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        leases: []const ProvisionedTableWriteCache.CachedDb,
    ) void {
        for (leases) |lease| {
            const entry = lease.entry orelse continue;
            publishRuntimeStatusSnapshot(self, alloc, entry.table_name, entry.group_id, lease.db) catch |err| switch (err) {
                error.RuntimeStatusPublicationFenced, error.WriterLocked => std.log.debug("cached writer runtime status publication deferred table={s} group_id={} err={s}", .{
                    entry.table_name,
                    entry.group_id,
                    @errorName(err),
                }),
                else => std.log.warn("cached writer runtime status publish failed table={s} group_id={} err={s}", .{
                    entry.table_name,
                    entry.group_id,
                    @errorName(err),
                }),
            };
        }
    }

    fn collectAllRuntimeStatusLeasesFromCacheLocked(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        maybe_cache: ?*ProvisionedTableWriteCache,
        out: *std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb),
    ) !void {
        const cache = maybe_cache orelse return;
        for (cache.entries.items) |entry| {
            if (entry.lsm_root_generation != self.visibleRootGeneration(entry.group_id)) continue;
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) continue;
            try cache.appendRuntimeStatusLeaseForEntryLocked(alloc, entry, out);
        }
    }

    pub fn lsmMaintenanceScore(self: *ProvisionedTableWriteSource) u64 {
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        return if (self.write_cache) |cache| @max(
            cache.maxLsmMaintenanceScoreLocked(),
            cache.maxPrimaryLsmMaintenanceScoreLocked(),
        ) else 0;
    }

    pub fn lsmMaintenanceScoreBestEffort(self: *ProvisionedTableWriteSource) u64 {
        if (!self.local_db_mutex.tryLock()) return 0;
        defer self.local_db_mutex.unlock();
        return if (self.write_cache) |cache| @max(
            cache.maxLsmMaintenanceScoreLocked(),
            cache.maxPrimaryLsmMaintenanceScoreLocked(),
        ) else 0;
    }

    pub fn nextLsmMaintenanceWakeDelayNsBestEffort(self: *ProvisionedTableWriteSource) ?u64 {
        if (!self.local_db_mutex.tryLock()) return null;
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return null;

        var delay_ns = cache.nextLsmMaintenanceWakeDelayNsLocked();
        if (cache.nextPrimaryLsmMaintenanceWakeDelayNsLocked()) |candidate| {
            delay_ns = if (delay_ns) |current| @min(current, candidate) else candidate;
        }
        return delay_ns;
    }

    pub fn hasActiveBulkIngestSession(self: *ProvisionedTableWriteSource) bool {
        if (!self.local_db_mutex.tryLock()) return true;
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return false;
        for (cache.entries.items) |entry| {
            if (entry.bulk_ingest_session_open) return true;
        }
        return false;
    }

    /// Holds the table-activity admission mutex for the full HA snapshot.
    /// Existing activity fails closed; new structural/group operations cannot
    /// begin after the preflight while the global mutation barrier is held.
    pub const HASeedCaptureActivityLease = struct {
        source: *ProvisionedTableWriteSource,
        active: bool = true,

        pub fn release(self: *@This()) void {
            if (!self.active) return;
            self.source.table_activity_mutex.unlock(self.source.table_activity_threaded.io());
            self.active = false;
        }
    };

    pub fn acquireHASeedCaptureActivityLease(self: *ProvisionedTableWriteSource) !HASeedCaptureActivityLease {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        errdefer self.table_activity_mutex.unlock(io);

        for (self.active_table_activities.items) |activity| {
            if (activity.table_request_active > 0 or activity.operation_active or activity.structural_active)
                return error.HASeedSnapshotRuntimeBusy;
        }
        if (self.startup_catch_up_active.load(.acquire)) return error.HASeedSnapshotRuntimeBusy;

        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        if (writerCacheHasHASeedBlockingActivity(self.write_cache) or
            writerCacheHasHASeedBlockingActivity(self.startup_write_cache))
            return error.HASeedSnapshotRuntimeBusy;

        return .{ .source = self };
    }

    fn writerCacheHasHASeedBlockingActivity(cache: ?*ProvisionedTableWriteCache) bool {
        const value = cache orelse return false;
        if (value.active_bulk_ingest_sessions.items.len > 0) return true;
        for (value.entries.items) |entry| {
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open or
                entry.auto_bulk_ingest_finish_requested) return true;
        }
        return false;
    }

    /// Exports one managed replica through DB's logical snapshot primitive.
    /// Live backend files are never copied. Ephemeral backends are rejected so
    /// callers cannot mistake process-local state for a restartable seed.
    pub fn captureHASeedReplicaSnapshot(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        snapshot_token: []const u8,
        destination_root: []const u8,
    ) !void {
        var probe = self.probeManagedWriterGroupBestEffort(table_name, group_id);
        defer probe.deinit();
        switch (probe) {
            .unknown => return error.HASeedSnapshotRuntimeBusy,
            .leased => |*cached| return try captureHASeedDbSnapshot(
                alloc,
                cached.db,
                cached.db.core.path,
                snapshot_token,
                destination_root,
            ),
            .absent => {},
        }

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        var io_impl = Io.Threaded.init(alloc, .{});
        defer io_impl.deinit();
        _ = Io.Dir.cwd().statFile(io_impl.io(), path, .{ .follow_symlinks = false }) catch |err| switch (err) {
            error.FileNotFound => return error.HASeedSnapshotReplicaMissing,
            else => return err,
        };
        var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(
            alloc,
            path,
            self.catalog,
            table_name,
            group_id,
            self.backend_runtime,
            self.ha_write_gate,
            null,
        );
        defer db.close();
        return try captureHASeedDbSnapshot(alloc, &db, path, snapshot_token, destination_root);
    }

    fn captureHASeedDbSnapshot(
        alloc: std.mem.Allocator,
        db: *db_mod.DB,
        db_path: []const u8,
        snapshot_token: []const u8,
        destination_root: []const u8,
    ) !void {
        switch (db.primary_backend) {
            .lmdb, .lsm => {},
            .mem, .lsm_memory => return error.HASeedSnapshotUnsupportedBackend,
        }
        const snapshot_root = try std.fmt.allocPrint(alloc, "{s}.snapshots/{s}", .{ db_path, snapshot_token });
        defer alloc.free(snapshot_root);
        var io_impl = Io.Threaded.init(alloc, .{});
        defer io_impl.deinit();
        Io.Dir.cwd().deleteTree(io_impl.io(), snapshot_root) catch {};
        defer Io.Dir.cwd().deleteTree(io_impl.io(), snapshot_root) catch {};
        _ = try db.snapshot(snapshot_token);
        try backups_api.copyDirectoryRecursive(alloc, snapshot_root, destination_root);
    }

    fn hasActiveBulkIngestSessionForTableBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
    ) bool {
        if (!self.local_db_mutex.tryLock()) return true;
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return false;
        return cache.bulkIngestSessionOpenForTable(table_name);
    }

    pub const ManagedWriterGroupProbe = union(enum) {
        absent,
        unknown,
        leased: ProvisionedTableWriteCache.CachedDb,

        pub fn deinit(self: *ManagedWriterGroupProbe) void {
            switch (self.*) {
                .leased => |*cached| {
                    const release_alloc = if (cached.cache) |cache| cache.alloc else std.heap.page_allocator;
                    cached.deinit(release_alloc);
                },
                .absent, .unknown => {},
            }
            self.* = .absent;
        }
    };

    pub fn probeManagedWriterGroupBestEffort(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
    ) ManagedWriterGroupProbe {
        if (!self.local_db_mutex.tryLock()) return .unknown;
        const lsm_root_generation = self.visibleRootGeneration(group_id);
        var leased: ?ProvisionedTableWriteCache.CachedDb = null;
        if (self.write_cache) |cache| {
            leased = cache.snapshotLeaseLocked(group_id, lsm_root_generation, table_name);
        }
        if (leased == null) {
            if (self.startup_write_cache) |cache| {
                leased = cache.snapshotLeaseLocked(group_id, lsm_root_generation, table_name);
            }
        }
        self.local_db_mutex.unlock();
        if (leased) |cached| return .{ .leased = cached };
        return .absent;
    }

    pub fn leaseManagedWriterGroupForTransition(
        self: *ProvisionedTableWriteSource,
        group_id: u64,
    ) ?ProvisionedTableWriteCache.CachedDb {
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        const lsm_root_generation = self.visibleRootGeneration(group_id);
        if (self.write_cache) |cache| {
            if (cache.snapshotGroupLeaseOrAdoptSeededLocked(group_id, lsm_root_generation)) |cached| return cached;
        }
        if (self.startup_write_cache) |cache| {
            if (cache.snapshotGroupLeaseOrAdoptSeededLocked(group_id, lsm_root_generation)) |cached| return cached;
        }
        return null;
    }

    pub fn snapshotManagedWriterGroupStatusBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
    ) !?runtime_status.LocalTableRuntimeStatus {
        return switch (self.probeManagedWriterGroupBestEffort(table_name, group_id)) {
            .absent, .unknown => null,
            .leased => |cached| blk: {
                var owned = cached;
                const release_alloc = if (owned.cache) |cache| cache.alloc else std.heap.page_allocator;
                defer owned.deinit(release_alloc);
                if (self.runtime_status_cache) |snapshot_cache| {
                    if (try snapshot_cache.snapshotGroupStatus(alloc, table_name, group_id)) |cached_status| {
                        var status = cached_status;
                        errdefer status.deinit(alloc);
                        if (runtimeStatusNeedsAuthoritativeLifecycleRefresh(status)) {
                            const fresh_stats = try owned.db.runtimeStatusStatsConsistent(alloc);
                            db_mod.types.freeDBStats(alloc, status.stats);
                            status.stats = fresh_stats;
                        } else {
                            owned.db.overlayRuntimeStatusBestEffort(alloc, &status.stats);
                        }
                        self.markManagedWriterRuntimeStatus(&status);
                        status.lsm_storage_stats = lsmStorageStatsFromDb(owned.db);
                        if (status.created_at_millis == 0) {
                            status.created_at_millis = (owned.db.getGroupCreatedAtMillis(alloc, group_id) catch null) orelse 0;
                        }
                        break :blk status;
                    }
                }
                var status = runtime_status.LocalTableRuntimeStatus{
                    .group_id = group_id,
                    .created_at_millis = (owned.db.getGroupCreatedAtMillis(alloc, group_id) catch null) orelse 0,
                    .stats = try owned.db.runtimeStatusStatsConsistent(alloc),
                    .lsm_storage_stats = lsmStorageStatsFromDb(owned.db),
                };
                self.markManagedWriterRuntimeStatus(&status);
                break :blk status;
            },
        };
    }

    pub fn overlayManagedWriterGroupStatusBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        status: *runtime_status.LocalTableRuntimeStatus,
    ) void {
        switch (self.probeManagedWriterGroupBestEffort(table_name, group_id)) {
            .absent, .unknown => {},
            .leased => |cached| {
                var owned = cached;
                const release_alloc = if (owned.cache) |cache| cache.alloc else std.heap.page_allocator;
                defer owned.deinit(release_alloc);
                owned.db.overlayRuntimeStatusBestEffort(alloc, &status.stats);
                self.markManagedWriterRuntimeStatus(status);
                status.lsm_storage_stats = lsmStorageStatsFromDb(owned.db);
                if (status.created_at_millis == 0) {
                    status.created_at_millis = (owned.db.getGroupCreatedAtMillis(std.heap.page_allocator, group_id) catch null) orelse 0;
                }
            },
        }
    }

    fn markManagedWriterRuntimeStatus(
        _: *ProvisionedTableWriteSource,
        status: *runtime_status.LocalTableRuntimeStatus,
    ) void {
        status.metadata = .{
            .updated_at_ns = platform_time.monotonicNs(),
            .source = .live_writer_publish,
            .freshness = .fresh,
        };
    }

    fn lsmStorageStatsFromDb(db: *db_mod.DB) runtime_status.LsmStorageStats {
        return .{
            .maintenance = db.snapshotLsmMaintenanceStats(),
            .write = db.snapshotLsmWriteStats(),
            .maintenance_score = db.lsmMaintenanceScore(),
            .maintenance_debt_hint = db.lsmMaintenanceDebtHint(),
        };
    }

    pub fn hasGroupActivityBestEffort(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) bool {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        if (self.findTableActivityLocked(table_name, null)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.structural_reconcile_queued > 0 or entry.structural_reconcile_waiters > 0 or entry.restore_preparations > 0) return true;
        }
        if (self.findTableActivityLocked(table_name, group_id)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.operation_active or entry.operation_waiters > 0 or entry.generation_preparation_active) return true;
        }
        return false;
    }

    pub fn hasReadBlockingActivityBestEffort(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) bool {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        if (self.findTableActivityLocked(table_name, null)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.structural_active or entry.structural_waiters > 0 or entry.table_request_active > 0 or entry.read_request_active > 0) return true;
        }
        if (self.findTableActivityLocked(table_name, group_id)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.operation_waiters > 0 or entry.transition_waiters > 0 or (entry.operation_active and !entry.operation_allows_reads)) return true;
        }
        return false;
    }

    fn structuralStatusSnapshotOnlyBestEffort(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        return self.statusUsesPublishedSnapshotLocked(table_name);
    }

    fn readCompatibleMaintenanceActiveBestEffort(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) bool {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);
        if (self.findTableActivityLocked(table_name, null)) |index| {
            // Structural reconciliation invalidates the resident writer while
            // retaining the published read generation. Its reservation stays
            // continuous across cooperative group quanta and queue retries,
            // so it is the authoritative fallback fence between those quanta.
            // Restore/drop use structural_active instead and must never enter
            // this read-compatible path.
            if (self.active_table_activities.items[index].structuralReconcileReserved()) return true;
        }
        const index = self.findTableActivityLocked(table_name, group_id) orelse return false;
        const entry = self.active_table_activities.items[index];
        return entry.operation_active and entry.operation_allows_reads;
    }

    fn activeOperationGroupsForTable(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !struct {
        structural_busy: bool,
        request_busy: bool,
        groups: []u64,
    } {
        const io = self.table_activity_threaded.io();
        self.table_activity_mutex.lockUncancelable(io);
        defer self.table_activity_mutex.unlock(io);

        var structural_busy = false;
        var request_busy = false;
        if (self.findTableActivityLocked(table_name, null)) |index| {
            const entry = self.active_table_activities.items[index];
            if (entry.structural_active or entry.structural_waiters > 0 or entry.structural_reconcile_active or entry.structural_reconcile_queued > 0 or entry.structural_reconcile_waiters > 0 or entry.restore_preparations > 0) structural_busy = true;
            if (entry.table_request_active > 0 or entry.read_request_active > 0) request_busy = true;
        }

        var groups = std.ArrayListUnmanaged(u64).empty;
        errdefer groups.deinit(alloc);
        for (self.active_table_activities.items) |activity| {
            if (!std.mem.eql(u8, activity.table_name, table_name)) continue;
            const group_id = activity.group_id orelse continue;
            if (!activity.operation_active and activity.operation_waiters == 0 and !activity.generation_preparation_active) continue;
            try groups.append(alloc, group_id);
        }

        return .{
            .structural_busy = structural_busy,
            .request_busy = request_busy,
            .groups = try groups.toOwnedSlice(alloc),
        };
    }

    fn takeStatusesWithoutActiveGroups(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        statuses: *runtime_status.LocalTableRuntimeStatuses,
        active_groups: []const u64,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        _ = self;
        if (active_groups.len == 0) {
            const owned = statuses.*;
            statuses.* = .{};
            return owned;
        }

        var keep_count: usize = 0;
        for (statuses.items) |item| {
            for (active_groups) |group_id| {
                if (item.group_id == group_id) break;
            } else {
                keep_count += 1;
            }
        }
        if (keep_count == statuses.items.len) {
            const owned = statuses.*;
            statuses.* = .{};
            return owned;
        }
        if (keep_count == 0) {
            statuses.deinit(alloc);
            statuses.* = .{};
            return null;
        }

        const original_items = statuses.items;
        const items = try alloc.alloc(runtime_status.LocalTableRuntimeStatus, keep_count);
        var write_index: usize = 0;
        for (original_items) |*item| {
            for (active_groups) |group_id| {
                if (item.group_id == group_id) break;
            } else {
                items[write_index] = item.*;
                item.* = undefined;
                write_index += 1;
                continue;
            }
            item.deinit(alloc);
        }

        alloc.free(original_items);
        statuses.* = .{};
        return .{ .items = items };
    }

    fn statusesWithoutActiveGroups(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        statuses: runtime_status.LocalTableRuntimeStatuses,
        active_groups: []const u64,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        var owned = statuses;
        defer owned.deinit(alloc);
        return try self.takeStatusesWithoutActiveGroups(alloc, &owned, active_groups);
    }

    fn appendOrReplaceRuntimeStatusClone(
        alloc: std.mem.Allocator,
        items: *std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus),
        item: runtime_status.LocalTableRuntimeStatus,
    ) !void {
        for (items.items) |*existing| {
            if (existing.group_id != item.group_id) continue;
            var cloned = try item.clone(alloc);
            errdefer cloned.deinit(alloc);
            existing.deinit(alloc);
            existing.* = cloned;
            return;
        }
        var cloned = try item.clone(alloc);
        errdefer cloned.deinit(alloc);
        try items.append(alloc, cloned);
    }

    fn appendOrReplaceRuntimeStatusClones(
        alloc: std.mem.Allocator,
        items: *std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus),
        statuses: *const runtime_status.LocalTableRuntimeStatuses,
    ) !void {
        for (statuses.items) |item| {
            try appendOrReplaceRuntimeStatusClone(alloc, items, item);
        }
    }

    fn mergedRuntimeStatusReplacement(
        alloc: std.mem.Allocator,
        current: *const runtime_status.LocalTableRuntimeStatuses,
        refresh: *const runtime_status.LocalTableRuntimeStatuses,
    ) !runtime_status.LocalTableRuntimeStatuses {
        var merged = std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus).empty;
        errdefer {
            for (merged.items) |*item| item.deinit(alloc);
            merged.deinit(alloc);
        }

        try merged.ensureTotalCapacity(alloc, current.items.len + refresh.items.len);
        try appendOrReplaceRuntimeStatusClones(alloc, &merged, current);
        try appendOrReplaceRuntimeStatusClones(alloc, &merged, refresh);
        return .{ .items = try merged.toOwnedSlice(alloc) };
    }

    fn replaceRuntimeStatusesWithMergedRefresh(
        alloc: std.mem.Allocator,
        statuses: *runtime_status.LocalTableRuntimeStatuses,
        refresh: *const runtime_status.LocalTableRuntimeStatuses,
    ) !void {
        var replacement = try mergedRuntimeStatusReplacement(alloc, statuses, refresh);
        errdefer replacement.deinit(alloc);
        statuses.deinit(alloc);
        statuses.* = replacement;
    }

    fn indexHasVisibilityFactsForStatus(item: db_mod.types.DBIndexStats) bool {
        return item.doc_count > 0 or item.term_count > 0 or item.edge_count > 0 or item.node_count > 0 or item.root_node > 0 or
            item.repair_degraded or item.repair_issue_count != 0;
    }

    fn runtimeStatusNeedsColdVisibilityRefresh(status: runtime_status.LocalTableRuntimeStatus) bool {
        if (status.stats.repair_degraded or status.stats.repair_issue_count != 0) return false;
        const has_primary_facts = status.stats.doc_identity.live_ordinals != 0 or status.stats.doc_count != 0;
        for (status.stats.indexes) |item| {
            if (item.kind != .dense_vector) continue;
            if (indexHasVisibilityFactsForStatus(item)) continue;
            if (item.replay_applied_sequence != 0 or item.replay_target_sequence != 0) continue;
            if (has_primary_facts) return true;
            if (status.metadata.source == .synthetic_config) return true;
            return status.metadata.source == .live_writer_publish;
        }
        return false;
    }

    fn runtimeStatusesNeedColdVisibilityRefresh(statuses: *const runtime_status.LocalTableRuntimeStatuses) bool {
        if (statuses.items.len == 0) return true;
        for (statuses.items) |status| {
            if (runtimeStatusNeedsColdVisibilityRefresh(status)) return true;
        }
        return false;
    }

    fn markRecoveredRuntimeStatuses(statuses: *runtime_status.LocalTableRuntimeStatuses) void {
        const now_ns = platform_time.monotonicNs();
        for (statuses.items) |*item| {
            item.metadata = item.metadata.withDefaults(.cached_snapshot, now_ns);
            item.metadata.source = .cached_snapshot;
            item.metadata.freshness = .fresh;
        }
    }

    fn markRuntimeStatusesStale(statuses: *runtime_status.LocalTableRuntimeStatuses) void {
        for (statuses.items) |*item| {
            if (item.metadata.freshness == .fresh) item.metadata.freshness = .stale;
        }
    }

    fn snapshotRuntimeStatusesFromStorageBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        // Cold inspection may open the same logical root as a foreground
        // writer. Never block the status path or race an in-process writer;
        // the next poll can retry after the owner releases the source lock.
        if (!self.local_db_mutex.tryLock()) return null;
        defer self.local_db_mutex.unlock();

        var recovered = (try snapshotLocalTableRuntimeStatusesUncachedMode(
            alloc,
            self.catalog,
            self.replica_root_dir,
            self.backend_runtime,
            table_name,
            .status_only,
        )) orelse return null;
        errdefer recovered.deinit(alloc);
        if (runtimeStatusesNeedColdVisibilityRefresh(&recovered)) {
            recovered.deinit(alloc);
            recovered = (try snapshotLocalTableRuntimeStatusesUncachedMode(
                alloc,
                self.catalog,
                self.replica_root_dir,
                self.backend_runtime,
                table_name,
                .query_readonly,
            )) orelse return null;
        }
        markRecoveredRuntimeStatuses(&recovered);
        return recovered;
    }

    fn recoverRuntimeStatusesFromStorage(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        const snapshot_cache = self.runtime_status_cache orelse return null;
        const publication_token = try snapshot_cache.capturePublicationToken(table_name);
        var recovered = (try self.snapshotRuntimeStatusesFromStorageBestEffort(alloc, table_name)) orelse return null;
        errdefer recovered.deinit(alloc);
        for (recovered.items) |item| _ = try snapshot_cache.publishGroup(publication_token, table_name, item);
        if (!self.overlayManagedWriterReplayTargetsBestEffort(alloc, table_name, &recovered)) {
            markRuntimeStatusesStale(&recovered);
        }
        return recovered;
    }

    pub fn snapshotRuntimeStatusesBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        return self.snapshotRuntimeStatusesBestEffortWithAdmission(alloc, table_name, false);
    }

    fn snapshotRuntimeStatusesBestEffortWithAdmission(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        snapshot_only: bool,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        if (snapshot_only or self.structuralStatusSnapshotOnlyBestEffort(table_name)) {
            const snapshot_cache = self.runtime_status_cache orelse return null;
            var cached = (try snapshot_cache.snapshot(alloc, table_name)) orelse return null;
            // Structural/index transitions deliberately keep the status path
            // cache-only so it cannot contend with publication. The snapshot
            // remains useful for diagnostics, but it is not authoritative for
            // readiness until live admission resumes.
            markRuntimeStatusesStale(&cached);
            return cached;
        }
        if (self.runtime_status_cache == null) {
            // Standalone/uncached sources have no owner-published status plane
            // to consult. Their caller holds status admission, so a cold
            // read-only inspection is serialized with structural publication
            // without opening a competing writer or changing cache semantics.
            return try self.snapshotRuntimeStatusesFromStorageBestEffort(alloc, table_name);
        }
        // Keep the hot HTTP status path on the cached status plane. After a
        // process restart the cache is empty, or can contain only a synthetic
        // dense placeholder. Production sources delegate recovery to the
        // coalesced runtime owner so status polling never opens a DB inline.
        // Standalone sources without that owner retain guarded synchronous
        // recovery for compatibility.
        const snapshot_cache = self.runtime_status_cache.?;
        var cached = (try snapshot_cache.snapshot(alloc, table_name)) orelse {
            if (self.local_change_hook != null) {
                self.notifyLocalChange(table_name, .runtime_status);
                return null;
            }
            return try self.recoverRuntimeStatusesFromStorage(alloc, table_name);
        };
        errdefer cached.deinit(alloc);
        const needs_cold_refresh = runtimeStatusesNeedColdVisibilityRefresh(&cached);
        if (needs_cold_refresh) {
            if (self.local_change_hook != null) {
                for (cached.items) |*status| status.metadata.freshness = .stale;
                self.notifyLocalChange(table_name, .runtime_status);
                return cached;
            }
            cached.deinit(alloc);
            return try self.recoverRuntimeStatusesFromStorage(alloc, table_name);
        }

        // Cached snapshots are the steady-state status plane, but an active
        // writer can advance derived replay after its last publish, including
        // after primary-write dirtiness has been cleared. Refresh stale/aged
        // snapshots from an already-open writer. Tables without one continue
        // to use the published snapshot, so polling never opens a DB.
        // Reconciliation can spend minutes building an unpublished index on
        // the resident writer. Status is observational and already has an
        // immutable published snapshot; do not contend on live DB stats merely
        // to refresh optional counters during that interval.
        if (!self.structuralStatusSnapshotOnlyBestEffort(table_name)) {
            try self.refreshRuntimeStatusesFromWriteCache(alloc, table_name, &cached);
            if (!self.overlayManagedWriterReplayTargetsBestEffort(alloc, table_name, &cached)) {
                markRuntimeStatusesStale(&cached);
            }
        }
        return cached;
    }

    fn refreshRuntimeStatusesFromWriteCache(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        statuses: *runtime_status.LocalTableRuntimeStatuses,
    ) !void {
        const now_ns = platform_time.monotonicNs();
        if (!runtimeStatusesNeedWriterRefresh(statuses, now_ns)) return;

        var leases = std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb).empty;
        defer {
            for (leases.items) |*lease| {
                const release_alloc = if (lease.cache) |cache| cache.alloc else std.heap.page_allocator;
                lease.deinit(release_alloc);
            }
            leases.deinit(alloc);
        }

        lockAtomic(&self.local_db_mutex);
        const has_leases = self.collectRuntimeStatusLeasesFromWriteCacheLocked(alloc, table_name, &leases) catch |err| {
            self.local_db_mutex.unlock();
            self.drainWriteCachePendingCloses();
            return err;
        };
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();
        if (!has_leases) return;

        var live_statuses = (try self.runtimeStatusesFromCachedDbLeasesBestEffort(alloc, table_name, leases.items)) orelse return;
        defer live_statuses.deinit(alloc);

        try replaceRuntimeStatusesWithMergedRefresh(alloc, statuses, &live_statuses);
    }

    fn runtimeStatusesNeedWriterRefresh(statuses: *const runtime_status.LocalTableRuntimeStatuses, now_ns: u64) bool {
        const min_refresh_interval_ns = std.time.ns_per_s;
        if (statuses.items.len == 0) return true;
        for (statuses.items) |status| {
            // A live-writer publication is still a point-in-time cache entry.
            // Enrichment and derived-index workers can advance immediately
            // after it is published (notably after inline table creation), so
            // treating it as permanently current strands readiness at the
            // pre-replay snapshot. Refresh both recovered and writer-published
            // observations from the already-open writer at the bounded cadence.
            switch (status.metadata.source) {
                .cached_snapshot, .live_writer_publish => {},
                else => continue,
            }
            if (!runtime_status.statusRuntimeFresh(status)) return true;
            if (status.metadata.updated_at_ns == 0) return true;
            if (now_ns -| status.metadata.updated_at_ns >= min_refresh_interval_ns) return true;
        }
        return false;
    }

    fn overlayManagedWriterReplayTargetsBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        statuses: *runtime_status.LocalTableRuntimeStatuses,
    ) bool {
        var leases = std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb).empty;
        defer {
            for (leases.items) |*lease| {
                const release_alloc = if (lease.cache) |cache| cache.alloc else std.heap.page_allocator;
                lease.deinit(release_alloc);
            }
            leases.deinit(alloc);
        }

        if (!self.local_db_mutex.tryLock()) return false;
        self.collectAllRuntimeStatusLeasesFromCacheLocked(alloc, self.write_cache, &leases) catch {
            self.local_db_mutex.unlock();
            return false;
        };
        self.collectAllRuntimeStatusLeasesFromCacheLocked(alloc, self.startup_write_cache, &leases) catch {
            self.local_db_mutex.unlock();
            return false;
        };
        self.local_db_mutex.unlock();

        for (leases.items) |lease| {
            const entry = lease.entry orelse continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            for (statuses.items) |*status| {
                if (status.group_id != entry.group_id) continue;
                overlayRuntimeStatusReplayTargetFromDb(alloc, status, lease.db);
                break;
            }
        }
        return true;
    }

    pub fn lsmMaintenanceStats(self: *ProvisionedTableWriteSource) lsm_backend.Backend.MaintenanceStats {
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        var stats = lsm_backend.Backend.MaintenanceStats{};
        if (self.write_cache) |cache| {
            for (cache.entries.items) |entry| {
                lsm_backend.Backend.accumulateMaintenanceStats(&stats, entry.db.snapshotLsmMaintenanceStats());
            }
        }
        return stats;
    }

    pub fn lsmMaintenanceStatsBestEffort(self: *ProvisionedTableWriteSource) lsm_backend.Backend.MaintenanceStats {
        if (!self.local_db_mutex.tryLock()) return .{};
        defer self.local_db_mutex.unlock();
        var stats = lsm_backend.Backend.MaintenanceStats{};
        if (self.write_cache) |cache| {
            for (cache.entries.items) |entry| {
                if (entry.db.trySnapshotLsmMaintenanceStats()) |entry_stats| {
                    lsm_backend.Backend.accumulateMaintenanceStats(&stats, entry_stats);
                }
            }
        }
        return stats;
    }

    pub fn lsmWriteStatsBestEffort(self: *ProvisionedTableWriteSource) lsm_backend.Backend.WriteStats {
        if (!self.local_db_mutex.tryLock()) return .{};
        defer self.local_db_mutex.unlock();
        var stats = lsm_backend.Backend.WriteStats{};
        if (self.write_cache) |cache| {
            for (cache.entries.items) |entry| {
                if (entry.db.trySnapshotLsmWriteStats()) |entry_stats| {
                    lsm_backend.Backend.accumulateWriteStats(&stats, entry_stats);
                }
            }
        }
        return stats;
    }

    /// Returns a bounded-cardinality attribution snapshot for already-open
    /// writer DBs. Labels identify the table group and concrete LSM owner, so
    /// a primary-store clone cannot be mistaken for dense-index residency (or
    /// vice versa). Contended DBs are skipped rather than delaying /metrics.
    pub fn lsmOwnerStatsBestEffortAlloc(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
    ) ![]LsmOwnerMetricStats {
        // Cumulative fields are observed into BackendRuntime. This temporary
        // result carries only best-effort active gauges while live DBs are
        // sampled; standalone sources without a runtime retain legacy totals.
        var result = std.ArrayListUnmanaged(LsmOwnerMetricStats).empty;
        errdefer {
            for (result.items) |*item| item.deinit(alloc);
            result.deinit(alloc);
        }
        var result_index = LsmOwnerMetricIndex.empty;
        defer result_index.deinit(alloc);

        var write_pins: ?PinnedLsmOwnerEntries = null;
        defer if (write_pins) |*pinned| pinned.deinit(alloc);
        var startup_pins: ?PinnedLsmOwnerEntries = null;
        defer if (startup_pins) |*pinned| pinned.deinit(alloc);

        // Phase 1 captures stable bindings and sizing hints under source state,
        // but performs no allocation. Buffers are allocated after releasing
        // the request-time source mutex.
        var planned_write_cache: ?*ProvisionedTableWriteCache = null;
        var planned_startup_cache: ?*ProvisionedTableWriteCache = null;
        var write_entry_count: ?usize = null;
        var startup_entry_count: ?usize = null;
        if (self.local_db_mutex.tryLock()) {
            planned_write_cache = self.write_cache;
            planned_startup_cache = self.startup_write_cache;
            if (planned_write_cache) |cache| {
                write_entry_count = writeCacheLsmOwnerEntryCountBestEffort(cache);
            }
            if (planned_startup_cache) |cache| {
                if (planned_write_cache == null or planned_write_cache.? != cache) {
                    startup_entry_count = writeCacheLsmOwnerEntryCountBestEffort(cache);
                }
            }
            self.local_db_mutex.unlock();
        }

        var write_storage: ?[]*ProvisionedTableWriteCache.Entry = if (write_entry_count) |count|
            try alloc.alloc(*ProvisionedTableWriteCache.Entry, count)
        else
            null;
        defer if (write_storage) |storage| alloc.free(storage);
        var startup_storage: ?[]*ProvisionedTableWriteCache.Entry = if (startup_entry_count) |count|
            try alloc.alloc(*ProvisionedTableWriteCache.Entry, count)
        else
            null;
        defer if (startup_storage) |storage| alloc.free(storage);

        // Phase 2 revalidates the bindings and installs leases without any
        // allocation. If state changed or either lifecycle mutex is contended,
        // omit only that best-effort active-gauge sample.
        if ((write_storage != null or startup_storage != null) and self.local_db_mutex.tryLock()) {
            if (write_storage) |storage| {
                if (self.write_cache == planned_write_cache) {
                    if (pinWriteCacheLsmOwnerEntriesBestEffort(planned_write_cache.?, storage)) |pinned| {
                        write_pins = pinned;
                        write_storage = null;
                    }
                }
            }
            if (startup_storage) |storage| {
                if (self.startup_write_cache == planned_startup_cache and
                    (self.write_cache == null or self.write_cache.? != planned_startup_cache.?))
                {
                    if (pinWriteCacheLsmOwnerEntriesBestEffort(planned_startup_cache.?, storage)) |pinned| {
                        startup_pins = pinned;
                        startup_storage = null;
                    }
                }
            }
            self.local_db_mutex.unlock();
        }

        if (write_pins) |*pinned| {
            try appendLiveLsmOwnerStatsAlloc(&result, &result_index, alloc, pinned.entries(), self.backend_runtime);
            pinned.deinit(alloc);
            write_pins = null;
        }
        if (startup_pins) |*pinned| {
            try appendLiveLsmOwnerStatsAlloc(&result, &result_index, alloc, pinned.entries(), self.backend_runtime);
            pinned.deinit(alloc);
            startup_pins = null;
        }

        if (self.backend_runtime) |runtime| {
            var cumulative = try runtime.snapshotRetiredLsmOwnerCloneStatsAlloc(alloc);
            // The processed prefix owns no labels: matching entries are freed
            // immediately, while new entries transfer both strings into
            // result. On error, only the untouched suffix still needs deinit.
            var cumulative_processed: usize = 0;
            defer {
                for (cumulative[cumulative_processed..]) |*owner| owner.deinit(alloc);
                alloc.free(cumulative);
            }
            while (cumulative_processed < cumulative.len) : (cumulative_processed += 1) {
                const owner = &cumulative[cumulative_processed];
                const maintenance = archivedLsmOwnerMaintenance(owner.stats);
                const key = lsmOwnerMetricKey(
                    owner.table_name,
                    owner.group_id,
                    owner.owner_kind,
                    owner.owner_name,
                    owner.owner_overflow,
                );
                if (result_index.get(key)) |existing_index| {
                    const existing = &result.items[existing_index];
                    accumulateLsmOwnerCloneMaintenance(&existing.maintenance, maintenance);
                    owner.deinit(alloc);
                } else {
                    try result.ensureUnusedCapacity(alloc, 1);
                    try result_index.ensureUnusedCapacity(alloc, 1);
                    result.appendAssumeCapacity(.{
                        .table_name = owner.table_name,
                        .group_id = owner.group_id,
                        .owner_kind = owner.owner_kind,
                        .owner_name = owner.owner_name,
                        .owner_overflow = owner.owner_overflow,
                        .maintenance = maintenance,
                    });
                    const new_index = result.items.len - 1;
                    const inserted = &result.items[new_index];
                    result_index.putAssumeCapacity(lsmOwnerMetricKey(
                        inserted.table_name,
                        inserted.group_id,
                        inserted.owner_kind,
                        inserted.owner_name,
                        inserted.owner_overflow,
                    ), new_index);
                }
            }
        }
        return try result.toOwnedSlice(alloc);
    }

    pub fn lsmOwnerCloneStatsDroppedTotal(self: *ProvisionedTableWriteSource) u64 {
        const runtime = self.backend_runtime orelse return 0;
        return runtime.retiredLsmOwnerCloneStatsDroppedTotal();
    }

    pub fn lsmOwnerCloneLabelsCollapsedTotal(self: *ProvisionedTableWriteSource) u64 {
        const runtime = self.backend_runtime orelse return 0;
        return runtime.retiredLsmOwnerCloneLabelsCollapsedTotal();
    }

    pub fn lsmNativeStorageStatsBestEffort(self: *ProvisionedTableWriteSource) ?lsm_backend.NativeStorageStats {
        // The descriptor pool belongs to BackendRuntime, not to any cached DB.
        // Sampling it directly keeps process-wide admission pressure visible
        // while the table cache is empty or its state lock is contended.
        if (self.backend_runtime) |runtime| return runtime.snapshotNativeStorageStats();

        // Standalone callers may not bind a backend runtime. Preserve their
        // legacy per-DB fallback while a cache entry is available.
        if (!self.local_db_mutex.tryLock()) return null;
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return null;
        var stats = lsm_backend.NativeStorageStats{};
        var observed = false;
        for (cache.entries.items) |entry| {
            const entry_stats = entry.db.trySnapshotLsmNativeStorageStats() orelse continue;
            observed = true;
            stats.fd_cache_entries = @max(stats.fd_cache_entries, entry_stats.fd_cache_entries);
            stats.fd_admitted_descriptors = @max(stats.fd_admitted_descriptors, entry_stats.fd_admitted_descriptors);
            stats.fd_persistent_descriptors = @max(stats.fd_persistent_descriptors, entry_stats.fd_persistent_descriptors);
            stats.fd_admission_capacity = @max(stats.fd_admission_capacity, entry_stats.fd_admission_capacity);
            stats.fd_persistent_reserve = @max(stats.fd_persistent_reserve, entry_stats.fd_persistent_reserve);
            stats.fd_admission_waiters = @max(stats.fd_admission_waiters, entry_stats.fd_admission_waiters);
            stats.fd_admission_waits = @max(stats.fd_admission_waits, entry_stats.fd_admission_waits);
            stats.fd_persistent_admission_failures = @max(stats.fd_persistent_admission_failures, entry_stats.fd_persistent_admission_failures);
        }
        if (!observed) return null;
        return stats;
    }

    pub fn asyncIndexingStats(self: *ProvisionedTableWriteSource) db_mod.types.AsyncIndexingStats {
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return .{};
        var stats = db_mod.types.AsyncIndexingStats{};
        for (cache.entries.items) |entry| {
            db_mod.types.accumulateAsyncIndexingStats(&stats, entry.db.snapshotAsyncIndexingStats());
        }
        return stats;
    }

    pub fn asyncIndexingStatsBestEffort(self: *ProvisionedTableWriteSource) db_mod.types.AsyncIndexingStats {
        const startup_active = self.startup_catch_up_active.load(.monotonic);
        if (!self.local_db_mutex.tryLock()) {
            if (self.runtime_status_cache) |snapshot_cache| return snapshot_cache.summary().async_indexing;
            return .{};
        }
        defer self.local_db_mutex.unlock();
        if (startup_active) {
            if (self.runtime_status_cache) |snapshot_cache| {
                const cached = snapshot_cache.summary().async_indexing;
                if (cached.startup.active or
                    cached.startup.phase != .idle or
                    cached.dense_catch_up.active or
                    cached.dense_catch_up.phase != .idle or
                    cached.bulk_coalescing.active_session)
                {
                    return cached;
                }
            }
        }
        const cache = self.write_cache orelse {
            if (self.runtime_status_cache) |snapshot_cache| return snapshot_cache.summary().async_indexing;
            return .{};
        };
        var stats = db_mod.types.AsyncIndexingStats{};
        var observed = false;
        for (cache.entries.items) |entry| {
            observed = true;
            db_mod.types.accumulateAsyncIndexingStats(&stats, entry.db.snapshotAsyncIndexingStats());
        }
        if (!observed) {
            if (self.runtime_status_cache) |snapshot_cache| return snapshot_cache.summary().async_indexing;
        }
        return stats;
    }

    pub fn textMemoryAttributionStatsBestEffort(self: *ProvisionedTableWriteSource) db_mod.TextMemoryAttributionStats {
        if (!self.local_db_mutex.tryLock()) return .{};
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return .{};
        var stats = db_mod.TextMemoryAttributionStats{};
        for (cache.entries.items) |entry| {
            const entry_stats = entry.db.trySnapshotTextMemoryAttributionStats() orelse continue;
            accumulateTextMemoryAttributionStats(&stats, entry_stats);
        }
        return stats;
    }

    pub fn textMergeStatsBestEffort(self: *ProvisionedTableWriteSource) db_mod.types.TextMergeStats {
        if (!self.local_db_mutex.tryLock()) {
            if (self.runtime_status_cache) |snapshot_cache| return snapshot_cache.summary().text_merge;
            return .{};
        }
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse {
            if (self.runtime_status_cache) |snapshot_cache| return snapshot_cache.summary().text_merge;
            return .{};
        };
        var stats = db_mod.types.TextMergeStats{};
        var observed = false;
        for (cache.entries.items) |entry| {
            const entry_stats = entry.db.trySnapshotTextMergeStats() orelse continue;
            observed = true;
            db_mod.types.accumulateTextMergeStats(&stats, entry_stats);
        }
        if (!observed) {
            if (self.runtime_status_cache) |snapshot_cache| return snapshot_cache.summary().text_merge;
        }
        return stats;
    }

    pub fn autoBulkIngestStatsBestEffort(self: *ProvisionedTableWriteSource) ProvisionedTableWriteCache.AutoBulkIngestStats {
        if (!self.local_db_mutex.tryLock()) return .{};
        defer self.local_db_mutex.unlock();
        const now_ns = platform_time.monotonicNs();
        var stats = ProvisionedTableWriteCache.AutoBulkIngestStats{};
        if (self.write_cache) |cache| stats.merge(cache.autoBulkIngestStatsLocked(now_ns));
        if (self.startup_write_cache) |cache| stats.merge(cache.autoBulkIngestStatsLocked(now_ns));
        return stats;
    }

    pub fn cachedWriteDbCount(self: *ProvisionedTableWriteSource) usize {
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return 0;
        return cache.entries.items.len;
    }

    pub fn cachedWriteDbCountBestEffort(self: *ProvisionedTableWriteSource) usize {
        if (!self.local_db_mutex.tryLock()) return 0;
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return 0;
        return cache.entries.items.len;
    }

    pub const ResidentWriterRepairState = enum {
        absent,
        clean,
        pending,
        busy,
    };

    /// Returns whether a resident writer can safely replace fallback repair
    /// discovery. Presence alone is insufficient: structural mutations can
    /// leave repair-summary rebuild work or a durable generation intent on an
    /// otherwise healthy writer. Take a lease under the cache mutex, then
    /// inspect the DB after releasing it to preserve DB/cache lock ordering.
    pub fn residentWriterRepairStateBestEffort(
        self: *ProvisionedTableWriteSource,
        group_id: u64,
        table_name: []const u8,
    ) ResidentWriterRepairState {
        if (!self.local_db_mutex.tryLock()) return .busy;
        var resident: ?ProvisionedTableWriteCache.CachedDb = null;
        var foreground_blocked = false;
        if (self.write_cache) |cache| {
            resident = cache.leaseLiveEntryForLocalMutationLocked(group_id, table_name, true);
            foreground_blocked = resident == null and cache.hasForegroundStateForGroupTableLocked(group_id, table_name);
        }
        if (resident == null and !foreground_blocked) {
            if (self.startup_write_cache) |cache| {
                if (self.write_cache == null or self.write_cache.? != cache) {
                    resident = cache.leaseLiveEntryForLocalMutationLocked(group_id, table_name, true);
                    foreground_blocked = resident == null and cache.hasForegroundStateForGroupTableLocked(group_id, table_name);
                }
            }
        }
        self.local_db_mutex.unlock();

        if (resident) |*cached| {
            defer cached.deinit(std.heap.page_allocator);
            if (cached.db.pendingWorkStats().repair_metadata_rebuild_pending) return .pending;
            // A durable-state read failure needs an authoritative repair pass
            // so it can be reported and backoff normally. Treating it as cache
            // contention would retain the fallback cursor forever without
            // ever surfacing corrupt or unavailable repair state.
            const has_intents = cached.db.hasPendingIndexRepairIntents(std.heap.page_allocator) catch return .pending;
            return if (has_intents) .pending else .clean;
        }
        return if (foreground_blocked) .busy else .absent;
    }

    pub fn hasResidentWriterForGroupTableBestEffort(
        self: *ProvisionedTableWriteSource,
        group_id: u64,
        table_name: []const u8,
    ) bool {
        return self.residentWriterRepairStateBestEffort(group_id, table_name) != .absent;
    }

    pub fn readPreparation(self: *ProvisionedTableWriteSource) table_reads.ReadPreparation {
        return .{
            .ptr = self,
            .vtable = &.{
                .prepare_for_read = prepareForRead,
                .begin_read = beginRead,
            },
        };
    }

    pub fn residentDbSource(self: *ProvisionedTableWriteSource) table_reads.ResidentDbSource {
        return .{
            .ptr = self,
            .lease_group = leaseResidentDb,
            .prepare_group_for_read_retry = prepareResidentDbForReadRetry,
        };
    }

    fn prepareForRead(ptr: *anyopaque, table_name: []const u8, kind: table_reads.ReadPreparation.Kind) void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.local_write_owner) |owner| return prepareForRead(owner, table_name, kind);
        if (!self.isWriteCacheDirtyForTable(table_name)) return;

        // This compatibility hook coordinates caches only. Read admission is
        // owned by beginRead/endRead below; waiting here can deadlock before the
        // caller has acquired that activity lease. Data writes and derived
        // catch-up are intentionally eventually visible, so discard only the
        // cached reader and never close the live writer cache from this path.
        self.invalidateReadCache(table_name);
        if (self.hasActiveBulkIngestSessionForTableBestEffort(table_name)) return;
        self.clearDirtyWriteTable(table_name);
    }

    fn beginRead(ptr: *anyopaque, table_name: []const u8, kind: table_reads.ReadPreparation.Kind) table_reads.ReadPreparation.Activity {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.local_write_owner) |owner| return beginRead(owner, table_name, kind);
        self.beginReadRequest(table_name);
        if (self.isWriteCacheDirtyForTable(table_name)) {
            self.invalidateReadCache(table_name);
            if (!self.hasActiveBulkIngestSessionForTableBestEffort(table_name)) {
                self.clearDirtyWriteTable(table_name);
            }
        }
        return .{
            .ptr = self,
            .table_name = table_name,
            .release_fn = endRead,
        };
    }

    fn endRead(ptr: *anyopaque, table_name: []const u8) void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        self.endReadRequest(table_name);
    }

    fn leaseResidentDb(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        lsm_root_generation: u64,
        options: table_reads.ResidentDbSource.LeaseOptions,
    ) !?table_reads.ResidentDbLease {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.local_write_owner) |owner| {
            return try leaseResidentDb(owner, alloc, table_name, group_id, lsm_root_generation, options);
        }
        var read_request_active = !options.read_activity_held;
        if (read_request_active) self.beginReadRequest(table_name);
        errdefer if (read_request_active) self.endReadRequest(table_name);

        lockAtomic(&self.local_db_mutex);
        const resident = self.snapshotResidentDbLocked(table_name, group_id, lsm_root_generation);
        self.local_db_mutex.unlock();

        if (resident.cached == null) {
            // Query-only runtimes have no writer owner; allow the caller to use
            // its readonly cache. Every runtime with a writer cache uses the
            // retry protocol, even when this function acquired admission on
            // the caller's behalf: no admitted execution may wait for or
            // initiate writer publication.
            if (self.write_cache == null and self.startup_write_cache == null) {
                if (read_request_active) {
                    self.endReadRequest(table_name);
                    read_request_active = false;
                }
                return null;
            }
            if (read_request_active) {
                self.endReadRequest(table_name);
                read_request_active = false;
            }
            return error.ResidentDbRetryRequired;
        }

        var cached_value = resident.cached orelse {
            if (read_request_active) {
                self.endReadRequest(table_name);
                read_request_active = false;
            }
            return null;
        };
        const owned_table_name = if (read_request_active)
            alloc.dupe(u8, table_name) catch |err| {
                cached_value.deinit(alloc);
                return err;
            }
        else
            null;
        errdefer if (owned_table_name) |name| alloc.free(name);
        const lease_ctx = alloc.create(ResidentLeaseContext) catch |err| {
            cached_value.deinit(alloc);
            return err;
        };
        lease_ctx.* = .{
            .source = self,
            .table_name = owned_table_name,
            .cached = cached_value,
        };
        read_request_active = false;
        return .{
            .ptr = lease_ctx,
            .db = lease_ctx.cached.db,
            .release_fn = releaseResidentDb,
        };
    }

    fn prepareResidentDbForReadRetry(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        lsm_root_generation: u64,
    ) !void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.local_write_owner) |owner| {
            return try owner.residentDbSource().prepareGroupForReadRetry(
                alloc,
                table_name,
                group_id,
                lsm_root_generation,
            );
        }

        // This method is deliberately admission-free. Waiting on cache open
        // barriers is safe here because no read lease can participate in the
        // apply -> admission -> open-barrier cycle.
        lockAtomic(&self.local_db_mutex);
        var resident = self.snapshotResidentDbLocked(table_name, group_id, lsm_root_generation);
        self.local_db_mutex.unlock();
        if (resident.cached) |*cached| {
            cached.deinit(alloc);
            return;
        }
        if (self.readCompatibleMaintenanceActiveBestEffort(table_name, group_id)) {
            return error.StorageReadTemporarilyUnavailable;
        }

        resident = self.waitForResidentDbOpen(table_name, group_id, lsm_root_generation);
        if (resident.cached) |*cached| {
            cached.deinit(alloc);
            return;
        }
        if (self.readCompatibleMaintenanceActiveBestEffort(table_name, group_id)) {
            return error.StorageReadTemporarilyUnavailable;
        }

        const cache = self.write_cache orelse self.startup_write_cache orelse return;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        var cached = self.getOrOpenCachedDbModeAtGeneration(
            alloc,
            cache,
            path,
            group_id,
            lsm_root_generation,
            table_name,
            .default_async,
            null,
            null,
            null,
            .{},
        ) catch |err| {
            if (isTransientWriterOpenConflict(err)) return error.StorageReadTemporarilyUnavailable;
            return err;
        };
        cached.deinit(alloc);
    }

    const ResidentDbSnapshot = struct {
        cached: ?ProvisionedTableWriteCache.CachedDb = null,
    };

    fn snapshotResidentDbLocked(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        lsm_root_generation: u64,
    ) ResidentDbSnapshot {
        var result: ResidentDbSnapshot = .{};
        const caches = [_]?*ProvisionedTableWriteCache{ self.write_cache, self.startup_write_cache };
        for (caches, 0..) |maybe_cache, index| {
            const cache = maybe_cache orelse continue;
            if (index != 0 and caches[0] != null and cache == caches[0].?) continue;
            if (cache.snapshotLeaseOrAdoptSeededLocked(group_id, lsm_root_generation, table_name)) |cached| {
                result.cached = cached;
                return result;
            }
        }
        return result;
    }

    fn waitForResidentDbOpen(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        lsm_root_generation: u64,
    ) ResidentDbSnapshot {
        const caches = [_]?*ProvisionedTableWriteCache{ self.write_cache, self.startup_write_cache };
        for (caches, 0..) |maybe_cache, index| {
            const cache = maybe_cache orelse continue;
            if (index != 0 and caches[0] != null and cache == caches[0].?) continue;
            lockAtomic(&cache.open_mutex);
            lockAtomic(&self.local_db_mutex);
            const observed = self.snapshotResidentDbLocked(table_name, group_id, lsm_root_generation);
            self.local_db_mutex.unlock();
            cache.open_mutex.unlock();
            if (observed.cached != null) return observed;
        }
        return .{};
    }

    const ResidentLeaseContext = struct {
        source: *ProvisionedTableWriteSource,
        table_name: ?[]u8,
        cached: ProvisionedTableWriteCache.CachedDb,
    };

    fn releaseResidentDb(ptr: *anyopaque, alloc: std.mem.Allocator) void {
        const lease_ctx: *ResidentLeaseContext = @ptrCast(@alignCast(ptr));
        lease_ctx.cached.deinit(alloc);
        if (lease_ctx.table_name) |table_name| {
            lease_ctx.source.endReadRequest(table_name);
            alloc.free(table_name);
        }
        alloc.destroy(lease_ctx);
    }

    fn hasDirtyWriteTableLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        return self.dirty_write_tables.contains(table_name);
    }

    fn publishDirtyWriteTableCountLocked(self: *ProvisionedTableWriteSource) void {
        const count = self.dirty_write_tables.count();
        self.dirty_write_table_count.store(@intCast(@min(count, std.math.maxInt(u32))), .release);
    }

    fn isWriteCacheDirtyForTable(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        if (self.local_write_owner) |owner| return owner.isWriteCacheDirtyForTable(table_name);
        if (self.dirty_write_table_count.load(.acquire) == 0) return false;
        lockAtomic(&self.dirty_write_tables_mutex);
        defer self.dirty_write_tables_mutex.unlock();
        return self.hasDirtyWriteTableLocked(table_name);
    }

    fn clearAllDirtyWriteTablesLocked(self: *ProvisionedTableWriteSource) void {
        var keys = self.dirty_write_tables.keyIterator();
        while (keys.next()) |table_name| std.heap.page_allocator.free(table_name.*);
        self.dirty_write_tables.clearRetainingCapacity();
        self.dirty_write_table_count.store(0, .release);
    }

    fn clearAllDirtyWriteTables(self: *ProvisionedTableWriteSource) void {
        lockAtomic(&self.dirty_write_tables_mutex);
        defer self.dirty_write_tables_mutex.unlock();
        self.clearAllDirtyWriteTablesLocked();
    }

    fn clearDirtyWriteTable(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        if (self.local_write_owner) |owner| return owner.clearDirtyWriteTable(table_name);
        lockAtomic(&self.dirty_write_tables_mutex);
        defer self.dirty_write_tables_mutex.unlock();
        if (self.dirty_write_tables.fetchRemove(table_name)) |removed| {
            std.heap.page_allocator.free(removed.key);
        }
        self.publishDirtyWriteTableCountLocked();
    }

    fn hasDirtyWriteTableWithLocalDbLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        if (self.dirty_write_table_count.load(.acquire) == 0) return false;
        const dirty = dirty_blk: {
            lockAtomic(&self.dirty_write_tables_mutex);
            defer self.dirty_write_tables_mutex.unlock();
            break :dirty_blk self.hasDirtyWriteTableLocked(table_name);
        };
        if (!dirty) return false;

        const cache = self.write_cache orelse {
            self.clearDirtyWriteTable(table_name);
            return false;
        };
        if (cache.bulkIngestSessionOpenForTable(table_name)) return true;
        if (cache.hasLiveEntryForTableLocked(table_name)) return true;

        self.clearDirtyWriteTable(table_name);
        return false;
    }

    fn markWriteCacheDirty(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        if (self.local_write_owner) |owner| return owner.markWriteCacheDirty(table_name);
        if (self.write_cache == null) return;
        lockAtomic(&self.dirty_write_tables_mutex);
        if (self.hasDirtyWriteTableLocked(table_name)) {
            self.dirty_write_tables_mutex.unlock();
            return;
        }
        // Own the name until successful publication/invalidation clears it.
        // This allocation happens once per clean-to-dirty transition, while
        // repeated writes to an already dirty table remain allocation-free.
        const owned_table_name = std.heap.page_allocator.dupe(u8, table_name) catch
            @panic("out of memory tracking dirty write tables");
        self.dirty_write_tables.put(std.heap.page_allocator, owned_table_name, {}) catch {
            std.heap.page_allocator.free(owned_table_name);
            @panic("out of memory tracking dirty write tables");
        };
        self.publishDirtyWriteTableCountLocked();
        self.dirty_write_tables_mutex.unlock();
    }

    fn invalidateDirtyWriteCacheForRead(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        lockAtomic(&self.dirty_write_tables_mutex);
        const dirty = self.hasDirtyWriteTableLocked(table_name);
        self.dirty_write_tables_mutex.unlock();
        if (!dirty) return;
        self.invalidateWriteCache(table_name);
    }

    fn notifyLocalChange(self: *ProvisionedTableWriteSource, table_name: []const u8, kind: LocalChangeKind) void {
        if (self.local_change_hook) |hook| hook.on_change(hook.ptr, table_name, kind);
    }

    fn notifyLocalIndexRepairDebt(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        action: LocalIndexRepairDebtAction,
    ) void {
        if (self.local_index_repair_debt_hook) |hook| hook.on_change(hook.ptr, table_name, group_id, action);
    }

    fn indexRepairDebtAction(
        req: db_mod.types.ArtifactRepairRunRequest,
        result: db_mod.types.ArtifactRepairResult,
    ) ?LocalIndexRepairDebtAction {
        if (req.target != .index or result.scanned == 0) return null;
        if (req.control) |control| {
            if (result.controls_applied == 0) return null;
            return switch (control) {
                // A named pause says nothing about other repair intents in the
                // same group. Keep the group queued for one aggregate owner
                // audit; that pass removes it cheaply when only paused debt
                // remains, or advances another runnable index immediately.
                .pause_automatic => .enqueue,
                .resume_automatic, .cancel_current_attempt => .enqueue,
            };
        }
        // Index repair requests are named-index operations. Even when that
        // index completes, another intent may remain in the group, so only the
        // aggregate owner-side pass is allowed to remove the group queue key.
        return .enqueue;
    }

    fn changeKindForHARecord(record: db_mod.HAReplicationRecordView) LocalChangeKind {
        return switch (record.kind) {
            .metadata_mutation => .structural,
            else => .data,
        };
    }

    fn publishRestoreRepairComplete(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        self.invalidateReadCache(table_name);
        self.invalidateWriteCacheForTable(table_name);
        // Restore publishes a new storage generation. Retire both the current
        // status and any refresh that started before publication so old repair
        // debt cannot be resurrected after the durable state is clean.
        self.invalidateRuntimeStatusCache(table_name);
        self.clearDirtyWriteTable(table_name);
        self.notifyLocalChange(table_name, .data);
    }

    fn enqueueRestoreRepairComplete(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const alloc = std.heap.page_allocator;
        const owned_table_name = alloc.dupe(u8, table_name) catch |err| {
            std.log.warn("restore repair completion failed phase=allocation class={s}", .{@errorName(err)});
            return;
        };

        const io = self.table_activity_threaded.io();
        self.restore_repair_completion_mutex.lockUncancelable(io);
        self.restore_repair_completions.append(alloc, owned_table_name) catch |err| {
            self.restore_repair_completion_mutex.unlock(io);
            alloc.free(owned_table_name);
            std.log.warn("restore repair completion failed phase=enqueue class={s}", .{@errorName(err)});
            return;
        };
        self.restore_repair_completion_mutex.unlock(io);
        self.scheduleRestoreRepairCompletionDrain();
    }

    fn scheduleRestoreRepairCompletionDrain(self: *ProvisionedTableWriteSource) void {
        if (self.restore_repair_completion_scheduled.cmpxchgStrong(false, true, .acq_rel, .acquire) != null) return;
        const io = self.table_activity_threaded.io();
        self.restore_repair_completion_group.concurrent(io, drainRestoreRepairCompletionsTask, .{self}) catch |err| {
            self.restore_repair_completion_scheduled.store(false, .release);
            std.log.warn("restore repair completion drain schedule failed err={}", .{err});
        };
    }

    fn drainRestoreRepairCompletionsTask(self: *ProvisionedTableWriteSource) !void {
        self.drainRestoreRepairCompletionsScheduled();
    }

    fn drainRestoreRepairCompletionsScheduled(self: *ProvisionedTableWriteSource) void {
        const alloc = std.heap.page_allocator;
        const io = self.table_activity_threaded.io();
        while (true) {
            self.restore_repair_completion_mutex.lockUncancelable(io);
            if (self.restore_repair_completions.items.len == 0) {
                self.restore_repair_completion_scheduled.store(false, .release);
                self.restore_repair_completion_mutex.unlock(io);
                return;
            }
            var pending = self.restore_repair_completions;
            self.restore_repair_completions = .empty;
            self.restore_repair_completion_mutex.unlock(io);

            for (pending.items) |table_name| {
                self.publishRestoreRepairComplete(table_name);
                alloc.free(table_name);
            }
            pending.deinit(alloc);
        }
    }

    fn freeRestoreRepairCompletions(self: *ProvisionedTableWriteSource) void {
        const alloc = std.heap.page_allocator;
        const io = self.table_activity_threaded.io();
        self.restore_repair_completion_mutex.lockUncancelable(io);
        defer self.restore_repair_completion_mutex.unlock(io);
        for (self.restore_repair_completions.items) |table_name| alloc.free(table_name);
        self.restore_repair_completions.deinit(alloc);
        self.restore_repair_completions = .empty;
    }

    fn openRestoreRepairDbForGroup(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        path: []const u8,
        group_id: u64,
        table_name: []const u8,
        indexes_json: []const u8,
        staged_generation: ?*const db_mod.generation_lifecycle.StagedGeneration,
    ) !db_mod.DB {
        const identity_namespace = try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id);
        var db = try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
            alloc,
            path,
            indexes_json,
            null,
            null,
            self.visibleRootGeneration(group_id),
            null,
            .restore_repair,
            self.backend_runtime,
            self.antfly_provider,
            self.secret_store,
            self.remote_content,
            identity_namespace,
            .{ .staged_generation = staged_generation },
        );
        errdefer db.close();
        try validateProvisionedDbIdentityNamespaceExpected(identity_namespace, &db);
        return db;
    }

    fn openRaftSnapshotStagingDbForGroup(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        staged_generation: *const db_mod.generation_lifecycle.StagedGeneration,
        group_id: u64,
        indexes_json: []const u8,
        identity_namespace: doc_identity.Namespace,
    ) !db_mod.DB {
        var db = try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
            alloc,
            staged_generation.path(),
            indexes_json,
            null,
            null,
            self.visibleRootGeneration(group_id),
            null,
            .startup_catch_up,
            self.backend_runtime,
            self.antfly_provider,
            self.secret_store,
            self.remote_content,
            identity_namespace,
            .{ .staged_generation = staged_generation },
        );
        errdefer db.close();
        try validateProvisionedDbIdentityNamespaceExpected(identity_namespace, &db);
        return db;
    }

    fn repairRestoredTableRuntimeStateBlocking(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        path: []const u8,
        group_id: u64,
        table_name: []const u8,
        indexes_json_override: ?[]const u8,
        schema_json_override: ?[]const u8,
        staged_generation: ?*const db_mod.generation_lifecycle.StagedGeneration,
    ) !void {
        const open_retry_timeout_ns = 2 * std.time.ns_per_s;
        const open_start_ns = platform_time.monotonicNs();
        var open_attempts: usize = 0;
        var logged_open_wait = false;
        var raft_apply_marker_reset = staged_generation == null;
        while (true) {
            const runtime_repair_needed = try db_mod.DB.restoreRuntimeRepairNeededForPathWithIo(
                alloc,
                self.table_activity_threaded.io(),
                path,
            );
            if (!runtime_repair_needed and raft_apply_marker_reset) return;

            const owned_indexes_json = if (indexes_json_override == null)
                (try loadTableIndexesJson(alloc, self.catalog, table_name)) orelse return error.TableVisibilityTimeout
            else
                null;
            defer if (owned_indexes_json) |value| alloc.free(value);
            const indexes_json = indexes_json_override orelse owned_indexes_json.?;

            open_attempts += 1;
            var db = self.openRestoreRepairDbForGroup(
                alloc,
                path,
                group_id,
                table_name,
                indexes_json,
                staged_generation,
            ) catch |err| {
                if (isTransientWriterOpenConflict(err)) {
                    if (platform_time.monotonicNs() -| open_start_ns >= open_retry_timeout_ns) return err;
                    if (!logged_open_wait) {
                        logged_open_wait = true;
                        std.log.warn("restore foreground repair waiting for writer group_id={d} class={s}", .{
                            group_id,
                            @errorName(err),
                        });
                    }
                    self.table_activity_threaded.io().sleep(Io.Duration.fromNanoseconds(replicated_apply_writer_open_retry_ns), .awake) catch |sleep_err| switch (sleep_err) {
                        error.Canceled => Io.recancel(self.table_activity_threaded.io()),
                    };
                    continue;
                }
                return err;
            };
            defer db.close();

            if (!raft_apply_marker_reset) {
                // A restored generation contains document state, not the
                // destination replica's Raft history. Reset the group-local
                // replay fence before this isolated generation is sealed.
                try db.clearRaftAppliedEntry();
                raft_apply_marker_reset = true;
            }

            if (schema_json_override) |schema_json| {
                try applyLocalTableSchemaJson(alloc, &db, schema_json);
            }
            if (runtime_repair_needed) {
                try self.repairRestoredDbRuntimeStateBlocking(alloc, &db, group_id, open_attempts);
            }
            return;
        }
    }

    fn repairRestoredDbRuntimeStateBlocking(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        db: *db_mod.DB,
        group_id: u64,
        open_attempts: usize,
    ) !void {
        const timeout_ns = 30 * std.time.ns_per_s;
        const start_ns = platform_time.monotonicNs();
        var attempts: usize = 0;
        std.log.info("restore foreground repair begin group_id={d}", .{group_id});
        while (try db.restoreRuntimeRepairNeeded()) {
            attempts += 1;
            const repaired = db.repairRestoreRuntimeStateStepIfNeeded(alloc) catch |err| switch (err) {
                error.RestoreRuntimeRepairIncomplete,
                error.RestoreDenseArtifactRebuildIncomplete,
                error.RestoreDenseConfigProofIncomplete,
                error.RestoreDenseCounterProofIncomplete,
                error.RestoreDenseIndexProofIncomplete,
                error.RestoreDenseCoverageProofIncomplete,
                error.RestoreDenseCheckpointIncomplete,
                error.RestoreIndexAvailabilityIncomplete,
                => {
                    if (platform_time.monotonicNs() -| start_ns >= timeout_ns)
                        return error.TableVisibilityTimeout;
                    self.table_activity_threaded.io().sleep(Io.Duration.fromMilliseconds(100), .awake) catch |sleep_err| switch (sleep_err) {
                        error.Canceled => Io.recancel(self.table_activity_threaded.io()),
                    };
                    continue;
                },
                else => return err,
            };
            if (repaired) {
                db.clearDenseHbcCaches();
            }
            if (platform_time.monotonicNs() -| start_ns >= timeout_ns) return error.TableVisibilityTimeout;
        }
        std.log.info("restore foreground repair complete group_id={d} attempts={d} open_attempts={d}", .{
            group_id,
            attempts,
            open_attempts,
        });
    }

    /// Complete an idempotent restore retry through the authoritative cached
    /// writer when one is already open. Opening a second repair DB would
    /// contend with that writer and could make an exact-identity retry report
    /// success while the durable runtime-repair marker remained incomplete.
    fn repairPublishedRestoreRuntimeStateBlocking(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        path: []const u8,
        group_id: u64,
        table_name: []const u8,
    ) !void {
        if (!try db_mod.DB.restoreRuntimeRepairNeededForPathWithIo(alloc, self.table_activity_threaded.io(), path)) return;

        self.beginLocalStructuralCachedDbMutationFromPreparation(table_name);
        errdefer self.abortLocalStructuralCachedDbMutation(table_name);

        // The catalog is authoritative once a generation is published. The
        // durable restore identity intentionally describes only the imported
        // artifact, so a retry manifest at the same location is not proof of
        // the table definition that was admitted with that artifact. Sampling
        // the definition only after structural admission prevents local table
        // mutation from racing this repair contract.
        const metadata = (try loadTableManagedMetadata(alloc, self.catalog, table_name)) orelse
            return error.TableVisibilityTimeout;
        defer {
            if (metadata.indexes_json) |value| alloc.free(value);
            if (metadata.schema_json) |value| alloc.free(value);
        }
        const indexes_json = metadata.indexes_json orelse tables_api.default_indexes_json;
        const schema_json = metadata.schema_json orelse "";

        if (self.write_cache orelse self.startup_write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbForLocalMutation(
                alloc,
                cache,
                path,
                group_id,
                self.visibleRootGeneration(group_id),
                table_name,
                false,
            );
            defer cached.deinit(alloc);
            try applyLocalTableSchemaJson(alloc, cached.db, schema_json);
            const reconcile_summary = try metadata_table_provisioner.reconcileDbIndexesWithOptions(
                alloc,
                cached.db,
                indexes_json,
                .{
                    .drain_resolver_backfill = false,
                    .source_table = table_name,
                    .destination_authorizer = self.destination_authorizer,
                },
            );
            try self.repairRestoredDbRuntimeStateBlocking(alloc, cached.db, group_id, 0);

            const entry = cached.entry orelse return error.StaleCachedDbLease;
            {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                if (entry.retired) return error.StaleCachedDbLease;
                try cache.replaceTableMetadataLocked(table_name, indexes_json, schema_json);
                try cache.replaceEntrySchemaLocked(entry, schema_json);
                ProvisionedTableWriteCache.publishEntryManagedConfig(entry, indexes_json);
                cached.schema_json = entry.schema_json;
            }
            if (reconcile_summary.indexes_pending != 0) {
                self.notifyLocalIndexRepairDebt(table_name, group_id, .enqueue);
            }
        } else {
            try self.repairRestoredTableRuntimeStateBlocking(
                alloc,
                path,
                group_id,
                table_name,
                indexes_json,
                schema_json,
                null,
            );
        }

        self.finishLocalStructuralCachedDbMutation(table_name);
        self.publishRestoreRepairComplete(table_name);
        self.notifyLocalChange(table_name, .structural);
    }

    const RestoreRepairCatchUpWork = struct {
        alloc: std.mem.Allocator,
        source: *ProvisionedTableWriteSource,
        group_id: u64,
        table_name: []u8,

        fn sleepRetry(self: *@This()) void {
            runTestBeforeRestoreRepairRetrySleepHook();
            self.source.table_activity_threaded.io().sleep(Io.Duration.fromMilliseconds(100), .awake) catch |err| switch (err) {
                error.Canceled => Io.recancel(self.source.table_activity_threaded.io()),
            };
        }

        fn runAndDeinit(work: *@This()) Io.Cancelable!void {
            defer RestoreRepairCatchUpWork.deinit(work);
            work.run() catch |err| {
                std.log.warn("restore background catch-up failed group_id={d} class={s}", .{
                    work.group_id,
                    @errorName(err),
                });
            };
        }

        fn run(work: *@This()) !void {
            const path = try metadata_mod.groupDbPathFromReplicaRoot(work.alloc, work.source.replica_root_dir, work.group_id);
            defer work.alloc.free(path);

            var attempts: usize = 0;
            std.log.info("restore background catch-up begin group_id={d}", .{work.group_id});
            while (true) {
                if (work.source.restore_repair_shutdown.load(.acquire)) return;
                attempts += 1;
                const busy = work.repairOnce(path) catch |err| retry: {
                    if (!isTransientRestoreRepairError(err)) return err;
                    std.log.info("restore background catch-up transient retry table={s} group_id={d} err={s}", .{
                        work.table_name,
                        work.group_id,
                        @errorName(err),
                    });
                    break :retry true;
                };
                const still_needed = try db_mod.DB.restoreRuntimeRepairNeededForPath(work.alloc, path);
                if (!busy and !still_needed) {
                    work.source.enqueueRestoreRepairComplete(work.table_name);
                    std.log.info("restore background catch-up complete group_id={d} attempts={d}", .{
                        work.group_id,
                        attempts,
                    });
                    return;
                }
                work.sleepRetry();
            }
        }

        fn repairOnce(self: *@This(), path: []const u8) !bool {
            if (!self.source.tryBeginStructuralTableActivity(self.table_name)) return true;
            defer self.source.endStructuralTableActivity(self.table_name);
            var read_cache_exclusive = try self.source.beginReadCacheExclusive(self.table_name);
            defer {
                if (read_cache_exclusive) |*exclusive| exclusive.deinit();
            }
            if (!try db_mod.DB.restoreRuntimeRepairNeededForPathWithIo(
                self.alloc,
                self.source.table_activity_threaded.io(),
                path,
            )) return false;

            if (!self.source.local_db_mutex.tryLock()) return true;
            if (self.source.hasDirtyWriteTableWithLocalDbLocked(self.table_name)) {
                self.source.local_db_mutex.unlock();
                return true;
            }
            if (self.source.write_cache) |cache| {
                if (cache.hasForegroundStateForGroupTableLocked(self.group_id, self.table_name)) {
                    self.source.local_db_mutex.unlock();
                    return true;
                }
            }
            self.source.local_db_mutex.unlock();

            const indexes_json = (try loadTableIndexesJson(self.alloc, self.source.catalog, self.table_name)) orelse return true;
            defer self.alloc.free(indexes_json);

            var db = self.source.openRestoreRepairDbForGroup(
                self.alloc,
                path,
                self.group_id,
                self.table_name,
                indexes_json,
                null,
            ) catch |err| {
                if (isTransientWriterOpenConflict(err)) return true;
                return err;
            };
            defer db.close();

            try runTestBeforeRestoreRepairStepHook();
            if (try db.repairRestoreRuntimeStateStepIfNeeded(self.alloc)) {
                db.clearDenseHbcCaches();
            }
            return try db.restoreRuntimeRepairNeeded();
        }

        fn deinit(ptr: *anyopaque) void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            const alloc = work.alloc;
            alloc.free(work.table_name);
            alloc.destroy(work);
        }
    };

    fn requestRestoreRepairCatchUp(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) void {
        if (self.restore_repair_shutdown.load(.acquire)) return;
        const alloc = std.heap.page_allocator;
        const work = alloc.create(RestoreRepairCatchUpWork) catch |err| {
            std.log.warn("restore background catch-up failed phase=allocation group_id={d} class={s}", .{ group_id, @errorName(err) });
            return;
        };
        const owned_table_name = alloc.dupe(u8, table_name) catch |err| {
            alloc.destroy(work);
            std.log.warn("restore background catch-up failed phase=identity_allocation group_id={d} class={s}", .{ group_id, @errorName(err) });
            return;
        };
        work.* = .{
            .alloc = alloc,
            .source = self,
            .group_id = group_id,
            .table_name = owned_table_name,
        };
        self.restore_repair_work_group.concurrent(self.table_activity_threaded.io(), RestoreRepairCatchUpWork.runAndDeinit, .{work}) catch |err| {
            RestoreRepairCatchUpWork.deinit(work);
            std.log.warn("restore background catch-up failed phase=submit group_id={d} class={s}", .{ group_id, @errorName(err) });
            return;
        };
    }

    fn freeStructuralReconcileTables(self: *ProvisionedTableWriteSource) void {
        const io = self.table_activity_threaded.io();
        const alloc = std.heap.page_allocator;
        self.structural_reconcile_mutex.lockUncancelable(io);
        defer self.structural_reconcile_mutex.unlock(io);
        for (self.structural_reconcile_tables.items) |*request| {
            if (request.reservesWriteAdmission()) self.cancelStructuralReconcileReservation(request.table_name);
            self.releaseStructuralReconcileStatus(request.table_name);
            request.deinit(alloc);
        }
        self.structural_reconcile_tables.deinit(alloc);
        self.structural_reconcile_tables = .empty;
    }

    fn enqueueTableStructuralReconcile(self: *ProvisionedTableWriteSource, table_name: []const u8) !void {
        try self.enqueueTableStructuralReconcileTarget(table_name, null);
    }

    fn enqueueTableIndexStructuralReconcile(self: *ProvisionedTableWriteSource, table_name: []const u8, index_name: []const u8) !void {
        try self.enqueueTableStructuralReconcileTarget(table_name, index_name);
    }

    fn enqueueTableStructuralReconcileTarget(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        index_name: ?[]const u8,
    ) !void {
        if (self.restore_repair_shutdown.load(.acquire)) return error.BackgroundOwnerClosing;
        // Enqueue is a structural invalidation boundary even when an existing
        // request already covers this target. A status observer admitted
        // before the request must not publish after it.
        self.invalidateRuntimeStatusCache(table_name);
        const alloc = std.heap.page_allocator;
        const io = self.table_activity_threaded.io();

        self.structural_reconcile_mutex.lockUncancelable(io);
        defer self.structural_reconcile_mutex.unlock(io);

        for (self.structural_reconcile_tables.items) |candidate| {
            if (candidate.covers(table_name, index_name) or candidate.sameTarget(table_name, index_name)) return;
        }

        if (index_name == null) {
            var i: usize = 0;
            while (i < self.structural_reconcile_tables.items.len) {
                if (std.mem.eql(u8, self.structural_reconcile_tables.items[i].table_name, table_name)) {
                    var removed = self.structural_reconcile_tables.orderedRemove(i);
                    if (removed.reservesWriteAdmission()) self.cancelStructuralReconcileReservation(removed.table_name);
                    self.releaseStructuralReconcileStatus(removed.table_name);
                    removed.deinit(alloc);
                    continue;
                }
                i += 1;
            }
        }

        const owned_table_name = try alloc.dupe(u8, table_name);
        errdefer alloc.free(owned_table_name);
        const owned_index_name = if (index_name) |name| try alloc.dupe(u8, name) else null;
        errdefer if (owned_index_name) |name| alloc.free(name);
        const appended_index = self.structural_reconcile_tables.items.len;
        // Keep one spare slot for the active worker to return a failed request
        // without allocating. This makes transient OOM itself retryable.
        try self.structural_reconcile_tables.ensureUnusedCapacity(alloc, 2);
        self.structural_reconcile_tables.appendAssumeCapacity(.{
            .table_name = owned_table_name,
            .index_name = owned_index_name,
        });
        self.reserveStructuralReconcileStatus(table_name);
        if (index_name == null) self.reserveStructuralReconcileActivity(table_name);

        if (self.structural_reconcile_scheduled.cmpxchgStrong(false, true, .acq_rel, .acquire) != null) return;
        self.restore_repair_work_group.concurrent(io, drainStructuralReconcileTask, .{self}) catch |err| {
            var removed = self.structural_reconcile_tables.orderedRemove(appended_index);
            if (removed.reservesWriteAdmission()) self.cancelStructuralReconcileReservation(removed.table_name);
            self.releaseStructuralReconcileStatus(removed.table_name);
            removed.deinit(alloc);
            self.structural_reconcile_scheduled.store(false, .release);
            return err;
        };
    }

    fn drainStructuralReconcileTask(self: *ProvisionedTableWriteSource) Io.Cancelable!void {
        const alloc = std.heap.page_allocator;
        const io = self.table_activity_threaded.io();
        while (true) {
            self.structural_reconcile_mutex.lockUncancelable(io);
            if (self.structural_reconcile_tables.items.len == 0) {
                self.structural_reconcile_scheduled.store(false, .release);
                self.structural_reconcile_mutex.unlock(io);
                return;
            }
            const now_ms: u64 = @intCast(@divTrunc(platform_time.monotonicNs(), std.time.ns_per_ms));
            var ready_index: ?usize = null;
            var earliest_ms: u64 = std.math.maxInt(u64);
            for (self.structural_reconcile_tables.items, 0..) |request, index| {
                if (request.not_before_ms <= now_ms) {
                    ready_index = index;
                    break;
                }
                earliest_ms = @min(earliest_ms, request.not_before_ms);
            }
            if (ready_index == null) {
                self.structural_reconcile_mutex.unlock(io);
                const wait_ms = @min(@as(u64, 100), earliest_ms -| now_ms);
                io.sleep(Io.Duration.fromMilliseconds(@max(@as(u64, 1), wait_ms)), .awake) catch |err| switch (err) {
                    error.Canceled => return Io.recancel(io),
                };
                continue;
            }

            var request = self.structural_reconcile_tables.orderedRemove(ready_index.?);
            self.structural_reconcile_mutex.unlock(io);

            if (request.reservesWriteAdmission()) self.beginReservedStructuralReconcileActivity(request.table_name);
            request.attempt_count +|= 1;
            var reconcile_outcome: StructuralReconcileOutcome = .complete;
            const reconcile_error: ?anyerror = blk: {
                if (!request.prepared) {
                    self.prepareTableStructuralReconcile(request.table_name, request.index_name) catch |err| break :blk err;
                    request.prepared = true;
                }
                reconcile_outcome = self.reconcileTableStructureStep(alloc, &request) catch |err| break :blk err;
                break :blk null;
            };
            if (reconcile_error) |err| {
                request.failure_count +|= 1;
                const retry_now_ms: u64 = @intCast(@divTrunc(platform_time.monotonicNs(), std.time.ns_per_ms));
                request.not_before_ms = retry_now_ms +| structuralReconcileRetryDelayMs(request.failure_count);
                if (request.index_name) |index_name| {
                    std.log.warn("structural reconcile deferred table={s} index={s} failures={d} retry_at_monotonic_ms={d} err={s}", .{ request.table_name, index_name, request.failure_count, request.not_before_ms, @errorName(err) });
                } else {
                    std.log.warn("structural reconcile deferred table={s} failures={d} retry_at_monotonic_ms={d} err={s}", .{ request.table_name, request.failure_count, request.not_before_ms, @errorName(err) });
                }
                self.requeueActiveStructuralReconcile(&request, alloc);
                continue;
            }
            if (reconcile_outcome == .yielded) {
                request.failure_count = 0;
                const retry_now_ms: u64 = @intCast(@divTrunc(platform_time.monotonicNs(), std.time.ns_per_ms));
                request.not_before_ms = structuralReconcileRequeueAtMs(.yielded, retry_now_ms);
                self.requeueActiveStructuralReconcile(&request, alloc);
                continue;
            }
            if (reconcile_outcome == .blocked) {
                request.pending_count +|= 1;
                request.failure_count = 0;
                const retry_now_ms: u64 = @intCast(@divTrunc(platform_time.monotonicNs(), std.time.ns_per_ms));
                // Pending is expected bounded maintenance, and each pass can
                // advance durable cleanup. A fixed delay preserves queue
                // fairness without exponentially throttling forward progress.
                request.not_before_ms = structuralReconcileRequeueAtMs(.blocked, retry_now_ms);
                if (request.pending_count == 1 or std.math.isPowerOfTwo(request.pending_count)) {
                    if (request.index_name) |index_name| {
                        std.log.info("structural reconcile waiting for bounded maintenance table={s} index={s} attempts={d}", .{ request.table_name, index_name, request.attempt_count });
                    } else {
                        std.log.info("structural reconcile waiting for bounded maintenance table={s} attempts={d}", .{ request.table_name, request.attempt_count });
                    }
                }
                self.requeueActiveStructuralReconcile(&request, alloc);
                continue;
            }
            if (reconcile_outcome == .discarded) {
                if (request.reservesWriteAdmission()) self.endStructuralReconcileActivity(request.table_name);
                request.handoffDeferredRepairDebt(self);
                request.deinit(alloc);
                continue;
            }
            self.notifyLocalChange(request.table_name, .runtime_reconciled);
            if (request.index_name) |index_name| {
                std.log.info("structural reconcile complete table={s} index={s} attempts={d}", .{ request.table_name, index_name, request.attempt_count });
            } else {
                std.log.info("structural reconcile complete table={s} attempts={d}", .{ request.table_name, request.attempt_count });
            }
            if (request.reservesWriteAdmission()) self.endStructuralReconcileActivity(request.table_name);
            request.handoffDeferredRepairDebt(self);
            request.deinit(alloc);
        }
    }

    fn requeueActiveStructuralReconcile(
        self: *ProvisionedTableWriteSource,
        request: *StructuralReconcileRequest,
        alloc: std.mem.Allocator,
    ) void {
        const io = self.table_activity_threaded.io();
        // Whole-table reconciliation keeps its reservation continuous across
        // retries. Index-targeted work has already installed write capability
        // and can retry without holding foreground admission.
        self.structural_reconcile_mutex.lockUncancelable(io);
        var covered = false;
        for (self.structural_reconcile_tables.items) |candidate| {
            if (candidate.covers(request.table_name, request.index_name)) {
                covered = true;
                break;
            }
        }
        var requeued = false;
        if (!covered and !self.restore_repair_shutdown.load(.acquire)) {
            if (request.reservesWriteAdmission()) self.reserveStructuralReconcileActivity(request.table_name);
            self.structural_reconcile_tables.appendAssumeCapacity(request.*);
            requeued = true;
        }
        if (request.reservesWriteAdmission()) self.endStructuralReconcileActivity(request.table_name);
        self.structural_reconcile_mutex.unlock(io);
        if (!requeued) {
            request.handoffDeferredRepairDebt(self);
            request.deinit(alloc);
        }
    }

    fn prepareTableStructuralReconcile(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        target_index_name: ?[]const u8,
    ) !void {
        _ = self;
        if (target_index_name) |index_name| {
            std.log.info("structural reconcile begin table={s} index={s}", .{ table_name, index_name });
        } else {
            std.log.info("structural reconcile begin table={s}", .{table_name});
        }
        // Whole-table work has already drained foreground writes. Targeted
        // index work instead owns only its per-group compatible operation and
        // is constrained below to that one index's desired state.
    }

    fn reconcileTableStructureStep(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        request: *StructuralReconcileRequest,
    ) !StructuralReconcileOutcome {
        if (self.restore_repair_shutdown.load(.acquire)) return .discarded;
        if (request.plan == null) {
            request.plan = (try self.captureStructuralReconcilePlan(alloc, request.table_name)) orelse return .discarded;
            if (request.plan.?.groups.len == 0) {
                request.plan.?.deinit(alloc);
                request.plan = null;
                return .discarded;
            }
        }

        // One whole-table ReadIndex fence admits each bounded quantum. Runtime
        // observations remain owned and invisible until a second whole-table
        // fence accepts every mutation completed by this quantum.
        if (!try self.structuralReconcilePlanStillCurrent(request.table_name, &request.plan.?)) {
            request.plan.?.deinit(alloc);
            request.plan = null;
            return .blocked;
        }

        const publication_fence = if (self.runtime_status_cache) |status_cache|
            try status_cache.capturePublicationToken(request.table_name)
        else
            null;
        var observations = std.ArrayListUnmanaged(StructuralRuntimeObservation).empty;
        defer {
            for (observations.items) |*observation| observation.deinit(alloc);
            observations.deinit(alloc);
        }
        try observations.ensureTotalCapacity(alloc, structural_reconcile_groups_per_quantum);
        // Once a shard installs its handoff-status fence, recording that shard
        // in the request must be allocation-free. Otherwise OOM between the
        // durable repair edge and request ownership could strand the fence.
        try request.deferred_repair_group_ids.ensureUnusedCapacity(
            alloc,
            structural_reconcile_groups_per_quantum,
        );

        var attempted: usize = 0;
        var made_progress = false;
        var lifecycle_transition = false;
        while (attempted < structural_reconcile_groups_per_quantum) : (attempted += 1) {
            const plan = &request.plan.?;
            const group = plan.currentGroup() orelse {
                break;
            };
            const outcome = self.reconcileTableGroupStructureWithRuntime(alloc, group.range.group_id, request.table_name, .{
                .indexes_json = plan.indexes_json,
                .schema_json = plan.schema_json,
                .identity_namespace = group.identity_namespace,
                .target_index_name = request.index_name,
            }, &observations) catch |err| {
                plan.deinit(alloc);
                request.plan = null;
                return err;
            };
            switch (outcome) {
                .busy => plan.markCurrentBusy(),
                .repair_pending => {
                    // Shard handoff authority was installed before its group
                    // operation released. Retain the exact group so final
                    // request handoff can issue the runnable wake after
                    // releasing the table-wide status reservation.
                    try request.deferRepairDebt(alloc, group.range.group_id);
                    made_progress = true;
                    lifecycle_transition = true;
                    plan.markCurrentComplete();
                },
                .publication_pending => {
                    // The durable replay append is complete, but its resident
                    // owner has not yet published the post-append target. The
                    // shard-local handoff fence bridges that scheduler edge
                    // without retaining table write admission.
                    made_progress = true;
                    plan.markCurrentComplete();
                },
                .complete => {
                    made_progress = true;
                    plan.markCurrentComplete();
                    if (plan.pending_group_indexes.items.len == 0) break;
                },
            }
        }

        if (made_progress) {
            const plan = &request.plan.?;
            const plan_current = self.structuralReconcilePlanStillCurrent(request.table_name, plan) catch |err| {
                plan.deinit(alloc);
                request.plan = null;
                return err;
            };
            if (!plan_current) {
                plan.deinit(alloc);
                request.plan = null;
                return .blocked;
            }
            publishStructuralRuntimeObservations(
                self,
                request.table_name,
                publication_fence,
                observations.items,
                lifecycle_transition,
            ) catch |err| switch (err) {
                error.RuntimeStatusPublicationFenced => {
                    plan.deinit(alloc);
                    request.plan = null;
                    return .blocked;
                },
                else => {
                    plan.deinit(alloc);
                    request.plan = null;
                    return err;
                },
            };
        }
        if (request.plan.?.pending_group_indexes.items.len == 0) return .complete;
        return if (made_progress) .yielded else .blocked;
    }

    fn captureStructuralReconcilePlan(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !?StructuralReconcilePlan {
        var snapshot = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_name) orelse return null;

        const indexes_json = try alloc.dupe(u8, table.indexes_json);
        errdefer alloc.free(indexes_json);
        const schema_json = try alloc.dupe(u8, table.schema_json);
        errdefer alloc.free(schema_json);

        var group_count: usize = 0;
        for (snapshot.ranges) |range| {
            if (range.table_id == table.table_id) group_count += 1;
        }
        const groups = try alloc.alloc(StructuralReconcileGroup, group_count);
        errdefer alloc.free(groups);
        var initialized: usize = 0;
        errdefer for (groups[0..initialized]) |*group| group.deinit(alloc);
        for (snapshot.ranges) |range| {
            if (range.table_id != table.table_id) continue;
            groups[initialized] = try StructuralReconcileGroup.clone(alloc, table.table_id, range);
            initialized += 1;
        }
        std.mem.sort(StructuralReconcileGroup, groups, {}, struct {
            fn lessThan(_: void, lhs: StructuralReconcileGroup, rhs: StructuralReconcileGroup) bool {
                return lhs.range.group_id < rhs.range.group_id;
            }
        }.lessThan);

        var pending_group_indexes = std.ArrayListUnmanaged(usize).empty;
        errdefer pending_group_indexes.deinit(alloc);
        try pending_group_indexes.ensureTotalCapacity(alloc, groups.len);
        for (groups, 0..) |_, index| pending_group_indexes.appendAssumeCapacity(index);
        return .{
            .metadata_group_id = snapshot.status.metadata_group_id,
            .metadata_incarnation = snapshot.status.metadata_incarnation,
            .table_id = table.table_id,
            .indexes_json = indexes_json,
            .schema_json = schema_json,
            .topology = metadata_api.catalogTableTopology(table.table_id, snapshot.ranges),
            .groups = groups,
            .pending_group_indexes = pending_group_indexes,
        };
    }

    fn structuralReconcilePlanStillCurrent(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        plan: *const StructuralReconcilePlan,
    ) !bool {
        if (self.catalog.vtable.requires_linearizable_publication_fence and
            self.catalog.vtable.validate_table_publication == null)
        {
            return error.CatalogPublicationFenceUnavailable;
        }
        if (self.catalog.vtable.validate_table_publication != null) {
            const incarnation = plan.metadata_incarnation orelse return false;
            return try self.catalog.validateTablePublication(.{
                .metadata_group_id = plan.metadata_group_id,
                .metadata_incarnation = incarnation,
                .table_id = plan.table_id,
                .table_name = table_name,
                .schema_json = plan.schema_json,
                .indexes_json = plan.indexes_json,
                .topology = plan.topology,
            });
        }

        var snapshot = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&snapshot);
        if (snapshot.status.metadata_group_id != plan.metadata_group_id or
            !structuralReconcileIncarnationMatches(plan.metadata_incarnation, snapshot.status.metadata_incarnation)) return false;
        const table = metadata_mod.findAdminTable(&snapshot, plan.table_id) orelse return false;
        if (!std.mem.eql(u8, table.name, table_name) or
            !std.mem.eql(u8, table.indexes_json, plan.indexes_json) or
            !std.mem.eql(u8, table.schema_json, plan.schema_json)) return false;

        var matching_groups: usize = 0;
        for (snapshot.ranges) |range| {
            if (range.table_id != plan.table_id) continue;
            matching_groups += 1;
            const group = structuralReconcilePlanGroup(plan, range.group_id) orelse return false;
            if (!metadata_table_manager.rangeRecordsEqual(group.range, range)) return false;
        }
        return matching_groups == plan.groups.len;
    }

    fn structuralReconcilePlanGroup(plan: *const StructuralReconcilePlan, group_id: u64) ?*const StructuralReconcileGroup {
        var lo: usize = 0;
        var hi = plan.groups.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const candidate = &plan.groups[mid];
            if (candidate.range.group_id < group_id) {
                lo = mid + 1;
            } else if (candidate.range.group_id > group_id) {
                hi = mid;
            } else {
                return candidate;
            }
        }
        return null;
    }

    fn structuralReconcileIncarnationMatches(
        expected: ?metadata_api.MetadataClusterIncarnation,
        actual: ?metadata_api.MetadataClusterIncarnation,
    ) bool {
        const expected_value = expected orelse return actual == null;
        const actual_value = actual orelse return false;
        return std.mem.eql(u8, &expected_value, &actual_value);
    }

    fn reconcileTableGroupStructureWithRuntime(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        metadata: StartupCatchUpMetadata,
        observations: *std.ArrayListUnmanaged(StructuralRuntimeObservation),
    ) !StructuralReconcileGroupOutcome {
        // The target generation is unpublished until catch-up and sync finish.
        // Queries are routed to the retained read generation, so do not turn a
        // corpus-sized backfill into a table-wide read outage.
        if (!self.tryBeginReadCompatibleGroupOperation(table_name, group_id)) return .busy;
        defer self.endGroupOperation(table_name, group_id);

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const lsm_root_generation = self.visibleRootGeneration(group_id);
        const identity_namespace = metadata.identity_namespace orelse
            try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id);
        const target_index_name = metadata.target_index_name;

        var configured_indexes_storage: ?StartupConfiguredIndexes = null;
        if (metadata.indexes_json) |value| configured_indexes_storage = try parseStartupConfiguredIndexes(alloc, value);
        defer if (configured_indexes_storage) |*summary| summary.deinit(alloc);

        if (self.write_cache) |cache| {
            var cached = self.getOrOpenCachedDbModeAtGeneration(alloc, cache, path, group_id, lsm_root_generation, table_name, .default_async, null, null, .{
                .indexes_json = metadata.indexes_json,
                .schema_json = if (target_index_name == null) metadata.schema_json else null,
                .identity_namespace = identity_namespace,
            }, .{
                .reconcile_target_index_name = target_index_name,
                .reuse_cached_writer_for_metadata_reconcile = true,
            }) catch |err| {
                if (isTransientWriterOpenConflict(err)) return .busy;
                return err;
            };
            var cached_active = true;
            defer if (cached_active) cached.deinit(alloc);
            errdefer if (cached_active) {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                cache.retireCachedLeaseAfterMutationFailureLocked(&cached);
                cached_active = false;
            };

            if (target_index_name == null) {
                if (metadata.schema_json) |schema_json| try applyLocalTableSchemaJson(alloc, cached.db, schema_json);
            }
            if (metadata.indexes_json) |indexes_json| {
                const managed_config_matches = matches: {
                    lockAtomic(&self.local_db_mutex);
                    defer self.local_db_mutex.unlock();
                    break :matches ProvisionedTableWriteCache.entryManagedConfigMatches(cached.entry.?, indexes_json);
                };
                if (!managed_config_matches) {
                    try reconfigureManagedDbEnrichmentRuntime(
                        alloc,
                        cached.db,
                        indexes_json,
                        self.backend_runtime,
                        self.antfly_provider,
                        self.inference_api_url,
                        self.secret_store,
                        self.remote_content,
                    );
                    lockAtomic(&self.local_db_mutex);
                    ProvisionedTableWriteCache.publishEntryManagedConfig(cached.entry.?, indexes_json);
                    self.local_db_mutex.unlock();
                }
                if (target_index_name == null) {
                    if (metadata.schema_json) |schema_json| {
                        lockAtomic(&self.local_db_mutex);
                        defer self.local_db_mutex.unlock();
                        try cache.replaceTableMetadataLocked(table_name, indexes_json, schema_json);
                        try cache.replaceEntrySchemaLocked(cached.entry.?, schema_json);
                        cached.schema_json = cached.entry.?.schema_json;
                    }
                }
            }
            if (metadata.indexes_json) |indexes_json| {
                // Reconciliation owns the desired-state diff. Pre-deleting
                // configured names would turn an unchanged generation into a
                // destructive rebuild and race its durable cleanup fence.
                const reconcile_summary = if (target_index_name) |target|
                    try metadata_table_provisioner.reconcileDbIndexTarget(alloc, cached.db, indexes_json, target)
                else
                    try metadata_table_provisioner.reconcileDbIndexesWithOptions(alloc, cached.db, indexes_json, .{
                        .drain_resolver_backfill = false,
                        .source_table = table_name,
                        .destination_authorizer = self.destination_authorizer,
                    });
                if (reconcile_summary.indexes_pending != 0) {
                    _ = try cached.db.advanceGeneratedArtifactCleanupPage(metadata.target_index_name);
                    if (try cached.db.hasPendingIndexRepairIntents(alloc)) {
                        // Reconciliation owns admission, while the DataServer's
                        // capacity-fenced scheduler owns corpus work. The
                        // caller publishes this debt edge once per group so it
                        // cannot erase scheduler backoff on every retry.
                        if (self.local_index_repair_debt_hook != null) {
                            appendStructuralRuntimeStatusObservation(
                                self,
                                alloc,
                                table_name,
                                group_id,
                                cached.db,
                                lsm_root_generation,
                                .artifact_rebuild,
                                observations,
                            ) catch |err| {
                                lockAtomic(&self.local_db_mutex);
                                defer self.local_db_mutex.unlock();
                                cache.retireCachedLeaseAfterMutationFailureLocked(&cached);
                                cached_active = false;
                                return err;
                            };
                            // Install shard authority before the compatible
                            // group operation releases. Repair may now overlap
                            // later shards without outrunning its clear edge.
                            self.ensureStructuralRepairHandoffStatus(table_name, group_id);
                            return .repair_pending;
                        }
                    } else {
                        return .busy;
                    }
                }
            }
            if (configured_indexes_storage) |configured_indexes| {
                for (configured_indexes.items) |item| {
                    if (metadata.target_index_name) |target| {
                        if (!std.mem.eql(u8, item.name, target)) continue;
                    }
                    const catch_up = catchUpManagedIndexCreate(
                        alloc,
                        cached.db,
                        item.name,
                        self.local_index_repair_debt_hook != null,
                    ) catch |err| {
                        lockAtomic(&self.local_db_mutex);
                        defer self.local_db_mutex.unlock();
                        cache.retireCachedLeaseAfterMutationFailureLocked(&cached);
                        cached_active = false;
                        return err;
                    };
                    switch (catch_up) {
                        .complete => {},
                        .retry => return .busy,
                        .asynchronous => |producer_target_sequence| {
                            appendStructuralRuntimeStatusObservation(
                                self,
                                alloc,
                                table_name,
                                group_id,
                                cached.db,
                                lsm_root_generation,
                                .artifact_rebuild,
                                observations,
                            ) catch |err| {
                                lockAtomic(&self.local_db_mutex);
                                defer self.local_db_mutex.unlock();
                                cache.retireCachedLeaseAfterMutationFailureLocked(&cached);
                                cached_active = false;
                                return err;
                            };
                            if (markLatestStructuralIndexPublicationPending(
                                observations,
                                item.name,
                                producer_target_sequence,
                                item.kind == .dense_vector,
                            )) |target| {
                                self.ensureStructuralPublicationHandoffStatus(table_name, group_id, target);
                                return .publication_pending;
                            }
                        },
                        .delegated => {
                            appendStructuralRuntimeStatusObservation(
                                self,
                                alloc,
                                table_name,
                                group_id,
                                cached.db,
                                lsm_root_generation,
                                .artifact_rebuild,
                                observations,
                            ) catch |err| {
                                lockAtomic(&self.local_db_mutex);
                                defer self.local_db_mutex.unlock();
                                cache.retireCachedLeaseAfterMutationFailureLocked(&cached);
                                cached_active = false;
                                return err;
                            };
                            self.ensureStructuralRepairHandoffStatus(table_name, group_id);
                            return .repair_pending;
                        },
                    }
                }
            } else {
                cached.db.runUntilIdle() catch |err| {
                    lockAtomic(&self.local_db_mutex);
                    defer self.local_db_mutex.unlock();
                    cache.retireCachedLeaseAfterMutationFailureLocked(&cached);
                    cached_active = false;
                    return err;
                };
            }
            appendStructuralRuntimeStatusObservation(
                self,
                alloc,
                table_name,
                group_id,
                cached.db,
                lsm_root_generation,
                .idle,
                observations,
            ) catch |err| {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                cache.retireCachedLeaseAfterMutationFailureLocked(&cached);
                cached_active = false;
                return err;
            };
            cache.publishCachedLeaseGeneration(&cached, lsm_root_generation);
            return .complete;
        }

        var db = if (metadata.indexes_json) |indexes_json|
            openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
                alloc,
                path,
                indexes_json,
                null,
                null,
                lsm_root_generation,
                null,
                .default_async,
                self.backend_runtime,
                self.antfly_provider,
                self.secret_store,
                self.remote_content,
                identity_namespace,
                .{
                    .drain_resolver_backfill = false,
                    .schema_json_before_index_load = metadata.schema_json,
                    .inference_api_url = self.inference_api_url,
                    .ha_write_gate = self.ha_write_gate,
                    .ha_async_effect_mirror = self.ha_async_mirror,
                    .ha_async_batch_mirror = self.ha_async_mirror,
                    .ha_async_metadata_mirror = self.ha_async_mirror,
                    .reconcile_target_index_name = target_index_name,
                },
            ) catch |err| {
                if (isTransientWriterOpenConflict(err)) return .busy;
                return err;
            }
        else
            db_mod.DB.open(alloc, path, .{
                .open_mode = .writer_no_replay,
                .lsm_root_generation = lsm_root_generation,
                .backend_runtime = self.backend_runtime,
                .identity_namespace = identity_namespace,
                .prefer_existing_identity_namespace = identity_namespace != null,
                .ha_write_gate = self.ha_write_gate,
                .ha_async_effect_mirror = self.ha_async_mirror,
                .ha_async_batch_mirror = self.ha_async_mirror,
                .ha_async_metadata_mirror = self.ha_async_mirror,
            }) catch |err| {
                if (isTransientWriterOpenConflict(err)) return .busy;
                return err;
            };
        defer db.close();
        try validateProvisionedDbIdentityNamespaceExpected(identity_namespace, &db);
        if (target_index_name == null) {
            if (metadata.schema_json) |schema_json| try applyLocalTableSchemaJson(alloc, &db, schema_json);
        }
        if (metadata.indexes_json) |indexes_json| {
            // Preserve matching generations and let the provisioner retire
            // only definitions whose desired configuration actually changed.
            const reconcile_summary = if (target_index_name) |target|
                try metadata_table_provisioner.reconcileDbIndexTarget(alloc, &db, indexes_json, target)
            else
                try metadata_table_provisioner.reconcileDbIndexesWithOptions(alloc, &db, indexes_json, .{
                    .drain_resolver_backfill = false,
                    .source_table = table_name,
                    .destination_authorizer = self.destination_authorizer,
                });
            if (reconcile_summary.indexes_pending != 0) {
                _ = try db.advanceGeneratedArtifactCleanupPage(metadata.target_index_name);
                if (try db.hasPendingIndexRepairIntents(alloc)) {
                    if (self.local_index_repair_debt_hook != null) {
                        try appendStructuralRuntimeStatusObservation(
                            self,
                            alloc,
                            table_name,
                            group_id,
                            &db,
                            lsm_root_generation,
                            .artifact_rebuild,
                            observations,
                        );
                        self.ensureStructuralRepairHandoffStatus(table_name, group_id);
                        return .repair_pending;
                    }
                } else {
                    return .busy;
                }
            }
        }
        if (configured_indexes_storage) |configured_indexes| {
            for (configured_indexes.items) |item| {
                if (metadata.target_index_name) |target| {
                    if (!std.mem.eql(u8, item.name, target)) continue;
                }
                switch (try catchUpManagedIndexCreate(
                    alloc,
                    &db,
                    item.name,
                    self.local_index_repair_debt_hook != null,
                )) {
                    .complete => {},
                    .retry => return .busy,
                    .asynchronous => |producer_target_sequence| {
                        try appendStructuralRuntimeStatusObservation(
                            self,
                            alloc,
                            table_name,
                            group_id,
                            &db,
                            lsm_root_generation,
                            .artifact_rebuild,
                            observations,
                        );
                        if (markLatestStructuralIndexPublicationPending(
                            observations,
                            item.name,
                            producer_target_sequence,
                            item.kind == .dense_vector,
                        )) |target| {
                            self.ensureStructuralPublicationHandoffStatus(table_name, group_id, target);
                            return .publication_pending;
                        }
                    },
                    .delegated => {
                        try appendStructuralRuntimeStatusObservation(
                            self,
                            alloc,
                            table_name,
                            group_id,
                            &db,
                            lsm_root_generation,
                            .artifact_rebuild,
                            observations,
                        );
                        self.ensureStructuralRepairHandoffStatus(table_name, group_id);
                        return .repair_pending;
                    },
                }
            }
        } else {
            try db.runUntilIdle();
        }
        try appendStructuralRuntimeStatusObservation(
            self,
            alloc,
            table_name,
            group_id,
            &db,
            lsm_root_generation,
            .idle,
            observations,
        );
        return .complete;
    }

    fn requestTableStructuralReconcile(
        ptr: *anyopaque,
        _: std.mem.Allocator,
        table_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.requestTableStructuralReconcile(std.heap.page_allocator, table_name);
        try self.enqueueTableStructuralReconcile(table_name);
        return {};
    }

    fn requestTableIndexStructuralReconcile(
        ptr: *anyopaque,
        _: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.requestTableIndexStructuralReconcile(std.heap.page_allocator, table_name, index_name);
        // This queue reconciles desired state in either direction. Create
        // admission is a separate synchronous operation so a delete retry can
        // enqueue after the catalog has intentionally removed the target.
        try self.enqueueTableIndexStructuralReconcile(table_name, index_name);
        return {};
    }

    fn beginBulkIngest(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.beginBulkIngest(alloc, table_name);
        try enforceHAWriteGateOptional(self.ha_write_gate);

        const EntryLease = struct {
            cached: ProvisionedTableWriteCache.CachedDb,
            already_open: bool,
            already_auto: bool,
            started: bool = false,
        };
        var leases = std.ArrayListUnmanaged(EntryLease).empty;
        var cache_alloc = alloc;
        defer {
            for (leases.items) |*item| item.cached.deinit(cache_alloc);
            leases.deinit(cache_alloc);
        }

        lockAtomic(&self.local_db_mutex);
        var mutex_locked = true;
        defer if (mutex_locked) self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return null;
        cache_alloc = cache.alloc;

        if (cache.findActiveBulkIngestSession(table_name)) |idx| {
            const session = &cache.active_bulk_ingest_sessions.items[idx];
            if (session.state != .active) return error.LsmRootWriterAlreadyOpen;
            session.depth = std.math.add(usize, session.depth, 1) catch
                return error.BulkIngestDepthOverflow;
            return {};
        }
        for (cache.entries.items) |entry| {
            if (std.mem.eql(u8, entry.table_name, table_name) and
                entry.auto_bulk_ingest_finishing)
            {
                return error.LsmRootWriterAlreadyOpen;
            }
        }

        try cache.active_bulk_ingest_sessions.ensureUnusedCapacity(cache.alloc, 1);
        try leases.ensureTotalCapacity(cache.alloc, cache.entries.items.len);
        var owned_table_name: ?[]u8 = try cache.alloc.dupe(u8, table_name);
        errdefer if (owned_table_name) |value| cache.alloc.free(value);
        for (cache.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            const already_open = entry.bulk_ingest_session_open;
            leases.appendAssumeCapacity(.{
                .cached = cache.leaseEntryLocked(entry),
                .already_open = already_open,
                .already_auto = entry.auto_bulk_ingest_session_open,
            });
            if (!already_open) {
                // Reserve the entry before releasing the cache mutex. Cache
                // retirement and maintenance already honor this flag, while
                // the table transition fences all new writer admission.
                entry.bulk_ingest_session_open = true;
                entry.auto_bulk_ingest_session_open = false;
                entry.auto_bulk_ingest_ops = 0;
                entry.auto_bulk_ingest_started_ns = 0;
                entry.auto_bulk_ingest_last_ns = 0;
                entry.auto_bulk_ingest_finish_requested = false;
            }
        }
        cache.active_bulk_ingest_sessions.appendAssumeCapacity(.{
            .table_name = owned_table_name.?,
            .state = .opening,
        });
        owned_table_name = null;
        self.local_db_mutex.unlock();
        mutex_locked = false;

        var first_err: ?anyerror = null;
        for (leases.items) |*item| {
            if (item.already_open) continue;
            item.cached.db.beginBulkIngestSession() catch |err| {
                first_err = err;
                break;
            };
            item.started = true;
        }

        lockAtomic(&self.local_db_mutex);
        mutex_locked = true;
        const session_idx = cache.findActiveBulkIngestSession(table_name);
        const abort_requested = if (session_idx) |idx|
            cache.active_bulk_ingest_sessions.items[idx].abort_requested
        else
            true;
        if (session_idx == null and first_err == null) first_err = error.InvalidBulkIngestTransition;
        if (first_err == null and !abort_requested) {
            for (leases.items) |*item| {
                if (!item.started) continue;
                const entry = item.cached.entry orelse continue;
                entry.bulk_ingest_session_open = true;
                entry.auto_bulk_ingest_session_open = false;
                entry.auto_bulk_ingest_ops = 0;
                entry.auto_bulk_ingest_started_ns = 0;
                entry.auto_bulk_ingest_last_ns = 0;
                entry.auto_bulk_ingest_finish_requested = false;
            }
            cache.active_bulk_ingest_sessions.items[session_idx.?].state = .active;
            return {};
        }
        self.local_db_mutex.unlock();
        mutex_locked = false;

        for (leases.items) |*item| {
            if (!item.started and !(abort_requested and item.already_open)) continue;
            if (item.already_auto) {
                item.cached.db.abortPrimaryStoreAutoBulkIngestSession();
            } else {
                item.cached.db.abortBulkIngestSession();
            }
        }

        lockAtomic(&self.local_db_mutex);
        mutex_locked = true;
        for (leases.items) |*item| {
            if (item.already_open and !abort_requested) continue;
            if (item.cached.entry) |entry| ProvisionedTableWriteCache.clearEntryBulkIngestState(entry);
        }
        if (cache.findActiveBulkIngestSession(table_name)) |idx| {
            var removed = cache.active_bulk_ingest_sessions.orderedRemove(idx);
            removed.deinit(cache.alloc);
        }
        if (first_err) |err| return err;
        return error.BulkIngestAborted;
    }

    fn finishBulkIngest(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        options: backend_types.BulkIngestFinishOptions,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.finishBulkIngest(alloc, table_name, options);
        try enforceHAWriteGateOptional(self.ha_write_gate);

        const EntryLease = struct {
            cached: ProvisionedTableWriteCache.CachedDb,
            auto: bool,
            finished: bool = false,
        };
        var leases = std.ArrayListUnmanaged(EntryLease).empty;
        var cache_alloc = alloc;
        defer {
            for (leases.items) |*item| item.cached.deinit(cache_alloc);
            leases.deinit(cache_alloc);
        }

        lockAtomic(&self.local_db_mutex);
        var mutex_locked = true;
        defer if (mutex_locked) self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return null;
        cache_alloc = cache.alloc;
        const idx = cache.findActiveBulkIngestSession(table_name) orelse return {};
        const session = &cache.active_bulk_ingest_sessions.items[idx];
        if (session.state != .active) return error.LsmRootWriterAlreadyOpen;
        if (session.depth > 1) {
            session.depth -= 1;
            return {};
        }
        try leases.ensureTotalCapacity(cache.alloc, cache.entries.items.len);
        for (cache.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name) or !entry.bulk_ingest_session_open) continue;
            leases.appendAssumeCapacity(.{
                .cached = cache.leaseEntryLocked(entry),
                .auto = entry.auto_bulk_ingest_session_open,
            });
        }
        session.state = .finishing;
        self.local_db_mutex.unlock();
        mutex_locked = false;

        var first_err: ?anyerror = null;
        for (leases.items) |*item| {
            if (item.auto) {
                item.cached.db.finishPrimaryStoreAutoBulkIngestSessionWithOptions(options) catch |err| {
                    if (first_err == null) first_err = err;
                    continue;
                };
            } else {
                item.cached.db.finishBulkIngestSessionWithOptions(options) catch |err| {
                    if (first_err == null) first_err = err;
                    continue;
                };
            }
            item.finished = true;
        }

        lockAtomic(&self.local_db_mutex);
        mutex_locked = true;
        for (leases.items) |*item| {
            if (item.finished) {
                if (item.cached.entry) |entry| ProvisionedTableWriteCache.clearEntryBulkIngestState(entry);
            }
        }
        if (cache.findActiveBulkIngestSession(table_name)) |active_idx| {
            if (first_err == null) {
                var removed = cache.active_bulk_ingest_sessions.orderedRemove(active_idx);
                removed.deinit(cache.alloc);
            } else {
                // Retain the session and only the entries whose finish failed.
                // A retry must re-enter the real DB finish path rather than
                // falsely succeeding against forgotten publication debt.
                cache.active_bulk_ingest_sessions.items[active_idx].state = .active;
            }
        }
        if (first_err) |err| return err;
        return {};
    }

    fn abortBulkIngest(ptr: *anyopaque, table_name: []const u8) void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| {
            owner.abortBulkIngest(table_name);
            return;
        }

        var leases = std.ArrayListUnmanaged(struct {
            cached: ProvisionedTableWriteCache.CachedDb,
            auto: bool,
        }).empty;
        var cache_alloc = std.heap.page_allocator;
        defer {
            for (leases.items) |*item| item.cached.deinit(cache_alloc);
            leases.deinit(cache_alloc);
        }

        lockAtomic(&self.local_db_mutex);
        const cache = self.write_cache orelse {
            self.local_db_mutex.unlock();
            return;
        };
        cache_alloc = cache.alloc;
        const idx = cache.findActiveBulkIngestSession(table_name) orelse {
            self.local_db_mutex.unlock();
            return;
        };
        const session = &cache.active_bulk_ingest_sessions.items[idx];
        if (session.state == .opening) {
            session.abort_requested = true;
            self.local_db_mutex.unlock();
            return;
        }
        if (session.state == .finishing) {
            self.local_db_mutex.unlock();
            return;
        }
        leases.ensureTotalCapacity(cache.alloc, cache.entries.items.len) catch {
            cache.abortBulkIngestLocked(table_name);
            self.local_db_mutex.unlock();
            return;
        };
        for (cache.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name) or !entry.bulk_ingest_session_open) continue;
            leases.appendAssumeCapacity(.{
                .cached = cache.leaseEntryLocked(entry),
                .auto = entry.auto_bulk_ingest_session_open,
            });
        }
        session.state = .finishing;
        self.local_db_mutex.unlock();

        for (leases.items) |*item| {
            if (item.auto) {
                item.cached.db.abortPrimaryStoreAutoBulkIngestSession();
            } else {
                item.cached.db.abortBulkIngestSession();
            }
        }

        lockAtomic(&self.local_db_mutex);
        for (leases.items) |*item| {
            if (item.cached.entry) |entry| ProvisionedTableWriteCache.clearEntryBulkIngestState(entry);
        }
        if (cache.findActiveBulkIngestSession(table_name)) |active_idx| {
            var removed = cache.active_bulk_ingest_sessions.orderedRemove(active_idx);
            removed.deinit(cache.alloc);
        }
        self.local_db_mutex.unlock();
    }

    pub fn source(self: *ProvisionedTableWriteSource) TableWriteSource {
        return .{
            .ptr = self,
            .vtable = &.{
                .create_table = createTable,
                .update_schema = updateSchema,
                .create_index = createIndex,
                .put_artifact_enrichment = putArtifactEnrichment,
                .delete_artifact_enrichment = deleteArtifactEnrichment,
                .drop_index = dropIndex,
                .drop_table = dropTable,
                .commit_transaction = commitTransaction,
                .commit_transaction_with_cancellation = commitTransactionWithCancellation,
                .commit_batch = commitBatch,
                .commit_batch_with_cancellation = commitBatchWithCancellation,
                .commit_transaction_with_id = commitTransactionWithId,
                .commit_transaction_with_id_with_cancellation = commitTransactionWithIdAndCancellation,
                .acknowledge_transaction_commit = acknowledgeTransactionCommit,
                .backup_table = backupTable,
                .restore_table = restoreTable,
                .begin_restore_lifecycle = beginRestoreLifecycle,
                .finish_restore_lifecycle = finishRestoreLifecycle,
                .batch = batch,
                .begin_bulk_ingest = beginBulkIngest,
                .finish_bulk_ingest = finishBulkIngest,
                .abort_bulk_ingest = abortBulkIngest,
                .batch_group_local = batchGroupLocal,
                .txn_begin_group_local = txnBeginGroupLocal,
                .txn_begin_group_local_with_pre_decision_context = txnBeginGroupLocalWithPreDecisionContext,
                .txn_prepare_group_local = txnPrepareGroupLocal,
                .txn_prepare_group_local_with_pre_decision_context = txnPrepareGroupLocalWithPreDecisionContext,
                .txn_resolve_group_local = txnResolveGroupLocal,
                .txn_resolve_group_local_with_cancellation = txnResolveGroupLocalWithCancellation,
                .txn_status_group_local = txnStatusGroupLocal,
                .txn_acknowledge_group_local = txnAcknowledgeGroupLocal,
                .corrupt_embedding_artifact = corruptEmbeddingArtifact,
                .reprocess_document_artifact = reprocessDocumentArtifact,
                .reprocess_document_artifact_range = reprocessDocumentArtifactRange,
                .list_artifact_repair_issues = listArtifactRepairIssues,
                .repair_artifact_issues = repairArtifactIssues,
                .repair_artifact_issues_controlled = repairArtifactIssuesControlled,
                .update_document_artifact_child_range_placement = updateDocumentArtifactChildRangePlacement,
                .apply_document_artifact_child_range_batch = applyDocumentArtifactChildRangeBatch,
                .reprocess_document_artifact_group_local = reprocessDocumentArtifactGroupLocal,
                .reprocess_document_artifact_range_group_local = reprocessDocumentArtifactRangeGroupLocal,
                .list_artifact_repair_issues_group_local = listArtifactRepairIssuesGroupLocal,
                .repair_artifact_issues_group_local = repairArtifactIssuesGroupLocal,
                .repair_artifact_issues_group_local_controlled = repairArtifactIssuesGroupLocalControlled,
                .update_document_artifact_child_range_placement_group_local = updateDocumentArtifactChildRangePlacementGroupLocal,
                .apply_document_artifact_child_range_batch_group_local = applyDocumentArtifactChildRangeBatchGroupLocal,
                .local_runtime_statuses = localRuntimeStatuses,
                .request_table_structural_reconcile = requestTableStructuralReconcile,
                .request_table_index_structural_reconcile = requestTableIndexStructuralReconcile,
            },
        };
    }

    fn putArtifactEnrichment(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        artifact_name: []const u8,
        enrichment_json: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.putArtifactEnrichment(alloc, table_name, artifact_name, enrichment_json);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        if (self.write_cache != null) {
            self.beginLocalStructuralCachedDbMutation(table_name);
            errdefer self.abortLocalStructuralCachedDbMutation(table_name);
            try putCachedLocalArtifactEnrichment(self, alloc, table_name, artifact_name, enrichment_json);
            self.finishLocalStructuralCachedDbMutation(table_name);
        } else {
            self.beginLocalStructuralCacheUpdate(table_name);
            errdefer self.abortLocalStructuralCacheUpdate(table_name);
            try putLocalArtifactEnrichment(alloc, self.catalog, self.replica_root_dir, self.backend_runtime, table_name, artifact_name, enrichment_json);
            self.finishLocalStructuralCacheUpdate(table_name);
        }
        self.notifyLocalChange(table_name, .structural);
    }

    fn deleteArtifactEnrichment(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        artifact_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.deleteArtifactEnrichment(alloc, table_name, artifact_name);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        if (self.write_cache != null) {
            self.beginLocalStructuralCachedDbMutation(table_name);
            errdefer self.abortLocalStructuralCachedDbMutation(table_name);
            try dropCachedLocalArtifactEnrichment(self, alloc, table_name, artifact_name);
            self.finishLocalStructuralCachedDbMutation(table_name);
        } else {
            self.beginLocalStructuralCacheUpdate(table_name);
            errdefer self.abortLocalStructuralCacheUpdate(table_name);
            try dropLocalArtifactEnrichment(alloc, self.catalog, self.replica_root_dir, self.backend_runtime, table_name, artifact_name);
            self.finishLocalStructuralCacheUpdate(table_name);
        }
        self.notifyLocalChange(table_name, .structural);
    }

    fn createTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: tables_api.CreateTableRequest,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.createTable(alloc, table_name, req);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        std.log.info("provisioned create table local begin table={s}", .{table_name});
        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;

        const raw_indexes_json = req.indexes_json orelse tables_api.default_indexes_json;
        const schema_json = tables_api.effectiveSchemaJson(req.schema_json);
        const indexes_json = try tables_api.expandSchemaDerivedAlgebraicIndexesAlloc(alloc, table_name, raw_indexes_json, schema_json);
        defer alloc.free(indexes_json);

        if (self.write_cache) |cache| {
            // Catalog admission and local owner reconciliation are concurrent.
            // Treat create as an idempotent ensure operation so a startup or
            // reconcile owner that already opened the generation is reused
            // through the shared writer cache instead of deleted underneath.
            self.beginLocalStructuralCachedDbMutation(table_name);
            errdefer self.abortLocalStructuralCachedDbMutation(table_name);

            var cached_groups = std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb).empty;
            defer {
                for (cached_groups.items) |*cached| cached.deinit(alloc);
                cached_groups.deinit(alloc);
            }
            try cached_groups.ensureTotalCapacity(alloc, group_ids.len);
            const target_generations = try alloc.alloc(u64, group_ids.len);
            defer alloc.free(target_generations);

            for (group_ids, 0..) |group_id, group_index| {
                std.log.info("provisioned create table local group begin table={s} group_id={d}", .{ table_name, group_id });
                const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
                defer alloc.free(path);

                const visible_generation = self.visibleRootGeneration(group_id);
                {
                    var cached = try self.getOrOpenCachedDbForLocalMutation(
                        alloc,
                        cache,
                        path,
                        group_id,
                        visible_generation,
                        table_name,
                        false,
                    );
                    errdefer cached.deinit(alloc);
                    const entry = cached.entry orelse return error.StaleCachedDbLease;
                    if (entry.retired) return error.StaleCachedDbLease;
                    target_generations[group_index] = entry.lsm_root_generation;
                    try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, cached.db);
                    try applyLocalTableSchemaJson(alloc, cached.db, schema_json);
                    // Catalog admission and local create can race an earlier
                    // startup/status open of this generation. The entry
                    // fingerprint is publication metadata, not proof that the
                    // resident DB successfully installed the same producer
                    // set: an adopted/opened writer can carry the new catalog
                    // fingerprint while still owning the old (often empty)
                    // runtime. Create is the authoritative, one-shot commit
                    // boundary, so always install its requested runtime before
                    // reconciling durable indexes. Publish the matching
                    // fingerprint only after every group commits.
                    try reconfigureManagedDbEnrichmentRuntime(
                        alloc,
                        cached.db,
                        indexes_json,
                        self.backend_runtime,
                        self.antfly_provider,
                        self.inference_api_url,
                        self.secret_store,
                        self.remote_content,
                    );
                    _ = try metadata_table_provisioner.reconcileDbIndexesWithOptions(alloc, cached.db, indexes_json, .{
                        .drain_resolver_backfill = false,
                        .source_table = table_name,
                        .destination_authorizer = self.destination_authorizer,
                    });
                    cached_groups.appendAssumeCapacity(cached);
                }
                std.log.info("provisioned create table local group ready table={s} group_id={d}", .{ table_name, group_id });
            }

            var publication = try cache.prepareStructuralPublication(
                table_name,
                indexes_json,
                schema_json,
                cached_groups.items.len,
            );
            defer publication.deinit(cache.alloc);
            lockAtomic(&self.local_db_mutex);
            cache.publishStructuralMutationLocked(cached_groups.items, target_generations, &publication) catch |err| {
                self.local_db_mutex.unlock();
                return err;
            };
            self.local_db_mutex.unlock();

            self.finishLocalStructuralCachedDbMutation(table_name);
            std.log.info("provisioned create table local notify table={s}", .{table_name});
            self.notifyLocalChange(table_name, .structural);
            // Structural publication is the create commit point. Runtime
            // status is observational and may be fenced by the invalidation
            // emitted above or by a concurrent refresh; it must never turn an
            // already-committed create into an HTTP failure.
            runTestBeforePostCreateRuntimeStatusPublishHook();
            for (group_ids, cached_groups.items) |group_id, cached| {
                publishRuntimeStatusSnapshotConsistent(self, alloc, table_name, group_id, cached.db) catch |err| switch (err) {
                    error.RuntimeStatusPublicationFenced => std.log.debug(
                        "post-create runtime status publication deferred table={s} group_id={d} err={s}",
                        .{ table_name, group_id, @errorName(err) },
                    ),
                    else => std.log.warn(
                        "post-create runtime status publication failed after commit table={s} group_id={d} err={s}",
                        .{ table_name, group_id, @errorName(err) },
                    ),
                };
            }
            std.log.info("provisioned create table local done table={s}", .{table_name});
            return {};
        }

        self.beginLocalStructuralMutation(table_name);
        errdefer self.abortLocalStructuralMutation(table_name);

        for (group_ids) |group_id| {
            std.log.info("provisioned create table local group begin table={s} group_id={d}", .{ table_name, group_id });
            try deleteGroupPathIfPresent(alloc, self.replica_root_dir, group_id);
            const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);

            const identity_namespace = try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id);
            const lsm_root_generation = self.visibleRootGeneration(group_id);
            if (self.write_cache) |cache| {
                if (cache.backend_runtime == null) cache.backend_runtime = self.backend_runtime;
                cache.antfly_provider = self.antfly_provider;
                cache.inference_api_url = self.inference_api_url;
                cache.secret_store = self.secret_store;
                cache.remote_content = self.remote_content;
            }
            const seed_create_table_writer = self.seed_create_table_writers and self.write_cache != null;
            const open_mode: ManagedDbOpenMode = if (seed_create_table_writer) .default else .startup_catch_up;
            const effective_ha_mirror = haMirrorForManagedDbOpenMode(open_mode, self.ha_async_mirror);
            var opened: ?db_mod.DB = try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
                alloc,
                path,
                indexes_json,
                if (self.write_cache) |cache| cache.lsm_cache else null,
                if (self.write_cache) |cache| cache.hbc_cache else null,
                lsm_root_generation,
                if (self.write_cache) |cache| cache.resource_manager else null,
                open_mode,
                if (self.write_cache) |cache| cache.backend_runtime else self.backend_runtime,
                self.antfly_provider,
                self.secret_store,
                self.remote_content,
                identity_namespace,
                .{
                    .inference_api_url = self.inference_api_url,
                    .drain_resolver_backfill = false,
                    .schema_json_before_index_load = schema_json,
                    .ha_write_gate = self.ha_write_gate,
                    .ha_async_effect_mirror = effective_ha_mirror,
                    .ha_async_batch_mirror = effective_ha_mirror,
                    .ha_async_metadata_mirror = effective_ha_mirror,
                    .transaction_recovery = if (open_mode == .startup_catch_up or open_mode == .restore_repair or open_mode == .query_readonly or open_mode == .status_only)
                        .{}
                    else
                        self.transactionRecoveryConfig(),
                },
            );
            defer if (opened) |*db| db.close();
            try applyLocalTableSchemaJson(alloc, &opened.?, schema_json);
            // Register entity resolvers declared in the index config. Indexes
            // and enrichments are provisioned through the managed-open path, but
            // resolvers are not, so do it here (idempotent: addResolver skips
            // names that already exist on reopen).
            _ = try metadata_table_provisioner.ensureResolversWithOptions(alloc, &opened.?, indexes_json, .{
                .drain_backfill = false,
                .source_table = table_name,
                .destination_authorizer = self.destination_authorizer,
            });
            if (seed_create_table_writer) {
                try self.write_cache.?.seedCreatedDbLocked(&opened, group_id, lsm_root_generation, table_name, indexes_json, schema_json);
            } else {
                try drainManagedDbBeforeClose(&opened.?);
            }
            std.log.info("provisioned create table local group ready table={s} group_id={d}", .{ table_name, group_id });
        }

        self.finishLocalStructuralMutation(table_name);
        std.log.info("provisioned create table local notify table={s}", .{table_name});
        self.notifyLocalChange(table_name, .structural);
        std.log.info("provisioned create table local done table={s}", .{table_name});
    }

    fn updateSchema(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        schema_json: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.updateSchema(alloc, table_name, schema_json);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;
        const indexes_json = try loadTableIndexesJson(alloc, self.catalog, table_name);
        defer if (indexes_json) |value| alloc.free(value);

        if (self.write_cache) |cache| {
            self.beginLocalStructuralCachedDbMutation(table_name);
            errdefer self.abortLocalStructuralCachedDbMutation(table_name);

            for (group_ids) |group_id| {
                const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
                defer alloc.free(path);
                const target_generation = self.visibleRootGeneration(group_id);

                var cached = try self.getOrOpenCachedDbForLocalMutation(
                    alloc,
                    cache,
                    path,
                    group_id,
                    target_generation,
                    table_name,
                    false,
                );
                defer cached.deinit(alloc);
                try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, cached.db);
                try applyLocalTableSchemaJson(alloc, cached.db, schema_json);
                if (indexes_json) |value| {
                    _ = try metadata_table_provisioner.reconcileDbIndexes(alloc, cached.db, value);
                }
                try drainManagedDbBeforeClose(cached.db);
                try publishRuntimeStatusSnapshotConsistent(self, alloc, table_name, group_id, cached.db);
            }

            lockAtomic(&self.local_db_mutex);
            errdefer self.local_db_mutex.unlock();
            try cache.replaceTableMetadataAndRetireEntriesLocked(table_name, indexes_json orelse "", schema_json);
            self.local_db_mutex.unlock();
            self.finishLocalStructuralCachedDbMutation(table_name);
            self.notifyLocalChange(table_name, .structural);
            return {};
        }

        self.beginLocalStructuralMutation(table_name);
        errdefer self.abortLocalStructuralMutation(table_name);

        for (group_ids) |group_id| {
            const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);

            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try applyLocalTableSchemaJson(alloc, &db, schema_json);
            try drainManagedDbBeforeClose(&db);
            try publishRuntimeStatusSnapshotConsistent(self, alloc, table_name, group_id, &db);
        }

        self.finishLocalStructuralMutation(table_name);
        self.notifyLocalChange(table_name, .structural);
    }

    fn finishLocalIndexCacheUpdateAndNotify(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        managed_visibility_changed: bool,
    ) void {
        self.finishLocalStructuralCacheUpdate(table_name);
        // Publish outside structural/cache admission, but before the
        // synchronous structural hook reports store status. A fenced or
        // skipped snapshot remains best-effort; the structural report and
        // dirty bit still make it retryable without turning committed DDL into
        // an API failure.
        if (managed_visibility_changed) {
            self.publishWriteCacheRuntimeStatusesForTableBestEffort(alloc, table_name);
        }
        self.notifyLocalChange(table_name, .structural);
        if (managed_visibility_changed) {
            self.notifyLocalChange(table_name, .data);
        }
    }

    fn installLocalIndexWriteCapability(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
    ) !void {
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginLocalStructuralIndexCacheUpdate(table_name);
        errdefer self.abortLocalStructuralIndexCacheUpdate(table_name, index_name);
        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);
        var repair_group_ids = std.ArrayListUnmanaged(u64).empty;
        defer repair_group_ids.deinit(alloc);
        if (self.local_index_repair_debt_hook != null) {
            try repair_group_ids.ensureTotalCapacity(alloc, group_ids.len);
        }
        const managed_visibility_changed = try reconcileLocalTableIndexCreate(
            self,
            alloc,
            table_name,
            index_name,
            group_ids,
            if (self.local_index_repair_debt_hook != null) &repair_group_ids else null,
        );
        self.finishLocalIndexCacheUpdateAndNotify(alloc, table_name, managed_visibility_changed);

        // Reconciliation records debt while each DB is already leased. Publish
        // those exact edges only after every structural and DB reservation is
        // released, avoiding a second durable-state read and false cold-owner
        // wakes for groups that were already clean.
        for (repair_group_ids.items) |group_id| {
            self.notifyLocalIndexRepairDebt(table_name, group_id, .enqueue_runnable);
        }
    }

    fn createIndex(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
        index_json: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.createIndex(alloc, table_name, index_name, index_json);
        // This is the synchronous write-capability barrier for create. Generic
        // desired-state reconciliation is intentionally enqueue-only because
        // the same API is also used to retry catalog-driven deletion.
        try self.installLocalIndexWriteCapability(alloc, table_name, index_name);
    }

    fn dropIndex(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.dropIndex(alloc, table_name, index_name);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginLocalStructuralIndexCacheUpdate(table_name);
        errdefer self.abortLocalStructuralIndexCacheUpdate(table_name, index_name);
        runTestBeforeDropIndexWorkHook();
        const managed_visibility_changed = if (self.write_cache) |cache|
            try reconcileCachedLocalTableIndexDrop(self, alloc, cache, table_name, index_name)
        else blk: {
            try dropLocalTableIndex(alloc, self.catalog, self.replica_root_dir, self.backend_runtime, table_name, index_name);
            break :blk false;
        };
        self.finishLocalIndexCacheUpdateAndNotify(alloc, table_name, managed_visibility_changed);
    }

    fn executeDroppedTableCleanup(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        contract: metadata_topology_protocol.DropCleanupContract,
        retire_publication_authority: bool,
    ) !void {
        if (self.dropped_table_cleanup_outer_mutex) |outer_mutex| lockAtomic(outer_mutex);
        defer if (self.dropped_table_cleanup_outer_mutex) |outer_mutex| outer_mutex.unlock();
        const group_ids = contract.group_ids;
        // A durable index repair owns group admission while it advances one
        // bounded build slice. Publish cancellation before waiting for the
        // table-wide structural barrier so dropping a table cannot sit behind
        // corpus work until the request itself times out.
        for (group_ids) |group_id| {
            self.notifyLocalIndexRepairDebt(table_name, group_id, .cancel);
        }
        errdefer for (group_ids) |group_id| {
            self.notifyLocalIndexRepairDebt(table_name, group_id, .clear_cancel);
        };

        self.beginLocalStructuralMutation(table_name);
        var structural_mutation_active = true;
        var local_db_mutex_held = true;
        errdefer if (structural_mutation_active) {
            if (local_db_mutex_held) {
                self.abortLocalStructuralMutation(table_name);
            } else {
                self.abortLocalStructuralMutationUnlockedForGroups(table_name, group_ids);
            }
        };
        // A restore may intentionally republish historical group ids, and an
        // older binary may have created a same-name table without incarnation
        // salting. Once local structural admission is exclusive, snapshot the
        // current catalog and fence every currently-owned group from cleanup.
        // If publication races after this read, its local provisioning waits
        // on the same barrier and therefore starts only after old paths move.
        var current_catalog = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&current_catalog);
        var owned_groups = std.AutoHashMapUnmanaged(u64, void).empty;
        defer owned_groups.deinit(alloc);
        try owned_groups.ensureTotalCapacity(alloc, @intCast(current_catalog.ranges.len));
        for (current_catalog.ranges) |range| owned_groups.putAssumeCapacity(range.group_id, {});
        for (group_ids) |group_id| {
            if (!owned_groups.contains(group_id)) continue;
            // Catalog ownership is a safety fence, not a successful cleanup.
            // In particular, a follower may not have applied the drop yet.
            // Retain the durable intent and retry after its projection catches
            // up instead of silently converting a stale read into leaked data.
            std.log.info(
                "dropped-table cleanup deferred by current catalog ownership table={s} table_id={d} generation={d} group_id={d}",
                .{ table_name, contract.table_id, contract.expected_transition_generation, group_id },
            );
            for (group_ids) |owned_group_id| {
                self.notifyLocalIndexRepairDebt(table_name, owned_group_id, .clear_cancel);
                self.notifyLocalIndexRepairDebt(table_name, owned_group_id, .enqueue_runnable);
            }
            return error.DropCleanupOwnershipInconclusive;
        }
        // Publication handoffs are name-scoped process state. Retire them only
        // while the committed catalog still confirms absence; a delayed
        // initial cleanup must not revoke authority from a replacement table.
        if (retire_publication_authority and
            tables_api.findTableByName(&current_catalog, table_name) == null)
        {
            self.retireDroppedTablePublicationAuthority(table_name);
        }
        var read_cache_exclusive = try self.beginReadCacheExclusive(table_name);
        defer {
            if (read_cache_exclusive) |*exclusive| exclusive.deinit();
        }
        self.local_db_mutex.unlock();
        local_db_mutex_held = false;
        self.drainWriteCachePendingClosesForGroups(table_name, group_ids);

        var moved_any_group = false;
        for (group_ids) |group_id| {
            const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);
            self.invalidateSharedPathCaches(path);
            const trash_path = try moveDroppedGroupPathToTrash(alloc, self.replica_root_dir, table_name, group_id);
            if (trash_path) |dropped_path| {
                moved_any_group = true;
                try self.deleteDroppedGroupPath(alloc, dropped_path);
            }
        }
        if (moved_any_group) {
            const trash_dir_path = try droppedTableTrashDirPath(alloc, self.replica_root_dir);
            defer alloc.free(trash_dir_path);
            var io_impl = std.Io.Threaded.init(alloc, .{});
            defer io_impl.deinit();
            // The repair intent is removed only after both sides of every
            // rename are durable. One shared-directory sync avoids an fsync
            // per range while preserving crash recovery.
            try fs_paths.syncDirPortable(io_impl.io(), trash_dir_path);
        }
        self.finishLocalStructuralMutationUnlockedForGroups(table_name, group_ids);
        structural_mutation_active = false;
        for (group_ids) |group_id| {
            self.notifyLocalIndexRepairDebt(table_name, group_id, .remove);
            self.notifyLocalIndexRepairDebt(table_name, group_id, .clear_cancel);
        }
        self.notifyLocalChange(table_name, .structural);
    }

    fn dropTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        contract: metadata_topology_protocol.DropCleanupContract,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.dropTable(alloc, table_name, contract);
        const group_ids = contract.group_ids;
        if (group_ids.len == 0) return null;

        // Metadata has already committed. Persist the exact cleanup contract
        // before any fallible cache/filesystem operation so every later
        // failure has a restart-safe, idempotent recovery owner.
        const intent_path = persistDroppedTableRepairIntent(
            alloc,
            self.replica_root_dir,
            table_name,
            contract,
        ) catch return error.DropCleanupIntentNotDurable;
        defer alloc.free(intent_path);

        // This is convergence for a metadata mutation that has already
        // committed, not admission of a new user write. It must run on a
        // standby as well as the active writer owner.
        self.executeDroppedTableCleanup(alloc, table_name, contract, true) catch |err| {
            if (self.backend_runtime != null) self.scheduleDroppedTableRecovery();
            return err;
        };
        removeDroppedTableRepairIntent(intent_path) catch |err| {
            if (self.backend_runtime != null) self.scheduleDroppedTableRecovery();
            return err;
        };
    }

    fn canCoalesceProvisionedGroupBatch(self: *ProvisionedTableWriteSource, group: GroupBatch, req: db_mod.types.BatchRequest) bool {
        if (self.write_cache == null) return false;
        if (group.transforms.items.len != 0) return false;
        if (req.graph_writes.len != 0 or req.graph_deletes.len != 0 or req.predicates.len != 0) return false;
        return switch (req.sync_level) {
            .propose, .write => true,
            .enrichments, .full_text, .full_index => false,
        };
    }

    fn writeCoalescerActive(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) bool {
        const io = self.table_activity_threaded.io();
        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        const queue_index = self.findWriteCoalesceQueueLocked(table_name, group_id) orelse return false;
        const queue = &self.write_coalesce_queues.items[queue_index];
        return queue.draining or queue.entries.items.len != 0;
    }

    fn testingWaitForWriteCoalesceQueueEntries(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        expected_entries: usize,
    ) !void {
        if (!builtin.is_test) @compileError("testingWaitForWriteCoalesceQueueEntries is test-only");
        const deadline_ns = platform_time.monotonicNs() + 5 * std.time.ns_per_s;
        while (true) {
            const count = self.testingWriteCoalesceQueueEntryCount(table_name, group_id);
            if (count >= expected_entries) return;
            if (platform_time.monotonicNs() >= deadline_ns) return error.Timeout;
            sleepNs(std.time.ns_per_ms);
        }
    }

    fn testingWriteCoalesceQueueEntryCount(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
    ) usize {
        if (!builtin.is_test) @compileError("testingWriteCoalesceQueueEntryCount is test-only");
        const io = self.table_activity_threaded.io();
        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        const queue_index = self.findWriteCoalesceQueueLocked(table_name, group_id) orelse return 0;
        return self.write_coalesce_queues.items[queue_index].entries.items.len;
    }

    fn coalesceCompatibleEntry(first: *const WriteCoalesceEntry, candidate: *const WriteCoalesceEntry) bool {
        return first.sync_level == candidate.sync_level and first.timestamp_ns == candidate.timestamp_ns;
    }

    fn coalescedEntryBatchRequest(entry: *const WriteCoalesceEntry) db_mod.types.BatchRequest {
        return .{
            .sync_level = entry.sync_level,
            .timestamp_ns = entry.timestamp_ns,
        };
    }

    fn enqueueProvisionedGroupBatchCoalesced(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group: GroupBatch,
        req: db_mod.types.BatchRequest,
    ) !void {
        var entry = WriteCoalesceEntry{
            .group = try cloneWriteCoalesceGroupBatch(alloc, group),
            .sync_level = req.sync_level,
            .timestamp_ns = req.timestamp_ns,
        };
        defer freeWriteCoalesceGroupBatch(alloc, &entry.group);

        const io = self.table_activity_threaded.io();
        var should_drain = false;
        self.write_coalesce_mutex.lockUncancelable(io);
        {
            errdefer self.write_coalesce_mutex.unlock(io);
            const queue = try self.writeCoalesceQueueLocked(table_name, group.group_id);
            try queue.entries.append(std.heap.page_allocator, &entry);
            if (!queue.draining) {
                queue.draining = true;
                should_drain = true;
            }
        }
        self.write_coalesce_mutex.unlock(io);

        while (true) {
            if (should_drain) {
                self.drainProvisionedGroupBatchCoalescer(alloc, table_name, group.group_id, &entry);
                should_drain = false;
            }

            self.write_coalesce_mutex.lockUncancelable(io);
            if (entry.done) {
                const entry_err = entry.err;
                self.write_coalesce_mutex.unlock(io);
                if (entry_err) |err| return err;
                return;
            }
            const queue_index = self.findWriteCoalesceQueueLocked(table_name, group.group_id) orelse {
                self.write_coalesce_mutex.unlock(io);
                return error.WriteCoalesceQueueMissing;
            };
            const queue = &self.write_coalesce_queues.items[queue_index];
            if (!queue.draining) {
                queue.draining = true;
                should_drain = true;
                self.write_coalesce_mutex.unlock(io);
                continue;
            }
            self.write_coalesce_ready.waitUncancelable(io, &self.write_coalesce_mutex);
            self.write_coalesce_mutex.unlock(io);
        }
    }

    fn drainProvisionedGroupBatchCoalescer(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        owner_entry: *WriteCoalesceEntry,
    ) void {
        const io = self.table_activity_threaded.io();
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);

        while (true) {
            var entries = std.ArrayListUnmanaged(*WriteCoalesceEntry).empty;
            defer entries.deinit(alloc);

            self.write_coalesce_mutex.lockUncancelable(io);
            {
                const queue_index = self.findWriteCoalesceQueueLocked(table_name, group_id) orelse {
                    self.write_coalesce_mutex.unlock(io);
                    return;
                };
                const queue = &self.write_coalesce_queues.items[queue_index];
                if (queue.entries.items.len == 0) {
                    queue.draining = false;
                    self.write_coalesce_ready.broadcast(io);
                    self.pruneWriteCoalesceQueueLocked(queue_index);
                    self.write_coalesce_mutex.unlock(io);
                    return;
                }

                const first = queue.entries.items[0];
                var take: usize = 0;
                var ops: usize = 0;
                while (take < queue.entries.items.len and take < provisioned_write_coalesce_max_waiters) : (take += 1) {
                    const candidate = queue.entries.items[take];
                    if (!coalesceCompatibleEntry(first, candidate)) break;
                    const candidate_ops = candidate.group.writes.items.len + candidate.group.deletes.items.len;
                    if (take > 0 and ops + candidate_ops > provisioned_write_coalesce_max_ops) break;
                    ops += candidate_ops;
                }
                entries.appendSlice(alloc, queue.entries.items[0..take]) catch |err| {
                    for (queue.entries.items) |entry| {
                        entry.err = err;
                        entry.done = true;
                    }
                    queue.entries.clearRetainingCapacity();
                    queue.draining = false;
                    self.write_coalesce_ready.broadcast(io);
                    self.pruneWriteCoalesceQueueLocked(queue_index);
                    self.write_coalesce_mutex.unlock(io);
                    return;
                };
                std.mem.copyForwards(*WriteCoalesceEntry, queue.entries.items[0 .. queue.entries.items.len - take], queue.entries.items[take..]);
                queue.entries.items.len -= take;
            }
            self.write_coalesce_mutex.unlock(io);

            self.applyCoalescedEntriesWithIsolation(alloc, table_name, group_id, entries.items);
            if (self.yieldWriteCoalesceDrainerIfOwnerDone(table_name, group_id, owner_entry)) return;
        }
    }

    // A request elected as drainer must not remain responsible for a queue
    // that is continuously replenished after its own entry completes. Hand
    // ownership to a waiting request so every public API handler can return
    // with bounded queue residency under sustained concurrency.
    fn yieldWriteCoalesceDrainerIfOwnerDone(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        owner_entry: *const WriteCoalesceEntry,
    ) bool {
        const io = self.table_activity_threaded.io();
        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        if (!owner_entry.done) return false;

        const queue_index = self.findWriteCoalesceQueueLocked(table_name, group_id) orelse return true;
        self.write_coalesce_queues.items[queue_index].draining = false;
        self.write_coalesce_ready.broadcast(io);
        self.pruneWriteCoalesceQueueLocked(queue_index);
        return true;
    }

    fn applyCoalescedEntriesWithIsolation(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        entries: []const *WriteCoalesceEntry,
    ) void {
        std.debug.assert(entries.len > 0);
        if (entries.len == 1) {
            const entry = entries[0];
            var arena = std.heap.ArenaAllocator.init(alloc);
            defer arena.deinit();
            const apply_err: ?anyerror = blk: {
                self.applyProvisionedGroupBatchLocked(arena.allocator(), table_name, entry.group, coalescedEntryBatchRequest(entry), .none) catch |err| break :blk err;
                break :blk null;
            };
            self.finishCoalescedEntry(entry, apply_err);
            return;
        }

        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const arena_alloc = arena.allocator();

        // A merged batch is only correct when the waiters touch disjoint
        // keys: DB batch application resolves writes before deletes
        // regardless of request order, so cross-waiter same-key merging
        // would invert enqueue order (an earlier delete beating a later
        // write), and collapsing ops per key would acknowledge a waiter
        // whose operation was never validated or applied. On any overlap,
        // fall back to applying the waiters individually in enqueue order,
        // which preserves per-key last-operation-wins and per-waiter error
        // isolation.
        const overlap = coalescedEntriesShareKeys(arena_alloc, entries) catch |err| {
            self.finishCoalescedEntries(entries, err);
            return;
        };
        if (overlap) {
            self.applyCoalescedEntriesIndividually(alloc, table_name, entries);
            return;
        }

        var merged = GroupBatch{ .group_id = group_id };
        merged.writes.ensureTotalCapacity(arena_alloc, totalCoalescedWrites(entries)) catch |err| {
            self.finishCoalescedEntries(entries, err);
            return;
        };
        merged.deletes.ensureTotalCapacity(arena_alloc, totalCoalescedDeletes(entries)) catch |err| {
            self.finishCoalescedEntries(entries, err);
            return;
        };
        for (entries) |entry| {
            for (entry.group.writes.items) |write| merged.writes.appendAssumeCapacity(write);
            for (entry.group.deletes.items) |key| merged.deletes.appendAssumeCapacity(key);
        }

        const merged_req = coalescedEntryBatchRequest(entries[0]);
        // Default timestamp_ns=0 intentionally remains a DB-batch timestamp:
        // coalescing preserves ordinary batch semantics and excludes CAS,
        // graph, transform, and derived-visibility writes.
        self.applyProvisionedGroupBatchLocked(arena_alloc, table_name, merged, merged_req, .none) catch |merged_err| {
            std.log.warn("coalesced provisioned batch failed; retrying waiters individually table={s} group_id={} waiters={} err={s}", .{
                table_name,
                group_id,
                entries.len,
                @errorName(merged_err),
            });
            self.applyCoalescedEntriesIndividually(alloc, table_name, entries);
            return;
        };
        self.finishCoalescedEntries(entries, null);
    }

    fn applyCoalescedEntriesIndividually(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        entries: []const *WriteCoalesceEntry,
    ) void {
        for (entries) |entry| {
            var arena = std.heap.ArenaAllocator.init(alloc);
            defer arena.deinit();
            const apply_err: ?anyerror = blk: {
                self.applyProvisionedGroupBatchLocked(arena.allocator(), table_name, entry.group, coalescedEntryBatchRequest(entry), .none) catch |err| break :blk err;
                break :blk null;
            };
            self.finishCoalescedEntry(entry, apply_err);
        }
    }

    // True when any key appears more than once across the coalesced waiters'
    // writes and deletes (including twice within one waiter's batch).
    fn coalescedEntriesShareKeys(
        arena_alloc: std.mem.Allocator,
        entries: []const *WriteCoalesceEntry,
    ) !bool {
        var seen = std.StringHashMapUnmanaged(void).empty;
        for (entries) |entry| {
            for (entry.group.writes.items) |write| {
                const gop = try seen.getOrPut(arena_alloc, write.key);
                if (gop.found_existing) return true;
            }
            for (entry.group.deletes.items) |key| {
                const gop = try seen.getOrPut(arena_alloc, key);
                if (gop.found_existing) return true;
            }
        }
        return false;
    }

    fn totalCoalescedWrites(entries: []const *WriteCoalesceEntry) usize {
        var total: usize = 0;
        for (entries) |entry| total += entry.group.writes.items.len;
        return total;
    }

    fn totalCoalescedDeletes(entries: []const *WriteCoalesceEntry) usize {
        var total: usize = 0;
        for (entries) |entry| total += entry.group.deletes.items.len;
        return total;
    }

    fn finishCoalescedEntries(self: *ProvisionedTableWriteSource, entries: []const *WriteCoalesceEntry, err: ?anyerror) void {
        const io = self.table_activity_threaded.io();
        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        for (entries) |entry| {
            entry.err = err;
            entry.done = true;
        }
        self.write_coalesce_ready.broadcast(io);
    }

    fn finishCoalescedEntry(self: *ProvisionedTableWriteSource, entry: *WriteCoalesceEntry, err: ?anyerror) void {
        const io = self.table_activity_threaded.io();
        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        entry.err = err;
        entry.done = true;
        self.write_coalesce_ready.broadcast(io);
    }

    fn applyProvisionedGroupBatchLocked(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group: GroupBatch,
        req: db_mod.types.BatchRequest,
        cancellation: db_mod.types.CancellationToken,
    ) !void {
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group.group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            const target_generation = self.visibleRootGeneration(group.group_id);
            var cached = try self.getOrOpenCachedDbForLocalMutation(
                alloc,
                cache,
                path,
                group.group_id,
                target_generation,
                table_name,
                true,
            );
            defer cached.deinit(alloc);
            try applyGroupBatchWithSchemaJson(alloc, cached.db, cached.schema_json, group, req, cancellation);
            cache.publishCachedLeaseGeneration(&cached, target_generation);
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group.group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group.group_id, &db);
            try applyGroupBatch(alloc, self.catalog, &db, table_name, group, req, cancellation);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group.group_id, &db);
        }
    }

    fn batch(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        return try self.batchWithVisibilityCancellation(alloc, table_name, req, .none);
    }

    fn batchWithVisibilityCancellation(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
        cancellation: db_mod.types.CancellationToken,
    ) !?void {
        if (self.raft_batcher == null) {
            if (self.local_write_owner) |owner| return try owner.batchWithVisibilityCancellation(alloc, table_name, req, cancellation);
        }
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginTableRequest(table_name);
        defer self.endTableRequest(table_name);
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();
        errdefer {
            lockAtomic(&self.local_db_mutex);
            defer self.local_db_mutex.unlock();
            self.invalidateReadCache(table_name);
            self.invalidateWriteCache(table_name);
        }
        var grouped = std.ArrayListUnmanaged(GroupBatch).empty;
        defer {
            for (grouped.items) |*group| group.deinit(alloc);
            grouped.deinit(alloc);
        }

        var snapshot = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_name) orelse return null;
        const ranges = try metadata_admin.listTableRanges(alloc, &snapshot, table.table_id);
        defer metadata_admin.freeRangeRefs(alloc, ranges);
        if (ranges.len == 0) return null;

        for (req.writes) |write| {
            const group_id = table_catalog.resolveGroupForKeyFromRanges(ranges, write.key) orelse return null;
            const group = try ensureGroupBatch(alloc, &grouped, group_id);
            try group.writes.append(alloc, write);
        }
        for (req.deletes) |key| {
            const group_id = table_catalog.resolveGroupForKeyFromRanges(ranges, key) orelse return null;
            const group = try ensureGroupBatch(alloc, &grouped, group_id);
            try group.deletes.append(alloc, key);
        }
        for (req.transforms) |transform| {
            const group_id = table_catalog.resolveGroupForKeyFromRanges(ranges, transform.key) orelse return null;
            const group = try ensureGroupBatch(alloc, &grouped, group_id);
            try group.transforms.append(alloc, transform);
        }

        if (self.raft_batcher) |batcher| {
            var accepted_groups: usize = 0;
            for (grouped.items) |group| {
                batcher.batchGroupWithCancellation(alloc, group.group_id, table_name, .{
                    .writes = group.writes.items,
                    .deletes = group.deletes.items,
                    .transforms = group.transforms.items,
                    .timestamp_ns = req.timestamp_ns,
                    .sync_level = req.sync_level,
                }, cancellation) catch |err| {
                    if (accepted_groups == 0) return err;
                    // The per-group error may be safe to retry in isolation,
                    // but replaying the complete public batch could apply
                    // non-idempotent transforms to an earlier accepted group
                    // twice. Preserve the root cause in logs and expose one
                    // non-retryable aggregate outcome to the caller.
                    std.log.warn(
                        "raft batch has partial write outcome table={s} accepted_groups={} failed_group_id={} err={s}",
                        .{ table_name, accepted_groups, group.group_id, @errorName(err) },
                    );
                    return error.RaftBatchWritePartialOutcome;
                };
                accepted_groups += 1;
            }
            return {};
        }

        for (grouped.items) |group| {
            if (cancellation.ptr == null and self.canCoalesceProvisionedGroupBatch(group, req)) {
                if (self.writeCoalescerActive(table_name, group.group_id)) {
                    try self.enqueueProvisionedGroupBatchCoalesced(alloc, table_name, group, req);
                } else if (self.tryBeginGroupOperation(table_name, group.group_id)) {
                    defer self.endGroupOperation(table_name, group.group_id);
                    try self.applyProvisionedGroupBatchLocked(alloc, table_name, group, req, cancellation);
                } else {
                    try self.enqueueProvisionedGroupBatchCoalesced(alloc, table_name, group, req);
                }
            } else {
                self.beginGroupOperation(table_name, group.group_id);
                defer self.endGroupOperation(table_name, group.group_id);
                try self.applyProvisionedGroupBatchLocked(alloc, table_name, group, req, cancellation);
            }
        }
        lockAtomic(&self.local_db_mutex);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();
        self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
        self.notifyLocalChange(table_name, .data);
    }

    fn beginRestoreLifecycle(ptr: *anyopaque, table_name: []const u8) !void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| {
            _ = try owner.beginRestoreLifecycle(table_name);
        }
        self.beginRestoreLifecycleActivity(table_name);
    }

    fn finishRestoreLifecycle(ptr: *anyopaque, table_name: []const u8) void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| {
            owner.finishRestoreLifecycle(table_name);
        }
        self.endRestoreLifecycleActivity(table_name);
    }

    fn backupTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        plan: backups_api.TableBackupPlan,
    ) !?[]backups_api.ShardSnapshot {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const group_id = (try resolveFencedBackupGroup(self.catalog, table_name, plan.fence)) orelse return null;
        self.beginGroupOperation(table_name, group_id);
        defer {
            self.endGroupOperation(table_name, group_id);
        }
        const guarded_group_id = (try resolveFencedBackupGroup(self.catalog, table_name, plan.fence)) orelse return error.CatalogChanged;
        if (guarded_group_id != group_id) return error.CatalogChanged;

        if (self.localWriteOwnerSource()) |owner| return try owner.backupTable(alloc, table_name, plan);

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (plan.format == .portable) {
            var read_cache_exclusive = try self.beginReadCacheExclusive(table_name);
            defer {
                if (read_cache_exclusive) |*exclusive| exclusive.deinit();
            }
            if (self.write_cache) |cache| {
                const target_generation = self.visibleRootGeneration(group_id);
                var cached = try self.getOrOpenCachedDbForLocalMutation(
                    alloc,
                    cache,
                    path,
                    group_id,
                    target_generation,
                    table_name,
                    true,
                );
                defer cached.deinit(alloc);
                return try exportPortableBackupShard(alloc, cached.db, plan.backup_root, plan.backup_id, group_id, plan.io);
            }

            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            return try exportPortableBackupShard(alloc, &db, plan.backup_root, plan.backup_id, group_id, plan.io);
        }

        if (self.write_cache) |cache| {
            var read_cache_exclusive = try self.beginReadCacheExclusive(table_name);
            defer {
                if (read_cache_exclusive) |*exclusive| exclusive.deinit();
            }
            const target_generation = self.visibleRootGeneration(group_id);
            var cached = try self.getOrOpenCachedDbForLocalMutation(
                alloc,
                cache,
                path,
                group_id,
                target_generation,
                table_name,
                true,
            );
            defer cached.deinit(alloc);

            var native_snapshot = try prepareNativeBackupShardSnapshot(alloc, cached.db, path, group_id, plan);
            defer native_snapshot.deinit(alloc);
            if (read_cache_exclusive) |*exclusive| {
                exclusive.deinit();
                read_cache_exclusive = null;
            }
            return try copyPreparedNativeBackupShardSnapshot(alloc, &native_snapshot);
        }

        var read_cache_exclusive = try self.beginReadCacheExclusive(table_name);
        defer {
            if (read_cache_exclusive) |*exclusive| exclusive.deinit();
        }
        var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
        defer db.close();
        var native_snapshot = try prepareNativeBackupShardSnapshot(alloc, &db, path, group_id, plan);
        defer native_snapshot.deinit(alloc);
        if (read_cache_exclusive) |*exclusive| {
            exclusive.deinit();
            read_cache_exclusive = null;
        }
        return try copyPreparedNativeBackupShardSnapshot(alloc, &native_snapshot);
    }

    const NativeBackupShardSnapshot = struct {
        snapshot_root: []const u8,
        dest_root: []const u8,
        io: ?std.Io,
        shard: backups_api.ShardSnapshot,
        owns_shard: bool = true,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            alloc.free(@constCast(self.snapshot_root));
            alloc.free(@constCast(self.dest_root));
            if (self.owns_shard) self.shard.deinit(alloc);
            self.* = undefined;
        }

        fn toShardsAlloc(self: *@This(), alloc: std.mem.Allocator) ![]backups_api.ShardSnapshot {
            const shards = try alloc.alloc(backups_api.ShardSnapshot, 1);
            shards[0] = self.shard;
            self.owns_shard = false;
            return shards;
        }
    };

    fn prepareNativeBackupShardSnapshot(
        alloc: std.mem.Allocator,
        db: *db_mod.DB,
        db_path: []const u8,
        group_id: u64,
        plan: backups_api.TableBackupPlan,
    ) !NativeBackupShardSnapshot {
        std.debug.assert(plan.format == .native);

        const snapshot_token = try std.fmt.allocPrint(alloc, "{s}-g{d}", .{ plan.backup_id, group_id });
        defer alloc.free(snapshot_token);
        _ = try db.snapshot(snapshot_token);

        const snapshot_root = try std.fmt.allocPrint(alloc, "{s}.snapshots/{s}", .{ db_path, snapshot_token });
        errdefer alloc.free(snapshot_root);
        const dest_root = try backups_api.shardSnapshotPath(alloc, plan.backup_root, plan.backup_id, group_id);
        errdefer alloc.free(dest_root);
        const rel_path = try backups_api.shardSnapshotRelPath(alloc, plan.backup_id, group_id);
        errdefer alloc.free(rel_path);

        const byte_range = db.getRange();
        const start_key = try alloc.dupe(u8, byte_range.start);
        errdefer alloc.free(start_key);
        const end_key = if (byte_range.end.len > 0) try alloc.dupe(u8, byte_range.end) else null;
        errdefer if (end_key) |value| alloc.free(value);

        return .{
            .snapshot_root = snapshot_root,
            .dest_root = dest_root,
            .io = plan.io,
            .shard = .{
                .group_id = group_id,
                .start_key = start_key,
                .end_key = end_key,
                .snapshot_path = rel_path,
            },
        };
    }

    fn copyPreparedNativeBackupShardSnapshot(
        alloc: std.mem.Allocator,
        native_snapshot: *NativeBackupShardSnapshot,
    ) ![]backups_api.ShardSnapshot {
        runTestBeforeNativeBackupCopyHook();
        try backups_api.copyDirectoryRecursiveUsingIo(
            alloc,
            native_snapshot.io,
            native_snapshot.snapshot_root,
            native_snapshot.dest_root,
        );
        try backups_api.populateShardArtifactIntegrity(
            alloc,
            native_snapshot.io,
            .native,
            native_snapshot.dest_root,
            &native_snapshot.shard,
        );
        return try native_snapshot.toShardsAlloc(alloc);
    }

    fn restoreTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        plan: backups_api.TableRestorePlan,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.restoreTableReserved(alloc, table_name, plan);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        try backups_api.validateRestorableManifestLayout(plan.manifest);
        try backups_api.validateRestoreManifest(alloc, plan.manifest, plan.manifest.backup_id);
        if (plan.reconcile_only and plan.replace_existing) return error.InvalidBackupRequest;
        const restore_io = plan.io orelse self.table_activity_threaded.io();
        const source_identity = try backups_api.canonicalRestoreSourceIdentityAlloc(alloc, plan.source_location);
        defer alloc.free(source_identity);

        const local_location = try std.fmt.allocPrint(alloc, "file://{s}", .{plan.backup_root});
        defer alloc.free(local_location);

        const source_shard = plan.manifest.shards[0];
        const group_id = if (plan.replace_existing)
            (try table_catalog.resolveSingleRangeGroup(alloc, self.catalog, table_name)) orelse return null
        else
            source_shard.group_id;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const restore_source: backup_restore.RestoreSource = .{
            .backup_id = plan.manifest.backup_id,
            .artifact_backup_id = plan.artifact_backup_id,
            .location = local_location,
            .identity_location = source_identity,
            .snapshot_path = source_shard.snapshot_path,
            .authority = .staged_local,
            .expected_artifact_size_bytes = source_shard.artifact_size_bytes,
            .expected_artifact_sha256 = source_shard.artifact_sha256,
            .manifest = plan.manifest,
            .io = restore_io,
        };

        var all_groups_already_admitted = true;
        var admitted_identity_mismatch = false;
        if (!try db_mod.generation_lifecycle.hasPublishedGenerationRead(path)) {
            all_groups_already_admitted = false;
        } else {
            const validation = if (plan.reconcile_only)
                backup_restore.validateCommittedRestoreIdentityWithIo(alloc, restore_io, path, group_id, restore_source)
            else
                backup_restore.validateImportedRestoreIdentityWithIo(alloc, restore_io, path, group_id, restore_source);
            validation catch |err| switch (err) {
                error.RestoreIdentityMismatch => {
                    admitted_identity_mismatch = true;
                    all_groups_already_admitted = false;
                },
                else => return err,
            };
        }
        if (all_groups_already_admitted and plan.publication_hook == null) {
            if (plan.reconcile_only) return;
            try self.repairPublishedRestoreRuntimeStateBlocking(
                alloc,
                path,
                group_id,
                table_name,
            );
            return;
        }
        if (plan.reconcile_only and admitted_identity_mismatch) return error.RestoreIdentityMismatch;

        const identity_namespace = try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id);

        const ready_deadline_ns = platform_time.monotonicNs() + 5 * std.time.ns_per_s;
        while (true) {
            if (std.Io.Dir.cwd().statFile(restore_io, path, .{})) |_| break else |_| {}
            if (platform_time.monotonicNs() >= ready_deadline_ns) break;
            sleepNs(50 * std.time.ns_per_ms);
        }
        runTestBeforeRestoreWorkHook();

        var preparation: ?db_mod.generation_lifecycle.PreparationTransition = null;
        defer if (preparation) |*value| value.deinit();
        var prepared_generation: ?db_mod.generation_lifecycle.StagedGeneration = null;
        defer if (prepared_generation) |*generation| generation.deinit();

        if (!plan.reconcile_only) {
            preparation = try db_mod.generation_lifecycle.beginProcessPreparationWithRuntime(path, self.backend_runtime);
            prepared_generation = backup_restore.prepareRestoreSnapshotToPathWithPreparation(&preparation.?, alloc, path, group_id, restore_source, .{
                .expected_table_name = table_name,
                .expected_identity_namespace = identity_namespace,
            }) catch |err| {
                if (err == error.IdentityNamespaceMismatch)
                    std.log.warn("provisioned restore failed phase=identity_validation class={s}", .{@errorName(err)})
                else
                    std.log.err("provisioned restore failed phase=materialization class={s}", .{@errorName(err)});
                return err;
            };
            // Import, derived rebuild, and validation run against the isolated
            // sibling while the current generation remains admitted.
            if (prepared_generation) |*generation| try self.repairRestoredTableRuntimeStateBlocking(
                alloc,
                generation.path(),
                group_id,
                table_name,
                plan.manifest.indexes_json,
                plan.manifest.schema_json,
                generation,
            );
            if (prepared_generation) |*generation| try generation.seal();
            if (prepared_generation == null) {
                preparation.?.deinit();
                preparation = null;
            }
        }

        var transition = try self.beginLocalTableGenerationTransitionFromPreparation(table_name);
        errdefer transition.abort();
        defer transition.deinit();
        self.invalidateSharedPathCaches(path);
        var publication_outcome: db_mod.generation_lifecycle.PublicationOutcome = .durable;
        var definition_published = false;
        errdefer if (definition_published) {
            if (plan.publication_hook) |hook| hook.rollback() catch |rollback_err| {
                std.log.err("restore metadata rollback failed phase=storage_publication class={s}", .{@errorName(rollback_err)});
            };
        };

        if (plan.reconcile_only) {
            var shard_transition = try transition.beginShardStorageTransition(path);
            defer shard_transition.deinit();
            try backup_restore.reconcileCommittedRestoreWithExclusiveTransitionWithIo(
                &shard_transition,
                alloc,
                restore_io,
                path,
                group_id,
                restore_source,
            );
        } else if (prepared_generation) |*generation| {
            var shard_transition = try preparation.?.promote();
            defer shard_transition.deinit();
            if (plan.publication_hook) |hook| {
                try hook.publish();
                definition_published = true;
            }
            publication_outcome = try backup_restore.publishPreparedRestore(alloc, path, generation);
            definition_published = false;
            if (publication_outcome == .durability_uncertain) {
                std.log.err("restore generation publication uncertain phase=durability", .{});
            }
        } else {
            // An idempotent retry may only owe runtime repair on the already
            // published generation. Keep that maintenance under exclusivity.
            var shard_transition = try transition.beginShardStorageTransition(path);
            defer shard_transition.deinit();
            try self.repairRestoredTableRuntimeStateBlocking(
                alloc,
                path,
                group_id,
                table_name,
                plan.manifest.indexes_json,
                plan.manifest.schema_json,
                null,
            );
            if (plan.publication_hook) |hook| try hook.publish();
        }

        self.invalidateSharedPathCaches(path);
        transition.finishMutation();
        self.publishRestoreRepairComplete(table_name);
        self.notifyLocalChange(table_name, .structural);
        if (publication_outcome == .durability_uncertain) return error.GenerationDurabilityUncertain;
    }

    fn commitTransaction(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
    ) !?distributed_txn.CommitOutcome {
        return try commitTransactionWithCancellation(ptr, alloc, tables, sync_level, .none);
    }

    fn commitTransactionWithCancellation(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        const txn_id = nextTxnId();
        return try commitProvisionedTransaction(ptr, alloc, txn_id, nextTxnTimestamp(), tables, sync_level, false, cancellation);
    }

    fn commitTransactionWithId(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
    ) !?distributed_txn.CommitOutcome {
        return try commitTransactionWithIdAndCancellation(ptr, alloc, txn_id, begin_timestamp, tables, sync_level, .none);
    }

    fn commitTransactionWithIdAndCancellation(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        return try commitProvisionedTransaction(ptr, alloc, txn_id, begin_timestamp, tables, sync_level, true, cancellation);
    }

    fn acknowledgeTransactionCommit(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        coordinator_group_id: u64,
        coordinator_table_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const participant = try distributed_txn.participantIdForGroup(alloc, coordinator_table_name, coordinator_group_id);
        defer alloc.free(participant);
        return try self.source().txnAcknowledgeGroupLocal(
            alloc,
            coordinator_group_id,
            coordinator_table_name,
            txn_id,
            participant,
        );
    }

    fn commitProvisionedTransaction(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        retain_terminal: bool,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        try enforceHAWriteGateOptional(self.ha_write_gate);
        var worker_impl = distributed_txn.LocalTableWriteParticipantWorker.init(self.source());
        const commit_version = begin_timestamp + 1;
        return try distributed_txn.executeMultiTableCommitWithOptions(
            alloc,
            self.catalog,
            worker_impl.worker(),
            txn_id,
            begin_timestamp,
            commit_version,
            tables,
            sync_level,
            if (comptime build_options.with_tla) tracing.stderrAntflyTraceWriter() else null,
            .{
                .retain_terminal = retain_terminal,
                .report_post_commit_failure = false,
                .fanout_io = self.table_activity_threaded.io(),
                .post_commit_cancellation = cancellation,
            },
        );
    }

    fn commitBatch(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
    ) !?distributed_txn.CommitOutcome {
        return try commitBatchWithCancellation(ptr, alloc, tables, sync_level, .none);
    }

    fn commitBatchWithCancellation(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        try enforceHAWriteGateOptional(self.ha_write_gate);
        const retry_conflicts = statelessBatchMayRetry(tables);
        var attempt: u8 = 0;
        while (true) : (attempt += 1) {
            const outcome = commitProvisionedBatchOnce(self, ptr, alloc, tables, sync_level, cancellation) catch |err| {
                if (retry_conflicts and attempt + 1 < stateless_batch_max_attempts and err == error.TopologyChanged) {
                    sleepNs(statelessBatchRetryDelayNs(attempt));
                    continue;
                }
                return err;
            };
            if (outcome) |result| switch (result) {
                .committed => return result,
                .conflict => {
                    // Every conflict outcome is returned only after the
                    // coordinator has established that no commit decision is
                    // durable. A fresh transaction ID is therefore safe for a
                    // predicate-free public batch. Explicit OCC conflicts and
                    // unknown outcomes remain visible to the caller.
                    if (retry_conflicts and attempt + 1 < stateless_batch_max_attempts) {
                        sleepNs(statelessBatchRetryDelayNs(attempt));
                        continue;
                    }
                    return result;
                },
            } else return null;
        }
    }

    fn commitProvisionedBatchOnce(
        self: *ProvisionedTableWriteSource,
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        if (try self.commitSingleGroupBatch(alloc, tables, sync_level, cancellation)) |outcome| return outcome;
        const txn_id = nextTxnId();
        return try commitProvisionedTransaction(ptr, alloc, txn_id, nextTxnTimestamp(), tables, sync_level, false, cancellation);
    }

    /// A transaction with one participant is already atomic at the shard DB
    /// boundary. Avoid materializing a durable begin/prepare/resolve protocol
    /// for that case: it adds three writer admissions, recovery bookkeeping,
    /// and extra WAL records without strengthening the commit contract.
    /// Multi-group and multi-table batches still use the distributed
    /// transaction coordinator below.
    fn commitSingleGroupBatch(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        if (self.raft_batcher != null)
            return try self.commitSingleGroupTransactionViaRaftBatcher(alloc, tables, sync_level, cancellation);
        // A forwarding facade does not own the activity fence for the local
        // writer. Leave it on the normal participant route until the hosted
        // path has an equivalent single-shard callback.
        if (self.localWriteOwnerSource() != null) return null;
        if (tables.len == 0) return .{ .committed = .{ .participant_count = 0 } };
        if (tables.len != 1) return null;

        const table_req = tables[0];
        const has_mutations = table_req.writes.len != 0 or
            table_req.deletes.len != 0 or
            table_req.transforms.len != 0;
        if (!has_mutations and table_req.predicates.len != 0) {
            // Predicates are validated by the transactional path. `batch`
            // groups only mutations, so sending a predicate-only request to
            // it would report success without evaluating the predicate.
            return null;
        }
        self.beginTableRequest(table_req.table_name);
        defer self.endTableRequest(table_req.table_name);

        var routing = (try table_catalog.transactionRoutingSnapshot(
            alloc,
            self.catalog,
            table_req.table_name,
        )) orelse return null;
        defer routing.deinit(alloc);

        var group_id_opt: ?u64 = null;
        const resolveOpGroup = struct {
            fn run(current: *?u64, route: *const table_catalog.TransactionRoutingSnapshot, key: []const u8) !void {
                const group_id = route.resolveGroupForKey(key) orelse return error.NotFound;
                if (current.*) |existing| {
                    if (existing != group_id) return error.MultipleGroups;
                } else {
                    current.* = group_id;
                }
            }
        }.run;
        for (table_req.writes) |write| resolveOpGroup(&group_id_opt, &routing, write.key) catch |err| switch (err) {
            error.MultipleGroups => return null,
            else => return err,
        };
        for (table_req.deletes) |key| resolveOpGroup(&group_id_opt, &routing, key) catch |err| switch (err) {
            error.MultipleGroups => return null,
            else => return err,
        };
        for (table_req.transforms) |transform| resolveOpGroup(&group_id_opt, &routing, transform.key) catch |err| switch (err) {
            error.MultipleGroups => return null,
            else => return err,
        };
        for (table_req.predicates) |predicate| resolveOpGroup(&group_id_opt, &routing, predicate.key) catch |err| switch (err) {
            error.MultipleGroups => return null,
            else => return err,
        };
        if (group_id_opt == null) return .{ .committed = .{ .participant_count = 0 } };

        // The outer table request prevents a topology publication between the
        // one-participant proof above and the ordinary atomic batch admission.
        // `batch` retains the established schema, cache, coalescing, HA, and
        // sync-level behavior used by all non-transactional shard writes.
        const applied = self.batchWithVisibilityCancellation(alloc, table_req.table_name, .{
            .writes = transactionWritesAsBatchWrites(table_req.writes),
            .deletes = table_req.deletes,
            .transforms = table_req.transforms,
            .predicates = table_req.predicates,
            .timestamp_ns = nextTxnTimestamp(),
            .sync_level = sync_level,
            .reject_graph_transform_projections = true,
        }, cancellation) catch |err| switch (err) {
            error.IntentConflict, error.VersionConflict => return .{ .conflict = boundConflict(table_req, err) },
            error.InvalidArgument,
            error.InvalidGraphEdges,
            error.UnsupportedTransformOperation,
            => return error.InvalidBatchRequest,
            else => return err,
        };
        if (applied == null) return null;
        return .{ .committed = .{ .participant_count = 1 } };
    }

    fn commitSingleGroupTransactionViaRaftBatcher(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        if (tables.len == 0) return .{ .committed = .{ .participant_count = 0 } };
        if (tables.len != 1) return null;
        const table_req = tables[0];
        if (table_req.predicates.len != 0) return null;
        if (try tableCommitHasGraphProjectionTransform(table_req)) return null;

        var snapshot = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_req.table_name) orelse return null;
        const ranges = try metadata_admin.listTableRanges(alloc, &snapshot, table.table_id);
        defer metadata_admin.freeRangeRefs(alloc, ranges);
        if (ranges.len == 0) return null;

        var group_id_opt: ?u64 = null;
        const resolveOpGroup = struct {
            fn run(current: *?u64, range_refs: []const *const metadata_table_manager.RangeRecord, key: []const u8) !void {
                const group_id = table_catalog.resolveGroupForKeyFromRanges(range_refs, key) orelse return error.NotFound;
                if (current.*) |existing| {
                    if (existing != group_id) return error.MultipleGroups;
                } else {
                    current.* = group_id;
                }
            }
        }.run;

        for (table_req.writes) |write| resolveOpGroup(&group_id_opt, ranges, write.key) catch |err| switch (err) {
            error.MultipleGroups => return null,
            else => return err,
        };
        for (table_req.deletes) |key| resolveOpGroup(&group_id_opt, ranges, key) catch |err| switch (err) {
            error.MultipleGroups => return null,
            else => return err,
        };
        for (table_req.transforms) |transform| resolveOpGroup(&group_id_opt, ranges, transform.key) catch |err| switch (err) {
            error.MultipleGroups => return null,
            else => return err,
        };
        const group_id = group_id_opt orelse return .{ .committed = .{ .participant_count = 0 } };

        const batcher = self.raft_batcher orelse return null;
        const req: db_mod.types.BatchRequest = .{
            .writes = transactionWritesAsBatchWrites(table_req.writes),
            .deletes = table_req.deletes,
            .transforms = table_req.transforms,
            .sync_level = sync_level,
        };
        batcher.batchGroupWithCancellation(alloc, group_id, table_req.table_name, req, cancellation) catch |err| switch (err) {
            error.IntentConflict, error.VersionConflict => return .{ .conflict = boundConflict(table_req, err) },
            else => return err,
        };
        return .{ .committed = .{ .participant_count = 1 } };
    }

    fn batchGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.raft_batcher) |batcher| {
            try enforceHAWriteGateOptional(self.ha_write_gate);
            try batcher.batchGroupLocal(alloc, group_id, table_name, req);
            return {};
        }
        if (self.localWriteOwnerSource()) |owner| return try owner.batchGroupLocal(alloc, group_id, table_name, req);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        return try self.applyReplicatedBatchGroupLocal(alloc, group_id, table_name, req);
    }

    pub fn applyReplicatedBatchGroupLocal(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
    ) !?void {
        return try self.applyReplicatedBatchGroupLocalWithMetadata(
            alloc,
            group_id,
            table_name,
            req,
            .catalog,
            null,
        );
    }

    /// Raft state-machine apply consumes only state committed in the command
    /// and the provisioned local generation. Remote catalog reads belong
    /// before proposal and can deadlock a metadata-driven transition.
    pub fn applyPreparedReplicatedBatchGroupLocal(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
    ) !?void {
        return try self.applyReplicatedBatchGroupLocalWithMetadata(
            alloc,
            group_id,
            table_name,
            req,
            .local_persisted,
            null,
        );
    }

    /// Applies an exact data-Raft entry. The DB commits the entry identity with
    /// ordinary document mutations so restart replay can skip non-idempotent
    /// transforms that were already durable before the Raft watermark advanced.
    pub fn applyPreparedReplicatedBatchGroupLocalAtRaftEntry(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
        entry: db_mod.RaftAppliedEntryIdentity,
    ) !?void {
        return try self.applyReplicatedBatchGroupLocalWithMetadata(
            alloc,
            group_id,
            table_name,
            req,
            .local_persisted,
            entry,
        );
    }

    const ReplicatedApplyMetadataSource = enum { catalog, local_persisted };

    fn mapReplicatedApplyWriterAcquireError(
        metadata_source: ReplicatedApplyMetadataSource,
        err: anyerror,
    ) anyerror {
        if (metadata_source == .local_persisted and isTransientWriterOpenConflict(err)) {
            return error.RaftApplyWriterUnavailable;
        }
        return err;
    }

    fn applyReplicatedBatchGroupLocalWithMetadata(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
        metadata_source: ReplicatedApplyMetadataSource,
        raft_entry: ?db_mod.RaftAppliedEntryIdentity,
    ) !?void {
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const apply_req = req;
        const split_identity_namespace = try validateSplitReplicationForApply(apply_req, group_id);
        if (metadata_source == .catalog) if (apply_req.split_replication) |replication| {
            try validateSplitReplicationIdentityAgainstCatalog(alloc, self.catalog, table_name, replication);
        };
        // A read may already be waiting for this committed entry at its Raft
        // read barrier. Replicated apply must therefore coexist with active
        // generation-pinned readers; making it read-exclusive would deadlock
        // the barrier behind the apply it is waiting for. Structural and
        // generation transitions remain exclusive in the activity gate.
        self.beginReplicatedApplyOperation(table_name, group_id);
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();
        defer {
            self.endGroupOperation(table_name, group_id);
        }
        // A reader may open after the pre-apply invalidation while this write
        // is still in flight. Retire that generation after every completed
        // apply so subsequent reads cannot remain pinned to the pre-commit
        // view. Active read leases may finish against their snapshot.
        defer {
            lockAtomic(&self.local_db_mutex);
            defer self.local_db_mutex.unlock();
            self.invalidateReadCache(table_name);
        }
        errdefer {
            lockAtomic(&self.local_db_mutex);
            defer self.local_db_mutex.unlock();
            self.invalidateReadCache(table_name);
            self.invalidateWriteCache(table_name);
        }
        if (self.write_cache) |cache| {
            const target_generation = self.visibleRootGeneration(group_id);
            var cached = if (split_identity_namespace) |namespace|
                (if (metadata_source == .local_persisted)
                    self.leasePreparedTransitionGroupWriter(alloc, group_id, table_name, namespace) catch |err|
                        return mapReplicatedApplyWriterAcquireError(metadata_source, err)
                else
                    self.leaseCachedTransitionGroupWriterWithOptions(alloc, group_id, table_name, namespace, .{
                        .reconcile_for_replicated_apply = true,
                    }) catch |err| return mapReplicatedApplyWriterAcquireError(metadata_source, err)) orelse
                    return error.TransitionDestinationNotProvisioned
            else
                self.getOrOpenCachedDbForLocalMutationWithOptions(
                    alloc,
                    cache,
                    path,
                    group_id,
                    target_generation,
                    table_name,
                    true,
                    .{
                        .reconcile_for_replicated_apply = true,
                        .retry_transient_writer_open = metadata_source != .local_persisted,
                    },
                ) catch |err| return mapReplicatedApplyWriterAcquireError(metadata_source, err);
            defer cached.deinit(alloc);
            const already_applied = if (raft_entry) |entry|
                try cached.db.raftEntryAlreadyApplied(entry)
            else
                false;
            if (!already_applied) {
                try validateTableBatchAgainstSchemaJson(alloc, cached.db, cached.schema_json, apply_req.writes, apply_req.deletes, apply_req.transforms);
                runTestBeforeBatchExecutionHook();
                try validateSplitCheckpointGroup(apply_req.split_checkpoint, group_id);
                if (apply_req.transaction != null) {
                    try cached.db.ensureTransactionRecoveryRuntime(self.transactionRecoveryConfig());
                    if (raft_entry) |entry|
                        try applyReplicatedTransactionMutationAtRaftEntry(alloc, cached.db, table_name, group_id, apply_req, entry)
                    else
                        try applyReplicatedTransactionMutation(alloc, cached.db, table_name, group_id, apply_req);
                } else if (raft_entry) |entry|
                    try cached.db.batchRaftReplicatedApply(apply_req, entry)
                else
                    try cached.db.batchReplicatedApply(apply_req);
            }
            cache.publishCachedLeaseGeneration(&cached, target_generation);
            {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                self.markWriteCacheDirty(table_name);
            }
            self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
            self.notifyLocalChange(table_name, .data);
        } else {
            if (metadata_source == .local_persisted and split_identity_namespace != null) {
                return error.TransitionDestinationNotProvisioned;
            }
            var db = try openManagedDbForReplicatedApply(
                alloc,
                path,
                self.catalog,
                table_name,
                group_id,
                self.backend_runtime,
                self.ha_write_gate,
                self.ha_async_mirror,
                split_identity_namespace,
            );
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            const already_applied = if (raft_entry) |entry|
                try db.raftEntryAlreadyApplied(entry)
            else
                false;
            if (!already_applied) {
                try validateTableBatchAgainstCatalogSchema(alloc, self.catalog, &db, table_name, apply_req.writes, apply_req.deletes, apply_req.transforms);
                runTestBeforeBatchExecutionHook();
                try validateSplitCheckpointGroup(apply_req.split_checkpoint, group_id);
                if (apply_req.transaction != null) {
                    try db.ensureTransactionRecoveryRuntime(self.transactionRecoveryConfig());
                    if (raft_entry) |entry|
                        try applyReplicatedTransactionMutationAtRaftEntry(alloc, &db, table_name, group_id, apply_req, entry)
                    else
                        try applyReplicatedTransactionMutation(alloc, &db, table_name, group_id, apply_req);
                } else if (raft_entry) |entry|
                    try db.batchRaftReplicatedApply(apply_req, entry)
                else
                    try db.batchReplicatedApply(apply_req);
            }
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            self.notifyLocalChange(table_name, .data);
        }
    }

    pub fn installRaftSnapshotGroupLocal(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        encoded: []const u8,
    ) !void {
        const state = try shard_state_store.GroupStateSnapshotStream.init(encoded);
        try shard_state_store.validateGroupStateSnapshotStream(alloc, group_id, state);

        var discovery_snapshot = try self.catalog.adminSnapshot();
        var discovery_snapshot_owned = true;
        defer if (discovery_snapshot_owned) self.catalog.freeAdminSnapshot(&discovery_snapshot);
        const discovered_range = metadata_mod.findAdminRange(&discovery_snapshot, group_id) orelse return error.UnknownGroup;
        const discovered_table = metadata_mod.findAdminTable(&discovery_snapshot, discovered_range.table_id) orelse return error.TableNotFound;
        const table_id = discovered_table.table_id;
        const table_name = try alloc.dupe(u8, discovered_table.name);
        self.catalog.freeAdminSnapshot(&discovery_snapshot);
        discovery_snapshot_owned = false;
        defer alloc.free(table_name);

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);

        self.beginGroupGenerationPreparation(table_name, group_id);
        var preparation_activity = true;
        defer if (preparation_activity) self.endGroupGenerationPreparation(table_name, group_id);

        // Capture every catalog value consumed by staging after admission. The
        // same contract is checked again before publication so a concurrent
        // split or schema/index change cannot publish a generation built for a
        // stale table topology.
        var catalog_contract = try captureRaftSnapshotCatalogContract(
            alloc,
            self.catalog,
            group_id,
            table_id,
            table_name,
        );
        defer catalog_contract.deinit(alloc);
        if (!std.mem.eql(u8, state.byte_range.start, catalog_contract.range.start_key) or
            !std.mem.eql(u8, state.byte_range.end, catalog_contract.range.end_key orelse ""))
        {
            return error.SnapshotRangeMismatch;
        }
        const identity_namespace = tableIdentityNamespaceForRangeId(
            catalog_contract.table_id,
            catalog_contract.range,
        );

        const generation_source = self.groupVisibleRootGenerationSource();
        var generation_reservation = if (generation_source) |root_generation_source|
            try root_generation_source.reserveRootGenerationForGroup(group_id)
        else
            null;
        defer if (generation_reservation) |*reservation| reservation.deinit();

        var preparation = try db_mod.generation_lifecycle.beginProcessPreparationWithRuntime(path, self.backend_runtime);
        defer preparation.deinit();
        var staged = try preparation.beginStaging();
        defer staged.deinit();

        var parsed_schema: ?tables_api.ParsedTableSchema = null;
        if (catalog_contract.schema_json.len > 0) parsed_schema = try tables_api.parseValidatedTableSchema(alloc, catalog_contract.schema_json);
        defer if (parsed_schema) |*schema| schema.deinit(alloc);

        {
            var staged_db = try self.openRaftSnapshotStagingDbForGroup(
                alloc,
                &staged,
                group_id,
                catalog_contract.indexes_json,
                identity_namespace,
            );
            defer staged_db.close();
            try applyLocalTableSchemaJson(alloc, &staged_db, catalog_contract.schema_json);

            const max_chunk_entries = 512;
            const max_chunk_payload_bytes = 4 * 1024 * 1024;
            var writes_buffer: [max_chunk_entries]db_mod.types.BatchWrite = undefined;
            var entries = state.entries();
            var exhausted = false;
            while (!exhausted) {
                var chunk_len: usize = 0;
                var chunk_payload_bytes: usize = 0;
                while (chunk_len < writes_buffer.len) {
                    var candidate_entries = entries;
                    const entry = (try candidate_entries.next()) orelse {
                        exhausted = true;
                        break;
                    };
                    const entry_bytes = std.math.add(usize, entry.key.len, entry.value.len) catch return error.SnapshotTooLarge;
                    if (chunk_len > 0 and entry_bytes > max_chunk_payload_bytes -| chunk_payload_bytes) break;
                    entries = candidate_entries;
                    writes_buffer[chunk_len] = .{ .key = entry.key, .value = entry.value };
                    chunk_len += 1;
                    chunk_payload_bytes = std.math.add(usize, chunk_payload_bytes, entry_bytes) catch return error.SnapshotTooLarge;
                }
                if (chunk_len == 0) break;
                const writes = writes_buffer[0..chunk_len];
                if (parsed_schema) |schema| try tables_api.validateWritesAgainstTableSchema(alloc, schema, writes);
                try staged_db.appendRaftDocumentSnapshotChunk(&staged, state.byte_range, writes);
            }
            try staged_db.finishRaftDocumentSnapshot(&staged, state.byte_range);
            try staged_db.sync(true);
            try staged_db.syncIndexes(true);
        }
        try staged.seal();

        var transition = try self.beginLocalGroupGenerationTransitionFromPreparation(table_name, group_id);
        preparation_activity = false;
        errdefer transition.abort();
        defer transition.deinit();

        self.invalidateSharedPathCaches(path);
        var shard_transition = try preparation.promote();
        defer shard_transition.deinit();
        const publication_outcome = try staged.publishPrepared();
        var publication_pending = true;
        errdefer if (publication_pending) staged.rollbackPublication() catch |rollback_err| {
            std.log.err("Raft snapshot catalog validation rollback failed group_id={} err={s}", .{ group_id, @errorName(rollback_err) });
        };

        // The candidate is physically installed but remains unservable under
        // the local generation transition. ReadIndex forwarding makes this
        // snapshot authoritative even when the contacted metadata node is a
        // follower. A mismatch atomically restores the prior root.
        const catalog_valid = self.catalog.validatePublication(catalog_contract.publicationContract()) catch |err| {
            try staged.rollbackPublication();
            publication_pending = false;
            return err;
        };
        if (!catalog_valid) {
            try staged.rollbackPublication();
            publication_pending = false;
            return error.CatalogChanged;
        }
        try staged.commitPublication();
        publication_pending = false;
        if (generation_reservation) |*reservation| reservation.advance();
        self.invalidateSharedPathCaches(path);
        transition.finishMutation();
        self.notifyLocalChange(table_name, .structural);
        self.notifyLocalChange(table_name, .data);
        if (publication_outcome == .durability_uncertain) return error.GenerationDurabilityUncertain;
    }

    pub fn applyHAReplicationRecordGroupLocal(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        record: db_mod.HAReplicationRecordView,
    ) !void {
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);

        if (self.write_cache) |cache| {
            const target_generation = self.visibleRootGeneration(group_id);
            var cached = try self.getOrOpenCachedDbForLocalMutationWithOptions(
                alloc,
                cache,
                path,
                group_id,
                target_generation,
                table_name,
                true,
                .{ .reconcile_for_replicated_apply = true },
            );
            defer cached.deinit(alloc);
            try cached.db.applyHAReplicationRecord(record);
            cache.publishCachedLeaseGeneration(&cached, target_generation);
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
            self.notifyLocalChange(table_name, changeKindForHARecord(record));
        } else {
            var db = try openManagedDbForReplicatedApply(
                alloc,
                path,
                self.catalog,
                table_name,
                group_id,
                self.backend_runtime,
                self.ha_write_gate,
                self.ha_async_mirror,
                null,
            );
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try db.applyHAReplicationRecord(record);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            self.notifyLocalChange(table_name, changeKindForHARecord(record));
        }
    }

    pub fn syncReplicatedBatchGroupLocal(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        sync_level: db_mod.types.SyncLevel,
    ) !void {
        try self.syncReplicatedBatchGroupLocalWithCancellation(alloc, group_id, table_name, sync_level, .none);
    }

    pub fn syncReplicatedBatchGroupLocalWithCancellation(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !void {
        switch (sync_level) {
            .propose, .write => return,
            .enrichments, .full_text, .full_index => {},
        }

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);

        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(
                alloc,
                cache,
                path,
                group_id,
                table_name,
                .default_async,
                null,
                null,
            );
            defer cached.deinit(alloc);
            try cached.db.waitForCurrentSyncLevelWithCancellation(sync_level, cancellation);
            self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try db.waitForCurrentSyncLevelWithCancellation(sync_level, cancellation);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
        }
        self.notifyLocalChange(table_name, .data);
    }

    fn finishTransientManagedDbWriteBeforeClose(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        db: *db_mod.DB,
    ) void {
        drainManagedDbBeforeClose(db) catch |err| {
            if (!isTransientReplayVisibilityError(err)) {
                std.log.warn("transient managed writer drain before close failed table={s} group_id={} err={s}", .{
                    table_name,
                    group_id,
                    @errorName(err),
                });
            }
        };
        if (self.runtime_status_cache != null)
            _ = self.publishManagedRuntimeStatusBestEffort(table_name, group_id, db);
    }

    fn txnBeginGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        topology_epoch: u64,
        retain_terminal: bool,
        participants: []const []const u8,
    ) !?void {
        return try txnBeginGroupLocalWithPreDecisionContext(ptr, alloc, group_id, table_name, txn_id, begin_timestamp, topology_epoch, retain_terminal, participants, .{});
    }

    fn txnBeginGroupLocalWithPreDecisionContext(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        topology_epoch: u64,
        retain_terminal: bool,
        participants: []const []const u8,
        context: distributed_txn.PreDecisionContext,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        try ensurePreDecisionContextActive(context);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        // Keep the epoch check and durable begin in the same transition
        // admission window. Otherwise a split can publish after validation
        // but before this transaction becomes visible to the pending-txn
        // transition fence.
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        try ensurePreDecisionContextActive(context);
        try table_catalog.validateTransactionTopologyEpoch(alloc, self.catalog, table_name, topology_epoch);
        try ensurePreDecisionContextActive(context);
        if (self.raft_batcher) |batcher| {
            try batcher.batchGroupLocalWithPreDecisionContext(alloc, group_id, table_name, .{
                .transaction = .{ .begin = .{
                    .txn_id = txn_id,
                    .begin_timestamp = begin_timestamp,
                    .created_at_ns = platform_time.realtimeNs(),
                    .topology_epoch = topology_epoch,
                    .retain_terminal = retain_terminal,
                    .participants = participants,
                } },
            }, context);
            return {};
        }
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
            defer cached.deinit(alloc);
            try ensurePreDecisionContextActive(context);
            try applyReplicatedTransactionMutation(alloc, cached.db, table_name, group_id, .{ .transaction = .{ .begin = .{
                .txn_id = txn_id,
                .begin_timestamp = begin_timestamp,
                .created_at_ns = platform_time.realtimeNs(),
                .topology_epoch = topology_epoch,
                .retain_terminal = retain_terminal,
                .participants = participants,
            } } });
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try ensurePreDecisionContextActive(context);
            try applyReplicatedTransactionMutation(alloc, &db, table_name, group_id, .{ .transaction = .{ .begin = .{
                .txn_id = txn_id,
                .begin_timestamp = begin_timestamp,
                .created_at_ns = platform_time.realtimeNs(),
                .topology_epoch = topology_epoch,
                .retain_terminal = retain_terminal,
                .participants = participants,
            } } });
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
        }
    }

    fn txnPrepareGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        topology_epoch: u64,
        req: db_mod.types.TransactionIntentRequest,
    ) !?void {
        return try txnPrepareGroupLocalWithPreDecisionContext(ptr, alloc, group_id, table_name, txn_id, topology_epoch, req, .{});
    }

    fn txnPrepareGroupLocalWithPreDecisionContext(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        topology_epoch: u64,
        req: db_mod.types.TransactionIntentRequest,
        context: distributed_txn.PreDecisionContext,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        try ensurePreDecisionContextActive(context);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        try ensurePreDecisionContextActive(context);
        try table_catalog.validateTransactionTopologyEpoch(alloc, self.catalog, table_name, topology_epoch);
        try ensurePreDecisionContextActive(context);
        if (self.raft_batcher) |batcher| {
            try batcher.batchGroupLocalWithPreDecisionContext(alloc, group_id, table_name, .{
                .writes = transactionWritesAsBatchWrites(req.writes),
                .deletes = req.deletes,
                .transforms = req.transforms,
                .predicates = req.predicates,
                .transaction = .{ .prepare = .{ .txn_id = txn_id, .topology_epoch = topology_epoch } },
            }, context);
            return {};
        }
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
            defer cached.deinit(alloc);
            try validateTransactionAgainstCatalogSchema(alloc, self.catalog, cached.db, table_name, req.writes, req.deletes, req.transforms);
            try ensurePreDecisionContextActive(context);
            try cached.db.writeTransaction(txn_id, req);
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try validateTransactionAgainstCatalogSchema(alloc, self.catalog, &db, table_name, req.writes, req.deletes, req.transforms);
            try ensurePreDecisionContextActive(context);
            try db.writeTransaction(txn_id, req);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
        }
    }

    fn txnResolveGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        status: db_mod.types.TxnStatus,
        commit_version: u64,
        topology_epoch: u64,
        sync_level: db_mod.types.SyncLevel,
    ) !?void {
        return try txnResolveGroupLocalWithCancellation(ptr, alloc, group_id, table_name, txn_id, status, commit_version, topology_epoch, sync_level, .none);
    }

    fn txnResolveGroupLocalWithCancellation(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        status: db_mod.types.TxnStatus,
        commit_version: u64,
        topology_epoch: u64,
        sync_level: db_mod.types.SyncLevel,
        cancellation: db_mod.types.CancellationToken,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        try enforceHAWriteGateOptional(self.ha_write_gate);
        // Serialize the final epoch validation with split/merge transition
        // admission. If a transition is already waiting, it wins admission;
        // otherwise this resolve remains ahead of the transition until the
        // durable decision has been applied.
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        if (topology_epoch != 0)
            try table_catalog.validateTransactionTopologyEpoch(alloc, self.catalog, table_name, topology_epoch);
        if (self.raft_batcher) |batcher| {
            try batcher.batchGroupLocalWithCancellation(alloc, group_id, table_name, .{
                .sync_level = sync_level,
                .transaction = .{ .resolve = .{
                    .txn_id = txn_id,
                    .status = status,
                    .commit_version = commit_version,
                } },
            }, cancellation);
            return {};
        }
        if (status == .committed) {
            lockAtomic(&self.local_db_mutex);
            self.invalidateReadCache(table_name);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            errdefer {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                self.invalidateReadCache(table_name);
                self.invalidateWriteCache(table_name);
            }
        }
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
            defer cached.deinit(alloc);
            try applyReplicatedTransactionMutationWithCancellation(alloc, cached.db, table_name, group_id, .{
                .sync_level = sync_level,
                .transaction = .{ .resolve = .{ .txn_id = txn_id, .status = status, .commit_version = commit_version } },
            }, cancellation);
            // Transaction resolution already honors the requested sync level.
            // In particular, `.write` must not become coupled to an external
            // enrichment provider merely because the ordinary batch route now
            // uses the transaction coordinator. The cached runtime owns the
            // durable replay tail and its background worker will resume it.
            if (status == .committed and shouldDrainCachedManagedDbAfterBatch(sync_level))
                try drainManagedDbBeforeClose(cached.db);
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try applyReplicatedTransactionMutationWithCancellation(alloc, &db, table_name, group_id, .{
                .sync_level = sync_level,
                .transaction = .{ .resolve = .{ .txn_id = txn_id, .status = status, .commit_version = commit_version } },
            }, cancellation);
            if (status == .committed) try drainManagedDbBeforeClose(&db);
            if (status == .committed) self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
        }
        if (status == .committed) {
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.invalidateReadCache(table_name);
            self.local_db_mutex.unlock();
            self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
            self.notifyLocalChange(table_name, .data);
        }
    }

    fn txnStatusGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
    ) !?db_mod.types.TxnStatus {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
            defer cached.deinit(alloc);
            return try cached.db.getTransactionStatus(txn_id);
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            return try db.getTransactionStatus(txn_id);
        }
    }

    fn txnAcknowledgeGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        participant: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        try enforceHAWriteGateOptional(self.ha_write_gate);
        if (self.raft_batcher) |batcher| {
            try batcher.batchGroupLocal(alloc, group_id, table_name, .{
                .sync_level = .write,
                .transaction = .{ .acknowledge = .{ .txn_id = txn_id, .participant = participant } },
            });
            return {};
        }
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
            defer cached.deinit(alloc);
            try cached.db.markTransactionParticipantResolved(txn_id, participant);
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try db.markTransactionParticipantResolved(txn_id, participant);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
        }
    }

    fn localRuntimeStatuses(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.localRuntimeStatuses(alloc, table_name);
        // Status must not observe a structural generation transition, but it
        // is safe to serve immutable snapshots during ordinary group work.
        // The narrower admission avoids deadlocking status callers that run
        // inside a group operation while still fencing restore/drop/publish.
        const admission = self.beginStatusRequest(table_name);
        defer self.endStatusRequest(table_name, admission);
        return try self.snapshotRuntimeStatusesBestEffortWithAdmission(alloc, table_name, admission == .snapshot_only);
    }

    fn collectRuntimeStatusLeasesFromWriteCacheLocked(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        out: *std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb),
    ) !bool {
        const cache = self.write_cache orelse return false;
        out.clearRetainingCapacity();
        if (self.isWriteCacheDirtyForTable(table_name)) {
            _ = try cache.finishExpiredAutoBulkIngestLocked(platform_time.monotonicNs());
        }

        var i: usize = 0;
        while (i < cache.entries.items.len) {
            const entry = cache.entries.items[i];
            if (!std.mem.eql(u8, entry.table_name, table_name)) {
                i += 1;
                continue;
            }
            if (entry.lsm_root_generation == self.visibleRootGeneration(entry.group_id)) {
                i += 1;
                continue;
            }
            if (cache.adoptSeededEntryGenerationLocked(entry, self.visibleRootGeneration(entry.group_id))) {
                i += 1;
                continue;
            }
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) {
                i += 1;
                continue;
            }
            if (try cache.retireInactiveEntryAtIndexForCloseLocked(i)) continue;
            i += 1;
        }

        var matching_entries: usize = 0;
        for (cache.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.lsm_root_generation != self.visibleRootGeneration(entry.group_id)) continue;
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) continue;
            matching_entries += 1;
        }
        try out.ensureTotalCapacity(alloc, matching_entries);

        for (cache.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.lsm_root_generation != self.visibleRootGeneration(entry.group_id)) continue;
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) continue;
            lockAtomic(&cache.entry_lifecycle_mutex);
            entry.active_leases += 1;
            cache.entry_lifecycle_mutex.unlock();
            out.appendAssumeCapacity(.{
                .cache = cache,
                .entry = entry,
                .db = &entry.db,
                .schema_json = entry.schema_json,
            });
        }
        return out.items.len != 0;
    }

    fn runtimeStatusesFromCachedDbLeasesBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        leases: []const ProvisionedTableWriteCache.CachedDb,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        const snapshot_cache = self.runtime_status_cache orelse return null;
        if (self.isWriteCacheDirtyForTable(table_name)) {
            if (self.write_cache) |cache| {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                _ = try cache.finishExpiredAutoBulkIngestLocked(platform_time.monotonicNs());
            }
        }
        var items = std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus).empty;
        errdefer {
            for (items.items) |*item| item.deinit(alloc);
            items.deinit(alloc);
        }

        try items.ensureTotalCapacity(alloc, leases.len);
        for (leases) |lease| {
            const group_id = lease.entry.?.group_id;
            try publishRuntimeStatusSnapshotConsistent(self, alloc, table_name, group_id, lease.db);
            var owned_status = (try snapshot_cache.snapshotGroupStatus(alloc, table_name, group_id)) orelse continue;
            errdefer owned_status.deinit(alloc);
            try self.overlayReadCacheIndexVisibilityBestEffort(alloc, table_name, group_id, &owned_status);
            items.appendAssumeCapacity(owned_status);
        }
        if (items.items.len == 0) {
            items.deinit(alloc);
            return try snapshot_cache.snapshot(alloc, table_name);
        }
        return .{ .items = try items.toOwnedSlice(alloc) };
    }

    fn overlayReadCacheHbcStatsBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        status: *runtime_status.LocalTableRuntimeStatus,
    ) !void {
        const read_cache = self.read_cache orelse return;
        const publication_token = if (self.runtime_status_cache) |snapshot_cache|
            try snapshot_cache.capturePublicationToken(table_name)
        else
            null;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);

        var read_lease = read_cache.getOrOpen(
            path,
            self.catalog,
            group_id,
            self.visibleRootGeneration(group_id),
            table_name,
        ) catch return;
        defer read_lease.release();

        overlayDenseHbcCacheStatsFromDb(&status.stats, read_lease.db);
        if (self.runtime_status_cache) |snapshot_cache| {
            _ = try snapshot_cache.publishGroup(publication_token.?, table_name, status.*);
        }
    }

    fn overlayReadCacheIndexVisibilityBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        status: *runtime_status.LocalTableRuntimeStatus,
    ) !void {
        if (self.isWriteCacheDirtyForTable(table_name)) return;
        if (self.hasActiveBulkIngestSessionForTableBestEffort(table_name)) return;

        const read_cache = self.read_cache orelse return;
        const publication_token = if (self.runtime_status_cache) |snapshot_cache|
            try snapshot_cache.capturePublicationToken(table_name)
        else
            null;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);

        var read_lease = read_cache.getOrOpen(
            path,
            self.catalog,
            group_id,
            self.visibleRootGeneration(group_id),
            table_name,
        ) catch return;
        defer read_lease.release();

        const visible_stats = try read_lease.db.stats(alloc);
        defer db_mod.types.freeDBStats(alloc, visible_stats);

        for (status.stats.indexes) |*item| {
            const visible = for (visible_stats.indexes) |candidate| {
                if (std.mem.eql(u8, candidate.name, item.name)) break candidate;
            } else continue;

            item.doc_count = visible.doc_count;
            item.term_count = visible.term_count;
            item.edge_count = visible.edge_count;
            item.node_count = visible.node_count;
            item.hbc_cache = visible.hbc_cache;
        }

        if (self.runtime_status_cache) |snapshot_cache| {
            _ = try snapshot_cache.publishGroup(publication_token.?, table_name, status.*);
        }
    }

    fn corruptEmbeddingArtifact(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        doc_key: []const u8,
        index_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.corruptEmbeddingArtifact(alloc, table_name, doc_key, index_name);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginTableRequest(table_name);
        defer self.endTableRequest(table_name);
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();
        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;

        for (group_ids) |group_id| {
            self.beginGroupOperation(table_name, group_id);
            {
                defer self.endGroupOperation(table_name, group_id);
                const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
                defer alloc.free(path);

                if (self.write_cache) |cache| {
                    var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default, null, null);
                    defer cached.deinit(alloc);
                    if (try corruptEmbeddingArtifactInDb(alloc, cached.db, doc_key, index_name)) {
                        lockAtomic(&self.local_db_mutex);
                        self.invalidateReadCache(table_name);
                        self.markWriteCacheDirty(table_name);
                        self.local_db_mutex.unlock();
                        self.notifyLocalChange(table_name, .data);
                        return;
                    }
                } else {
                    var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
                    defer db.close();
                    try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
                    if (try corruptEmbeddingArtifactInDb(alloc, &db, doc_key, index_name)) {
                        lockAtomic(&self.local_db_mutex);
                        self.invalidateReadCache(table_name);
                        self.markWriteCacheDirty(table_name);
                        self.local_db_mutex.unlock();
                        self.notifyLocalChange(table_name, .data);
                        return;
                    }
                }
            }
        }

        return error.NotFound;
    }

    fn reprocessDocumentArtifact(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        doc_key: []const u8,
        artifact_name: []const u8,
    ) !?bool {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.reprocessDocumentArtifact(alloc, table_name, doc_key, artifact_name);
        const group_id = (try table_catalog.resolveGroupForKey(alloc, self.catalog, table_name, doc_key)) orelse return null;
        return try reprocessDocumentArtifactGroupLocal(ptr, alloc, group_id, table_name, doc_key, artifact_name);
    }

    fn reprocessDocumentArtifactRange(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        artifact_name: []const u8,
        req: db_mod.types.DocumentArtifactTableReprocessRequest,
    ) !?db_mod.types.DocumentArtifactTableReprocessResult {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.reprocessDocumentArtifactRange(alloc, table_name, artifact_name, req);
        var result = db_mod.types.DocumentArtifactTableReprocessResult{};
        errdefer result.deinit(alloc);
        var failures = std.ArrayListUnmanaged(db_mod.types.DocumentArtifactReprocessFailure).empty;
        var shard_cursors = std.ArrayListUnmanaged(db_mod.types.DocumentArtifactReprocessShardCursor).empty;
        errdefer {
            for (failures.items) |*failure| failure.deinit(alloc);
            failures.deinit(alloc);
            for (shard_cursors.items) |*cursor| cursor.deinit(alloc);
            shard_cursors.deinit(alloc);
        }

        var handled_any = false;
        if (req.shard_cursors.len > 0) {
            for (req.shard_cursors) |cursor| {
                const group_id = cursor.group_id orelse return error.InvalidArgument;
                const group_req = documentArtifactReprocessRequestForCursor(req, cursor);
                var group_result = (try reprocessDocumentArtifactRangeGroupLocal(ptr, alloc, group_id, table_name, artifact_name, group_req)) orelse continue;
                defer group_result.deinit(alloc);
                handled_any = true;
                try mergeDocumentArtifactTableReprocessResult(alloc, &result, &failures, &shard_cursors, group_id, group_result);
            }
        } else {
            const group_ids = try table_catalog.resolveGroupsForSpanEventually(
                alloc,
                self.catalog,
                table_name,
                req.from_key,
                req.to_key,
                5 * std.time.ns_per_s,
                10,
            );
            defer alloc.free(group_ids);
            if (group_ids.len == 0) return null;

            for (group_ids) |group_id| {
                var group_result = (try reprocessDocumentArtifactRangeGroupLocal(ptr, alloc, group_id, table_name, artifact_name, req)) orelse continue;
                defer group_result.deinit(alloc);
                handled_any = true;
                try mergeDocumentArtifactTableReprocessResult(alloc, &result, &failures, &shard_cursors, group_id, group_result);
            }
        }
        if (!handled_any) return null;
        result.failures = try failures.toOwnedSlice(alloc);
        result.shard_cursors = try shard_cursors.toOwnedSlice(alloc);
        return result;
    }

    fn listArtifactRepairIssues(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: db_mod.types.ArtifactRepairListRequest,
    ) !?db_mod.types.ArtifactRepairListResult {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.listArtifactRepairIssues(alloc, table_name, req);
        self.beginTableRequest(table_name);
        defer self.endTableRequest(table_name);

        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;

        const parsed_cursor = try parseArtifactRepairTableCursor(req.cursor);
        var start_index: usize = 0;
        var start_cursor: ?[]const u8 = null;
        if (parsed_cursor) |cursor| {
            while (start_index < group_ids.len and group_ids[start_index] != cursor.group_id) : (start_index += 1) {}
            if (start_index == group_ids.len) return error.InvalidArgument;
            start_cursor = cursor.local_cursor;
        }

        var result = db_mod.types.ArtifactRepairListResult{ .limit = req.limit };
        errdefer result.deinit(alloc);
        var out = std.ArrayListUnmanaged(db_mod.types.ArtifactRepairIssue).empty;
        errdefer {
            for (out.items) |*issue| issue.deinit(alloc);
            out.deinit(alloc);
        }

        var groups_scanned: usize = 0;
        for (group_ids[start_index..], start_index..) |group_id, idx| {
            if (groups_scanned >= artifact_repair_max_groups_per_request) {
                result.has_more = true;
                result.next_cursor = try formatArtifactRepairTableCursorAlloc(alloc, group_id, null);
                break;
            }
            if (req.limit != 0 and out.items.len >= req.limit) {
                result.has_more = true;
                result.next_cursor = try formatArtifactRepairTableCursorAlloc(alloc, group_id, null);
                break;
            }
            const remaining: u32 = if (req.limit == 0) 0 else @intCast(req.limit - @as(u32, @intCast(out.items.len)));
            var group_result = (try listArtifactRepairIssuesGroupLocal(ptr, alloc, group_id, table_name, artifactRepairListRequestForShard(
                req,
                remaining,
                if (idx == start_index) start_cursor else null,
            ))) orelse continue;
            defer group_result.deinit(alloc);
            groups_scanned += 1;
            result.groups_scanned += 1;
            result.scanned += group_result.scanned;
            try appendOwnedArtifactRepairIssues(alloc, &out, group_result.issues);
            group_result.issues = &.{};
            if (group_result.has_more) {
                result.has_more = true;
                result.next_cursor = try formatArtifactRepairTableCursorAlloc(alloc, group_id, group_result.next_cursor);
                break;
            }
        }

        result.issues = try out.toOwnedSlice(alloc);
        out = .empty;
        return result;
    }

