        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const sequence = if (self.write_cache) |cache| blk: {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
            defer cached.deinit(alloc);
            break :blk try cached.db.applyDocumentArtifactChildRangeBatch(child_batch);
        } else blk: {
            const indexes_json = try loadTableIndexesJson(alloc, self.catalog, table_name);
            defer if (indexes_json) |value| alloc.free(value);
            var db = if (indexes_json) |value|
                try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentity(
                    alloc,
                    path,
                    value,
                    null,
                    null,
                    self.visibleRootGeneration(group_id),
                    null,
                    .default_async,
                    self.backend_runtime,
                    self.antfly_provider,
                    self.secret_store,
                    self.remote_content,
                    try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id),
                )
            else
                try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            const result = try db.applyDocumentArtifactChildRangeBatch(child_batch);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
            break :blk result;
        };
        if (sequence > 0) {
            lockAtomic(&self.local_db_mutex);
            self.invalidateReadCache(table_name);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            self.notifyLocalChange(table_name, .data);
        }
        return sequence;
    }

    fn reprocessDocumentArtifactRangeGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        artifact_name: []const u8,
        req: db_mod.types.DocumentArtifactTableReprocessRequest,
    ) !?db_mod.types.DocumentArtifactTableReprocessResult {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.reprocessDocumentArtifactRangeGroupLocal(alloc, group_id, table_name, artifact_name, req);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginTableRequest(table_name);
        defer self.endTableRequest(table_name);
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);

        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        var result = if (self.write_cache) |cache| blk: {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default, null, null);
            defer cached.deinit(alloc);
            break :blk try cached.db.reprocessDocumentArtifactRange(alloc, artifact_name, req);
        } else blk: {
            const indexes_json = try loadTableIndexesJson(alloc, self.catalog, table_name);
            defer if (indexes_json) |value| alloc.free(value);
            var db = if (indexes_json) |value|
                try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentity(
                    alloc,
                    path,
                    value,
                    null,
                    null,
                    self.visibleRootGeneration(group_id),
                    null,
                    .default,
                    self.backend_runtime,
                    self.antfly_provider,
                    self.secret_store,
                    self.remote_content,
                    try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id),
                )
            else
                try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            const range_result = try db.reprocessDocumentArtifactRange(alloc, artifact_name, req);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
            break :blk range_result;
        };
        errdefer result.deinit(alloc);
        if (result.reprocessed > 0 or result.failed > 0) {
            lockAtomic(&self.local_db_mutex);
            self.invalidateReadCache(table_name);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            self.notifyLocalChange(table_name, .data);
        }
        return result;
    }

    fn listArtifactRepairIssuesGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.ArtifactRepairListRequest,
    ) !?db_mod.types.ArtifactRepairListResult {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.listArtifactRepairIssuesGroupLocal(alloc, group_id, table_name, req);
        self.beginTableRequest(table_name);
        defer self.endTableRequest(table_name);
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        return if (self.write_cache) |cache| blk: {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default, null, null);
            defer cached.deinit(alloc);
            break :blk try cached.db.listArtifactRepairIssuesPage(alloc, req);
        } else blk: {
            const indexes_json = try loadTableIndexesJson(alloc, self.catalog, table_name);
            defer if (indexes_json) |value| alloc.free(value);
            var db = if (indexes_json) |value|
                try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentity(
                    alloc,
                    path,
                    value,
                    null,
                    null,
                    self.visibleRootGeneration(group_id),
                    null,
                    .default,
                    self.backend_runtime,
                    self.antfly_provider,
                    self.secret_store,
                    self.remote_content,
                    try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id),
                )
            else
                try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            break :blk try db.listArtifactRepairIssuesPage(alloc, req);
        };
    }

    fn repairArtifactIssuesGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.ArtifactRepairRunRequest,
    ) !?db_mod.types.ArtifactRepairResult {
        return try repairArtifactIssuesGroupLocalWithOptions(ptr, alloc, group_id, table_name, req, .{});
    }

    fn repairArtifactIssuesGroupLocalControlled(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.ArtifactRepairRunRequest,
        options: db_mod.types.ArtifactRepairRunOptions,
    ) !?db_mod.types.ArtifactRepairResult {
        return try repairArtifactIssuesGroupLocalWithOptions(ptr, alloc, group_id, table_name, req, options);
    }

    fn repairArtifactIssuesGroupLocalWithOptions(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.ArtifactRepairRunRequest,
        options: db_mod.types.ArtifactRepairRunOptions,
    ) !?db_mod.types.ArtifactRepairResult {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.repairArtifactIssuesGroupLocalControlled(alloc, group_id, table_name, req, options);
        if (options.cancelled()) return error.Canceled;
        var effective_options = options;
        if (req.target == .index and req.control == null) {
            // Persist the generation intent while the group lifecycle guard is
            // held, then let the DataServer's BackendRuntime maintenance owner
            // perform the admitted long-running work. This request remains a
            // bounded metadata operation and cannot stall foreground writes.
            effective_options.defer_durable_index_repair_execution = true;
        }
        const notify_cancellation = req.target == .index and req.control == .pause_automatic;
        if (notify_cancellation) self.notifyLocalIndexRepairDebt(table_name, group_id, .cancel);
        errdefer if (notify_cancellation) self.notifyLocalIndexRepairDebt(table_name, group_id, .clear_cancel);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginTableRequest(table_name);
        defer self.endTableRequest(table_name);
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        var result = if (self.write_cache) |cache| blk: {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default, null, null);
            defer cached.deinit(alloc);
            break :blk try cached.db.repairArtifactIssuesWithRequestOptions(alloc, req, effective_options);
        } else blk: {
            const indexes_json = try loadTableIndexesJson(alloc, self.catalog, table_name);
            defer if (indexes_json) |value| alloc.free(value);
            var db = if (indexes_json) |value|
                try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentity(
                    alloc,
                    path,
                    value,
                    null,
                    null,
                    self.visibleRootGeneration(group_id),
                    null,
                    .default,
                    self.backend_runtime,
                    self.antfly_provider,
                    self.secret_store,
                    self.remote_content,
                    try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id),
                )
            else
                try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            const group_result = try db.repairArtifactIssuesWithRequestOptions(alloc, req, effective_options);
            if (group_result.scanned > 0) self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
            break :blk group_result;
        };
        errdefer result.deinit(alloc);
        if (result.scanned > 0) {
            lockAtomic(&self.local_db_mutex);
            self.invalidateReadCache(table_name);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            self.notifyLocalChange(table_name, if (req.target == .index) .index_repair else .data);
            if (indexRepairDebtAction(req, result)) |action| {
                self.notifyLocalIndexRepairDebt(table_name, group_id, action);
            }
        }
        if (notify_cancellation) self.notifyLocalIndexRepairDebt(table_name, group_id, .clear_cancel);
        return result;
    }
};

test "provisioned table write source has a finite worker ceiling" {
    var source = ProvisionedTableWriteSource.init("unused", table_catalog.emptyCatalogSource());
    defer source.deinit();

    try std.testing.expectEqual(
        std.Io.Limit.limited(threaded_io_limits.service),
        source.table_activity_threaded.concurrent_limit,
    );
}

test "provisioned owner clone snapshot preserves retired runtime counters" {
    const alloc = std.testing.allocator;
    var runtime = try db_mod.background_runtime.BackendRuntimeHandle.init(alloc, .{ .backend = .manual });
    defer runtime.deinit();
    var source = ProvisionedTableWriteSource.init("unused", table_catalog.emptyCatalogSource());
    defer source.deinit();
    source.backend_runtime = runtime.ptr();

    var archived = db_mod.background_runtime.LsmOwnerCloneStats{
        .calls = 2,
        .bytes_total = 4096,
        .peak_bytes = 3072,
    };
    archived.by_reason[@intFromEnum(lsm_backend.MutableSnapshotReason.bulk_current_scan)] = .{
        .calls = 2,
        .bytes_total = 4096,
        .peak_bytes = 3072,
    };
    try runtime.ptr().accumulateRetiredLsmOwnerCloneStats(
        "docs",
        17,
        .dense_vector,
        "embedding",
        false,
        archived,
    );

    // Source/cache contention can hide active gauges, but runtime-owned
    // counters must remain present and monotonic.
    lockAtomic(&source.local_db_mutex);
    const owners = source.lsmOwnerStatsBestEffortAlloc(alloc) catch |err| {
        source.local_db_mutex.unlock();
        return err;
    };
    source.local_db_mutex.unlock();
    defer {
        for (owners) |*owner| owner.deinit(alloc);
        alloc.free(owners);
    }
    try std.testing.expectEqual(@as(usize, 1), owners.len);
    try std.testing.expectEqualStrings("docs", owners[0].table_name);
    try std.testing.expectEqualStrings("embedding", owners[0].owner_name);
    try std.testing.expectEqual(@as(u64, 2), owners[0].maintenance.mutable_snapshot_clone_calls);
    try std.testing.expectEqual(@as(u64, 4096), owners[0].maintenance.mutable_snapshot_clone_bytes_total);
    try std.testing.expectEqual(
        @as(u64, 2),
        owners[0].maintenance.mutable_snapshot_clone_by_reason[@intFromEnum(lsm_backend.MutableSnapshotReason.bulk_current_scan)].calls,
    );

    const AllocationRunner = struct {
        fn run(test_alloc: std.mem.Allocator, write_source: *ProvisionedTableWriteSource) !void {
            const snapshot = try write_source.lsmOwnerStatsBestEffortAlloc(test_alloc);
            defer {
                for (snapshot) |*owner| owner.deinit(test_alloc);
                test_alloc.free(snapshot);
            }
            try std.testing.expectEqual(@as(usize, 1), snapshot.len);
            try std.testing.expectEqualStrings("docs", snapshot[0].table_name);
            try std.testing.expectEqualStrings("embedding", snapshot[0].owner_name);
        }
    };
    try std.testing.checkAllAllocationFailures(alloc, AllocationRunner.run, .{&source});
}

fn enforceHAWriteGateOptional(gate: ?db_mod.HAWriteGate) !void {
    const configured = gate orelse return;
    try configured.check();
}

fn forwardedTableBackupRequestAlloc(
    alloc: std.mem.Allocator,
    backup_id: []const u8,
    location_uri: []const u8,
    connection: []const u8,
    format: backups_api.BackupFormat,
) ![]u8 {
    const format_name = switch (format) {
        .native => "native",
        .portable => "portable",
    };
    return try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(.{
        .backup_id = backup_id,
        .location = location_uri,
        .connection = connection,
        .format = format_name,
    }, .{})});
}

test "hosted backup forwarding preserves external io authority" {
    const alloc = std.testing.allocator;
    const body = try forwardedTableBackupRequestAlloc(
        alloc,
        "snap-1",
        "file:///backups",
        "archive-writer",
        .portable,
    );
    defer alloc.free(body);
    var parsed = try std.json.parseFromSlice(struct {
        backup_id: []const u8,
        location: []const u8,
        connection: []const u8,
        format: []const u8,
    }, alloc, body, .{});
    defer parsed.deinit();

    try std.testing.expectEqualStrings("snap-1", parsed.value.backup_id);
    try std.testing.expectEqualStrings("file:///backups", parsed.value.location);
    try std.testing.expectEqualStrings("archive-writer", parsed.value.connection);
    try std.testing.expectEqualStrings("portable", parsed.value.format);
}

test "backup storage resolution rejects a reused table name from another incarnation" {
    const Catalog = struct {
        table_id: u64 = 7,
        metadata_incarnation: metadata_api.MetadataClusterIncarnation = "0123456789abcdef0123456789abcdef".*,

        fn iface(self: *@This()) table_catalog.CatalogSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const tables = try std.testing.allocator.alloc(metadata_table_manager.TableRecord, 1);
            errdefer std.testing.allocator.free(tables);
            tables[0] = .{ .table_id = self.table_id, .name = "docs", .placement_role = "data", .schema_json = "{}", .indexes_json = "{}" };
            const ranges = try std.testing.allocator.alloc(metadata_table_manager.RangeRecord, 1);
            ranges[0] = .{ .group_id = 7001, .table_id = self.table_id, .start_key = "", .end_key = null };
            return .{
                .status = .{ .metadata_group_id = 1, .metadata_incarnation = self.metadata_incarnation, .metrics = .{} },
                .tables = tables,
                .ranges = ranges,
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, snapshot: *metadata_api.AdminSnapshot) void {
            std.testing.allocator.free(snapshot.tables);
            std.testing.allocator.free(snapshot.ranges);
        }
    };

    var catalog = Catalog{};
    var admitted = try catalog.iface().adminSnapshot();
    const fence = backups_api.tableBackupFence(&admitted, &admitted.tables[0]);
    catalog.iface().freeAdminSnapshot(&admitted);
    try std.testing.expectEqual(@as(?u64, 7001), try resolveFencedBackupGroup(catalog.iface(), "docs", fence));

    catalog.metadata_incarnation = "fedcba9876543210fedcba9876543210".*;
    try std.testing.expectError(error.CatalogChanged, resolveFencedBackupGroup(catalog.iface(), "docs", fence));
    catalog.metadata_incarnation = "0123456789abcdef0123456789abcdef".*;
    catalog.table_id = 8;
    try std.testing.expectError(error.CatalogChanged, resolveFencedBackupGroup(catalog.iface(), "docs", fence));
}

pub const HostedProvisionedTableWriteSource = struct {
    replica_root_dir: []const u8,
    catalog: table_catalog.CatalogSource,
    router: table_router.HostedGroupRouter,
    executor: http_common.RequestExecutor,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime = null,
    antfly_provider: ?managed_embedder.AntflyProvider = null,
    inference_api_url: ?[]const u8 = null,
    group_visible_root_generation: ?table_reads.GroupVisibleRootGenerationSource = null,
    secret_store: ?*common_secrets.FileStore = null,
    remote_content: ?*const scraping.RemoteContentConfig = null,
    internal_service_secret: ?[]const u8 = null,
    internal_service_issuer: ?[]const u8 = null,
    destination_authorizer: ?stored_destination_authorization.Authorizer = null,
    foreground_derived_progress: bool = false,

    pub fn init(
        replica_root_dir: []const u8,
        catalog: table_catalog.CatalogSource,
        router: table_router.HostedGroupRouter,
        executor: http_common.RequestExecutor,
    ) HostedProvisionedTableWriteSource {
        return .{
            .replica_root_dir = replica_root_dir,
            .catalog = catalog,
            .router = router,
            .executor = executor,
        };
    }

    pub fn withBackendRuntime(self: *HostedProvisionedTableWriteSource, backend_runtime: *db_mod.background_runtime.BackendRuntime) *HostedProvisionedTableWriteSource {
        self.backend_runtime = backend_runtime;
        if (hostedManagedDbCacheForRootIfPresent(self.replica_root_dir)) |cache| {
            cache.write_cache.backend_runtime = backend_runtime;
        }
        return self;
    }

    pub fn withAntflyProvider(
        self: *HostedProvisionedTableWriteSource,
        provider: ?managed_embedder.AntflyProvider,
    ) *HostedProvisionedTableWriteSource {
        self.antfly_provider = provider;
        if (hostedManagedDbCacheForRootIfPresent(self.replica_root_dir)) |cache| {
            cache.write_cache.antfly_provider = provider;
        }
        return self;
    }

    pub fn withInferenceAPIURL(
        self: *HostedProvisionedTableWriteSource,
        inference_api_url: ?[]const u8,
    ) *HostedProvisionedTableWriteSource {
        self.inference_api_url = inference_api_url;
        if (hostedManagedDbCacheForRootIfPresent(self.replica_root_dir)) |cache| {
            cache.write_cache.inference_api_url = inference_api_url;
        }
        return self;
    }

    pub fn withInternalServiceAuth(
        self: *HostedProvisionedTableWriteSource,
        secret: ?[]const u8,
        issuer: ?[]const u8,
    ) *HostedProvisionedTableWriteSource {
        self.internal_service_secret = secret;
        self.internal_service_issuer = issuer;
        return self;
    }

    fn httpClient(self: *HostedProvisionedTableWriteSource, alloc: std.mem.Allocator) http_client.ApiHttpClient {
        var client = http_client.ApiHttpClient.init(alloc, self.executor);
        _ = client.withInternalServiceAuth(self.internal_service_secret, self.internal_service_issuer);
        return client;
    }

    pub fn withDestinationAuthorization(
        self: *HostedProvisionedTableWriteSource,
        authorizer: ?stored_destination_authorization.Authorizer,
    ) *HostedProvisionedTableWriteSource {
        self.destination_authorizer = authorizer;
        return self;
    }

    pub fn withGroupVisibleRootGeneration(
        self: *HostedProvisionedTableWriteSource,
        generation_source: ?table_reads.GroupVisibleRootGenerationSource,
    ) *HostedProvisionedTableWriteSource {
        self.group_visible_root_generation = generation_source;
        return self;
    }

    pub fn withSecretStore(
        self: *HostedProvisionedTableWriteSource,
        secret_store: ?*common_secrets.FileStore,
    ) *HostedProvisionedTableWriteSource {
        self.secret_store = secret_store;
        if (hostedManagedDbCacheForRootIfPresent(self.replica_root_dir)) |cache| {
            cache.write_cache.secret_store = secret_store;
        }
        return self;
    }

    pub fn withRemoteContent(
        self: *HostedProvisionedTableWriteSource,
        remote_content: ?*const scraping.RemoteContentConfig,
    ) *HostedProvisionedTableWriteSource {
        self.remote_content = remote_content;
        if (hostedManagedDbCacheForRootIfPresent(self.replica_root_dir)) |cache| {
            cache.write_cache.remote_content = remote_content;
        }
        return self;
    }

    pub fn withForegroundDerivedProgress(self: *HostedProvisionedTableWriteSource) *HostedProvisionedTableWriteSource {
        self.foreground_derived_progress = true;
        return self;
    }

    fn transactionRecoveryConfig(self: *HostedProvisionedTableWriteSource) db_mod.transaction_runtime.Config {
        const backend_runtime = self.backend_runtime orelse return .{};
        if (backend_runtime.io() == null) return .{};
        return .{
            .enabled = true,
            .lease_owned = true,
            .owner_id = "hosted-2pc",
            .interval_ms = 5_000,
            .cutoff_ns = 5 * std.time.ns_per_min,
            .resolver_ctx = self,
            .resolve_participant_fn = resolveRecoveryParticipant,
        };
    }

    fn resolveRecoveryParticipant(
        ptr: *anyopaque,
        txn_id: db_mod.types.TxnId,
        participant: []const u8,
        status: db_mod.types.TxnStatus,
        commit_version: u64,
    ) !void {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const alloc = std.heap.page_allocator;
        var worker = distributed_txn.HostedParticipantWorker.init(self.catalog, self.router, self.source(), self.executor);
        _ = worker.withInternalServiceAuth(self.internal_service_secret, self.internal_service_issuer);
        try distributed_txn.resolveParticipant(alloc, worker.worker(), participant, txn_id, status, commit_version);
    }

    fn shouldDrainAfterBatch(self: *const HostedProvisionedTableWriteSource, sync_level: db_mod.types.SyncLevel) bool {
        return self.foreground_derived_progress or shouldDrainCachedManagedDbAfterBatch(sync_level);
    }

    fn visibleRootGeneration(self: *const HostedProvisionedTableWriteSource, group_id: u64) u64 {
        return if (self.group_visible_root_generation) |generation_source| generation_source.visibleRootGenerationForGroup(group_id) else table_reads.backend_current_root_generation;
    }

    fn invalidateManagedCache(self: *HostedProvisionedTableWriteSource, table_name: []const u8) void {
        const hosted_cache = hostedManagedDbCacheForRootIfPresent(self.replica_root_dir) orelse return;
        lockAtomic(&hosted_cache.mutex);
        hosted_cache.write_cache.invalidateTable(table_name);
        hosted_cache.runtime_status_cache.invalidateTable(table_name);
        hosted_cache.mutex.unlock();
        hosted_cache.write_cache.drainPendingCloses();
    }

    fn getOrOpenCachedDbMode(
        self: *HostedProvisionedTableWriteSource,
        cache: *HostedManagedDbCache,
        path: []const u8,
        group_id: u64,
        table_name: []const u8,
        mode: ManagedDbOpenMode,
    ) !ProvisionedTableWriteCache.CachedDb {
        const lsm_root_generation = self.visibleRootGeneration(group_id);
        if (self.backend_runtime) |runtime| cache.write_cache.backend_runtime = runtime;
        cache.write_cache.antfly_provider = self.antfly_provider;
        cache.write_cache.inference_api_url = self.inference_api_url;
        cache.write_cache.secret_store = self.secret_store;
        cache.write_cache.remote_content = self.remote_content;
        const identity_namespace = try loadTableIdentityNamespaceForGroup(cache.write_cache.alloc, self.catalog, table_name, group_id);
        const expected_identity_namespace = identity_namespace;
        if (mode == .status_only) {
            while (true) {
                lockAtomic(&cache.mutex);
                var cached = cache.write_cache.getOrOpenLockedMode(path, self.catalog, group_id, lsm_root_generation, table_name, .status_only) catch |err| switch (err) {
                    error.LsmRootWriterAlreadyOpen => {
                        if (!cache.write_cache.hasPendingCloseForGroupTableLocked(group_id, table_name)) {
                            cache.mutex.unlock();
                            return err;
                        }
                        cache.mutex.unlock();
                        cache.write_cache.drainPendingClosesForGroupTable(group_id, table_name);
                        continue;
                    },
                    else => {
                        cache.mutex.unlock();
                        return err;
                    },
                };
                cache.mutex.unlock();
                errdefer cached.deinit(cache.write_cache.alloc);
                try validateProvisionedDbIdentityNamespaceExpected(expected_identity_namespace, cached.db);
                return cached;
            }
        }

        var prepared_open: ?ProvisionedTableWriteCache.PreparedOpen = null;
        defer if (prepared_open) |*prepared| prepared.deinit(cache.write_cache.alloc);

        while (true) {
            lockAtomic(&cache.mutex);
            const open_state = cache.write_cache.getOrPrepareOpenLocked(
                group_id,
                lsm_root_generation,
                table_name,
                expected_identity_namespace,
                null,
            ) catch |err| {
                cache.mutex.unlock();
                return err;
            };
            switch (open_state) {
                .cached => |cached_value| {
                    var cached = cached_value;
                    cache.mutex.unlock();
                    errdefer cached.deinit(cache.write_cache.alloc);
                    try validateProvisionedDbIdentityNamespaceExpected(expected_identity_namespace, cached.db);
                    return cached;
                },
                .prepared => |prepared| {
                    cache.mutex.unlock();
                    prepared_open = prepared;
                    break;
                },
                .pending_close => {
                    cache.mutex.unlock();
                    cache.write_cache.drainPendingClosesForGroupTable(group_id, table_name);
                    continue;
                },
            }
        }

        lockAtomic(&cache.write_cache.open_mutex);
        defer cache.write_cache.open_mutex.unlock();

        while (true) {
            lockAtomic(&cache.mutex);
            const open_state = cache.write_cache.getOrPrepareOpenLocked(
                group_id,
                lsm_root_generation,
                table_name,
                expected_identity_namespace,
                null,
            ) catch |err| {
                cache.mutex.unlock();
                return err;
            };
            switch (open_state) {
                .cached => |cached_value| {
                    var cached = cached_value;
                    cache.mutex.unlock();
                    errdefer cached.deinit(cache.write_cache.alloc);
                    try validateProvisionedDbIdentityNamespaceExpected(expected_identity_namespace, cached.db);
                    return cached;
                },
                .prepared => |prepared| {
                    cache.mutex.unlock();
                    prepared_open.?.deinit(cache.write_cache.alloc);
                    prepared_open = prepared;
                    break;
                },
                .pending_close => {
                    cache.mutex.unlock();
                    cache.write_cache.drainPendingClosesForGroupTableAssumeOpenMutexHeld(group_id, table_name);
                    continue;
                },
            }
        }

        if (try loadTableManagedMetadata(cache.write_cache.alloc, self.catalog, table_name)) |metadata| {
            prepared_open.?.indexes_json = metadata.indexes_json;
            prepared_open.?.schema_json = metadata.schema_json;
        }

        const effective_ha_mirror = haMirrorForManagedDbOpenMode(mode, cache.write_cache.ha_async_mirror);
        var opened: ?db_mod.DB = if (prepared_open.?.indexes_json) |value|
            try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
                cache.write_cache.alloc,
                path,
                value,
                cache.write_cache.lsm_cache,
                cache.write_cache.hbc_cache,
                lsm_root_generation,
                cache.write_cache.resource_manager,
                mode,
                cache.write_cache.backend_runtime,
                cache.write_cache.antfly_provider,
                cache.write_cache.secret_store,
                cache.write_cache.remote_content,
                identity_namespace,
                .{
                    .drain_resolver_backfill = false,
                    .source_table = table_name,
                    .destination_authorizer = self.destination_authorizer,
                    .schema_json_before_index_load = prepared_open.?.schema_json,
                    .inference_api_url = cache.write_cache.inference_api_url,
                    .ha_write_gate = cache.write_cache.ha_write_gate,
                    .ha_async_effect_mirror = effective_ha_mirror,
                    .ha_async_batch_mirror = effective_ha_mirror,
                    .ha_async_metadata_mirror = effective_ha_mirror,
                    .transaction_recovery = if (mode == .startup_catch_up or mode == .restore_repair or mode == .query_readonly or mode == .status_only)
                        .{}
                    else
                        self.transactionRecoveryConfig(),
                },
            )
        else
            try db_mod.DB.open(cache.write_cache.alloc, path, .{
                .lsm_cache = cache.write_cache.lsm_cache,
                .hbc_cache = cache.write_cache.hbc_cache,
                .lsm_root_generation = lsm_root_generation,
                .resource_manager = cache.write_cache.resource_manager,
                .backend_runtime = cache.write_cache.backend_runtime,
                .identity_namespace = identity_namespace,
                .prefer_existing_identity_namespace = identity_namespace != null,
                .ha_write_gate = cache.write_cache.ha_write_gate,
                .ha_async_effect_mirror = effective_ha_mirror,
                .ha_async_batch_mirror = effective_ha_mirror,
                .ha_async_metadata_mirror = effective_ha_mirror,
                .open_mode = switch (mode) {
                    .default => .writer,
                    .default_async, .writer_no_replay => .writer_no_replay,
                    .startup_catch_up, .restore_repair => .writer_no_replay,
                    .query_readonly => .query_readonly,
                    .status_only => .status_only,
                },
                .start_index_workers = if (mode == .startup_catch_up or mode == .restore_repair or mode == .query_readonly) false else true,
                .start_optional_runtimes = mode != .startup_catch_up and mode != .restore_repair and mode != .query_readonly,
                .ttl_cleanup = if (mode == .startup_catch_up or mode == .restore_repair or mode == .query_readonly) .{ .enabled = false } else .{},
                .transaction_recovery = if (mode == .startup_catch_up or mode == .restore_repair or mode == .query_readonly or mode == .status_only)
                    .{}
                else
                    self.transactionRecoveryConfig(),
                .text_merge = if (mode == .startup_catch_up or mode == .restore_repair or mode == .query_readonly) .{ .enabled = false } else .{},
            });
        defer if (opened) |*db| db.close();
        try validateProvisionedDbIdentityNamespaceExpected(identity_namespace, &opened.?);

        var cached = blk: {
            lockAtomic(&cache.mutex);
            defer cache.mutex.unlock();
            try cache.write_cache.reserveRetiredEntriesCapacityLocked(1);
            break :blk try cache.write_cache.adoptPreparedOpenLocked(&opened, group_id, lsm_root_generation, table_name, mode, &prepared_open.?);
        };
        errdefer {
            lockAtomic(&cache.mutex);
            defer cache.mutex.unlock();
            cache.write_cache.retireFailedOpenLocked(&cached);
        }
        if (managedDbOpenModeDrainsResolverBackfill(mode)) {
            try cached.db.drainResolverBackfill();
        }
        return cached;
    }

    fn reconcileCachedIndexCreate(
        self: *HostedProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
    ) !void {
        var metadata: ?struct { indexes_json: []u8, schema_json: []u8 } = null;
        defer if (metadata) |loaded| {
            alloc.free(loaded.indexes_json);
            alloc.free(loaded.schema_json);
        };

        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);

        var hosted_cache: ?*HostedManagedDbCache = null;
        for (group_ids) |group_id| {
            const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);

            // Public routes can run on nodes with stale on-disk group paths.
            // Reconcile only groups the hosted router says this process actively owns.
            if (self.router.localStatus(group_id) != .active) continue;

            const cache = hosted_cache orelse blk: {
                const cache = try hostedManagedDbCacheForRoot(self.replica_root_dir);
                hosted_cache = cache;
                break :blk cache;
            };
            if (metadata == null) {
                const loaded = try cachedTableMetadataFromCatalog(alloc, self.catalog, &cache.write_cache, table_name);
                metadata = .{
                    .indexes_json = loaded.indexes_json,
                    .schema_json = loaded.schema_json,
                };
            }

            var cached = try self.getOrOpenCachedDbMode(cache, path, group_id, table_name, .default_async);
            defer cached.deinit(cache.write_cache.alloc);

            try applyIndexCreateToCachedDb(
                alloc,
                cached.db,
                metadata.?.indexes_json,
                index_name,
                cache.write_cache.backend_runtime,
                cache.write_cache.antfly_provider,
                cache.write_cache.inference_api_url,
                cache.write_cache.secret_store,
                cache.write_cache.remote_content,
            );

            if (try cached.db.core.indexRequiresEnrichmentReplay(index_name)) {
                _ = try seedManagedIndexReplayFromStoredDocsIfNeeded(alloc, cached.db, index_name);
            }

            if (try cached.db.denseArtifactRebuildMaintenanceNeeded(alloc)) {
                _ = try cached.db.runDenseArtifactRebuildMaintenanceWithProgress(alloc, null, null);
            }
            try drainManagedDbBeforeClose(cached.db);
            try publishRuntimeStatusSnapshotToCacheConsistent(
                &cache.runtime_status_cache,
                alloc,
                table_name,
                group_id,
                cached.db,
            );
        }
    }

    pub fn source(self: *HostedProvisionedTableWriteSource) TableWriteSource {
        // Source publication is the hosted process startup boundary. Create
        // the persistent cleanup owner here so intents left by a crash are
        // recovered even when no subsequent table drop happens.
        if (hostedManagedDbCacheForRoot(self.replica_root_dir)) |cache| {
            if (self.persistentDropCleanupSource(cache)) |cleanup| {
                cleanup.startDroppedTableRecovery();
            } else |err| {
                std.log.warn(
                    "hosted dropped-table recovery owner unavailable root={s} err={s}",
                    .{ self.replica_root_dir, @errorName(err) },
                );
            }
        } else |err| {
            std.log.warn(
                "hosted dropped-table cache unavailable root={s} err={s}",
                .{ self.replica_root_dir, @errorName(err) },
            );
        }
        return .{
            .ptr = self,
            .vtable = &.{
                .drop_table = dropTable,
                .create_index = createIndex,
                .put_artifact_enrichment = putArtifactEnrichment,
                .delete_artifact_enrichment = deleteArtifactEnrichment,
                .drop_index = dropIndex,
                .commit_transaction = commitTransaction,
                .commit_transaction_with_cancellation = commitTransactionWithCancellation,
                .commit_batch = commitBatch,
                .commit_batch_with_cancellation = commitBatchWithCancellation,
                .commit_transaction_with_id = commitTransactionWithId,
                .commit_transaction_with_id_with_cancellation = commitTransactionWithIdAndCancellation,
                .acknowledge_transaction_commit = acknowledgeTransactionCommit,
                .backup_table = backupTable,
                .backup_table_to_location = backupTableToLocation,
                .restore_table = restoreTable,
                .batch = batch,
                .batch_group_local = batchGroupLocal,
                .txn_begin_group_local = txnBeginGroupLocal,
                .txn_begin_group_local_with_pre_decision_context = txnBeginGroupLocalWithPreDecisionContext,
                .txn_prepare_group_local = txnPrepareGroupLocal,
                .txn_prepare_group_local_with_pre_decision_context = txnPrepareGroupLocalWithPreDecisionContext,
                .txn_resolve_group_local = txnResolveGroupLocal,
                .txn_resolve_group_local_with_cancellation = txnResolveGroupLocalWithCancellation,
                .txn_status_group_local = txnStatusGroupLocal,
                .txn_acknowledge_group_local = txnAcknowledgeGroupLocal,
                .corrupt_embedding_artifact = corruptEmbeddingArtifact,
                .reprocess_document_artifact = reprocessDocumentArtifact,
                .reprocess_document_artifact_range = reprocessDocumentArtifactRange,
                .list_artifact_repair_issues = listArtifactRepairIssues,
                .repair_artifact_issues = repairArtifactIssues,
                .repair_artifact_issues_controlled = repairArtifactIssuesControlled,
                .update_document_artifact_child_range_placement = updateDocumentArtifactChildRangePlacement,
                .apply_document_artifact_child_range_batch = applyDocumentArtifactChildRangeBatch,
                .reprocess_document_artifact_group_local = reprocessDocumentArtifactGroupLocal,
                .reprocess_document_artifact_range_group_local = reprocessDocumentArtifactRangeGroupLocal,
                .list_artifact_repair_issues_group_local = listArtifactRepairIssuesGroupLocal,
                .repair_artifact_issues_group_local = repairArtifactIssuesGroupLocal,
                .repair_artifact_issues_group_local_controlled = repairArtifactIssuesGroupLocalControlled,
                .update_document_artifact_child_range_placement_group_local = updateDocumentArtifactChildRangePlacementGroupLocal,
                .apply_document_artifact_child_range_batch_group_local = applyDocumentArtifactChildRangeBatchGroupLocal,
                .local_runtime_statuses = localRuntimeStatuses,
            },
        };
    }

    fn persistentDropCleanupSource(
        self: *HostedProvisionedTableWriteSource,
        cache: *HostedManagedDbCache,
    ) !*ProvisionedTableWriteSource {
        lockAtomic(&cache.mutex);
        defer cache.mutex.unlock();
        if (cache.drop_cleanup_source == null) {
            const cleanup = try std.heap.page_allocator.create(ProvisionedTableWriteSource);
            errdefer std.heap.page_allocator.destroy(cleanup);
            cleanup.* = ProvisionedTableWriteSource.init(self.replica_root_dir, self.catalog);
            cleanup.write_cache = &cache.write_cache;
            cleanup.runtime_status_cache = &cache.runtime_status_cache;
            cleanup.dropped_table_cleanup_outer_mutex = &cache.mutex;
            cleanup.backend_runtime = self.backend_runtime;
            cache.drop_cleanup_source = cleanup;
        } else if (self.backend_runtime) |runtime| {
            // Runtime attachment may happen after the process-wide hosted
            // cache was first opened. Publish it before recovery scheduling.
            cache.drop_cleanup_source.?.backend_runtime = runtime;
        }
        return cache.drop_cleanup_source.?;
    }

    fn dropTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        contract: metadata_topology_protocol.DropCleanupContract,
    ) !?void {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (contract.group_ids.len == 0) return null;

        // Hosted reads and writes share this process-wide cache. A persistent
        // cleanup source owns startup scans and durable retry jobs; unlike a
        // request-scoped adapter it remains valid until the cache is closed.
        const cache = try hostedManagedDbCacheForRoot(self.replica_root_dir);
        const cleanup = try self.persistentDropCleanupSource(cache);
        cleanup.startDroppedTableRecovery();
        // Later failures schedule additional runs through the same persistent
        // owner, and every run takes cache.mutex inside the cleanup path.
        return try cleanup.source().dropTable(alloc, table_name, contract);
    }

    fn createIndex(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
        _: []const u8,
    ) !?void {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const deadline_ns = platform_time.monotonicNs() + replicated_apply_writer_open_timeout_ns;
        while (true) {
            self.reconcileCachedIndexCreate(alloc, table_name, index_name) catch |err| switch (err) {
                error.LsmRootWriterAlreadyOpen, error.WriterLocked, error.PersistentDescriptorAdmissionExhausted => {
                    self.invalidateManagedCache(table_name);
                    if (platform_time.monotonicNs() >= deadline_ns) return err;
                    sleepNs(replicated_apply_writer_open_retry_ns);
                    continue;
                },
                else => {
                    self.invalidateManagedCache(table_name);
                    return err;
                },
            };
            return;
        }
    }

    fn putArtifactEnrichment(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        artifact_name: []const u8,
        enrichment_json: []const u8,
    ) !?void {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        self.invalidateManagedCache(table_name);
        try putLocalArtifactEnrichment(alloc, self.catalog, self.replica_root_dir, self.backend_runtime, table_name, artifact_name, enrichment_json);
        self.invalidateManagedCache(table_name);
    }

    fn deleteArtifactEnrichment(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        artifact_name: []const u8,
    ) !?void {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        self.invalidateManagedCache(table_name);
        try dropLocalArtifactEnrichment(alloc, self.catalog, self.replica_root_dir, self.backend_runtime, table_name, artifact_name);
        self.invalidateManagedCache(table_name);
    }

    fn dropIndex(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
    ) !?void {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const deadline_ns = platform_time.monotonicNs() + replicated_apply_writer_open_timeout_ns;
        while (true) {
            self.invalidateManagedCache(table_name);
            dropLocalTableIndex(alloc, self.catalog, self.replica_root_dir, self.backend_runtime, table_name, index_name) catch |err| switch (err) {
                error.LsmRootWriterAlreadyOpen, error.WriterLocked, error.PersistentDescriptorAdmissionExhausted => {
                    if (platform_time.monotonicNs() >= deadline_ns) return err;
                    sleepNs(replicated_apply_writer_open_retry_ns);
                    continue;
                },
                else => return err,
            };
            self.invalidateManagedCache(table_name);
            return;
        }
    }

    fn batch(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
    ) !?void {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        var grouped = std.ArrayListUnmanaged(GroupBatch).empty;
        defer {
            for (grouped.items) |*group| group.deinit(alloc);
            grouped.deinit(alloc);
        }

        var snapshot = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_name) orelse return null;
        const ranges = try metadata_admin.listTableRanges(alloc, &snapshot, table.table_id);
        defer metadata_admin.freeRangeRefs(alloc, ranges);
        if (ranges.len == 0) return null;

        for (req.writes) |write| {
            const group_id = table_catalog.resolveGroupForKeyFromRanges(ranges, write.key) orelse return null;
            const group = try ensureGroupBatch(alloc, &grouped, group_id);
            try group.writes.append(alloc, write);
        }
        for (req.deletes) |key| {
            const group_id = table_catalog.resolveGroupForKeyFromRanges(ranges, key) orelse return null;
            const group = try ensureGroupBatch(alloc, &grouped, group_id);
            try group.deletes.append(alloc, key);
        }
        for (req.transforms) |transform| {
            const group_id = table_catalog.resolveGroupForKeyFromRanges(ranges, transform.key) orelse return null;
            const group = try ensureGroupBatch(alloc, &grouped, group_id);
            try group.transforms.append(alloc, transform);
        }

        for (grouped.items) |group| {
            var resolved_route = try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group.group_id, .prefer_leader);
            if (resolved_route) |*route| {
                defer route.deinit(alloc);

                switch (route.*) {
                    .local => {
                        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group.group_id);
                        defer alloc.free(path);
                        const hosted_cache = try hostedManagedDbCacheForRoot(self.replica_root_dir);
                        var cached = try self.getOrOpenCachedDbMode(hosted_cache, path, group.group_id, table_name, .default_async);
                        defer cached.deinit(hosted_cache.write_cache.alloc);
                        try validateTableBatchAgainstSchemaJson(alloc, cached.db, cached.schema_json, group.writes.items, group.deletes.items, group.transforms.items);
                        var dispatch_ctx = DocumentChildRangeDispatchContext{
                            .source = self.source(),
                            .table_name = table_name,
                        };
                        try cached.db.batchWithDocumentArtifactChildRangeDispatcher(.{
                            .writes = group.writes.items,
                            .deletes = group.deletes.items,
                            .transforms = group.transforms.items,
                            .graph_writes = req.graph_writes,
                            .graph_deletes = req.graph_deletes,
                            .predicates = req.predicates,
                            .timestamp_ns = req.timestamp_ns,
                            .sync_level = req.sync_level,
                        }, dispatch_ctx.dispatcher());
                        if (self.shouldDrainAfterBatch(req.sync_level)) try drainManagedDbBeforeClose(cached.db);
                    },
                    .remote => |remote| {
                        var client = self.httpClient(alloc);
                        const body = try encodeRemoteBatchRequest(alloc, .{
                            .writes = group.writes.items,
                            .deletes = group.deletes.items,
                            .transforms = group.transforms.items,
                            .graph_writes = req.graph_writes,
                            .graph_deletes = req.graph_deletes,
                            .predicates = req.predicates,
                            .timestamp_ns = req.timestamp_ns,
                            .sync_level = req.sync_level,
                        });
                        defer alloc.free(body);
                        var response = try client.fetchGroupBatch(remote.base_uri, group.group_id, table_name, body);
                        response.deinit(alloc);
                    },
                }
            } else {
                const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group.group_id);
                defer alloc.free(path);
                var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
                defer io_impl.deinit();
                std.Io.Dir.cwd().access(io_impl.io(), path, .{}) catch |err| switch (err) {
                    error.FileNotFound => return null,
                    else => return err,
                };
                const hosted_cache = try hostedManagedDbCacheForRoot(self.replica_root_dir);
                var cached = try self.getOrOpenCachedDbMode(hosted_cache, path, group.group_id, table_name, .default_async);
                defer cached.deinit(hosted_cache.write_cache.alloc);
                try validateTableBatchAgainstSchemaJson(alloc, cached.db, cached.schema_json, group.writes.items, group.deletes.items, group.transforms.items);
                var dispatch_ctx = DocumentChildRangeDispatchContext{
                    .source = self.source(),
                    .table_name = table_name,
                };
                try cached.db.batchWithDocumentArtifactChildRangeDispatcher(.{
                    .writes = group.writes.items,
                    .deletes = group.deletes.items,
                    .transforms = group.transforms.items,
                    .graph_writes = req.graph_writes,
                    .graph_deletes = req.graph_deletes,
                    .predicates = req.predicates,
                    .timestamp_ns = req.timestamp_ns,
                    .sync_level = req.sync_level,
                }, dispatch_ctx.dispatcher());
                if (self.shouldDrainAfterBatch(req.sync_level)) try drainManagedDbBeforeClose(cached.db);
            }
        }
    }

    fn commitTransaction(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
    ) !?distributed_txn.CommitOutcome {
        return try commitTransactionWithCancellation(ptr, alloc, tables, sync_level, .none);
    }

    fn commitTransactionWithCancellation(
