    fn acknowledgeTransactionCommit(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        coordinator_group_id: u64,
        coordinator_table_name: []const u8,
    ) !?void {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const participant = try distributed_txn.participantIdForGroup(alloc, coordinator_table_name, coordinator_group_id);
        defer alloc.free(participant);
        var worker = distributed_txn.HostedParticipantWorker.init(self.catalog, self.router, self.source(), self.executor);
        _ = worker.withInternalServiceAuth(self.internal_service_secret, self.internal_service_issuer);
        try worker.worker().acknowledgeGroup(alloc, coordinator_group_id, coordinator_table_name, .{
            .txn_id = txn_id,
            .participant = participant,
        });
        return {};
    }

    fn commitHostedTransaction(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
        retain_terminal: bool,
        cancellation: db_mod.types.CancellationToken,
    ) !?distributed_txn.CommitOutcome {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        var worker_impl = distributed_txn.HostedParticipantWorker.init(self.catalog, self.router, self.source(), self.executor);
        _ = worker_impl.withInternalServiceAuth(self.internal_service_secret, self.internal_service_issuer);
        const commit_version = begin_timestamp + 1;
        return try distributed_txn.executeMultiTableCommitWithOptions(
            alloc,
            self.catalog,
            worker_impl.worker(),
            txn_id,
            begin_timestamp,
            commit_version,
            tables,
            sync_level,
            if (comptime build_options.with_tla) tracing.stderrAntflyTraceWriter() else null,
            .{
                .retain_terminal = retain_terminal,
                .report_post_commit_failure = false,
                .fanout_io = if (self.backend_runtime) |runtime|
                    if (runtime.apiIoImpl()) |io_impl| io_impl.io() else null
                else
                    null,
                .post_commit_cancellation = cancellation,
            },
        );
    }

    fn backupTable(
        _: *anyopaque,
        _: std.mem.Allocator,
        _: []const u8,
        _: backups_api.TableBackupPlan,
    ) !?[]backups_api.ShardSnapshot {
        return error.UnsupportedOperation;
    }

    fn backupTableToLocation(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        backup_id: []const u8,
        format: backups_api.BackupFormat,
        fence: backups_api.TableBackupFence,
        location_uri: []const u8,
        connection: []const u8,
        location_ptr: *anyopaque,
    ) !?[]backups_api.ShardSnapshot {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const location: *backups_api.BackupLocation = @ptrCast(@alignCast(location_ptr));
        const group_id = (try resolveFencedBackupGroup(self.catalog, table_name, fence)) orelse return null;
        const resolved_route = try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_id, .prefer_leader);
        var route = resolved_route orelse return null;
        defer route.deinit(alloc);
        switch (route) {
            .local => return error.UnsupportedOperation,
            .remote => |remote| {
                const body = try forwardedTableBackupRequestAlloc(alloc, backup_id, location_uri, connection, format);
                defer alloc.free(body);

                var client = self.httpClient(alloc);
                var response = try client.fetchBackupTableFenced(remote.base_uri, table_name, body, fence);
                response.deinit(alloc);

                var manifest = try backups_api.readManifestFromLocation(alloc, location, backup_id);
                defer manifest.deinit(alloc);
                return try cloneShardSnapshots(alloc, manifest.shards);
            },
        }
    }

