test "prepared raft apply reclassifies every transient pre-mutation writer conflict" {
    const map = ProvisionedTableWriteSource.mapReplicatedApplyWriterAcquireError;
    try std.testing.expect(map(.local_persisted, error.LsmRootWriterAlreadyOpen) == error.RaftApplyWriterUnavailable);
    try std.testing.expect(map(.local_persisted, error.WriterLocked) == error.RaftApplyWriterUnavailable);
    try std.testing.expect(map(.local_persisted, error.PersistentDescriptorAdmissionExhausted) == error.RaftApplyWriterUnavailable);
    try std.testing.expect(map(.catalog, error.LsmRootWriterAlreadyOpen) == error.LsmRootWriterAlreadyOpen);
    try std.testing.expect(map(.local_persisted, error.OutOfMemory) == error.OutOfMemory);
}

const GroupBatch = struct {
    group_id: u64,
    writes: std.ArrayListUnmanaged(db_mod.types.BatchWrite) = .empty,
    deletes: std.ArrayListUnmanaged([]const u8) = .empty,
    transforms: std.ArrayListUnmanaged(db_mod.types.DocumentTransform) = .empty,

    fn deinit(self: *GroupBatch, alloc: std.mem.Allocator) void {
        self.writes.deinit(alloc);
        self.deletes.deinit(alloc);
        self.transforms.deinit(alloc);
        self.* = undefined;
    }
};

fn cloneWriteCoalesceGroupBatch(
    alloc: std.mem.Allocator,
    group: GroupBatch,
) !GroupBatch {
    var cloned = GroupBatch{ .group_id = group.group_id };
    errdefer freeWriteCoalesceGroupBatch(alloc, &cloned);

    try cloned.writes.ensureTotalCapacity(alloc, group.writes.items.len);
    for (group.writes.items) |write| {
        const key = try alloc.dupe(u8, write.key);
        const value = alloc.dupe(u8, write.value) catch |err| {
            alloc.free(key);
            return err;
        };
        cloned.writes.appendAssumeCapacity(.{ .key = key, .value = value });
    }

    try cloned.deletes.ensureTotalCapacity(alloc, group.deletes.items.len);
    for (group.deletes.items) |key| {
        const owned_key = try alloc.dupe(u8, key);
        cloned.deletes.appendAssumeCapacity(owned_key);
    }

    return cloned;
}

fn freeWriteCoalesceGroupBatch(alloc: std.mem.Allocator, group: *GroupBatch) void {
    for (group.writes.items) |write| {
        alloc.free(write.key);
        alloc.free(write.value);
    }
    for (group.deletes.items) |key| alloc.free(key);
    group.deinit(alloc);
}

fn ensureGroupBatch(
    alloc: std.mem.Allocator,
    grouped: *std.ArrayListUnmanaged(GroupBatch),
    group_id: u64,
) !*GroupBatch {
    for (grouped.items) |*group| {
        if (group.group_id == group_id) return group;
    }
    try grouped.append(alloc, .{ .group_id = group_id });
    return &grouped.items[grouped.items.len - 1];
}

fn applyGroupBatch(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    db: *db_mod.DB,
    table_name: []const u8,
    group: GroupBatch,
    req: db_mod.types.BatchRequest,
    cancellation: db_mod.types.CancellationToken,
) !void {
    try validateTableBatchAgainstCatalogSchema(alloc, catalog, db, table_name, group.writes.items, group.deletes.items, group.transforms.items);
    try applyGroupBatchUnchecked(db, group, req, cancellation);
}

fn applyGroupBatchWithSchemaJson(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    schema_json: ?[]const u8,
    group: GroupBatch,
    req: db_mod.types.BatchRequest,
    cancellation: db_mod.types.CancellationToken,
) !void {
    try validateTableBatchAgainstSchemaJson(alloc, db, schema_json, group.writes.items, group.deletes.items, group.transforms.items);
    try applyGroupBatchUnchecked(db, group, req, cancellation);
}

fn applyGroupBatchUnchecked(
    db: *db_mod.DB,
    group: GroupBatch,
    req: db_mod.types.BatchRequest,
    cancellation: db_mod.types.CancellationToken,
) !void {
    runTestBeforeBatchExecutionHook();
    const batch_req: db_mod.types.BatchRequest = .{
        .writes = group.writes.items,
        .deletes = group.deletes.items,
        .transforms = group.transforms.items,
        .graph_writes = req.graph_writes,
        .graph_deletes = req.graph_deletes,
        .predicates = req.predicates,
        .timestamp_ns = req.timestamp_ns,
        .sync_level = req.sync_level,
    };
    if (req.reject_graph_transform_projections) {
        try db.batchTransactionCompatibleWithVisibilityCancellation(batch_req, cancellation);
    } else {
        try db.batchWithVisibilityCancellation(batch_req, cancellation);
    }
    if (shouldDrainManagedDbAfterBatch(req.sync_level)) try drainManagedDbBeforeClose(db);
}

