}

fn applyReplicatedTransactionMutationAtRaftEntry(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    table_name: []const u8,
    group_id: u64,
    req: db_mod.types.BatchRequest,
    raft_entry: db_mod.RaftAppliedEntryIdentity,
) !void {
    try applyReplicatedTransactionMutationInternal(alloc, db, table_name, group_id, req, .none, raft_entry);
}

fn applyReplicatedTransactionMutationInternal(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    table_name: []const u8,
    group_id: u64,
    req: db_mod.types.BatchRequest,
    visibility_cancellation: db_mod.types.CancellationToken,
    raft_entry: ?db_mod.RaftAppliedEntryIdentity,
) !void {
    const mutation = req.transaction orelse return error.InvalidBatchRequest;
    switch (mutation) {
        .begin => |begin| {
            const local_participant = try distributed_txn.participantIdForGroup(alloc, table_name, group_id);
            defer alloc.free(local_participant);
            if (begin.participants.len == 0) return error.InvalidBatchRequest;
            var seen = std.StringHashMapUnmanaged(void).empty;
            defer seen.deinit(alloc);
            var local_present = false;
            for (begin.participants) |participant| {
                if (distributed_txn.parseParticipantRef(participant) == null) return error.InvalidBatchRequest;
                const entry = try seen.getOrPut(alloc, participant);
                if (entry.found_existing) return error.InvalidBatchRequest;
                if (std.mem.eql(u8, participant, local_participant)) local_present = true;
            }
            if (!local_present) return error.InvalidBatchRequest;
            const coordinator = std.mem.eql(u8, begin.participants[0], local_participant);
            const local_only = [_][]const u8{local_participant};
            // Only the coordinator owns the full participant fan-out. A
            // follower tracks itself, making successful cleanup O(N) rather
            // than every participant retrying every other participant.
            const durable_participants: []const []const u8 = if (coordinator) begin.participants else &local_only;
            if (raft_entry) |entry|
                _ = try db.beginReplicatedTransactionAtRaftEntry(
                    begin.txn_id,
                    begin.begin_timestamp,
                    begin.created_at_ns,
                    durable_participants,
                    coordinator,
                    begin.retain_terminal,
                    entry,
                )
            else
                _ = try db.beginTransactionWithIdAndParticipantsCreatedAtRoleAndRetention(
                    begin.txn_id,
                    begin.begin_timestamp,
                    begin.created_at_ns,
                    durable_participants,
                    coordinator,
                    begin.retain_terminal,
                );
        },
        .prepare => |prepare| {
            const intents: db_mod.types.TransactionIntentRequest = .{
                .writes = batchWritesAsTransactionWrites(req.writes),
                .deletes = req.deletes,
                .transforms = req.transforms,
                .predicates = req.predicates,
            };
            if (raft_entry) |entry|
                try db.writeReplicatedTransactionAtRaftEntry(prepare.txn_id, intents, entry)
            else
                try db.writeTransaction(prepare.txn_id, intents);
        },
        .resolve => |resolve| {
            const local_participant = try distributed_txn.participantIdForGroup(alloc, table_name, group_id);
            defer alloc.free(local_participant);
            if (raft_entry) |entry| {
                // Retained coordinators keep their own acknowledgement pending
                // until the API session registry durably records the response.
                // Everyone else records resolution, acknowledgement, and the
                // Raft receipt in one backend batch.
                const defer_coordinator_ack = db.transactionRetainsCoordinatorAcknowledgement(resolve.txn_id) catch |err| switch (err) {
                    transactions_mod.TxnError.TxnNotFound => if (resolve.status == .aborted) false else return err,
                    else => return err,
                };
                try db.resolveReplicatedTransactionAtRaftEntry(
                    resolve.txn_id,
                    resolve.status,
                    resolve.commit_version,
                    req.sync_level,
                    visibility_cancellation,
                    entry,
                    if (defer_coordinator_ack) null else local_participant,
                );
            } else {
                try db.resolveTransactionIntentsWithSyncLevelAndCancellation(
                    resolve.txn_id,
                    resolve.status,
                    resolve.commit_version,
                    req.sync_level,
                    visibility_cancellation,
                );
                const defer_coordinator_ack = db.transactionDefersCoordinatorAcknowledgement(resolve.txn_id) catch |err| switch (err) {
                    transactions_mod.TxnError.TxnNotFound => if (resolve.status == .aborted) false else return err,
                    else => return err,
                };
                if (!defer_coordinator_ack) {
                    db.markTransactionParticipantResolved(resolve.txn_id, local_participant) catch |err| switch (err) {
                        transactions_mod.TxnError.TxnNotFound => if (resolve.status != .aborted) return err,
                        else => return err,
                    };
                }
            }
        },
        .acknowledge => |ack| (if (raft_entry) |entry|
            db.markReplicatedTransactionParticipantResolvedAtRaftEntry(ack.txn_id, ack.participant, entry)
        else
            db.markTransactionParticipantResolved(ack.txn_id, ack.participant)) catch |err| switch (err) {
            // Cleanup and acknowledgements are independently retryable Raft
            // commands. Once cleanup wins, a late acknowledgement is a safe
            // no-op and must not recreate coordinator sidecar metadata.
            transactions_mod.TxnError.TxnNotFound => {},
            else => return err,
        },
        .cleanup => |cleanup| {
            if (raft_entry) |entry|
                _ = try db.cleanupReplicatedTransactionAtRaftEntry(
                    cleanup.txn_id,
                    cleanup.cutoff_timestamp,
                    cleanup.retained_cutoff_timestamp,
                    entry,
                )
            else
                _ = try db.cleanupTransactionMetadataIfEligible(
                    cleanup.txn_id,
                    cleanup.cutoff_timestamp,
                    cleanup.retained_cutoff_timestamp,
                );
        },
    }
}

fn batchWritesAsTransactionWrites(writes: []const db_mod.types.BatchWrite) []const db_mod.types.TransactionWrite {
    comptime std.debug.assert(@sizeOf(db_mod.types.BatchWrite) == @sizeOf(db_mod.types.TransactionWrite));
    comptime std.debug.assert(@alignOf(db_mod.types.BatchWrite) == @alignOf(db_mod.types.TransactionWrite));
    return @ptrCast(writes);
}

fn parseIndexKind(value: std.json.Value) !db_mod.types.IndexKind {
    if (value != .object) return .full_text;
    const type_value = value.object.get("type") orelse return .full_text;
    if (type_value != .string) return error.InvalidCreateTableRequest;
    if (std.mem.eql(u8, type_value.string, "full_text")) return .full_text;
    if (std.mem.eql(u8, type_value.string, "graph")) return .graph;
    if (std.mem.eql(u8, type_value.string, "algebraic")) return .algebraic;
    if (std.mem.eql(u8, type_value.string, "embeddings")) {
        const sparse = if (value.object.get("sparse")) |sparse_value| switch (sparse_value) {
            .bool => sparse_value.bool,
            else => return error.InvalidCreateTableRequest,
        } else false;
        return if (sparse) .sparse_vector else .dense_vector;
    }
    return error.UnsupportedCreateTableRequest;
}

fn parseIndexConfig(alloc: std.mem.Allocator, index_name: []const u8, index_json: []const u8) !db_mod.types.IndexConfig {
    return try parseIndexConfigWithOptions(alloc, index_name, index_json, .{});
}

fn parseIndexConfigWithOptions(
    alloc: std.mem.Allocator,
    index_name: []const u8,
    index_json: []const u8,
    options: managed_embedder.InitOptions,
) !db_mod.types.IndexConfig {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, index_json, .{});
    defer parsed.deinit();
    const kind = try parseIndexKind(parsed.value);
    const config_json = try extractIndexConfigJsonWithOptions(alloc, index_name, parsed.value, options);
    errdefer alloc.free(config_json);
    return .{
        .name = try alloc.dupe(u8, index_name),
        .kind = kind,
        .config_json = config_json,
        .coverage_generation = coverage_policy_mod.incarnation(parsed.value) orelse 0,
    };
}

pub fn validateIndexConfig(alloc: std.mem.Allocator, index_name: []const u8, index_json: []const u8) !void {
    return table_index_config.validateIndexConfig(alloc, index_name, index_json);
}

pub fn validateIndexConfigWithOptions(
    alloc: std.mem.Allocator,
    index_name: []const u8,
    index_json: []const u8,
    options: managed_embedder.InitOptions,
) !void {
    return table_index_config.validateIndexConfigWithOptions(alloc, index_name, index_json, options);
}

pub const validateGraphIndexesJson = table_index_config.validateGraphIndexesJson;

fn extractIndexConfigJson(alloc: std.mem.Allocator, index_name: []const u8, value: std.json.Value) ![]u8 {
    return try extractIndexConfigJsonWithOptions(alloc, index_name, value, .{});
}

fn extractIndexConfigJsonWithOptions(
    alloc: std.mem.Allocator,
    index_name: []const u8,
    value: std.json.Value,
    options: managed_embedder.InitOptions,
) ![]u8 {
    if (value != .object) return try alloc.dupe(u8, "{}");
    const kind = try parseIndexKind(value);
    switch (kind) {
        .dense_vector, .sparse_vector => return try managed_embedder.translateEmbeddingsIndexConfigJsonWithOptions(alloc, index_name, value, options),
        else => {},
    }

    var out = std.ArrayListUnmanaged(u8).empty;
    defer out.deinit(alloc);
    try out.append(alloc, '{');
    var first = true;
    var it = value.object.iterator();
    while (it.next()) |entry| {
        if (std.mem.eql(u8, entry.key_ptr.*, "type") or
            std.mem.eql(u8, entry.key_ptr.*, "name") or
            std.mem.eql(u8, entry.key_ptr.*, "description") or
            std.mem.eql(u8, entry.key_ptr.*, "validation") or
            std.mem.eql(u8, entry.key_ptr.*, "enrichments"))
        {
            continue;
        }
        if (std.mem.eql(u8, entry.key_ptr.*, "version") and kind != .algebraic) continue;
        if (!first) try out.append(alloc, ',');
        first = false;
        try appendJsonString(alloc, &out, entry.key_ptr.*);
        try out.append(alloc, ':');
        const encoded = try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(entry.value_ptr.*, .{})});
        defer alloc.free(encoded);
        try out.appendSlice(alloc, encoded);
    }
    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

pub fn normalizeManagedEmbeddingIndexDimensionJsonWithOptions(
    alloc: std.mem.Allocator,
    index_name: []const u8,
    index_json: []const u8,
    options: managed_embedder.InitOptions,
) ![]u8 {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, index_json, .{});
    defer parsed.deinit();
    if (try managed_embedder.normalizeEmbeddingsIndexDimensionJsonWithOptions(alloc, index_name, parsed.value, options)) |normalized| {
        return normalized;
    }
    return try alloc.dupe(u8, index_json);
}

pub fn normalizeManagedEmbeddingIndexDimensionsJsonWithOptions(
    alloc: std.mem.Allocator,
    indexes_json: []const u8,
    options: managed_embedder.InitOptions,
) ![]u8 {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, indexes_json, .{});
    defer parsed.deinit();
    const object = switch (parsed.value) {
        .object => |object| object,
        else => return error.InvalidCreateTableRequest,
    };

    var out = std.ArrayListUnmanaged(u8).empty;
    defer out.deinit(alloc);
    try out.append(alloc, '{');
    var first = true;
    var it = object.iterator();
    while (it.next()) |entry| {
        if (!first) try out.append(alloc, ',');
        first = false;
        try appendJsonString(alloc, &out, entry.key_ptr.*);
        try out.append(alloc, ':');
        if (try managed_embedder.normalizeEmbeddingsIndexDimensionJsonWithOptions(alloc, entry.key_ptr.*, entry.value_ptr.*, options)) |normalized| {
            defer alloc.free(normalized);
            try out.appendSlice(alloc, normalized);
        } else {
            const encoded = try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(entry.value_ptr.*, .{})});
            defer alloc.free(encoded);
            try out.appendSlice(alloc, encoded);
        }
    }
    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

