fn replayManagedIndexForTableIfNeeded(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    replica_root_dir: []const u8,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime,
    table_name: []const u8,
    index_name: []const u8,
) !bool {
    const group_ids = try table_catalog.resolveGroupsForSpanEventually(
        alloc,
        catalog,
        table_name,
        "",
        "",
        5 * std.time.ns_per_s,
        10,
    );
    defer alloc.free(group_ids);

    var managed_visibility_changed = false;
    for (group_ids) |group_id| {
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, replica_root_dir, group_id);
        defer alloc.free(path);

        var db = try openManagedDbForTableGroupWithRuntime(alloc, path, catalog, table_name, group_id, backend_runtime);
        defer db.close();
        if (!try db.core.indexRequiresEnrichmentReplay(index_name)) continue;
        managed_visibility_changed = true;

        _ = try seedManagedIndexReplayFromStoredDocsIfNeeded(alloc, &db, index_name);

        if (try db.denseArtifactRebuildMaintenanceNeeded(alloc)) {
            _ = try db.runDenseArtifactRebuildMaintenanceWithProgress(alloc, null, null);
            try db.runUntilIdle();
        }
    }
    return managed_visibility_changed;
}

const ManagedIndexCreateCatchUp = union(enum) {
    complete,
    retry,
    delegated,
    asynchronous: u64,
};

fn catchUpManagedIndexCreate(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    index_name: []const u8,
    delegate_background_repair: bool,
) !ManagedIndexCreateCatchUp {
    // Managed full-text admission persists a generation-repair intent instead
    // of rebuilding the existing corpus inline with catalog mutation. A data
    // runtime has one dedicated, capacity-fenced repair owner; structural
    // reconciliation only admits its durable intent and then releases the
    // group operation. Direct/embedded sources without that owner retain the
    // synchronous fallback through the same restartable state machine.
    var generation_repair = try db.repairArtifactIssuesWithRequestOptions(alloc, .{
        .target = .index,
        .index_name = index_name,
        .limit = 1,
    }, .{
        .defer_durable_index_repair_execution = delegate_background_repair,
    });
    defer generation_repair.deinit(alloc);
    if (generation_repair.debt_remaining) {
        return if (delegate_background_repair) .delegated else .retry;
    }

    const requires_enrichment_replay = try db.core.indexRequiresEnrichmentReplay(index_name);
    if (requires_enrichment_replay) {
        // A completed managed dense generation already proves source outcome
        // coverage, durable replay convergence, physical artifact cardinality,
        // and a quiet HBC publication boundary. Re-forcing every stored source
        // at this point does not add recovery authority; it replays historical
        // delete/upsert windows over the final deterministic chunk identities
        // and can regress an otherwise ready generation.
        if (try db.completedManagedDenseGenerationIsServiceable(alloc, index_name)) {
            return .complete;
        }
        if (db.enrichment_runtime != null) {
            const appended = try db.reprocessGeneratedEnrichmentFromStoredDocsWithProgress(
                alloc,
                managedIndexEmbeddingArtifactName(db, index_name),
            );
            // No durable producer record means there is no future output edge
            // to publish. Treat empty and already-covered tables as complete
            // instead of installing a handoff that no worker can settle.
            if (delegate_background_repair) {
                if (appended.generated_ref_count == 0) return .complete;
                std.debug.assert(appended.target_sequence != 0);
                return .{ .asynchronous = appended.target_sequence };
            }
        } else {
            _ = try seedManagedIndexReplayFromStoredDocsIfNeeded(alloc, db, index_name);
        }
        // A provisioned owner has a resident asynchronous enrichment runtime.
        // Once its durable replay records are posted, structural reconciliation
        // must release group admission instead of synchronously draining a
        // provider that may be rate limited or unavailable. Direct/embedded
        // sources keep the synchronous readiness barrier below.
    }

    try db.runUntilIdle();

    if (try db.denseArtifactRebuildMaintenanceNeeded(alloc)) {
        _ = try db.runDenseArtifactRebuildMaintenanceWithProgress(alloc, null, null);
        try db.runUntilIdle();
    }
    if (requires_enrichment_replay) {
        const debt_remaining = try repairManagedEmbeddingArtifactsForIndex(alloc, db, index_name);
        if (debt_remaining) try markManagedIndexRepairRequired(alloc, db, index_name);
    }
    try drainManagedIndexReplayUntilConverged(alloc, db, index_name);
    try db.core.index_manager.syncAll(true);
    return .complete;
}

test "managed structural catch-up delegates durable generation repair without rebuilding inline" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(
        alloc,
        ".zig-cache/tmp/{s}/managed-structural-repair-delegation",
        .{tmp.sub_path},
    );
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{
        .open_mode = .writer_no_replay,
        .start_index_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"alpha\"}" }},
        .sync_level = .write,
    });
    _ = (try db.admitManagedFullTextIndex(.{
        .name = "full_text_index_v1",
        .kind = .full_text,
        .config_json = "{}",
    })) orelse return error.TestUnexpectedResult;

    try std.testing.expectEqual(
        ManagedIndexCreateCatchUp.delegated,
        try catchUpManagedIndexCreate(alloc, &db, "full_text_index_v1", true),
    );

    const summary = try db.indexRepairIntentSummary(alloc);
    try std.testing.expectEqual(@as(usize, 1), summary.runnable);
    const stats = try db.stats(alloc);
    defer db_mod.types.freeDBStats(alloc, stats);
    const index = for (stats.indexes) |item| {
        if (std.mem.eql(u8, item.name, "full_text_index_v1")) break item;
    } else return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 0), index.doc_count);
}

test "managed structural catch-up leaves pending enrichment with the asynchronous owner" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(
        alloc,
        ".zig-cache/tmp/{s}/managed-structural-enrichment-delegation",
        .{tmp.sub_path},
    );
    defer alloc.free(path);

    const FakeEmbeddingProvider = struct {
        var allow_requests: std.atomic.Value(bool) = .init(false);
        var rate_limited_count: std.atomic.Value(u32) = .init(0);

        fn executor() http_common.RequestExecutor {
            return .{
                .ptr = undefined,
                .vtable = &.{ .execute = execute },
            };
        }

        fn execute(_: *anyopaque, arena: std.mem.Allocator, req: http_common.HttpRequest) !http_common.HttpResponse {
            try std.testing.expectEqual(http_common.Method.POST, req.method);
            if (!allow_requests.load(.acquire)) {
                _ = rate_limited_count.fetchAdd(1, .monotonic);
                return .{
                    .status = 429,
                    .content_type = try arena.dupe(u8, "application/json"),
                    .body = try arena.dupe(u8, "{\"error\":{\"message\":\"rate limited\",\"type\":\"rate_limit_exceeded\"}}"),
                };
            }
            return .{
                .status = 200,
                .content_type = try arena.dupe(u8, "application/json"),
                .body = try arena.dupe(u8, "{\"object\":\"list\",\"data\":[{\"object\":\"embedding\",\"index\":0,\"embedding\":[1,0,0]}],\"model\":\"test-embed\",\"usage\":{\"prompt_tokens\":1,\"total_tokens\":1}}"),
            };
        }
    };

    var listener = std_http_listener.StdHttpListener.init(alloc, .{}, FakeEmbeddingProvider.executor());
    defer listener.deinit();
    try listener.start();
    const base_uri = try listener.baseUri(alloc);
    defer alloc.free(base_uri);
    const indexes_json = try std.fmt.allocPrint(alloc,
        \\{{"semantic_idx":{{"type":"embeddings","field":"body","dimension":3,"embedder":{{"provider":"openai","model":"test-embed","url":"{s}"}}}}}}
    , .{base_uri});
    defer alloc.free(indexes_json);

    FakeEmbeddingProvider.allow_requests.store(false, .release);
    FakeEmbeddingProvider.rate_limited_count.store(0, .monotonic);
    var db = try openManagedDbWithIndexesJsonAndCacheMode(
        alloc,
        path,
        indexes_json,
        null,
        null,
        0,
        null,
        .default,
    );
    defer {
        FakeEmbeddingProvider.allow_requests.store(true, .release);
        db.close();
    }
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"alpha\"}" }},
        .sync_level = .write,
    });

    var attempts: usize = 0;
    while (attempts < 100 and FakeEmbeddingProvider.rate_limited_count.load(.monotonic) == 0) : (attempts += 1) {
        sleepNs(10 * std.time.ns_per_ms);
    }
    try std.testing.expect(FakeEmbeddingProvider.rate_limited_count.load(.monotonic) > 0);

    const target_sequence = switch (try catchUpManagedIndexCreate(alloc, &db, "semantic_idx", true)) {
        .asynchronous => |target_sequence| target_sequence,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(target_sequence > 0);

    // An uncached source still has a valid resident asynchronous owner, but it
    // has no cached status authority to bridge. Its direct status reads are
    // serialized with structural work and observe the resident DB instead.
    var source = ProvisionedTableWriteSource.init(path, table_catalog.emptyCatalogSource());
    defer source.deinit();
    var observations = std.ArrayListUnmanaged(ProvisionedTableWriteSource.StructuralRuntimeObservation).empty;
    defer observations.deinit(alloc);
    try appendStructuralRuntimeStatusObservation(
        &source,
        alloc,
        "docs",
        7001,
        &db,
        db.core.index_manager.lsm_root_generation,
        .artifact_rebuild,
        &observations,
    );
    try std.testing.expectEqual(@as(usize, 0), observations.items.len);
    try std.testing.expect(markLatestStructuralIndexPublicationPending(
        &observations,
        "semantic_idx",
        target_sequence,
        true,
    ) == null);

    const enrichment = db.enrichment_runtime orelse return error.MissingStartupEnrichmentRuntime;
    const stats = enrichment.stats();
    try std.testing.expect(stats.applied_sequence < stats.target_sequence);
}

