    _: std.mem.Allocator,
    db: *db_mod.DB,
    indexes_json: []const u8,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime,
    antfly_provider: ?managed_embedder.AntflyProvider,
    inference_api_url: ?[]const u8,
    secret_store: ?*common_secrets.FileStore,
    remote_content: ?*const scraping.RemoteContentConfig,
) !void {
    var enrichments = try createManagedDbEnrichments(
        db.runtime_alloc,
        indexes_json,
        backend_runtime,
        antfly_provider,
        inference_api_url,
        secret_store,
        remote_content,
    );
    errdefer enrichments.deinit(db.runtime_alloc);
    // An empty replacement is meaningful: dropping the last managed producer
    // must retire the old provider instead of leaving an unused runtime alive.
    try db.reconfigureEnrichmentRuntime(enrichments.takeConfig());
}

pub const StartupCatchUpMetadata = struct {
    pub const MetadataSource = enum { supplied, local_persisted };
    pub const IdentityValidation = enum {
        exact,
        reassign_same_table,
    };

    indexes_json: ?[]const u8 = null,
    schema_json: ?[]const u8 = null,
    identity_namespace: ?doc_identity.Namespace = null,
    identity_validation: IdentityValidation = .exact,
    target_index_name: ?[]const u8 = null,
    metadata_source: MetadataSource = .supplied,
    /// Internal owner-side executor mode. Normal startup inspection only
    /// discovers durable repair debt; the bounded repair worker sets this to
    /// advance at most one admitted intent.
    advance_index_repairs: bool = false,
    index_repair_options: db_mod.types.ArtifactRepairRunOptions = .{},
};

fn existingPrimaryBackend() @TypeOf((db_mod.OpenOptions{}).primary_backend) {
    return switch ((db_mod.OpenOptions{}).primary_backend) {
        .lsm => |default_options| blk: {
            var options = default_options;
            options.backend.create_if_missing = false;
            break :blk .{ .lsm = options };
        },
        else => unreachable,
    };
}

fn openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
    alloc: std.mem.Allocator,
    path: []const u8,
    indexes_json: []const u8,
    lsm_cache: ?*lsm_backend.Cache,
    hbc_cache: ?*hbc_mod.Cache,
    lsm_root_generation: u64,
    resource_manager: ?*resource_manager_mod.ResourceManager,
    mode: ManagedDbOpenMode,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime,
    antfly_provider: ?managed_embedder.AntflyProvider,
    secret_store: ?*common_secrets.FileStore,
    remote_content: ?*const scraping.RemoteContentConfig,
    identity_namespace: ?doc_identity.Namespace,
    options: ManagedDbOpenOptions,
) !db_mod.DB {
    const reconcile_mode: ManagedDbOpenMode = if (options.reconcile_for_replicated_apply) .restore_repair else mode;
    var reconcile_options = options;
    if (options.reconcile_for_replicated_apply) {
        reconcile_options.ha_write_gate = null;
        reconcile_options.ha_async_effect_mirror = null;
        reconcile_options.ha_async_batch_mirror = null;
        reconcile_options.ha_async_metadata_mirror = null;
    }
    var enrichments = try createManagedDbEnrichments(alloc, indexes_json, backend_runtime, antfly_provider, options.inference_api_url, secret_store, remote_content);
    errdefer enrichments.deinit(alloc);

    const openDb = struct {
        fn run(
            allocator: std.mem.Allocator,
            db_path: []const u8,
            enrichment_cfg: ?db_mod.enrichment_runtime.Config,
            cache: ?*lsm_backend.Cache,
            vector_cache: ?*hbc_mod.Cache,
            root_generation: u64,
            manager: ?*resource_manager_mod.ResourceManager,
            open_mode: ManagedDbOpenMode,
            runtime: ?*db_mod.background_runtime.BackendRuntime,
            store: ?*common_secrets.FileStore,
            remote: ?*const scraping.RemoteContentConfig,
            namespace: ?doc_identity.Namespace,
            open_options: ManagedDbOpenOptions,
        ) !db_mod.DB {
            const schema_before_index_load: ?storage_schema.TableSchema = if (open_mode == .query_readonly or open_mode == .status_only) null else if (open_options.schema_json_before_index_load) |schema_json| blk: {
                if (schema_json.len == 0) break :blk null;
                var parsed_schema = try tables_api.parseValidatedTableSchema(allocator, schema_json);
                defer parsed_schema.deinit(allocator);
                break :blk try tables_api.deriveRuntimeTableSchema(allocator, parsed_schema);
            } else null;
            defer if (schema_before_index_load) |schema| storage_schema.freeSchema(allocator, schema);

            const base: db_mod.OpenOptions = .{
                .lsm_cache = cache,
                .hbc_cache = vector_cache,
                .lsm_root_generation = root_generation,
                .resource_manager = manager,
                .backend_runtime = runtime,
                .secret_store = store,
                .remote_content = remote,
                .identity_namespace = namespace,
                .prefer_existing_identity_namespace = namespace != null,
                .enrichment = enrichment_cfg,
                .ha_write_gate = open_options.ha_write_gate,
                .ha_async_effect_mirror = open_options.ha_async_effect_mirror,
                .ha_async_batch_mirror = open_options.ha_async_batch_mirror,
                .ha_async_metadata_mirror = open_options.ha_async_metadata_mirror,
                .transaction_recovery = open_options.transaction_recovery,
                .schema_before_index_load = schema_before_index_load,
            };
            return switch (open_mode) {
                .default => if (enrichment_cfg != null)
                    try db_mod.DB.open(allocator, db_path, base)
                else
                    try db_mod.DB.open(allocator, db_path, .{
                        .lsm_cache = cache,
                        .hbc_cache = vector_cache,
                        .lsm_root_generation = root_generation,
                        .resource_manager = manager,
                        .backend_runtime = runtime,
                        .secret_store = store,
                        .remote_content = remote,
                        .identity_namespace = namespace,
                        .prefer_existing_identity_namespace = namespace != null,
                        .ha_write_gate = open_options.ha_write_gate,
                        .ha_async_effect_mirror = open_options.ha_async_effect_mirror,
                        .ha_async_batch_mirror = open_options.ha_async_batch_mirror,
                        .ha_async_metadata_mirror = open_options.ha_async_metadata_mirror,
                        .transaction_recovery = open_options.transaction_recovery,
                        .schema_before_index_load = schema_before_index_load,
                    }),
                .default_async, .writer_no_replay => if (enrichment_cfg != null)
                    try db_mod.DB.open(allocator, db_path, .{
                        .lsm_cache = cache,
                        .hbc_cache = vector_cache,
                        .lsm_root_generation = root_generation,
                        .resource_manager = manager,
                        .backend_runtime = runtime,
                        .secret_store = store,
                        .remote_content = remote,
                        .identity_namespace = namespace,
                        .prefer_existing_identity_namespace = namespace != null,
                        .enrichment = enrichment_cfg,
                        .ha_write_gate = open_options.ha_write_gate,
                        .ha_async_effect_mirror = open_options.ha_async_effect_mirror,
                        .ha_async_batch_mirror = open_options.ha_async_batch_mirror,
                        .ha_async_metadata_mirror = open_options.ha_async_metadata_mirror,
                        .transaction_recovery = open_options.transaction_recovery,
                        .schema_before_index_load = schema_before_index_load,
                        .open_mode = .writer_no_replay,
                        // The managed write cache opens DBs synchronously while
                        // table/index metadata can still be settling. Keep
                        // index catalog opens serial on this no-replay path
                        // until the parallel index opener is allocator-safe.
                        .index_open_parallelism = 1,
                    })
                else
                    try db_mod.DB.open(allocator, db_path, .{
                        .lsm_cache = cache,
                        .hbc_cache = vector_cache,
                        .lsm_root_generation = root_generation,
                        .resource_manager = manager,
                        .backend_runtime = runtime,
                        .secret_store = store,
                        .remote_content = remote,
                        .identity_namespace = namespace,
                        .prefer_existing_identity_namespace = namespace != null,
                        .ha_write_gate = open_options.ha_write_gate,
                        .ha_async_effect_mirror = open_options.ha_async_effect_mirror,
                        .ha_async_batch_mirror = open_options.ha_async_batch_mirror,
                        .ha_async_metadata_mirror = open_options.ha_async_metadata_mirror,
                        .transaction_recovery = open_options.transaction_recovery,
                        .schema_before_index_load = schema_before_index_load,
                        .open_mode = .writer_no_replay,
                        .index_open_parallelism = 1,
                    }),
                .startup_catch_up => try db_mod.DB.open(allocator, db_path, .{
                    .lsm_cache = cache,
                    .hbc_cache = vector_cache,
                    .lsm_root_generation = root_generation,
                    .resource_manager = manager,
                    .backend_runtime = runtime,
                    .secret_store = store,
                    .remote_content = remote,
                    .identity_namespace = namespace,
                    .prefer_existing_identity_namespace = namespace != null,
                    .ha_write_gate = open_options.ha_write_gate,
                    .schema_before_index_load = schema_before_index_load,
                    .open_mode = .writer_no_replay,
                    .start_index_workers = false,
                    .enrichment = if (enrichment_cfg) |configured| blk: {
                        var bounded = configured;
                        // Loaded-state startup must not wait through the
                        // normal external-provider inline retry budget. One
                        // attempt records durable retry state; the startup
                        // scheduler owns later attempts.
                        bounded.inline_retry_max_attempts = 1;
                        // Startup is a short-lived foreground owner. If a
                        // retry budget was nearly exhausted before shutdown,
                        // do not convert one startup probe into terminal
                        // coverage before the long-lived worker can resume it.
                        // The persisted attempt count is retained, so the
                        // normal worker still enforces its bounded budget.
                        bounded.worker_retry_max_attempts = std.math.maxInt(u32);
                        break :blk bounded;
                    } else null,
                    // Startup catch-up drives enrichment synchronously below.
                    // Construct the runtime with metadata-owned providers, but
                    // do not leave workers attached to this short-lived owner.
                    .start_optional_runtimes = enrichment_cfg != null,
                    .start_optional_runtime_workers = false,
                    .ttl_cleanup = .{ .enabled = false },
                    .transaction_recovery = .{ .enabled = false },
                    .text_merge = .{ .enabled = false },
                    .staged_generation = open_options.staged_generation,
                }),
                .restore_repair => if (enrichment_cfg != null)
                    try db_mod.DB.open(allocator, db_path, .{
                        .lsm_cache = cache,
                        .hbc_cache = vector_cache,
                        .lsm_root_generation = root_generation,
                        .resource_manager = manager,
                        .backend_runtime = runtime,
                        .secret_store = store,
                        .remote_content = remote,
                        .identity_namespace = namespace,
                        .prefer_existing_identity_namespace = namespace != null,
                        .enrichment = enrichment_cfg,
                        .ha_write_gate = open_options.ha_write_gate,
                        .schema_before_index_load = schema_before_index_load,
                        .open_mode = .writer_no_replay,
                        .start_index_workers = false,
                        .start_optional_runtime_workers = false,
                        .ttl_cleanup = .{ .enabled = false },
                        .transaction_recovery = .{ .enabled = false },
                        .text_merge = .{ .enabled = false },
                        .staged_generation = open_options.staged_generation,
                    })
                else
                    try db_mod.DB.open(allocator, db_path, .{
                        .lsm_cache = cache,
                        .hbc_cache = vector_cache,
                        .lsm_root_generation = root_generation,
                        .resource_manager = manager,
                        .backend_runtime = runtime,
                        .secret_store = store,
                        .remote_content = remote,
                        .identity_namespace = namespace,
                        .prefer_existing_identity_namespace = namespace != null,
                        .ha_write_gate = open_options.ha_write_gate,
                        .schema_before_index_load = schema_before_index_load,
                        .open_mode = .writer_no_replay,
                        .start_index_workers = false,
                        .start_optional_runtimes = false,
                        .ttl_cleanup = .{ .enabled = false },
                        .transaction_recovery = .{ .enabled = false },
                        .text_merge = .{ .enabled = false },
                        .staged_generation = open_options.staged_generation,
                    }),
                .query_readonly => if (enrichment_cfg != null)
                    try db_mod.DB.open(allocator, db_path, .{
                        .lsm_cache = cache,
                        .hbc_cache = vector_cache,
                        .lsm_root_generation = root_generation,
                        .resource_manager = manager,
                        .backend_runtime = runtime,
                        .secret_store = store,
                        .remote_content = remote,
                        .identity_namespace = namespace,
                        .prefer_existing_identity_namespace = namespace != null,
                        .enrichment = enrichment_cfg,
                        .ha_write_gate = open_options.ha_write_gate,
                        .open_mode = .query_readonly,
                        .start_index_workers = false,
                        .ttl_cleanup = .{ .enabled = false },
                        .transaction_recovery = .{ .enabled = false },
                        .text_merge = .{ .enabled = false },
                    })
                else
                    try db_mod.DB.open(allocator, db_path, .{
                        .lsm_cache = cache,
                        .hbc_cache = vector_cache,
                        .lsm_root_generation = root_generation,
                        .resource_manager = manager,
                        .backend_runtime = runtime,
                        .secret_store = store,
                        .remote_content = remote,
                        .identity_namespace = namespace,
                        .prefer_existing_identity_namespace = namespace != null,
                        .ha_write_gate = open_options.ha_write_gate,
                        .open_mode = .query_readonly,
                        .start_index_workers = false,
                        .ttl_cleanup = .{ .enabled = false },
                        .transaction_recovery = .{ .enabled = false },
                        .text_merge = .{ .enabled = false },
                    }),
                .status_only => if (enrichment_cfg != null)
                    try db_mod.DB.open(allocator, db_path, .{
                        .lsm_cache = cache,
                        .hbc_cache = vector_cache,
                        .lsm_root_generation = root_generation,
                        .resource_manager = manager,
                        .backend_runtime = runtime,
                        .secret_store = store,
                        .remote_content = remote,
                        .identity_namespace = namespace,
                        .prefer_existing_identity_namespace = namespace != null,
                        .enrichment = enrichment_cfg,
                        .ha_write_gate = open_options.ha_write_gate,
                        .open_mode = .status_only,
                        .start_index_workers = false,
                        .ttl_cleanup = .{ .enabled = false },
                        .transaction_recovery = .{ .enabled = false },
                        .text_merge = .{ .enabled = false },
                    })
                else
                    try db_mod.DB.open(allocator, db_path, .{
                        .lsm_cache = cache,
                        .hbc_cache = vector_cache,
                        .lsm_root_generation = root_generation,
                        .resource_manager = manager,
                        .backend_runtime = runtime,
                        .secret_store = store,
                        .remote_content = remote,
                        .identity_namespace = namespace,
                        .prefer_existing_identity_namespace = namespace != null,
                        .ha_write_gate = open_options.ha_write_gate,
                        .open_mode = .status_only,
                        .start_index_workers = false,
                        .ttl_cleanup = .{ .enabled = false },
                        .transaction_recovery = .{ .enabled = false },
                        .text_merge = .{ .enabled = false },
                    }),
            };
        }
    }.run;

    var db = blk: {
        const enrichment_cfg = if (enrichments.enabled()) enrichments.takeConfig() else null;
        const opened = try openDb(alloc, path, enrichment_cfg, lsm_cache, hbc_cache, lsm_root_generation, resource_manager, reconcile_mode, backend_runtime, secret_store, remote_content, identity_namespace, reconcile_options);
        break :blk opened;
    };
    var db_open = true;
    errdefer if (db_open) db.close();

    try validateProvisionedDbIdentityNamespaceWithPolicy(
        identity_namespace,
        options.identity_validation,
        &db,
    );
    if (mode == .status_only or mode == .query_readonly) return db;

    if ((mode == .startup_catch_up or mode == .restore_repair) and db.core.index_manager.hasLoadFailures()) {
        // Startup maintenance must preserve the failed generation so status
        // publication and repair discovery can report the original failure.
        // Catalog reconciliation is a structural-owner responsibility; doing
        // it here could delete a quarantined index and immediately collide
        // with the durable same-name cleanup fence.
        return db;
    }

    const summary = if (options.reconcile_target_index_name) |target_index_name|
        try metadata_table_provisioner.reconcileDbIndexTarget(alloc, &db, indexes_json, target_index_name)
    else
        try metadata_table_provisioner.reconcileDbIndexesWithOptions(alloc, &db, indexes_json, .{
            .drain_resolver_backfill = options.drain_resolver_backfill,
            .source_table = options.source_table,
            .destination_authorizer = options.destination_authorizer,
        });
    if (summary.indexManagerCatalogChanged() or options.reconcile_for_replicated_apply) {
        // First-open provisioning can mutate the live index manager. Reopen so
        // request work runs against the stabilized post-reconcile state.
        db.close();
        db_open = false;
        enrichments = try createManagedDbEnrichments(
            alloc,
            indexes_json,
            backend_runtime,
            antfly_provider,
            options.inference_api_url,
            secret_store,
            remote_content,
        );
        db = blk: {
            const enrichment_cfg = if (enrichments.enabled()) enrichments.takeConfig() else null;
            const opened = try openDb(alloc, path, enrichment_cfg, lsm_cache, hbc_cache, lsm_root_generation, resource_manager, mode, backend_runtime, secret_store, remote_content, identity_namespace, options);
            break :blk opened;
        };
        db_open = true;
        try validateProvisionedDbIdentityNamespaceWithPolicy(
            identity_namespace,
            options.identity_validation,
            &db,
        );
    }

    // Metadata-driven index reconciliation happens during open/reopen rather
    // than through DB.addIndex(), so managed enrichment replay must be re-armed
    // here for pre-existing documents after an index is added.
    if ((mode == .default or mode == .default_async) and summary.indexes_added > 0) {
        if (db.enrichment_runtime != null) {
            _ = try db.replayGeneratedEnrichmentsFromStoredDocs(alloc);
        }
    }
    return db;
}

fn indexesJsonNeedsAssetProducer(alloc: std.mem.Allocator, indexes_json: []const u8) !bool {
    if (indexes_json.len == 0) return false;
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, indexes_json, .{});
    defer parsed.deinit();
    return try jsonValueNeedsAssetProducer(alloc, parsed.value);
}

fn indexesJsonHasGeneratedEnrichment(alloc: std.mem.Allocator, indexes_json: []const u8) !bool {
    if (indexes_json.len == 0) return false;
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, indexes_json, .{});
    defer parsed.deinit();
    return try jsonValueHasGeneratedEnrichment(alloc, parsed.value);
}

fn jsonValueHasGeneratedEnrichment(alloc: std.mem.Allocator, value: std.json.Value) anyerror!bool {
    switch (value) {
        .object => |object| {
            if (object.get("kind")) |kind| {
                if (kind == .string and (std.mem.eql(u8, kind.string, "asset") or std.mem.eql(u8, kind.string, "chunk"))) return true;
            }
            if (object.get("generator") != null or object.get("chunker") != null) return true;
            var it = object.iterator();
            while (it.next()) |entry| {
                if (try jsonValueHasGeneratedEnrichment(alloc, entry.value_ptr.*)) return true;
            }
            return false;
        },
        .array => |array| {
            for (array.items) |item| {
                if (try jsonValueHasGeneratedEnrichment(alloc, item)) return true;
            }
            return false;
        },
        .string => |raw| {
            return try jsonStringHasGeneratedEnrichment(alloc, raw);
        },
        else => return false,
    }
}

fn jsonStringHasGeneratedEnrichment(alloc: std.mem.Allocator, raw: []const u8) anyerror!bool {
    const trimmed = std.mem.trim(u8, raw, &std.ascii.whitespace);
    if (!jsonStringLooksStructured(trimmed)) return false;
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, trimmed, .{}) catch return false;
    defer parsed.deinit();
    return try jsonValueHasGeneratedEnrichment(alloc, parsed.value);
}

fn jsonValueNeedsAssetProducer(alloc: std.mem.Allocator, value: std.json.Value) anyerror!bool {
    switch (value) {
        .object => |object| {
            if (try objectIsModelBackedAssetEnrichment(alloc, object)) return true;
            var it = object.iterator();
            while (it.next()) |entry| {
                if (try jsonValueNeedsAssetProducer(alloc, entry.value_ptr.*)) return true;
            }
            return false;
        },
        .array => |array| {
            for (array.items) |item| {
                if (try jsonValueNeedsAssetProducer(alloc, item)) return true;
            }
            return false;
        },
        .string => |raw| {
            return try jsonStringNeedsAssetProducer(alloc, raw);
        },
        else => return false,
    }
}

fn jsonStringNeedsAssetProducer(alloc: std.mem.Allocator, raw: []const u8) anyerror!bool {
    const trimmed = std.mem.trim(u8, raw, &std.ascii.whitespace);
    if (!jsonStringLooksStructured(trimmed)) return false;
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, trimmed, .{}) catch return false;
    defer parsed.deinit();
    return try jsonValueNeedsAssetProducer(alloc, parsed.value);
}

fn jsonStringLooksStructured(trimmed: []const u8) bool {
    return trimmed.len >= 2 and
        ((trimmed[0] == '{' and trimmed[trimmed.len - 1] == '}') or
            (trimmed[0] == '[' and trimmed[trimmed.len - 1] == ']'));
}

fn objectIsModelBackedAssetEnrichment(alloc: std.mem.Allocator, object: std.json.ObjectMap) !bool {
    const kind = object.get("kind") orelse return false;
    if (kind != .string or !std.mem.eql(u8, kind.string, "asset")) return false;
    const producer_value = object.get("producer_json") orelse return false;
    const producer_json = switch (producer_value) {
        .string => |raw| raw,
        .object, .array => try std.json.Stringify.valueAlloc(alloc, producer_value, .{}),
        else => return false,
    };
    const owns_producer_json = producer_value != .string;
    defer if (owns_producer_json) alloc.free(@constCast(producer_json));
    var producer_cfg = asset_producer_mod.parseProducerConfig(alloc, producer_json) catch return false;
    defer producer_cfg.deinit(alloc);
    if (producer_cfg.type == .document_extraction) {
        var extraction_cfg = document_extraction_mod.parseConfig(alloc, producer_cfg.config_json) catch return false;
        defer extraction_cfg.deinit(alloc);
        return extraction_cfg.ocr_enabled or
            extraction_cfg.ocr_pdf_fallback_enabled or
            extraction_cfg.transcription_enabled;
    }
    return producer_cfg.type != .copy;
}

test "provisioning detects model backed graph shorthand assets inside config_json strings" {
    const alloc = std.testing.allocator;
    try std.testing.expect(try indexesJsonNeedsAssetProducer(alloc,
        \\[{
        \\  "name":"relations_graph",
        \\  "kind":"graph",
        \\  "config_json":"{\"source\":{\"kind\":\"artifact\",\"artifact\":\"relations_v1\"},\"artifact\":{\"name\":\"relations_v1\",\"kind\":\"asset\",\"source\":{\"type\":\"field\",\"value\":\"body\"},\"producer_json\":{\"type\":\"extractor\",\"config\":{\"provider\":\"antfly\"}}}}"
        \\}]
    ));
}

test "provisioning does not require asset producer for copy graph shorthand assets inside config_json strings" {
    const alloc = std.testing.allocator;
    try std.testing.expect(!(try indexesJsonNeedsAssetProducer(alloc,
        \\[{
        \\  "name":"relations_graph",
        \\  "kind":"graph",
        \\  "config_json":"{\"source\":{\"kind\":\"artifact\",\"artifact\":\"relations_v1\"},\"artifact\":{\"name\":\"relations_v1\",\"kind\":\"asset\",\"source\":{\"type\":\"field\",\"value\":\"relations\"}}}"
        \\}]
    )));
    try std.testing.expect(try indexesJsonHasGeneratedEnrichment(alloc,
        \\[{
        \\  "name":"relations_graph",
        \\  "kind":"graph",
        \\  "config_json":"{\"source\":{\"kind\":\"artifact\",\"artifact\":\"relations_v1\"},\"artifact\":{\"name\":\"relations_v1\",\"kind\":\"asset\",\"source\":{\"type\":\"field\",\"value\":\"relations\"}}}"
        \\}]
    ));
}

test "provisioning detects document extraction OCR as model backed" {
    const alloc = std.testing.allocator;
    try std.testing.expect(try indexesJsonNeedsAssetProducer(alloc,
        \\[{"enrichments":[{"name":"units","kind":"asset","field":"url","producer_json":"{\"type\":\"document_extraction\",\"config\":{\"ocr\":{\"enabled\":true,\"config\":{\"provider\":\"antfly\"}}}}"}]}]
    ));
    // PDF OCR fallback is enabled by default, so an otherwise-empty document
    // extraction config still needs the model-backed asset producer.
    try std.testing.expect(try indexesJsonNeedsAssetProducer(alloc,
        \\[{"enrichments":[{"name":"units","kind":"asset","field":"url","producer_json":"{\"type\":\"document_extraction\",\"config\":{}}"}]}]
    ));
    try std.testing.expect(!(try indexesJsonNeedsAssetProducer(alloc,
        \\[{"enrichments":[{"name":"units","kind":"asset","field":"url","producer_json":"{\"type\":\"document_extraction\",\"config\":{\"ocr_fallback\":false}}"}]}]
    )));
}

test "provisioning detects generated embedding chunkers inside index metadata" {
    const alloc = std.testing.allocator;
    try std.testing.expect(try indexesJsonHasGeneratedEnrichment(alloc,
        \\{"semantic_chunked_idx":{"type":"embeddings","field":"body","dimension":3,"chunker":{"provider":"antfly","model":"fixed-bert-tokenizer","store_chunks":false,"full_text_index":{},"text":{"target_tokens":4,"overlap_tokens":1,"separator":" "}}}}
    ));
    try std.testing.expect(try indexesJsonHasGeneratedEnrichment(alloc,
        \\[{
        \\  "name":"semantic_chunked_idx",
        \\  "type":"embeddings",
        \\  "config_json":"{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"chunker\":{\"provider\":\"antfly\",\"model\":\"fixed-bert-tokenizer\",\"store_chunks\":false}}}"
        \\}]
    ));
}

test "bound table write source locally deletes artifact enrichment" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/bound-table-write-source-delete-artifact-enrichment", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();

    _ = try db.upsertEnrichment(.{
        .name = "body_chunks_v1",
        .kind = .chunk,
        .field = "body",
        .chunk_size = 128,
    });

    var bound = BoundTableWriteSource.init("docs", &db);
    _ = try bound.source().deleteArtifactEnrichment(alloc, "docs", "body_chunks_v1");

    const remaining = try db.listEnrichments(alloc);
    defer db_mod.types.freeEnrichmentConfigs(alloc, remaining);
    for (remaining) |cfg| {
        try std.testing.expect(!std.mem.eql(u8, cfg.name, "body_chunks_v1"));
    }
}

fn drainManagedDbBeforeClose(db: *db_mod.DB) !void {
    // Provisioned writes open a managed DB per request, so queued enrichment
    // must drain before the DB is closed or semantic indexes can stay empty.
    try db.runUntilIdle();
    try db.core.index_manager.syncAll(true);
}

fn publishRuntimeStatusSnapshot(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    db: *db_mod.DB,
) !void {
    try publishRuntimeStatusSnapshotWithStartupPhaseMode(
        source,
        alloc,
        table_name,
        group_id,
        .idle,
        .best_effort,
        db,
    );
}

fn publishRuntimeStatusSnapshotConsistent(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    db: *db_mod.DB,
) !void {
    try publishRuntimeStatusSnapshotWithStartupPhaseMode(
        source,
        alloc,
        table_name,
        group_id,
        .idle,
        .consistent,
        db,
    );
}

fn publishPostCommitIndexRuntimeStatusBestEffort(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    index_name: []const u8,
    group_id: u64,
    db: *db_mod.DB,
    operation: []const u8,
) void {
    // Index reconciliation above this boundary has already durably decided
    // the catalog mutation. Runtime status is an observational cache: repair,
    // restore, or another refresh may legitimately invalidate its publication
    // token while the snapshot is being collected. Never turn that expected
    // race (or another post-commit diagnostic failure) into a false DDL error.
    publishRuntimeStatusSnapshotConsistent(source, alloc, table_name, group_id, db) catch |err| switch (err) {
        error.RuntimeStatusPublicationFenced => std.log.debug(
            "post-index-{s} runtime status publication deferred table={s} index={s} group_id={d} err={s}",
            .{ operation, table_name, index_name, group_id, @errorName(err) },
        ),
        else => std.log.warn(
            "post-index-{s} runtime status publication failed after commit table={s} index={s} group_id={d} err={s}",
            .{ operation, table_name, index_name, group_id, @errorName(err) },
        ),
    };
}

fn captureStructuralRuntimeStatusObservation(
    snapshot_cache: *runtime_status.TableRuntimeSnapshotCache,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    db: *db_mod.DB,
    lsm_root_generation: u64,
    phase: db_mod.types.StartupCatchUpPhase,
) !runtime_status.LocalTableRuntimeStatus {
    var disk_bytes: u64 = 0;
    var created_at_millis: u64 = 0;
    var cached_startup: db_mod.types.StartupCatchUpStats = .{};
    if (try snapshot_cache.snapshotGroupStatus(alloc, table_name, group_id)) |cached_status| {
        var cached = cached_status;
        defer cached.deinit(alloc);
        disk_bytes = cached.disk_bytes;
        created_at_millis = cached.created_at_millis;
        cached_startup = cached.stats.async_indexing.startup;
    }

    var status = runtime_status.LocalTableRuntimeStatus{
        .group_id = group_id,
        .disk_bytes = disk_bytes,
        .created_at_millis = created_at_millis,
        .stats = try db.runtimeStatusStatsConsistent(alloc),
    };
    errdefer status.deinit(alloc);

    var startup = startupCatchUpStatsForPhase(phase, db);
    if (!startup.wal_retention_known and cached_startup.wal_retention_known) {
        startup.wal_retention_known = true;
        startup.wal_retained_segments = cached_startup.wal_retained_segments;
        startup.wal_retained_bytes = cached_startup.wal_retained_bytes;
    }
    applyStartupCatchUpAsyncOverlay(&status, db.snapshotAsyncIndexingStats(), startup);
    markRuntimeStatusFromDb(&status, phase);
    status.metadata.lsm_root_generation = lsm_root_generation;
    return status;
}

fn appendStructuralRuntimeStatusObservation(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    db: *db_mod.DB,
    lsm_root_generation: u64,
    phase: db_mod.types.StartupCatchUpPhase,
    observations: *std.ArrayListUnmanaged(ProvisionedTableWriteSource.StructuralRuntimeObservation),
) !void {
    const snapshot_cache = source.runtime_status_cache orelse return;
    std.debug.assert(observations.items.len < ProvisionedTableWriteSource.structural_reconcile_groups_per_quantum);
    const status = try captureStructuralRuntimeStatusObservation(
        snapshot_cache,
        alloc,
        table_name,
        group_id,
        db,
        lsm_root_generation,
        phase,
    );
    observations.appendAssumeCapacity(.{
        .status = status,
        .opened_root_generation = lsm_root_generation,
    });
}

fn markLatestStructuralIndexPublicationPending(
    observations: *std.ArrayListUnmanaged(ProvisionedTableWriteSource.StructuralRuntimeObservation),
    index_name: []const u8,
    producer_target_sequence: u64,
    requires_blocking: bool,
) ?ProvisionedTableWriteSource.PublicationHandoffTarget {
    // Uncached sources publish no snapshot authority and therefore need no
    // handoff fence: their direct status reads are serialized with structural
    // reconciliation and inspect the resident DB. The asynchronous producer
    // remains authoritative without manufacturing a cached observation.
    if (observations.items.len == 0) return null;
    const observation = &observations.items[observations.items.len - 1];
    for (observation.status.stats.indexes) |*item| {
        if (!std.mem.eql(u8, item.name, index_name)) continue;
        const target = ProvisionedTableWriteSource.PublicationHandoffTarget{
            .index_name = item.name,
            .coverage_generation = item.coverage_generation,
            .coverage_config_hash = item.coverage_config_hash,
            .producer_target_sequence = producer_target_sequence,
            .requires_blocking = requires_blocking,
        };
        // This snapshot becomes the fail-closed status authority while the
        // resident producer takes ownership. Preserve that handoff explicitly
        // even when the first replay window happens to be caught up at the
        // instant structural reconciliation samples it.
        item.backfill_active = true;
        item.replay_catch_up_required = true;
        item.catch_up_active = true;
        return target;
    }
    return null;
}

fn publishStructuralRuntimeObservations(
    source: *ProvisionedTableWriteSource,
    table_name: []const u8,
    publication_fence: ?runtime_status.TableRuntimeSnapshotCache.PublicationToken,
    observations: []const ProvisionedTableWriteSource.StructuralRuntimeObservation,
    lifecycle_transition: bool,
) !void {
    const snapshot_cache = source.runtime_status_cache orelse return;
    const token = publication_fence orelse return error.RuntimeStatusPublicationFenced;
    for (observations) |observation| {
        if (source.visibleRootGeneration(observation.status.group_id) != observation.opened_root_generation) {
            return error.RuntimeStatusPublicationFenced;
        }
    }
    const completed = try snapshot_cache.capturePublicationToken(table_name);
    // Creating durable repair debt emits the managed-visibility invalidation
    // from inside this reserved structural operation. Its post-mutation token
    // is therefore the transition's publication authority after the catalog
    // and physical-root fences above succeed. Non-transition observations
    // must still remain in the epoch sampled before DB inspection.
    if (!lifecycle_transition and !std.meta.eql(token.table_epoch, completed.table_epoch)) {
        return error.RuntimeStatusPublicationFenced;
    }
    std.debug.assert(observations.len <= ProvisionedTableWriteSource.structural_reconcile_groups_per_quantum);
    var statuses: [ProvisionedTableWriteSource.structural_reconcile_groups_per_quantum]runtime_status.LocalTableRuntimeStatus = undefined;
    for (observations, 0..) |observation, index| statuses[index] = observation.status;
    const result = if (lifecycle_transition)
        try snapshot_cache.publishLifecycleTransition(completed, table_name, statuses[0..observations.len])
    else
        try snapshot_cache.publishGroups(completed, table_name, statuses[0..observations.len]);
    try acceptRuntimeStatusPublication(result);
}

fn publishRuntimeStatusSnapshotConsistentIfAvailable(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    db: *db_mod.DB,
) !void {
    try publishRuntimeStatusSnapshotWithStartupPhaseMode(
        source,
        alloc,
        table_name,
        group_id,
        .idle,
        .consistent_if_available,
        db,
    );
}

fn publishRuntimeStatusSnapshotWithStartupPhase(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    phase: db_mod.types.StartupCatchUpPhase,
    db: *db_mod.DB,
) !void {
    try publishRuntimeStatusSnapshotWithStartupPhaseMode(source, alloc, table_name, group_id, phase, .best_effort, db);
}

const RuntimeStatusSnapshotMode = enum {
    best_effort,
    consistent,
    consistent_if_available,
    diagnostic,
};

const RuntimeStatusPublicationKind = enum {
    runtime,
    terminal_startup,
};

fn refreshRuntimeStatusStatsIfAvailable(
    alloc: std.mem.Allocator,
    status: *runtime_status.LocalTableRuntimeStatus,
    db: *db_mod.DB,
) !bool {
    const fresh_stats = (try db.runtimeStatusStatsConsistentIfAvailable(alloc)) orelse return false;
    db_mod.types.freeDBStats(alloc, status.stats);
    status.stats = fresh_stats;
    return true;
}

fn publishRuntimeStatusSnapshotWithStartupPhaseMode(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    phase: db_mod.types.StartupCatchUpPhase,
    mode: RuntimeStatusSnapshotMode,
    db: *db_mod.DB,
) !void {
    const repair_handoff_token = source.captureRepairHandoffPublicationTokenBestEffort(
        table_name,
        group_id,
        true,
    );
    const snapshot_cache = source.runtime_status_cache orelse {
        if (repair_handoff_token) |token| {
            _ = source.settleRepairHandoffStatusIfUnchangedBestEffort(table_name, group_id, token);
        }
        return;
    };
    const publication_token = try snapshot_cache.capturePublicationToken(table_name);
    const visible_root_generation = source.visibleRootGeneration(group_id);
    const opened_root_generation = db.core.index_manager.lsm_root_generation;
    // A retiring writer may finish status collection after restore publishes
    // its successor. Never stamp that observation with the successor's
    // generation: ownership belongs to the DB that produced the status.
    if (opened_root_generation != visible_root_generation) return;
    try publishRuntimeStatusSnapshotToCacheWithStartupPhaseMode(
        snapshot_cache,
        alloc,
        table_name,
        group_id,
        opened_root_generation,
        publication_token,
        phase,
        mode,
        .runtime,
        db,
    );
    // The cache now contains an observation captured after the durable repair
    // clear edge. That publication, rather than global DB idleness, is the
    // causal boundary that makes status authoritative again. Unrelated dense
    // or enrichment work remains visible as ordinary catch-up diagnostics and
    // cannot indefinitely hold another index's status fence.
    if (repair_handoff_token) |token| {
        _ = source.settleRepairHandoffStatusIfUnchangedBestEffort(table_name, group_id, token);
    }
    _ = source.settlePublicationHandoffStatusBestEffort(snapshot_cache, table_name, group_id, false);
}

fn publishTerminalStartupRuntimeStatusSnapshot(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    db: *db_mod.DB,
) !bool {
    const repair_handoff_token = source.captureRepairHandoffPublicationTokenBestEffort(
        table_name,
        group_id,
        false,
    );
    const snapshot_cache = source.runtime_status_cache orelse {
        // Uncached sources serve their next status directly from the DB. The
        // durable terminal state is already authoritative and has no cached
        // publication plane that can fence it.
        if (repair_handoff_token) |token| {
            if (!source.settleTerminalRepairHandoffStatusIfUnchangedBestEffort(table_name, group_id, token)) return false;
        }
        return true;
    };
    const publication_token = try snapshot_cache.capturePublicationToken(table_name);
    const visible_root_generation = source.visibleRootGeneration(group_id);
    const opened_root_generation = db.core.index_manager.lsm_root_generation;
    if (opened_root_generation != visible_root_generation) return false;
    publishRuntimeStatusSnapshotToCacheWithStartupPhaseMode(
        snapshot_cache,
        alloc,
        table_name,
        group_id,
        opened_root_generation,
        publication_token,
        .idle,
        .consistent,
        .terminal_startup,
        db,
    ) catch |err| switch (err) {
        error.RuntimeStatusPublicationFenced => return false,
        else => return err,
    };
    if (repair_handoff_token) |token| {
        if (!source.settleTerminalRepairHandoffStatusIfUnchangedBestEffort(table_name, group_id, token)) return false;
    }
    return true;
}

fn publishRuntimeStatusSnapshotToCacheConsistent(
    snapshot_cache: *runtime_status.TableRuntimeSnapshotCache,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    db: *db_mod.DB,
) !void {
    const publication_token = try snapshot_cache.capturePublicationToken(table_name);
    try publishRuntimeStatusSnapshotToCacheWithStartupPhaseMode(
        snapshot_cache,
        alloc,
        table_name,
        group_id,
        table_reads.backend_current_root_generation,
        publication_token,
        .idle,
        .consistent,
        .runtime,
        db,
    );
}

fn publishRuntimeStatusSnapshotToCacheWithStartupPhaseMode(
    snapshot_cache: *runtime_status.TableRuntimeSnapshotCache,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    lsm_root_generation: u64,
    publication_token: runtime_status.TableRuntimeSnapshotCache.PublicationToken,
    phase: db_mod.types.StartupCatchUpPhase,
    mode: RuntimeStatusSnapshotMode,
    publication_kind: RuntimeStatusPublicationKind,
    db: *db_mod.DB,
) !void {
    const async_stats = db.snapshotAsyncIndexingStats();
    if (mode == .best_effort and phase != .idle) {
        if (try snapshot_cache.snapshotGroupStatus(alloc, table_name, group_id)) |cached_status| {
            var status = cached_status;
            defer status.deinit(alloc);
            var startup = startupCatchUpStatsForPhase(phase, db);
            const cached_startup = status.stats.async_indexing.startup;
            if (!startup.wal_retention_known and cached_startup.wal_retention_known) {
                startup.wal_retention_known = true;
                startup.wal_retained_segments = cached_startup.wal_retained_segments;
                startup.wal_retained_bytes = cached_startup.wal_retained_bytes;
            }
            // Startup publication must remain non-blocking, but when the
            // writer is immediately readable replace stale table counters
            // before layering the startup progress fields onto them.
            _ = try refreshRuntimeStatusStatsIfAvailable(alloc, &status, db);
            applyStartupCatchUpAsyncOverlay(&status, async_stats, startup);
            markStartupRuntimeStatus(&status, startup);
            status.metadata.lsm_root_generation = lsm_root_generation;
            try publishRuntimeStatusGroupAfterObservation(snapshot_cache, publication_token, table_name, status);
        } else {
            var status = runtime_status.LocalTableRuntimeStatus{
                .group_id = group_id,
                .stats = try db.stats(alloc),
            };
            defer status.deinit(alloc);
            const startup = startupCatchUpStatsForPhase(phase, db);
            applyStartupCatchUpAsyncOverlay(&status, async_stats, startup);
            markStartupRuntimeStatus(&status, startup);
            status.metadata.lsm_root_generation = lsm_root_generation;
            try publishRuntimeStatusGroupAfterObservation(snapshot_cache, publication_token, table_name, status);
        }
        return;
    }
    var cached_startup: db_mod.types.StartupCatchUpStats = .{};
    var status = runtime_status.LocalTableRuntimeStatus{
        .group_id = group_id,
        .stats = .{},
    };
    var status_initialized = false;
    var status_from_cached_best_effort = false;
    var cached_best_effort_source: runtime_status.RuntimeStatusSource = .unknown;
    defer {
        if (status_initialized) {
            var owned = status;
            owned.deinit(alloc);
        }
    }
    if (try snapshot_cache.snapshotGroupStatus(alloc, table_name, group_id)) |cached_status| {
        cached_startup = cached_status.stats.async_indexing.startup;
        switch (mode) {
            .best_effort => {
                cached_best_effort_source = cached_status.metadata.source;
                status = cached_status;
                status_initialized = true;
                status_from_cached_best_effort = true;
                // Relabeling a cached observation as a fresh writer snapshot is
                // safe only after sampling source cardinality and derived
                // coverage under the same apply-lock boundary. A runtime-only
                // overlay can legitimately no-op during foreground apply; in
                // that case preserve the existing cached status and retry.
                if (!try refreshRuntimeStatusStatsIfAvailable(alloc, &status, db)) return error.WriterLocked;
                status_from_cached_best_effort = false;
            },
            .consistent => {
                const disk_bytes = cached_status.disk_bytes;
                const created_at_millis = cached_status.created_at_millis;
                var discard = cached_status;
                discard.deinit(alloc);
                status = .{
                    .group_id = group_id,
                    .disk_bytes = disk_bytes,
                    .created_at_millis = created_at_millis,
                    .stats = try db.runtimeStatusStatsConsistent(alloc),
                };
                status_initialized = true;
            },
            .consistent_if_available => {
                const disk_bytes = cached_status.disk_bytes;
                const created_at_millis = cached_status.created_at_millis;
                var discard = cached_status;
                discard.deinit(alloc);
                const fresh_stats = (try db.runtimeStatusStatsConsistentIfAvailable(alloc)) orelse return error.WriterLocked;
                status = .{
                    .group_id = group_id,
                    .disk_bytes = disk_bytes,
                    .created_at_millis = created_at_millis,
                    .stats = fresh_stats,
                };
                status_initialized = true;
            },
            .diagnostic => {
                const disk_bytes = cached_status.disk_bytes;
                const created_at_millis = cached_status.created_at_millis;
                var discard = cached_status;
                discard.deinit(alloc);
                status = .{
                    .group_id = group_id,
                    .disk_bytes = disk_bytes,
                    .created_at_millis = created_at_millis,
                    .stats = try db.diagnosticStats(alloc),
                };
                status_initialized = true;
            },
        }
    }
    if (!status_initialized) {
        status = .{
            .group_id = group_id,
            .stats = switch (mode) {
                // Never turn apply-lock contention into a fresh, authoritative
                // zero-cardinality observation. Callers already treat
                // WriterLocked as a retryable status-publication miss, and the
                // next targeted read can sample the resident writer exactly.
                .best_effort => (try db.runtimeStatusStatsConsistentIfAvailable(alloc)) orelse return error.WriterLocked,
                .consistent => try db.runtimeStatusStatsConsistent(alloc),
                .consistent_if_available => (try db.runtimeStatusStatsConsistentIfAvailable(alloc)) orelse return error.WriterLocked,
                .diagnostic => try db.diagnosticStats(alloc),
            },
        };
        status_initialized = true;
    }
    var startup = startupCatchUpStatsForPhase(phase, db);
    if (!startup.wal_retention_known and cached_startup.wal_retention_known) {
        startup.wal_retention_known = true;
        startup.wal_retained_segments = cached_startup.wal_retained_segments;
        startup.wal_retained_bytes = cached_startup.wal_retained_bytes;
    }
    applyStartupCatchUpAsyncOverlay(&status, async_stats, startup);
    if (phase == .idle and status_from_cached_best_effort and
        cachedBestEffortStartupPlaceholderSource(cached_best_effort_source) and
        !statusHasRuntimeFactsIgnoringMetadataSource(status))
    {
        markClearedStartupRuntimeStatus(&status);
        try publishRuntimeStatusGroupAfterObservation(snapshot_cache, publication_token, table_name, status);
    } else {
        if (publication_kind == .terminal_startup)
            markStartupRuntimeStatus(&status, startup)
        else
            markRuntimeStatusFromDb(&status, phase);
        status.metadata.lsm_root_generation = lsm_root_generation;
        try publishRuntimeStatusGroupAfterObservation(snapshot_cache, publication_token, table_name, status);
    }
}

fn publishRuntimeStatusGroupAfterObservation(
    snapshot_cache: *runtime_status.TableRuntimeSnapshotCache,
    publication_fence: runtime_status.TableRuntimeSnapshotCache.PublicationToken,
    table_name: []const u8,
    status: runtime_status.LocalTableRuntimeStatus,
) !void {
    // The first token fences table invalidation while DB state is sampled. A
    // second token orders the completed observation after any refresh that
    // started during that sampling window. This prevents an older cached
    // refresh from rejecting a lifecycle-completion hook without allowing a
    // retired writer to cross a table/root epoch.
    runTestBeforeRuntimeStatusPublishHook();
    const completed = try snapshot_cache.capturePublicationToken(table_name);
    if (!std.meta.eql(publication_fence.table_epoch, completed.table_epoch)) {
        return error.RuntimeStatusPublicationFenced;
    }
    try acceptRuntimeStatusPublication(try snapshot_cache.publishGroup(completed, table_name, status));
    // Exercise and document the real concurrency boundary: lifecycle edges
    // may arrive after cache publication but before handoff settlement.
    runTestAfterRuntimeStatusPublishHook();
}

fn acceptRuntimeStatusPublication(result: runtime_status.TableRuntimeSnapshotCache.PublishResult) !void {
    // A newer observation already owns publication ordering. It must not
    // cancel the maintenance operation whose status was superseded.
    switch (result) {
        .published, .stale_observation => {},
        .stale_table => return error.RuntimeStatusPublicationFenced,
    }
}

fn runtimeStatusNeedsAuthoritativeLifecycleRefresh(status: runtime_status.LocalTableRuntimeStatus) bool {
    if (status.stats.repair_degraded or
        status.stats.repair_issue_count != 0 or
        !status.stats.repair_summary_ready)
    {
        return true;
    }
    for (status.stats.indexes) |item| {
        if (item.backfill_active or
            item.repair_degraded or
            item.repair_issue_count != 0 or
            !item.repair_summary_ready or
            item.enrichment_failed or
            item.load_error != null or
            item.index_repair_id != null or
            !std.mem.eql(u8, item.projection_checkpoint_status, "clean"))
        {
            return true;
        }
    }
    return false;
}

fn markRuntimeStatusFromDb(
    status: *runtime_status.LocalTableRuntimeStatus,
    phase: db_mod.types.StartupCatchUpPhase,
) void {
    status.metadata = .{
        .updated_at_ns = platform_time.monotonicNs(),
        .source = if (phase != .idle)
            .startup_catch_up
        else
            .live_writer_publish,
        .freshness = if (phase == .idle)
            .fresh
        else
            startupRuntimeStatusFreshness(phase),
    };
}

fn statusHasRuntimeFactsIgnoringMetadataSource(status: runtime_status.LocalTableRuntimeStatus) bool {
    var runtime_fact_probe = status;
    runtime_fact_probe.metadata.source = .cached_snapshot;
    return runtime_status.statusHasRuntimeFacts(runtime_fact_probe);
}

fn cachedBestEffortStartupPlaceholderSource(source: runtime_status.RuntimeStatusSource) bool {
    return switch (source) {
        .live_writer_publish, .background_refresh, .remote_store, .rebuild_state_quarantine => false,
        .unknown, .synthetic_config, .cached_snapshot, .startup_catch_up => true,
    };
}

fn cachedStartupCatchUpStats(
    snapshot_cache: *runtime_status.TableRuntimeSnapshotCache,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
) !db_mod.types.StartupCatchUpStats {
    if (try snapshot_cache.snapshotGroupStatus(alloc, table_name, group_id)) |owned_status| {
        defer {
            var to_free = owned_status;
            to_free.deinit(alloc);
        }
        return owned_status.stats.async_indexing.startup;
    }
    return .{};
}

fn dbHbcCacheKindStatsFromIndex(cache_stats: hbc_mod.HbcCacheKindStats) db_mod.types.HbcCacheKindStats {
    return .{
        .used_bytes = cache_stats.used_bytes,
        .peak_bytes = cache_stats.peak_bytes,
        .hits = cache_stats.hits,
        .misses = cache_stats.misses,
        .insertions = cache_stats.insertions,
        .replacements = cache_stats.replacements,
        .sampled_admissions = cache_stats.sampled_admissions,
        .admission_skips = cache_stats.admission_skips,
        .evictions = cache_stats.evictions,
    };
}

fn dbHbcCacheStatsFromIndex(cache_stats: hbc_mod.HbcCacheStats) db_mod.types.HbcCacheStats {
    return .{
        .total_bytes = cache_stats.total_bytes,
        .accounted_bytes = cache_stats.accounted_bytes,
        .pinned_bytes = cache_stats.pinned_bytes,
        .node = dbHbcCacheKindStatsFromIndex(cache_stats.node),
        .quantized = dbHbcCacheKindStatsFromIndex(cache_stats.quantized),
        .vector = dbHbcCacheKindStatsFromIndex(cache_stats.vector),
        .metadata = dbHbcCacheKindStatsFromIndex(cache_stats.metadata),
    };
}

fn dbHbcPostingStatsFromIndex(backlog: hbc_mod.PostingBacklogStats, profile: hbc_mod.WriteProfile) db_mod.types.HbcPostingStats {
    return .{
        .scanned_nodes = backlog.scanned_nodes,
        .scanned_postings = backlog.scanned_postings,
        .dirty_postings = backlog.dirty_postings,
        .centroid_dirty_postings = backlog.centroid_dirty_postings,
        .payload_dirty_postings = backlog.payload_dirty_postings,
        .max_centroid_version_lag = backlog.max_centroid_version_lag,
        .max_payload_version_lag = backlog.max_payload_version_lag,
        .max_mutation_version = backlog.max_mutation_version,
        .skipped_missing = backlog.skipped_missing,
        .maintenance_scanned_nodes = profile.posting_maintenance_scanned_nodes,
        .maintenance_scanned_postings = profile.posting_maintenance_scanned_postings,
        .maintenance_dirty_postings = profile.posting_maintenance_dirty_postings,
        .maintenance_repaired_postings = profile.posting_maintenance_repaired_postings,
        .maintenance_centroid_refreshed = profile.posting_maintenance_centroid_refreshed,
        .maintenance_payload_refreshed = profile.posting_maintenance_payload_refreshed,
        .maintenance_ancestor_refresh_roots = profile.posting_maintenance_ancestor_refresh_roots,
        .maintenance_split_postings = profile.posting_maintenance_split_postings,
        .maintenance_merged_postings = profile.posting_maintenance_merged_postings,
        .maintenance_boundary_reassigned_vectors = profile.posting_maintenance_boundary_reassigned_vectors,
        .lazy_centroid_deferrals = profile.posting_lazy_centroid_deferrals,
        .lazy_payload_deferrals = profile.posting_lazy_payload_deferrals,
        .lazy_ancestor_deferrals = profile.posting_lazy_ancestor_deferrals,
    };
}

fn overlayDenseHbcCacheStatsFromDb(stats: *db_mod.types.DBStats, db: *db_mod.DB) void {
    if (!db.core.tryLockApplyShared()) return;
    defer db.core.unlockApplyShared();

    for (stats.indexes) |*item| {
        if (item.kind != .dense_vector) continue;
        if (db.core.denseIndex(item.name)) |entry| {
            item.hbc_cache = dbHbcCacheStatsFromIndex(entry.index.hbcCacheStats());
        }
    }
}

fn overlayRuntimeStatusReplayTargetFromDb(
    alloc: std.mem.Allocator,
    status: *runtime_status.LocalTableRuntimeStatus,
    db: *db_mod.DB,
) void {
    // Cold/query-only recovery has no producer runtime of its own. If a live
    // writer is resident, overlay its lock-free lifecycle snapshot together
    // with replay watermarks so a just-recovered status cannot transiently
    // report a ready managed index with `enrichment_runtime.enabled=false`.
    db.overlayRuntimeStatusRuntimeBestEffort(&status.stats);
    const async_stats = status.stats.async_indexing;
    for (status.stats.indexes) |*item| {
        const prior_backfill_active = item.backfill_active;
        const prior_backfill_progress = item.backfill_progress;
        const preserve_non_replay_backfill = runtimeStatusHasNonReplayBackfillSignal(item.*);
        if (db.executor.appliedSequence(item.name)) |live_applied| {
            item.replay_applied_sequence = @max(item.replay_applied_sequence, live_applied);
        }
        // The primary replay head is shared by every managed index. Derive the
        // target from this index's matching replay lane so unrelated commits
        // cannot manufacture replay debt in public provisioned status.
        item.replay_target_sequence = db.managedIndexReplayTargetSequence(
            alloc,
            item.name,
            item.kind,
            item.replay_applied_sequence,
        ) catch @max(item.replay_target_sequence, item.replay_applied_sequence);
        item.replay_target_sequence = @max(item.replay_target_sequence, item.replay_applied_sequence);
        item.catch_up_target_sequence = item.replay_target_sequence;
        item.catch_up_applied_sequence = item.replay_applied_sequence;
        item.catch_up_active = item.kind == .dense_vector and async_stats.dense_catch_up.active;
        item.catch_up_phase = if (item.kind == .dense_vector) async_stats.dense_catch_up.phase else .idle;
        item.replay_catch_up_required = item.replay_applied_sequence < item.replay_target_sequence;
        if (item.catch_up_active or item.replay_catch_up_required) {
            item.backfill_active = true;
            if (item.replay_target_sequence > 0) {
                item.backfill_progress = @min(
                    1.0,
                    @as(f64, @floatFromInt(item.replay_applied_sequence)) /
                        @as(f64, @floatFromInt(item.replay_target_sequence)),
                );
            }
        } else if (prior_backfill_active and preserve_non_replay_backfill) {
            item.backfill_active = true;
            item.backfill_progress = prior_backfill_progress;
        } else {
            item.backfill_active = false;
            if (item.replay_target_sequence > 0) item.backfill_progress = 1.0;
        }
    }
}

fn runtimeStatusHasNonReplayBackfillSignal(item: db_mod.types.DBIndexStats) bool {
    if (!item.backfill_active) return false;
    // Health and activity are independent axes. Load failures, terminal
    // coverage gaps, and incomplete repair summaries are degraded states, but
    // none proves that a worker is still making progress. Preserve the bit
    // only when a durable build/checkpoint or algebraic runtime explicitly
    // reports active work.
    if (std.mem.eql(u8, item.projection_checkpoint_status, "rebuilding")) return true;
    if (item.index_repair_id != null and
        !std.mem.eql(u8, item.index_repair_phase, "terminal") and
        !std.mem.eql(u8, item.index_repair_automation, "paused")) return true;
    if (item.algebraic_active_progress != null) return true;
    if (item.algebraic_adaptive_backfilling_count != 0) return true;
    return false;
}

test "runtime status distinguishes degraded health from active generation work" {
    var degraded = db_mod.types.DBIndexStats{
        .name = "semantic_idx",
        .kind = .dense_vector,
        .backfill_active = true,
        .repair_degraded = true,
        .repair_issue_count = 3,
        .repair_summary_ready = false,
        .projection_checkpoint_status = "degraded",
    };
    try std.testing.expect(!runtimeStatusHasNonReplayBackfillSignal(degraded));

    degraded.projection_checkpoint_status = "rebuilding";
    try std.testing.expect(runtimeStatusHasNonReplayBackfillSignal(degraded));

    degraded.projection_checkpoint_status = "degraded";
    degraded.index_repair_id = 42;
    degraded.index_repair_phase = "building";
    degraded.index_repair_automation = "enabled";
    try std.testing.expect(runtimeStatusHasNonReplayBackfillSignal(degraded));

    degraded.index_repair_automation = "paused";
    try std.testing.expect(!runtimeStatusHasNonReplayBackfillSignal(degraded));
}

fn startupCatchUpStatsForPhase(
    phase: db_mod.types.StartupCatchUpPhase,
    db: ?*db_mod.DB,
) db_mod.types.StartupCatchUpStats {
    var stats: db_mod.types.StartupCatchUpStats = if (db) |managed_db|
        managed_db.snapshotAsyncIndexingStats().startup
    else
        .{};
    stats.active = phase != .idle;
    stats.phase = phase;
    if (phase == .idle) return stats;
    if (db) |managed_db| {
        const maintenance = managed_db.snapshotLsmMaintenanceStats();
        stats.wal_retention_known = true;
        stats.wal_retained_segments = maintenance.wal_retained_segments;
        stats.wal_retained_bytes = maintenance.wal_retained_bytes;
    }
    return stats;
}

const StartupConfiguredIndex = struct {
    name: []u8 = &.{},
    kind: db_mod.types.IndexKind = .dense_vector,
    algebraic_schema_version: u32 = 0,
    algebraic_capability_fingerprint: ?[]u8 = null,
    algebraic_capability_lifecycle_status: ?[]u8 = null,
    algebraic_capability_change_added_fields: u32 = 0,
    algebraic_capability_change_removed_fields: u32 = 0,
    algebraic_capability_change_changed_type_fields: u32 = 0,
    algebraic_skipped_dynamic_fields: u32 = 0,
    algebraic_skipped_complex_fields: u32 = 0,
    algebraic_skipped_unbounded_fields: u32 = 0,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        if (self.name.len > 0) alloc.free(self.name);
        if (self.algebraic_capability_fingerprint) |value| alloc.free(value);
        if (self.algebraic_capability_lifecycle_status) |value| alloc.free(value);
        self.* = undefined;
    }

    fn populateStats(self: *const @This(), alloc: std.mem.Allocator, stats: *db_mod.types.DBIndexStats) !void {
        if (self.kind != .algebraic) return;
        stats.algebraic_schema_version = self.algebraic_schema_version;
        stats.algebraic_capability_change_added_fields = self.algebraic_capability_change_added_fields;
        stats.algebraic_capability_change_removed_fields = self.algebraic_capability_change_removed_fields;
        stats.algebraic_capability_change_changed_type_fields = self.algebraic_capability_change_changed_type_fields;
        stats.algebraic_skipped_dynamic_fields = self.algebraic_skipped_dynamic_fields;
        stats.algebraic_skipped_complex_fields = self.algebraic_skipped_complex_fields;
        stats.algebraic_skipped_unbounded_fields = self.algebraic_skipped_unbounded_fields;
        if (self.algebraic_capability_fingerprint) |value| {
            stats.algebraic_capability_fingerprint = try alloc.dupe(u8, value);
        }
        if (self.algebraic_capability_lifecycle_status) |value| {
            stats.algebraic_capability_lifecycle_status = try alloc.dupe(u8, value);
        }
    }
};

const StartupConfiguredIndexes = struct {
    items: []StartupConfiguredIndex,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        for (self.items) |*item| item.deinit(alloc);
        alloc.free(self.items);
        self.* = undefined;
    }

    fn populateConfiguredCounts(self: *const @This(), stats: *db_mod.types.StartupCatchUpStats) void {
        for (self.items) |item| incrementStartupConfiguredIndexCounts(stats, item.kind);
    }

    fn accumulateRetention(
        self: *const @This(),
        storage: lsm_backend.Storage,
        alloc: std.mem.Allocator,
        table_path: []const u8,
        stats: *db_mod.types.StartupCatchUpStats,
    ) !void {
        for (self.items) |item| {
            const index_path = try std.fmt.allocPrint(alloc, "{s}/indexes/{s}", .{ table_path, item.name });
            defer alloc.free(index_path);
            const main_retention = try lsm_backend.wal.snapshotRetention(storage, alloc, index_path);
            const replay_retention = try lsm_backend.wal.snapshotReplayRetention(storage, alloc, index_path);
            stats.wal_retained_segments += main_retention.segments + replay_retention.segments;
            stats.wal_retained_bytes += main_retention.bytes + replay_retention.bytes;
        }
    }
};

fn parseStartupConfiguredIndexes(
    alloc: std.mem.Allocator,
    indexes_json: []const u8,
) !StartupConfiguredIndexes {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, indexes_json, .{});
    defer parsed.deinit();

    const object = switch (parsed.value) {
        .object => |object| object,
        else => return error.InvalidCreateTableRequest,
    };
    const array_form = object.get("indexes");
    const index_count: usize = if (array_form) |value|
        switch (value) {
            .array => value.array.items.len,
            else => return error.InvalidCreateTableRequest,
        }
    else
        object.count();
    const items = try alloc.alloc(StartupConfiguredIndex, index_count);
    errdefer {
        for (items[0..index_count]) |*item| item.deinit(alloc);
        alloc.free(items);
    }
    @memset(items, .{});
    var initialized: usize = 0;

    if (array_form) |value| {
        const array_items = switch (value) {
            .array => value.array.items,
            else => return error.InvalidCreateTableRequest,
        };
        for (array_items) |item| {
            if (item != .object) return error.InvalidCreateTableRequest;
            const name_value = item.object.get("name") orelse return error.InvalidCreateTableRequest;
            if (name_value != .string) return error.InvalidCreateTableRequest;
            const kind = try parseIndexKind(item);
            var configured = StartupConfiguredIndex{
                .name = try alloc.dupe(u8, name_value.string),
                .kind = kind,
            };
            errdefer configured.deinit(alloc);
            try populateStartupAlgebraicCapability(alloc, &configured, item);
            items[initialized] = configured;
            initialized += 1;
        }
        return .{ .items = items };
    }

    var it = object.iterator();
    while (it.next()) |entry| {
        const kind = try parseIndexKind(entry.value_ptr.*);
        var configured = StartupConfiguredIndex{
            .name = try alloc.dupe(u8, entry.key_ptr.*),
            .kind = kind,
        };
        errdefer configured.deinit(alloc);
        try populateStartupAlgebraicCapability(alloc, &configured, entry.value_ptr.*);
        items[initialized] = configured;
        initialized += 1;
    }
    return .{ .items = items };
}

fn startupAlgebraicField(value: std.json.Value, field: []const u8) ?std.json.Value {
    const object = switch (value) {
        .object => |object| object,
        else => return null,
    };
    if (object.get(field)) |direct| return direct;
    const config = object.get("config") orelse return null;
    const config_object = switch (config) {
        .object => |config_object| config_object,
        else => return null,
    };
    return config_object.get(field);
}

fn startupAlgebraicString(value: std.json.Value, field: []const u8) ?[]const u8 {
    const field_value = startupAlgebraicField(value, field) orelse return null;
    return switch (field_value) {
        .string => |string| string,
        else => null,
    };
}

fn startupAlgebraicU32(value: std.json.Value, field: []const u8) ?u32 {
    const field_value = startupAlgebraicField(value, field) orelse return null;
    return switch (field_value) {
        .integer => |integer| if (integer >= 0 and integer <= std.math.maxInt(u32)) @intCast(integer) else null,
        else => null,
    };
}

fn populateStartupAlgebraicCapability(
    alloc: std.mem.Allocator,
    item: *StartupConfiguredIndex,
    value: std.json.Value,
) !void {
    if (item.kind != .algebraic) return;
    item.algebraic_schema_version = startupAlgebraicU32(value, "schema_version") orelse 0;
    item.algebraic_capability_change_added_fields = startupAlgebraicU32(value, "capability_change_added_fields") orelse 0;
    item.algebraic_capability_change_removed_fields = startupAlgebraicU32(value, "capability_change_removed_fields") orelse 0;
    item.algebraic_capability_change_changed_type_fields = startupAlgebraicU32(value, "capability_change_changed_type_fields") orelse 0;
    item.algebraic_skipped_dynamic_fields = startupAlgebraicU32(value, "skipped_dynamic_fields") orelse 0;
    item.algebraic_skipped_complex_fields = startupAlgebraicU32(value, "skipped_complex_fields") orelse 0;
    item.algebraic_skipped_unbounded_fields = startupAlgebraicU32(value, "skipped_unbounded_fields") orelse 0;
    if (startupAlgebraicString(value, "capability_fingerprint")) |fingerprint| {
        if (fingerprint.len > 0) item.algebraic_capability_fingerprint = try alloc.dupe(u8, fingerprint);
    }
    if (startupAlgebraicString(value, "capability_lifecycle_status")) |status| {
        if (status.len > 0) item.algebraic_capability_lifecycle_status = try alloc.dupe(u8, status);
    }
}

fn startupCatchUpStatsForPath(
    path: []const u8,
    phase: db_mod.types.StartupCatchUpPhase,
    configured_indexes: ?*const StartupConfiguredIndexes,
) !db_mod.types.StartupCatchUpStats {
    var stats: db_mod.types.StartupCatchUpStats = .{
        .active = phase != .idle,
        .phase = phase,
        .wal_retention_known = phase != .idle,
    };
    if (phase == .idle) return stats;

    var native = try lsm_backend.storage_io.NativeStorage.init(std.heap.page_allocator, .threaded);
    defer native.deinit();

    const main_retention = try lsm_backend.wal.snapshotRetention(native.storage(), std.heap.page_allocator, path);
    const replay_retention = try lsm_backend.wal.snapshotReplayRetention(native.storage(), std.heap.page_allocator, path);
    stats.wal_retained_segments = main_retention.segments + replay_retention.segments;
    stats.wal_retained_bytes = main_retention.bytes + replay_retention.bytes;
    if (configured_indexes) |summary| {
        summary.populateConfiguredCounts(&stats);
        try summary.accumulateRetention(native.storage(), std.heap.page_allocator, path, &stats);
    }
    return stats;
}

fn applyStartupCatchUpAsyncOverlay(
    status: *runtime_status.LocalTableRuntimeStatus,
    async_stats: db_mod.types.AsyncIndexingStats,
    startup: db_mod.types.StartupCatchUpStats,
) void {
    status.stats.async_indexing = async_stats;
    var merged_startup = status.stats.async_indexing.startup;
    db_mod.types.accumulateStartupCatchUpStats(&merged_startup, startup);
    status.stats.async_indexing.startup = merged_startup;
}

fn incrementStartupConfiguredIndexCounts(
    stats: *db_mod.types.StartupCatchUpStats,
    kind: db_mod.types.IndexKind,
) void {
    stats.configured_indexes += 1;
    switch (kind) {
        .dense_vector => stats.configured_dense_indexes += 1,
        .sparse_vector => stats.configured_sparse_indexes += 1,
        .full_text => stats.configured_full_text_indexes += 1,
        .graph => stats.configured_graph_indexes += 1,
        .algebraic => {},
    }
}

fn startupRuntimeStatusFreshness(phase: db_mod.types.StartupCatchUpPhase) runtime_status.RuntimeStatusFreshness {
    return switch (phase) {
        .idle => .stale,
        .opening_db => .opening,
        .artifact_rebuild, .startup_catch_up => .catching_up,
    };
}

fn setRuntimeStatusMetadata(
    status: *runtime_status.LocalTableRuntimeStatus,
    source: runtime_status.RuntimeStatusSource,
    freshness: runtime_status.RuntimeStatusFreshness,
) void {
    status.metadata.source = source;
    status.metadata.freshness = freshness;
    status.metadata.updated_at_ns = platform_time.monotonicNs();
}

fn markStartupRuntimeStatus(
    status: *runtime_status.LocalTableRuntimeStatus,
    startup: db_mod.types.StartupCatchUpStats,
) void {
    setRuntimeStatusMetadata(status, .startup_catch_up, startupRuntimeStatusFreshness(startup.phase));
}

fn clearStartupRuntimeStatus(status: *runtime_status.LocalTableRuntimeStatus) void {
    status.stats.async_indexing.startup.active = false;
    status.stats.async_indexing.startup.phase = .idle;
}

fn markClearedStartupRuntimeStatus(status: *runtime_status.LocalTableRuntimeStatus) void {
    clearStartupRuntimeStatus(status);
    if (status.metadata.freshness == .fresh) {
        switch (status.metadata.source) {
            .cached_snapshot, .live_writer_publish, .background_refresh, .remote_store, .rebuild_state_quarantine => return,
            .unknown, .synthetic_config, .startup_catch_up => {},
        }
    }
    var runtime_fact_probe = status.*;
    runtime_fact_probe.metadata.source = .cached_snapshot;
    const source: runtime_status.RuntimeStatusSource = if (runtime_status.statusHasRuntimeFacts(runtime_fact_probe))
        .cached_snapshot
    else
        .synthetic_config;
    setRuntimeStatusMetadata(status, source, .stale);
}

fn publishStartupCatchUpRuntimeStatusSnapshot(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    startup: db_mod.types.StartupCatchUpStats,
    db: ?*db_mod.DB,
    configured_indexes: ?*const StartupConfiguredIndexes,
) !void {
    const snapshot_cache = source.runtime_status_cache orelse return;
    const publication_token = try snapshot_cache.capturePublicationToken(table_name);
    var status = runtime_status.LocalTableRuntimeStatus{
        .group_id = group_id,
        .stats = .{},
    };
    var status_initialized = false;
    defer {
        if (status_initialized) {
            var owned = status;
            owned.deinit(alloc);
        }
    }

    if (startup.active) {
        if (try snapshot_cache.snapshotGroupStatus(alloc, table_name, group_id)) |owned_status| {
            status = owned_status;
            status_initialized = true;
            var merged_startup = startup;
            if (!merged_startup.wal_retention_known) {
                const cached_startup = status.stats.async_indexing.startup;
                merged_startup.wal_retention_known = cached_startup.wal_retention_known;
                merged_startup.wal_retained_segments = cached_startup.wal_retained_segments;
                merged_startup.wal_retained_bytes = cached_startup.wal_retained_bytes;
            }
            var merged_existing = status.stats.async_indexing.startup;
            db_mod.types.accumulateStartupCatchUpStats(&merged_existing, merged_startup);
            if (db) |managed_db| {
                _ = try refreshRuntimeStatusStatsIfAvailable(alloc, &status, managed_db);
            }
            status.stats.async_indexing.startup = merged_existing;
            if (db) |managed_db| {
                applyStartupCatchUpAsyncOverlay(&status, managed_db.snapshotAsyncIndexingStats(), status.stats.async_indexing.startup);
            }
        } else if (db) |managed_db| {
            status = .{
                .group_id = group_id,
                .stats = try managed_db.runtimeStatusStatsConsistent(alloc),
            };
            applyStartupCatchUpAsyncOverlay(&status, managed_db.snapshotAsyncIndexingStats(), startup);
            status_initialized = true;
        } else if (configured_indexes) |summary| {
            status = try syntheticStartupRuntimeStatusFromConfiguredIndexes(alloc, group_id, summary, startup, null);
            status_initialized = true;
        }
    } else if (db) |managed_db| {
        status = .{
            .group_id = group_id,
            .stats = try managed_db.runtimeStatusStatsConsistent(alloc),
        };
        applyStartupCatchUpAsyncOverlay(&status, managed_db.snapshotAsyncIndexingStats(), startup);
        status_initialized = true;
    } else if (try snapshot_cache.snapshot(alloc, table_name)) |owned_statuses| {
        var statuses = owned_statuses;
        defer statuses.deinit(alloc);
        for (statuses.items) |item| {
            if (item.group_id != group_id) continue;
            status = try item.clone(alloc);
            status_initialized = true;
            break;
        }
    }

    if (!status_initialized) return;

    status.group_id = group_id;
    if (startup.active) {
        markStartupRuntimeStatus(&status, startup);
    } else if (db == null) {
        var merged_startup = status.stats.async_indexing.startup;
        db_mod.types.accumulateStartupCatchUpStats(&merged_startup, startup);
        status.stats.async_indexing.startup = merged_startup;
        markClearedStartupRuntimeStatus(&status);
    } else {
        markRuntimeStatusFromDb(&status, .idle);
    }
    _ = try snapshot_cache.publishGroup(publication_token, table_name, status);
}

fn syntheticStartupRuntimeStatusFromConfiguredIndexes(
    alloc: std.mem.Allocator,
    group_id: u64,
    configured_indexes: *const StartupConfiguredIndexes,
    startup: db_mod.types.StartupCatchUpStats,
    load_error: ?[]const u8,
) !runtime_status.LocalTableRuntimeStatus {
    const indexes = try alloc.alloc(db_mod.types.DBIndexStats, configured_indexes.items.len);
    var initialized: usize = 0;
    errdefer {
        for (indexes[0..initialized]) |index| freeSyntheticStartupIndexStatsItem(alloc, index);
        alloc.free(indexes);
    }

    for (configured_indexes.items) |item| {
        var stats = db_mod.types.DBIndexStats{
            .name = try alloc.dupe(u8, item.name),
            .kind = item.kind,
        };
        errdefer freeSyntheticStartupIndexStatsItem(alloc, stats);
        try item.populateStats(alloc, &stats);
        if (load_error) |message| {
            stats.load_error = try alloc.dupe(u8, message);
            stats.repair_degraded = true;
        }
        indexes[initialized] = stats;
        initialized += 1;
    }

    return .{
        .group_id = group_id,
        .stats = .{
            .index_count = @intCast(indexes.len),
            .indexes = indexes,
            .async_indexing = .{ .startup = startup },
            .repair_degraded = load_error != null,
        },
    };
}

fn freeSyntheticStartupIndexStatsItem(alloc: std.mem.Allocator, item: db_mod.types.DBIndexStats) void {
    alloc.free(item.name);
    if (item.load_error) |value| alloc.free(value);
    if (item.algebraic_capability_fingerprint) |value| alloc.free(value);
    if (item.algebraic_capability_lifecycle_status) |value| alloc.free(value);
}

fn isTerminalStartupCatchUpOpenFailure(err: anyerror) bool {
    return err == error.FileNotFound;
}

fn publishTerminalStartupCatchUpRuntimeStatus(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    startup: db_mod.types.StartupCatchUpStats,
    configured_indexes: ?*const StartupConfiguredIndexes,
    err: anyerror,
) !bool {
    const repair_handoff_token = source.captureRepairHandoffPublicationTokenBestEffort(
        table_name,
        group_id,
        false,
    );
    const snapshot_cache = source.runtime_status_cache orelse {
        if (repair_handoff_token) |token| {
            if (!source.settleTerminalRepairHandoffStatusIfUnchangedBestEffort(table_name, group_id, token)) return false;
        }
        return true;
    };
    const publication_token = try snapshot_cache.capturePublicationToken(table_name);
    // Without configured index metadata there is no synthetic observation to
    // publish. That is harmless when no structural handoff is waiting, but a
    // waiting handoff must retain its exact retry route.
    const summary = configured_indexes orelse return repair_handoff_token == null;
    const message = try std.fmt.allocPrint(alloc, "startup catch-up open failed: {s}", .{@errorName(err)});
    defer alloc.free(message);
    var terminal_startup = startup;
    terminal_startup.active = false;
    terminal_startup.phase = .idle;
    terminal_startup.lsm_open_failed += 1;
    var status = try syntheticStartupRuntimeStatusFromConfiguredIndexes(alloc, group_id, summary, terminal_startup, message);
    defer status.deinit(alloc);
    setRuntimeStatusMetadata(&status, .startup_catch_up, .stale);
    publishRuntimeStatusGroupAfterObservation(snapshot_cache, publication_token, table_name, status) catch |publish_err| switch (publish_err) {
        error.RuntimeStatusPublicationFenced => return false,
        else => return publish_err,
    };
    if (repair_handoff_token) |token| {
        if (!source.settleTerminalRepairHandoffStatusIfUnchangedBestEffort(table_name, group_id, token)) return false;
    }
    return true;
}

fn finishManagedMaintenanceStatusPublication(publication: anyerror!void) !void {
    publication catch |err| switch (err) {
        // Runtime status is an observation of repair, never its commit point.
        // A table-epoch change must reject the stale snapshot without aborting
        // durable replay/generation progress or stranding its active intent.
        error.RuntimeStatusPublicationFenced => return,
        else => return err,
    };
}

const ManagedCatchUpOwner = enum {
    isolated,
    live_writer,
};

fn mergeLiveIndexRepairResult(
    result: *ProvisionedTableWriteSource.StartupCatchUpResult,
    repair: ProvisionedTableWriteSource.StartupCatchUpResult,
) void {
    result.had_debt = result.had_debt or repair.had_debt;
    result.cleared_debt = result.cleared_debt or repair.cleared_debt;
    result.made_progress = result.made_progress or repair.made_progress;
    result.busy = repair.busy;
    result.index_repair_pending = repair.index_repair_pending;
    result.index_repair_paused = repair.index_repair_paused;
    result.index_repair_attempted = repair.index_repair_attempted;
    result.index_repair_repaired = repair.index_repair_repaired;
    result.index_repair_degraded = repair.index_repair_degraded;
    result.index_repair_disk_wait = repair.index_repair_disk_wait;
    result.index_repair_retry_at_ms = repair.index_repair_retry_at_ms;
    result.terminal_degraded = repair.terminal_degraded;
}

const ManagedCatchUpMode = enum {
    all_debt,
    broad_debt_only,
    index_repair_only,
    // Restore completion can depend on making an unavailable candidate
    // generation readable. This mode performs only that bounded generation
    // work after the caller releases broad lifecycle exclusivity.
    index_repair_prerequisite,
};

fn managedDbHasBroadCatchUpDebt(alloc: std.mem.Allocator, db: *db_mod.DB) !bool {
    const replay_debt = try db.listDerivedReplayDebt(alloc);
    defer {
        for (replay_debt) |*status| status.deinit(alloc);
        alloc.free(replay_debt);
    }
    for (replay_debt) |status| {
        if (status.catch_up_required) return true;
    }
    const pending_work = db.pendingWorkStats();
    if (pending_work.repair_metadata_rebuild_pending) return true;
    const enrichment = pending_work.enrichment;
    if (enrichment.enabled and enrichment.applied_sequence < enrichment.target_sequence) return true;
    if (try db.restoreRuntimeRepairNeeded()) return true;
    return try db.denseArtifactRebuildMaintenanceNeeded(alloc);
}

fn catchUpManagedDb(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    group_id: u64,
    table_name: []const u8,
    db: *db_mod.DB,
    advance_index_repairs: bool,
    owner: ManagedCatchUpOwner,
    mode: ManagedCatchUpMode,
    index_repair_options: db_mod.types.ArtifactRepairRunOptions,
) !ProvisionedTableWriteSource.StartupCatchUpResult {
    const max_startup_catch_up_replay_passes: usize = 16;

    const before = db.listDerivedReplayDebt(alloc) catch |err| {
        std.log.warn("managed startup catch-up list debt failed table={s} err={}", .{ table_name, err });
        return err;
    };
    defer {
        for (before) |*status| status.deinit(alloc);
        alloc.free(before);
    }

    var had_debt = false;
    for (before) |status| {
        if (!status.catch_up_required) continue;
        had_debt = true;
        break;
    }
    const pending_work_before = db.pendingWorkStats();
    const repair_metadata_rebuild_pending = pending_work_before.repair_metadata_rebuild_pending;
    const enrichment_before = pending_work_before.enrichment;
    if (enrichment_before.enabled and
        enrichment_before.applied_sequence < enrichment_before.target_sequence)
    {
        had_debt = true;
    }
    const ProgressCtx = struct {
        source: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        db: *db_mod.DB,
        phase: db_mod.types.StartupCatchUpPhase,

        fn run(ptr: *anyopaque, _: []const u8, _: db_mod.ReplayProgress) !void {
            const ctx: *@This() = @ptrCast(@alignCast(ptr));
            try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(ctx.source, ctx.alloc, ctx.table_name, ctx.group_id, ctx.phase, ctx.db));
        }
    };

    var progress_ctx = ProgressCtx{
        .source = source,
        .alloc = alloc,
        .group_id = group_id,
        .table_name = table_name,
        .db = db,
        .phase = .startup_catch_up,
    };

    const restore_repair_needed = db.restoreRuntimeRepairNeeded() catch |err| {
        std.log.warn("managed startup restore repair failed phase=probe class={s}", .{@errorName(err)});
        return err;
    };
    const needs_dense_artifact_maintenance = db.denseArtifactRebuildMaintenanceNeeded(alloc) catch |err| {
        std.log.warn("managed startup catch-up dense rebuild probe failed table={s} err={}", .{ table_name, err });
        return err;
    };
    const initial_index_load_failure = try managedDbHasIndexLoadFailure(alloc, db);
    // An unavailable checkpoint is not proof that repair debt is absent. Let
    // the scheduler retain this exact route and apply its normal error
    // backoff instead of publishing a false completion edge.
    const initial_index_repair_intents = try db.hasPendingIndexRepairIntents(alloc);
    const initial_index_repair_debt = initial_index_load_failure or initial_index_repair_intents;
    const initial_repair_debt = had_debt or
        repair_metadata_rebuild_pending or
        restore_repair_needed or
        needs_dense_artifact_maintenance or
        initial_index_load_failure or
        initial_index_repair_intents;

    if (mode == .index_repair_only) {
        if (!initial_index_repair_debt) {
            return .{};
        }
        if (had_debt or restore_repair_needed or needs_dense_artifact_maintenance) {
            // Full startup/restore catch-up owns these mutations under its
            // exclusive lifecycle fence. Retain the exact index-repair queue
            // entry, but do not let a live, cooperatively admitted repair pass
            // perform broader replay or root recovery after releasing that
            // fence.
            return .{
                .had_debt = true,
                .busy = true,
                .index_repair_pending = true,
            };
        }
    }

    if (restore_repair_needed and initial_index_load_failure) {
        // Restore repair mutates every managed projection and eventually
        // clears the table-level restore marker. A quarantined generation
        // cannot participate in that proof, so preserve both debts and fail
        // closed until the index repair owner has recovered (or an operator
        // has replaced) the unavailable generation.
        return .{
            .had_debt = true,
            .terminal_degraded = true,
        };
    }

    var repaired_restore_runtime = false;
    var repaired_dense_artifacts = false;
    var repaired_artifact_metadata = false;
    var attempted_index_repairs: usize = 0;
    var repaired_indexes: usize = 0;
    var degraded_indexes: usize = 0;
    var made_progress = false;
    defer if (made_progress) {
        // Readers must reopen after any durable visibility change. A repair
        // that leased the live writer has already changed that authoritative
        // in-memory owner, however, so retiring it would turn the next bounded
        // quantum into a cold, read-exclusive reopen. Keep that writer both to
        // avoid repeated open/replay work and to let queued repair progress
        // while status continues reading the immutable published generation.
        // Isolated startup owners still retire shared write handles so no
        // independently cached writer can survive their durable mutation.
        source.invalidateReadCache(table_name);
        if (owner == .isolated) source.invalidateWriteCacheForTable(table_name);
        source.clearDirtyWriteTable(table_name);
    };
    const runs_broad_debt = mode == .all_debt or mode == .broad_debt_only;
    if (runs_broad_debt and repair_metadata_rebuild_pending) {
        progress_ctx.phase = .artifact_rebuild;
        try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(source, alloc, table_name, group_id, .artifact_rebuild, db));
        try db.runArtifactRepairMetadataMaintenanceUntilIdle();
        repaired_artifact_metadata = true;
        made_progress = true;
        try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(source, alloc, table_name, group_id, .artifact_rebuild, db));
    }
    if (runs_broad_debt and restore_repair_needed) {
        std.log.info("managed restore repair begin group_id={d}", .{group_id});
        progress_ctx.phase = .artifact_rebuild;
        try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(source, alloc, table_name, group_id, .artifact_rebuild, db));
        repaired_restore_runtime = db.repairRestoreRuntimeStateStepIfNeeded(alloc) catch |err| {
            if (owner == .live_writer and isPendingRestoreRuntimeRepairError(err)) {
                // A resident writer keeps its managed workers enabled. Some
                // restore proof phases must wait for those workers rather than
                // rebuilding the same coverage inline. Retain the exact route
                // and yield this bounded quantum; never turn ordinary async
                // convergence into an operator-visible repair failure.
                std.log.info("managed restore repair waiting for resident worker convergence group_id={d} class={s}", .{ group_id, @errorName(err) });
                // An unavailable index generation is not resolved by waiting
                // for replay workers. The caller must release this exclusive
                // phase and admit one bounded generation-repair quantum.
                if (err == error.RestoreIndexAvailabilityIncomplete) return err;
                return .{
                    .had_debt = true,
                    .busy = true,
                    .index_repair_pending = advance_index_repairs,
                };
            }
            std.log.warn("managed startup restore repair failed phase=execution class={s}", .{@errorName(err)});
            return err;
        };
        made_progress = repaired_restore_runtime;
        // Dense mutation phases retire their own HBC state inside DB repair.
        // Keep the resident writer's warm cache across watermark, graph, and
        // phase-marker-only quanta.
        try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(source, alloc, table_name, group_id, .artifact_rebuild, db));
        std.log.info("managed restore repair step complete group_id={d} repaired={}", .{ group_id, repaired_restore_runtime });
    } else if (runs_broad_debt and had_debt) {
        var pass: usize = 0;
        var last_debt_signature = try startupReplayDebtSignature(alloc, db);
        while (pass < max_startup_catch_up_replay_passes) : (pass += 1) {
            try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(source, alloc, table_name, group_id, .startup_catch_up, db));
            db.catchUpPendingDerivedReplayWithProgress(&progress_ctx, ProgressCtx.run) catch |err| {
                std.log.warn("managed startup catch-up replay failed table={s} err={}", .{ table_name, err });
                if (err == error.WriterLocked or err == error.ReplayDocumentNotVisible) {
                    return .{
                        .had_debt = true,
                        .cleared_debt = false,
                        .busy = true,
                    };
                }
                return err;
            };
            db.runUntilIdle() catch |err| {
                std.log.warn("managed startup catch-up replay idle drain failed table={s} err={}", .{ table_name, err });
                if (err == error.WriterLocked or err == error.ReplayDocumentNotVisible) {
                    return .{
                        .had_debt = true,
                        .cleared_debt = false,
                        .busy = true,
                    };
                }
                return err;
            };
            try runTestAfterStartupCatchUpReplayPassHook(db);

            const next_debt_signature = try startupReplayDebtSignature(alloc, db);
            if (next_debt_signature.remaining < last_debt_signature.remaining or
                next_debt_signature.applied_sum > last_debt_signature.applied_sum)
            {
                made_progress = true;
            }
            if (next_debt_signature.remaining == 0) break;
            if (next_debt_signature.applied_sum <= last_debt_signature.applied_sum and next_debt_signature.target_sum <= last_debt_signature.target_sum) break;
            last_debt_signature = next_debt_signature;
        }
        try db.core.index_manager.syncAll(true);
    }

    if (mode == .all_debt and !initial_repair_debt) {
        try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(source, alloc, table_name, group_id, .idle, db));
        return .{};
    }

    if (runs_broad_debt and !restore_repair_needed and needs_dense_artifact_maintenance) {
        progress_ctx.phase = .artifact_rebuild;
        try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(source, alloc, table_name, group_id, .artifact_rebuild, db));
        repaired_dense_artifacts = db.runDenseArtifactRebuildMaintenanceWithProgress(alloc, &progress_ctx, ProgressCtx.run) catch |err| {
            std.log.warn("managed startup catch-up dense rebuild failed table={s} err={}", .{ table_name, err });
            return err;
        };
        made_progress = made_progress or repaired_dense_artifacts;
        if (repaired_dense_artifacts) {
            db.runUntilIdle() catch |err| {
                std.log.warn("managed startup catch-up dense rebuild idle drain failed table={s} err={}", .{ table_name, err });
                return err;
            };
            try db.core.index_manager.syncAll(true);
        }
        try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(source, alloc, table_name, group_id, .artifact_rebuild, db));
    }

    if (mode == .all_debt and !initial_repair_debt and !repaired_restore_runtime and !repaired_dense_artifacts) {
        return .{};
    }

    if (mode == .broad_debt_only) {
        const initial_broad_debt = had_debt or repair_metadata_rebuild_pending or restore_repair_needed or needs_dense_artifact_maintenance;
        return .{
            .had_debt = initial_repair_debt,
            // The caller rechecks broad debt under the same exclusive guard
            // before trusting this completion edge.
            .cleared_debt = initial_broad_debt,
            .made_progress = made_progress,
            .index_repair_pending = advance_index_repairs,
        };
    }

    if (initial_index_load_failure) {
        const discovery = try db.discoverRecoverableStartupIndexFailures(alloc, 1);
        made_progress = made_progress or discovery.discovered != 0;
    }
    var repair_summary = try db.indexRepairIntentSummary(alloc);
    if (repair_summary.runnable != 0) {
        progress_ctx.phase = .artifact_rebuild;
        try finishManagedMaintenanceStatusPublication(publishRuntimeStatusSnapshotWithStartupPhase(source, alloc, table_name, group_id, .artifact_rebuild, db));
        if (!advance_index_repairs) {
            return .{
                .had_debt = true,
                .made_progress = made_progress,
                .index_repair_pending = true,
            };
        }
        const repair = try db.repairRecoverableStartupIndexFailures(alloc, 1, index_repair_options);
        attempted_index_repairs = repair.attempted;
        repaired_indexes = repair.repaired;
        degraded_indexes = repair.degraded;
        made_progress = made_progress or repair.attempted != 0 or repair.repaired != 0 or repair.discovered != 0;
        repair_summary = try db.indexRepairIntentSummary(alloc);
        if (repair_summary.runnable != 0) {
            return .{
                .had_debt = true,
                .made_progress = made_progress,
                .busy = repair.busy != 0,
                .index_repair_pending = true,
                .index_repair_attempted = repair.attempted != 0,
                .index_repair_repaired = repair.repaired != 0,
                .index_repair_degraded = repair.degraded != 0,
                .index_repair_disk_wait = repair.disk_waits != 0,
                .index_repair_retry_at_ms = repair.next_retry_at_ms,
            };
        }
    }

    if (mode == .all_debt) {
        const after = db.listDerivedReplayDebt(alloc) catch |err| {
            std.log.warn("managed startup catch-up post-check debt failed table={s} err={}", .{ table_name, err });
            return err;
        };
        defer {
            for (after) |*status| status.deinit(alloc);
            alloc.free(after);
        }

        for (after) |status| {
            if (!status.catch_up_required) continue;
            return .{
                .had_debt = initial_repair_debt,
                .cleared_debt = false,
                .made_progress = made_progress,
            };
        }
        if (db.denseArtifactRebuildMaintenanceNeeded(alloc) catch |err| {
            std.log.warn("managed startup catch-up post-check dense rebuild probe failed table={s} err={}", .{ table_name, err });
            return err;
        }) {
            return .{
                .had_debt = initial_repair_debt,
                .cleared_debt = false,
                .made_progress = made_progress,
            };
        }
        if (db.pendingWorkStats().repair_metadata_rebuild_pending) {
            return .{
                .had_debt = initial_repair_debt,
                .cleared_debt = false,
                .made_progress = made_progress,
            };
        }
        if (db.restoreRuntimeRepairNeeded() catch |err| {
            std.log.warn("managed startup restore repair failed phase=post_check class={s}", .{@errorName(err)});
            return err;
        }) {
            return .{
                .had_debt = initial_repair_debt,
                .cleared_debt = false,
                .made_progress = made_progress,
            };
        }
    }
    repair_summary = try db.indexRepairIntentSummary(alloc);
    if (repair_summary.terminal != 0) {
        return .{
            .had_debt = true,
            .terminal_degraded = true,
            .made_progress = made_progress,
        };
    }
    if (try managedDbHasIndexLoadFailure(alloc, db)) {
        return .{
            .had_debt = true,
            .terminal_degraded = true,
            .made_progress = made_progress,
        };
    }
    if (repair_summary.paused != 0) {
        return .{
            .had_debt = true,
            .made_progress = made_progress,
            .index_repair_paused = true,
            .index_repair_attempted = attempted_index_repairs != 0,
            .index_repair_repaired = repaired_indexes != 0,
            .index_repair_degraded = degraded_indexes != 0,
        };
    }
    // The caller performs one final durable audit after reacquiring exact
    // group mutation ownership, then publishes and settles under that same
    // lease. The long scan above is intentionally read-compatible.
    const index_only_result = mode == .index_repair_only or mode == .index_repair_prerequisite;
    const result_had_debt = if (index_only_result) initial_index_repair_debt else initial_repair_debt;
    return .{
        .had_debt = result_had_debt,
        .cleared_debt = if (index_only_result)
            repaired_indexes > 0
        else
            had_debt or repaired_artifact_metadata or repaired_restore_runtime or repaired_dense_artifacts or repaired_indexes > 0,
        .made_progress = made_progress,
        .index_repair_attempted = advance_index_repairs and attempted_index_repairs != 0,
        .index_repair_repaired = repaired_indexes != 0,
        .index_repair_degraded = degraded_indexes != 0,
    };
}

const StartupReplayDebtSignature = struct {
    remaining: usize = 0,
    applied_sum: u128 = 0,
    target_sum: u128 = 0,
};

fn startupReplayDebtSignature(alloc: std.mem.Allocator, db: *db_mod.DB) !StartupReplayDebtSignature {
    const replay_debt = try db.listDerivedReplayDebt(alloc);
    defer {
        for (replay_debt) |*status| status.deinit(alloc);
        alloc.free(replay_debt);
    }

    var signature = StartupReplayDebtSignature{};
    for (replay_debt) |status| {
        signature.applied_sum += status.applied_sequence;
        signature.target_sum += status.target_sequence;
        if (status.catch_up_required) signature.remaining += 1;
    }
    return signature;
}

fn shouldDrainManagedDbAfterBatch(sync_level: db_mod.types.SyncLevel) bool {
    // Request latency for weak sync levels must not depend on derived replay.
    // Pending replay is durable in the journal and is resumed by later writes,
    // explicit catch-up, or bulk-session finish.
    return switch (sync_level) {
        .propose, .write, .enrichments => false,
        .full_text, .full_index => false,
    };
}

fn shouldDrainCachedManagedDbAfterBatch(sync_level: db_mod.types.SyncLevel) bool {
    _ = sync_level;
    return false;
}

test "weak sync levels do not drain managed db after batch" {
    try std.testing.expect(!shouldDrainManagedDbAfterBatch(.propose));
    try std.testing.expect(!shouldDrainManagedDbAfterBatch(.write));
}

fn prepareLocalTablePathForRestore(alloc: std.mem.Allocator, path: []const u8) !void {
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    const io = io_impl.io();

    try fs_paths.createDirPathPortable(io, path);

    const indexes_path = try std.fmt.allocPrint(alloc, "{s}/indexes", .{path});
    defer alloc.free(indexes_path);
    try moveRestorePathToTrashIfPresent(alloc, io, path, indexes_path, "indexes");

    const snapshots_path = try std.fmt.allocPrint(alloc, "{s}.snapshots", .{path});
    defer alloc.free(snapshots_path);
    std.Io.Dir.cwd().deleteTree(io, snapshots_path) catch {};
}

fn moveRestorePathToTrashIfPresent(
    alloc: std.mem.Allocator,
    io: anytype,
    table_path: []const u8,
    source_path: []const u8,
    name: []const u8,
) !void {
    const trash_dir_path = try std.fmt.allocPrint(alloc, "{s}/../{s}", .{ table_path, restore_trash_dir_name });
    defer alloc.free(trash_dir_path);
    try fs_paths.createDirPathPortable(io, trash_dir_path);

    const trash_path = try std.fmt.allocPrint(alloc, "{s}/{s}-{d}", .{
        trash_dir_path,
        name,
        platform_time.monotonicNs(),
    });
    defer alloc.free(trash_path);
    std.Io.Dir.rename(std.Io.Dir.cwd(), source_path, std.Io.Dir.cwd(), trash_path, io) catch |err| switch (err) {
        error.FileNotFound => {},
        else => return err,
    };
}

fn sleepNs(duration_ns: u64) void {
    var req = std.posix.timespec{
        .sec = @intCast(duration_ns / std.time.ns_per_s),
        .nsec = @intCast(duration_ns % std.time.ns_per_s),
    };
    while (true) switch (std.posix.errno(std.posix.system.nanosleep(&req, &req))) {
        .SUCCESS => return,
        .INTR => continue,
        else => return,
    };
}

const SourceStateMutex = struct {
    owned: std.atomic.Mutex = .unlocked,
    shared: ?*std.atomic.Mutex = null,

    fn bind(self: *SourceStateMutex, shared: *std.atomic.Mutex) void {
        if (self.shared) |existing| {
            if (existing != shared) {
                @panic("writer source cannot be rebound to a different state mutex");
            }
            return;
        }
        self.shared = shared;
    }

    fn atomicMutex(self: *SourceStateMutex) *std.atomic.Mutex {
        return self.shared orelse &self.owned;
    }

    fn tryLock(self: *SourceStateMutex) bool {
        return self.atomicMutex().tryLock();
    }

    fn unlock(self: *SourceStateMutex) void {
        self.atomicMutex().unlock();
    }
};

fn lockAtomic(mutex: anytype) void {
    // Bounded spin, then yield (platform_sync): local_db_mutex guards cache
    // bookkeeping that can take a while under contention (opens,
    // invalidation), and a pure spin pins a core per waiter — on
    // CPU-constrained hosts (CI runners) that starves the very threads that
    // would release the lock.
    const atomic_mutex = if (comptime @TypeOf(mutex) == *SourceStateMutex)
        mutex.atomicMutex()
    else
        mutex;
    platform_sync.lockYielding(atomic_mutex);
}

fn loadLocalTableSchemaJson(alloc: std.mem.Allocator, db: *db_mod.DB) !?[]u8 {
    return db.core.store.get(alloc, local_schema_json_key) catch |err| switch (err) {
        error.NotFound => null,
        else => return err,
    };
}

fn validateTableWritesAgainstLocalSchema(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    writes: anytype,
) !void {
    if (writes.len == 0) return;
    const schema_json = (try loadLocalTableSchemaJson(alloc, db)) orelse return;
    defer alloc.free(schema_json);
    if (schema_json.len == 0) return;

    var parsed_schema = try tables_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    try tables_api.validateWritesAgainstTableSchema(alloc, parsed_schema, writes);
}

fn freeOwnedBatchWrites(alloc: std.mem.Allocator, writes: []const db_mod.types.BatchWrite) void {
    for (writes) |write| {
        alloc.free(@constCast(write.key));
        alloc.free(@constCast(write.value));
    }
    if (writes.len > 0) alloc.free(@constCast(writes));
}

const SchemaValidationWriteState = struct {
    const Kind = enum { write, delete };

    const Entry = struct {
        key: []u8,
        kind: Kind,
        value: ?[]u8 = null,

        fn deinit(self: *Entry, alloc: std.mem.Allocator) void {
            alloc.free(self.key);
            if (self.value) |value| alloc.free(value);
            self.* = undefined;
        }
    };

    entries: std.ArrayListUnmanaged(Entry) = .empty,

    fn deinit(self: *SchemaValidationWriteState, alloc: std.mem.Allocator) void {
        for (self.entries.items) |*entry| entry.deinit(alloc);
        self.entries.deinit(alloc);
        self.* = undefined;
    }

    fn findIndex(self: *const SchemaValidationWriteState, key: []const u8) ?usize {
        for (self.entries.items, 0..) |entry, i| {
            if (std.mem.eql(u8, entry.key, key)) return i;
        }
        return null;
    }

    fn applyBorrowedWrite(self: *SchemaValidationWriteState, alloc: std.mem.Allocator, key: []const u8, value: []const u8) !void {
        const owned_value = try alloc.dupe(u8, value);
        errdefer alloc.free(owned_value);
        if (self.findIndex(key)) |idx| {
            const entry = &self.entries.items[idx];
            if (entry.value) |old_value| alloc.free(old_value);
            entry.kind = .write;
            entry.value = owned_value;
            return;
        }

        const owned_key = try alloc.dupe(u8, key);
        errdefer alloc.free(owned_key);
        try self.entries.append(alloc, .{
            .key = owned_key,
            .kind = .write,
            .value = owned_value,
        });
    }

    fn applyDelete(self: *SchemaValidationWriteState, alloc: std.mem.Allocator, key: []const u8) !void {
        if (self.findIndex(key)) |idx| {
            const entry = &self.entries.items[idx];
            if (entry.value) |old_value| alloc.free(old_value);
            entry.kind = .delete;
            entry.value = null;
            return;
        }

        const owned_key = try alloc.dupe(u8, key);
        errdefer alloc.free(owned_key);
        try self.entries.append(alloc, .{
            .key = owned_key,
            .kind = .delete,
        });
    }

    fn applyOwnedWrite(self: *SchemaValidationWriteState, alloc: std.mem.Allocator, key: []const u8, value: []u8) !void {
        if (self.findIndex(key)) |idx| {
            const entry = &self.entries.items[idx];
            if (entry.value) |old_value| alloc.free(old_value);
            entry.kind = .write;
            entry.value = value;
            return;
        }

        const owned_key = try alloc.dupe(u8, key);
        errdefer alloc.free(owned_key);
        try self.entries.append(alloc, .{
            .key = owned_key,
            .kind = .write,
            .value = value,
        });
    }

    fn baseValue(self: *const SchemaValidationWriteState, key: []const u8) ?[]const u8 {
        const idx = self.findIndex(key) orelse return null;
        const entry = self.entries.items[idx];
        return switch (entry.kind) {
            .write => entry.value.?,
            .delete => null,
        };
    }

    fn hasRequestState(self: *const SchemaValidationWriteState, key: []const u8) bool {
        return self.findIndex(key) != null;
    }

    fn toOwnedWrites(self: *const SchemaValidationWriteState, alloc: std.mem.Allocator) ![]db_mod.types.BatchWrite {
        var count: usize = 0;
        for (self.entries.items) |entry| {
            if (entry.kind == .write) count += 1;
        }

        var out = try alloc.alloc(db_mod.types.BatchWrite, count);
        var filled: usize = 0;
        errdefer {
            for (out[0..filled]) |write| {
                alloc.free(@constCast(write.key));
                alloc.free(@constCast(write.value));
            }
            alloc.free(out);
        }

        var i: usize = 0;
        for (self.entries.items) |entry| {
            if (entry.kind != .write) continue;
            {
                const owned_key = try alloc.dupe(u8, entry.key);
                errdefer alloc.free(owned_key);
                const owned_value = try alloc.dupe(u8, entry.value.?);
                errdefer alloc.free(owned_value);
                out[i] = .{
                    .key = owned_key,
                    .value = owned_value,
                };
            }
            filled += 1;
            i += 1;
        }
        return out;
    }
};

fn portableBackupShardRelPath(alloc: std.mem.Allocator, backup_id: []const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "{s}.afb", .{backup_id});
}

fn exportPortableBackupShard(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    backup_root: []const u8,
    backup_id: []const u8,
    group_id: u64,
    shared_io: ?std.Io,
) ![]backups_api.ShardSnapshot {
    const rel_path = try portableBackupShardRelPath(alloc, backup_id);
    errdefer alloc.free(rel_path);

    const dest_path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ backup_root, rel_path });
    defer alloc.free(dest_path);
    try exportPortableBackupFile(alloc, db.core.store, dest_path, shared_io);

    const byte_range = db.getRange();
    const shards = try alloc.alloc(backups_api.ShardSnapshot, 1);
    shards[0] = .{
        .group_id = group_id,
        .start_key = try alloc.dupe(u8, byte_range.start),
        .end_key = if (byte_range.end.len > 0) try alloc.dupe(u8, byte_range.end) else null,
        .snapshot_path = rel_path,
    };
    errdefer shards[0].deinit(alloc);
    try backups_api.populateShardArtifactIntegrity(alloc, shared_io, .portable, dest_path, &shards[0]);
    return shards;
}

fn exportPortableBackupFile(alloc: std.mem.Allocator, store: *db_mod.docstore.DocStore, path: []const u8, shared_io: ?std.Io) !void {
    if (shared_io) |io| return try exportPortableBackupFileWithIo(alloc, store, path, io);
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    return try exportPortableBackupFileWithIo(alloc, store, path, io_impl.io());
}

fn exportPortableBackupFileWithIo(alloc: std.mem.Allocator, store: *db_mod.docstore.DocStore, path: []const u8, io: std.Io) !void {
    if (std.fs.path.dirname(path)) |parent| try fs_paths.createDirPathPortable(io, parent);
    const tmp_path = try std.fmt.allocPrint(alloc, "{s}.tmp-{d}", .{ path, platform_time.monotonicNs() });
    defer alloc.free(tmp_path);
    errdefer if (std.fs.path.isAbsolute(tmp_path))
        std.Io.Dir.deleteFileAbsolute(io, tmp_path) catch {}
    else
        std.Io.Dir.cwd().deleteFile(io, tmp_path) catch {};
    var file = try fs_paths.createFilePortable(io, tmp_path, .{ .truncate = true });
    var file_open = true;
    defer if (file_open) file.close(io);
    var buf: [64 * 1024]u8 = undefined;
    var writer = file.writer(io, &buf);
    try portable_backup.exportPortableToWriter(alloc, store, &writer.interface);
    try writer.end();
    try file.sync(io);
    file.close(io);
    file_open = false;
    if (std.fs.path.isAbsolute(path))
        try std.Io.Dir.renameAbsolute(tmp_path, path, io)
    else
        try std.Io.Dir.rename(std.Io.Dir.cwd(), tmp_path, std.Io.Dir.cwd(), path, io);
}

fn readBackupFileAlloc(alloc: std.mem.Allocator, path: []const u8) ![]u8 {
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    return try std.Io.Dir.cwd().readFileAlloc(
        io_impl.io(),
        path,
        alloc,
        .limited(backups_api.max_portable_backup_file_bytes),
    );
}

fn importPortableBackupFile(alloc: std.mem.Allocator, store: *db_mod.docstore.DocStore, path: []const u8, shared_io: ?std.Io) !void {
    if (shared_io) |io| return try importPortableBackupFileWithIo(alloc, store, path, io);
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    return try importPortableBackupFileWithIo(alloc, store, path, io_impl.io());
}

fn importPortableBackupFileWithIo(alloc: std.mem.Allocator, store: *db_mod.docstore.DocStore, path: []const u8, io: std.Io) !void {
    var file = if (std.fs.path.isAbsolute(path))
        try std.Io.Dir.openFileAbsolute(io, path, .{})
    else
        try std.Io.Dir.cwd().openFile(io, path, .{});
    defer file.close(io);
    const stat = try file.stat(io);
    try portable_backup.importPortableFile(alloc, store, io, file, stat.size);
}

fn freeBackupShards(alloc: std.mem.Allocator, shards: []const backups_api.ShardSnapshot) void {
    for (shards) |shard| shard.deinit(alloc);
    alloc.free(@constCast(shards));
}

fn cloneShardSnapshots(
    alloc: std.mem.Allocator,
    shards: []const backups_api.ShardSnapshot,
) ![]backups_api.ShardSnapshot {
    const out = try alloc.alloc(backups_api.ShardSnapshot, shards.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |shard| shard.deinit(alloc);
        alloc.free(out);
    }
    for (shards, 0..) |shard, i| {
        out[i] = .{
            .group_id = shard.group_id,
            .start_key = try alloc.dupe(u8, shard.start_key),
            .end_key = if (shard.end_key) |value| try alloc.dupe(u8, value) else null,
            .snapshot_path = try alloc.dupe(u8, shard.snapshot_path),
            .artifact_size_bytes = shard.artifact_size_bytes,
            .artifact_sha256 = if (shard.artifact_sha256.len > 0)
                try alloc.dupe(u8, shard.artifact_sha256)
            else
                "",
        };
        initialized += 1;
    }
    return out;
}

fn resolveWritesForSchemaValidation(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    base_writes: []const db_mod.types.BatchWrite,
    deletes: []const []const u8,
    transforms: []const db_mod.types.DocumentTransform,
) ![]db_mod.types.BatchWrite {
    var state = SchemaValidationWriteState{};
    defer state.deinit(alloc);

    for (base_writes) |write| {
        try state.applyBorrowedWrite(alloc, write.key, write.value);
    }

    for (deletes) |key| {
        try state.applyDelete(alloc, key);
    }

    for (transforms) |transform| {
        const has_request_state = state.hasRequestState(transform.key);
        const existing_from_request = state.baseValue(transform.key);
        const existing_from_db = if (!has_request_state) try db.get(alloc, transform.key) else null;
        defer if (existing_from_db) |body| alloc.free(body);
        const existing = existing_from_request orelse existing_from_db;
        const resolved = db_mod.transform.resolveDocumentTransform(alloc, existing, transform) catch |err| switch (err) {
            error.InvalidArgument, error.UnsupportedTransformOperation => return error.InvalidBatchRequest,
            else => return err,
        } orelse continue;

        state.applyOwnedWrite(alloc, transform.key, resolved) catch |err| {
            alloc.free(resolved);
            return err;
        };
    }

    return try state.toOwnedWrites(alloc);
}

fn transactionWritesToBatchWrites(
    alloc: std.mem.Allocator,
    writes: []const db_mod.types.TransactionWrite,
) ![]db_mod.types.BatchWrite {
    var out = try alloc.alloc(db_mod.types.BatchWrite, writes.len);
    for (writes, 0..) |write, i| {
        out[i] = .{
            .key = write.key,
            .value = write.value,
        };
    }
    return out;
}

fn transactionWritesAsBatchWrites(
    writes: []const db_mod.types.TransactionWrite,
) []const db_mod.types.BatchWrite {
    comptime {
        std.debug.assert(@sizeOf(db_mod.types.TransactionWrite) == @sizeOf(db_mod.types.BatchWrite));
        std.debug.assert(@alignOf(db_mod.types.TransactionWrite) == @alignOf(db_mod.types.BatchWrite));
    }
    return @ptrCast(writes);
}

fn validateTableBatchAgainstLocalSchema(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    writes: []const db_mod.types.BatchWrite,
    deletes: []const []const u8,
    transforms: []const db_mod.types.DocumentTransform,
) !void {
    if (writes.len == 0 and deletes.len == 0 and transforms.len == 0) return;
    const schema_json = (try loadLocalTableSchemaJson(alloc, db)) orelse return;
    defer alloc.free(schema_json);
    if (schema_json.len == 0) return;

    const effective_writes = try resolveWritesForSchemaValidation(alloc, db, writes, deletes, transforms);
    defer freeOwnedBatchWrites(alloc, effective_writes);
    if (effective_writes.len == 0) return;

    var parsed_schema = try tables_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    try tables_api.validateWritesAgainstTableSchema(alloc, parsed_schema, effective_writes);
}

fn validateTransactionAgainstLocalSchema(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    writes: []const db_mod.types.TransactionWrite,
    deletes: []const []const u8,
    transforms: []const db_mod.types.DocumentTransform,
) !void {
    const batch_writes = try transactionWritesToBatchWrites(alloc, writes);
    defer alloc.free(batch_writes);
    try validateTableBatchAgainstLocalSchema(alloc, db, batch_writes, deletes, transforms);
}

fn applyLocalTableSchemaJson(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    schema_json: []const u8,
) !void {
    if (schema_json.len == 0) return;

    const previous_schema_json = try loadLocalTableSchemaJson(alloc, db);
    defer if (previous_schema_json) |value| alloc.free(value);
    const marker_changed = if (previous_schema_json) |value|
        !std.mem.eql(u8, value, schema_json)
    else
        true;

    var parsed_schema = try tables_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);

    const runtime_schema = try tables_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer storage_schema.freeSchema(alloc, runtime_schema);

    try db.setSchema(runtime_schema);
    // Propagate schema-derived changes to live algebraic indexes so dynamic
    // template updates take effect without a reopen.
    try db.reloadAlgebraicSchemaConfigs(schema_json);
    if (marker_changed) try db.core.store.put(local_schema_json_key, schema_json);
}

fn loadTableIndexesJson(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
) !?[]u8 {
    var snapshot = try catalog.adminSnapshot();
    defer catalog.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return null;
    return try alloc.dupe(u8, table.indexes_json);
}

fn loadTableManagedMetadata(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
) !?struct { indexes_json: ?[]u8, schema_json: ?[]u8 } {
    var snapshot = try catalog.adminSnapshot();
    defer catalog.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return null;
    const indexes_json = if (table.indexes_json.len == 0) null else try alloc.dupe(u8, table.indexes_json);
    errdefer if (indexes_json) |value| alloc.free(value);
    const schema_json = if (table.schema_json.len == 0) null else try alloc.dupe(u8, table.schema_json);
    return .{
        .indexes_json = indexes_json,
        .schema_json = schema_json,
    };
}

/// Resolves the single storage group while checking the complete table
/// incarnation carried by backup admission. Callers repeat this after taking
/// their structural-operation guard so catalog replacement cannot redirect a
/// snapshot by reusing the same table name.
fn resolveFencedBackupGroup(
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
    expected_fence: ?backups_api.TableBackupFence,
) !?u64 {
    var snapshot = try catalog.adminSnapshot();
    defer catalog.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return null;
    const resolution = metadata_api.catalogTableTopologyResolution(table.table_id, snapshot.ranges);
    if (expected_fence) |expected| {
        const actual = backups_api.tableBackupFenceWithTopology(&snapshot, table, resolution.topology);
        if (!expected.matches(actual)) return error.CatalogChanged;
    }

    if (resolution.topology.range_count == 0) return null;
    if (resolution.topology.range_count != 1) return error.UnsupportedMultiRangeTable;
    return resolution.single_group_id orelse error.CatalogChanged;
}

fn loadTableIdentityNamespaceForGroup(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
    group_id: u64,
) !?doc_identity.Namespace {
    _ = alloc;
    var snapshot = try catalog.adminSnapshot();
    defer catalog.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return null;
    for (snapshot.ranges) |range| {
        if (range.table_id != table.table_id or range.group_id != group_id) continue;
        return tableIdentityNamespaceForRange(table.*, range);
    }
    return null;
}

fn tableIdentityNamespaceForRange(
    table: metadata_table_manager.TableRecord,
    range: metadata_table_manager.RangeRecord,
) doc_identity.Namespace {
    return tableIdentityNamespaceForRangeId(table.table_id, range);
}

fn tableIdentityNamespaceForRangeId(
    table_id: u64,
    range: metadata_table_manager.RangeRecord,
) doc_identity.Namespace {
    return .{
        .table_id = table_id,
        .shard_id = metadata_table_manager.rangeDocIdentityShardId(range),
        .range_id = metadata_table_manager.rangeDocIdentityRangeId(range),
    };
}

const RaftSnapshotCatalogContract = struct {
    metadata_group_id: u64,
    metadata_incarnation: metadata_api.MetadataClusterIncarnation,
    table_id: u64,
    table_name: []u8,
    schema_json: []u8,
    indexes_json: []u8,
    range: metadata_table_manager.RangeRecord,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.table_name);
        alloc.free(self.schema_json);
        alloc.free(self.indexes_json);
        metadata_table_manager.freeRange(alloc, self.range);
        self.* = undefined;
    }

    fn publicationContract(self: *const @This()) metadata_api.CatalogPublicationContract {
        return .{
            .metadata_group_id = self.metadata_group_id,
            .metadata_incarnation = self.metadata_incarnation,
            .table_id = self.table_id,
            .table_name = self.table_name,
            .schema_json = self.schema_json,
            .indexes_json = self.indexes_json,
            .range = self.range,
        };
    }
};

fn captureRaftSnapshotCatalogContract(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    group_id: u64,
    expected_table_id: u64,
    expected_table_name: []const u8,
) !RaftSnapshotCatalogContract {
    var snapshot = try catalog.adminSnapshot();
    defer catalog.freeAdminSnapshot(&snapshot);
    const range = metadata_mod.findAdminRange(&snapshot, group_id) orelse return error.CatalogChanged;
    if (range.table_id != expected_table_id) return error.CatalogChanged;
    const table = metadata_mod.findAdminTable(&snapshot, expected_table_id) orelse return error.CatalogChanged;
    if (!std.mem.eql(u8, table.name, expected_table_name)) return error.CatalogChanged;
    const metadata_incarnation = snapshot.status.metadata_incarnation orelse return error.MetadataIncarnationUnavailable;

    const table_name = try alloc.dupe(u8, table.name);
    errdefer alloc.free(table_name);
    const schema_json = try alloc.dupe(u8, table.schema_json);
    errdefer alloc.free(schema_json);
    const indexes_json = try alloc.dupe(u8, table.indexes_json);
    errdefer alloc.free(indexes_json);
    const owned_range = try metadata_table_manager.cloneRange(alloc, range.*);
    return .{
        .metadata_group_id = snapshot.status.metadata_group_id,
        .metadata_incarnation = metadata_incarnation,
        .table_id = expected_table_id,
        .table_name = table_name,
        .schema_json = schema_json,
        .indexes_json = indexes_json,
        .range = owned_range,
    };
}

fn findTableRecord(tables: []const metadata_table_manager.TableRecord, table_id: u64) ?metadata_table_manager.TableRecord {
    for (tables) |table| {
        if (table.table_id == table_id) return table;
    }
    return null;
}

fn findRangeRecord(ranges: []const metadata_table_manager.RangeRecord, group_id: u64) ?metadata_table_manager.RangeRecord {
    for (ranges) |range| {
        if (range.group_id == group_id) return range;
    }
    return null;
}

fn validateProvisionedDbIdentityNamespaceExpected(expected: ?doc_identity.Namespace, db: *const db_mod.DB) !void {
    return validateProvisionedDbIdentityNamespaceWithPolicy(expected, .exact, db);
}

fn validateProvisionedDbIdentityNamespaceWithPolicy(
    expected: ?doc_identity.Namespace,
    validation: StartupCatchUpMetadata.IdentityValidation,
    db: *const db_mod.DB,
) !void {
    const namespace = expected orelse return;
    const valid = switch (validation) {
        .exact => db.core.identity_namespace.eql(namespace),
        .reassign_same_table => db.core.identity_namespace.table_id ==
            namespace.table_id,
    };
    if (!valid) return error.DocIdentityNamespaceMismatch;
}

fn validateSplitReplicationForApply(req: db_mod.types.BatchRequest, group_id: u64) !?doc_identity.Namespace {
    const replication = req.split_replication orelse {
        if (req.split_checkpoint) |checkpoint| {
            if (checkpoint.kind != .source_ack) return error.MissingSplitReplicationContext;
        }
        return null;
    };
    if (replication.transition_id == 0 or replication.attempt_epoch == 0 or
        replication.source_group_id == replication.destination_group_id or
        replication.destination_group_id != group_id or
        replication.identity_namespace.table_id == 0 or
        replication.identity_namespace.shard_id == 0 or
        replication.identity_namespace.range_id == 0 or
        req.split_transition != null)
    {
        return error.InvalidBatchRequest;
    }
    if (req.split_checkpoint) |checkpoint| {
        if (checkpoint.kind == .source_ack or
            replication.operation != .checkpoint or
            checkpoint.transition_id != replication.transition_id or
            checkpoint.attempt_epoch != replication.attempt_epoch or
            checkpoint.source_group_id != replication.source_group_id or
            checkpoint.destination_group_id != replication.destination_group_id or
            checkpoint.delta_sequence != replication.sequence)
        {
            return error.InvalidBatchRequest;
        }
        if (req.deletes.len != 0 or req.transforms.len != 0 or req.graph_writes.len != 0 or
            req.graph_deletes.len != 0 or req.predicates.len != 0 or req.writes.len != 0)
        {
            return error.InvalidBatchRequest;
        }
    } else if (replication.operation == .checkpoint) {
        return error.MissingSplitReplicationCheckpoint;
    }
    return replication.identity_namespace;
}

fn validateSplitCheckpointGroup(checkpoint: ?db_mod.types.SplitReplicationCheckpoint, group_id: u64) !void {
    const value = checkpoint orelse return;
    if (value.transition_id == 0) return error.InvalidBatchRequest;
    switch (value.kind) {
        .destination_begin, .destination_complete => if (value.destination_group_id != group_id) return error.InvalidBatchRequest,
        .source_ack => if (value.source_group_id != group_id) return error.InvalidBatchRequest,
    }
}

fn validateSplitReplicationIdentityAgainstCatalog(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
    replication: db_mod.types.SplitReplicationContext,
) !void {
    const source_namespace = (try loadTableIdentityNamespaceForGroup(
        alloc,
        catalog,
        table_name,
        replication.source_group_id,
    )) orelse return error.MissingIdentityNamespace;
    if (!source_namespace.eql(replication.identity_namespace)) return error.DocIdentityNamespaceMismatch;
}

fn openManagedDbForReplicatedApply(
    alloc: std.mem.Allocator,
    path: []const u8,
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
    group_id: u64,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime,
    ha_write_gate: ?db_mod.HAWriteGate,
    ha_async_mirror: ?db_mod.HAAsyncEffectMirror,
    split_identity_namespace: ?doc_identity.Namespace,
) !db_mod.DB {
    const namespace: ?doc_identity.Namespace = if (split_identity_namespace) |value|
        value
    else
        try loadTableIdentityNamespaceForGroup(alloc, catalog, table_name, group_id);
    const metadata = try loadTableManagedMetadata(alloc, catalog, table_name);
    defer if (metadata) |owned| {
        if (owned.indexes_json) |value| alloc.free(value);
        if (owned.schema_json) |value| alloc.free(value);
    };
    const indexes_json = if (metadata) |owned| owned.indexes_json else null;
    const schema_json = if (metadata) |owned| owned.schema_json else null;
    const effective_ha_mirror = haMirrorForManagedDbOpenMode(.default_async, ha_async_mirror);
    var db = if (indexes_json) |value|
        try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
            alloc,
            path,
            value,
            null,
            null,
            table_reads.backend_current_root_generation,
            null,
            .default_async,
            backend_runtime,
            null,
            null,
            null,
            namespace,
            .{
                .drain_resolver_backfill = false,
                .schema_json_before_index_load = schema_json,
                .reconcile_for_replicated_apply = true,
                .ha_write_gate = ha_write_gate,
                .ha_async_effect_mirror = effective_ha_mirror,
                .ha_async_batch_mirror = effective_ha_mirror,
                .ha_async_metadata_mirror = effective_ha_mirror,
            },
        )
    else
        try db_mod.DB.open(alloc, path, .{
            .backend_runtime = backend_runtime,
            .identity_namespace = namespace,
            .prefer_existing_identity_namespace = true,
            .ha_write_gate = ha_write_gate,
            .ha_async_effect_mirror = effective_ha_mirror,
            .ha_async_batch_mirror = effective_ha_mirror,
            .ha_async_metadata_mirror = effective_ha_mirror,
            .open_mode = .writer_no_replay,
            .index_open_parallelism = 1,
        });
    errdefer db.close();
    try validateProvisionedDbIdentityNamespaceExpected(namespace, &db);
    return db;
}

fn validateProvisionedDbIdentityNamespace(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
    group_id: u64,
    db: *const db_mod.DB,
) !void {
    const expected = try loadTableIdentityNamespaceForGroup(alloc, catalog, table_name, group_id);
    try validateProvisionedDbIdentityNamespaceExpected(expected, db);
}

fn loadTableSchemaJson(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
) !?[]u8 {
    var snapshot = try catalog.adminSnapshot();
    defer catalog.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return null;
    return try alloc.dupe(u8, table.schema_json);
}

fn validateTableWritesAgainstCatalogSchema(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
    writes: anytype,
) !void {
    if (writes.len == 0) return;
    const schema_json = (try loadTableSchemaJson(alloc, catalog, table_name)) orelse return;
    defer alloc.free(schema_json);
    if (schema_json.len == 0) return;

    var parsed_schema = try tables_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    try tables_api.validateWritesAgainstTableSchema(alloc, parsed_schema, writes);
}

fn validateTableBatchAgainstCatalogSchema(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    db: *db_mod.DB,
    table_name: []const u8,
    writes: []const db_mod.types.BatchWrite,
    deletes: []const []const u8,
    transforms: []const db_mod.types.DocumentTransform,
) !void {
    if (writes.len == 0 and deletes.len == 0 and transforms.len == 0) return;
    const schema_json = (try loadTableSchemaJson(alloc, catalog, table_name)) orelse return;
    defer alloc.free(schema_json);
    try validateTableBatchAgainstSchemaJson(alloc, db, schema_json, writes, deletes, transforms);
}

fn validateTableBatchAgainstSchemaJson(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    schema_json: ?[]const u8,
    writes: []const db_mod.types.BatchWrite,
    deletes: []const []const u8,
    transforms: []const db_mod.types.DocumentTransform,
) !void {
    if (writes.len == 0 and deletes.len == 0 and transforms.len == 0) return;
    const raw_schema_json = schema_json orelse return;
    if (raw_schema_json.len == 0) return;

    const effective_writes = try resolveWritesForSchemaValidation(alloc, db, writes, deletes, transforms);
    defer freeOwnedBatchWrites(alloc, effective_writes);
    if (effective_writes.len == 0) return;

    var parsed_schema = try tables_api.parseValidatedTableSchema(alloc, raw_schema_json);
    defer parsed_schema.deinit(alloc);
    try tables_api.validateWritesAgainstTableSchema(alloc, parsed_schema, effective_writes);
}

fn validateTransactionAgainstCatalogSchema(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    db: *db_mod.DB,
    table_name: []const u8,
    writes: []const db_mod.types.TransactionWrite,
    deletes: []const []const u8,
    transforms: []const db_mod.types.DocumentTransform,
) !void {
    const batch_writes = try transactionWritesToBatchWrites(alloc, writes);
    defer alloc.free(batch_writes);
    try validateTableBatchAgainstCatalogSchema(alloc, catalog, db, table_name, batch_writes, deletes, transforms);
}

fn encodeRemoteBatchRequest(alloc: std.mem.Allocator, req: db_mod.types.BatchRequest) ![]u8 {
    var out = std.ArrayListUnmanaged(u8).empty;
    defer out.deinit(alloc);

    try out.appendSlice(alloc, "{\"inserts\":{");
    for (req.writes, 0..) |write, i| {
        if (i > 0) try out.append(alloc, ',');
        try appendJsonString(alloc, &out, write.key);
        try out.append(alloc, ':');
        try out.appendSlice(alloc, write.value);
    }
    try out.append(alloc, '}');
    if (req.deletes.len > 0) {
        try out.appendSlice(alloc, ",\"deletes\":[");
        for (req.deletes, 0..) |key, i| {
            if (i > 0) try out.append(alloc, ',');
            try appendJsonString(alloc, &out, key);
        }
        try out.append(alloc, ']');
    }
    if (req.transforms.len > 0) {
        try out.appendSlice(alloc, ",\"transforms\":[");
        for (req.transforms, 0..) |transform, i| {
            if (i > 0) try out.append(alloc, ',');
            try out.appendSlice(alloc, "{\"key\":");
            try appendJsonString(alloc, &out, transform.key);
            try out.appendSlice(alloc, ",\"operations\":[");
            for (transform.operations, 0..) |op, op_index| {
                if (op_index > 0) try out.append(alloc, ',');
                try out.appendSlice(alloc, "{\"op\":");
                try appendJsonString(alloc, &out, db_mod.transform.transformOpText(op.op));
                try out.appendSlice(alloc, ",\"path\":");
                try appendJsonString(alloc, &out, op.path);
                if (op.value_json) |value_json| {
                    try out.appendSlice(alloc, ",\"value\":");
                    try out.appendSlice(alloc, value_json);
                }
                try out.append(alloc, '}');
            }
            try out.append(alloc, ']');
            if (transform.upsert) try out.appendSlice(alloc, ",\"upsert\":true");
            try out.append(alloc, '}');
        }
        try out.append(alloc, ']');
    }
    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

fn encodeRemoteDocumentArtifactChildRangeApplyBatch(
    alloc: std.mem.Allocator,
    child_batch: db_mod.DocumentArtifactChildRangeApplyBatch,
) ![]u8 {
    return try std.json.Stringify.valueAlloc(alloc, child_batch, .{ .emit_null_optional_fields = false });
}

