test "provisioned writer cache starts DB workers after stable entry installation" {
    const alloc = std.testing.allocator;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const Catalog = struct {
        var table_records = [_]metadata_table_manager.TableRecord{.{
            .table_id = 7,
            .name = "docs",
            .placement_role = "data",
        }};
        var range_records = [_]metadata_table_manager.RangeRecord{
            .{ .group_id = 7001, .table_id = 7, .start_key = "", .end_key = null },
        };

        fn iface() table_catalog.CatalogSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = table_records[0..],
                .ranges = range_records[0..],
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    const InstallationPath = enum {
        catalog_open,
        prepared_open,
        seeded_create,
    };

    inline for (std.enums.values(InstallationPath)) |installation_path| {
        const path = try std.fmt.allocPrint(
            alloc,
            ".zig-cache/tmp/{s}/stable-worker-owner-{s}",
            .{ tmp.sub_path, @tagName(installation_path) },
        );
        defer alloc.free(path);

        var write_cache = ProvisionedTableWriteCache.init(alloc);
        defer write_cache.deinit();

        switch (installation_path) {
            .catalog_open => {
                var cached = try write_cache.getOrOpenLocked(path, Catalog.iface(), 7001, 0, "docs");
                defer cached.deinit(alloc);
                try std.testing.expect(cached.db.quarantineRetryWorkerStartedAtCurrentAddressForTest());
            },
            .prepared_open => {
                var opened: ?db_mod.DB = try db_mod.DB.open(alloc, path, .{});
                defer if (opened) |*db| db.close();
                var prepared: ProvisionedTableWriteCache.PreparedOpen = .{};
                defer prepared.deinit(alloc);
                var cached = try write_cache.adoptPreparedOpenLocked(
                    &opened,
                    7001,
                    0,
                    "docs",
                    .default,
                    &prepared,
                );
                defer cached.deinit(alloc);
                try std.testing.expect(cached.db.quarantineRetryWorkerStartedAtCurrentAddressForTest());
            },
            .seeded_create => {
                var opened: ?db_mod.DB = try db_mod.DB.open(alloc, path, .{});
                defer if (opened) |*db| db.close();
                try write_cache.seedCreatedDbLocked(&opened, 7001, 0, "docs", "{}", "{}");
                try std.testing.expectEqual(@as(usize, 1), write_cache.entries.items.len);
                try std.testing.expect(write_cache.entries.items[0].db.quarantineRetryWorkerStartedAtCurrentAddressForTest());
            },
        }
    }
}

test "provisioned table write cache retires stale db when index metadata changes" {
    const alloc = std.testing.allocator;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/write-cache-metadata-refresh", .{tmp.sub_path});
    defer alloc.free(path);

    const Catalog = struct {
        var indexes_json_buf: []const u8 = "";
        var table_records = [_]metadata_table_manager.TableRecord{.{
            .table_id = 7,
            .name = "docs",
            .placement_role = "data",
        }};
        var range_records = [_]metadata_table_manager.RangeRecord{
            .{ .group_id = 7001, .table_id = 7, .start_key = "", .end_key = null },
        };

        fn iface() table_catalog.CatalogSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            table_records[0].indexes_json = indexes_json_buf;
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = table_records[0..],
                .ranges = range_records[0..],
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    Catalog.indexes_json_buf = "{\"first_idx\":{\"type\":\"full_text\",\"field\":\"body\"}}";

    var write_cache = ProvisionedTableWriteCache.init(alloc);
    defer write_cache.deinit();

    var first = try write_cache.getOrOpenLocked(path, Catalog.iface(), 7001, 0, "docs");
    var first_released = false;
    defer if (!first_released) first.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), write_cache.entries.items.len);
    try std.testing.expectEqual(@as(usize, 1), write_cache.table_metadata.items.len);
    try std.testing.expect(first.db.core.index_manager.textIndex("first_idx") != null);
    const initial_cache_stats = write_cache.cacheStats();

    Catalog.indexes_json_buf = "{\"second_idx\":{\"type\":\"full_text\",\"field\":\"body\"}}";

    try std.testing.expectError(error.LsmRootWriterAlreadyOpen, write_cache.getOrOpenLocked(path, Catalog.iface(), 7001, 0, "docs"));

    first.deinit(alloc);
    first_released = true;
    write_cache.drainPendingClosesForGroupTable(7001, "docs");

    var second = try write_cache.getOrOpenLocked(path, Catalog.iface(), 7001, 0, "docs");
    defer second.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), write_cache.entries.items.len);
    try std.testing.expectEqual(@as(usize, 0), write_cache.retired_entries.items.len);
    try std.testing.expectEqual(@as(usize, 1), write_cache.table_metadata.items.len);
    const refreshed_cache_stats = write_cache.cacheStats();
    try std.testing.expectEqual(initial_cache_stats.hit_count, refreshed_cache_stats.hit_count);
    try std.testing.expectEqual(initial_cache_stats.miss_count + 1, refreshed_cache_stats.miss_count);
    try std.testing.expect(second.db.core.index_manager.textIndex("second_idx") != null);
    try std.testing.expect(second.db.core.index_manager.textIndex("first_idx") == null);
}

test "provisioned transition writer fences exact supplied table metadata" {
    const alloc = std.testing.allocator;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const replica_root_dir = try std.fmt.allocPrint(
        alloc,
        ".zig-cache/tmp/{s}/transition-writer-metadata-fence",
        .{tmp.sub_path},
    );
    defer alloc.free(replica_root_dir);

    const NoCatalog = struct {
        fn iface() table_catalog.CatalogSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return error.UnexpectedCatalogCall;
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    const namespace: doc_identity.Namespace = .{
        .table_id = 7,
        .shard_id = 7001,
        .range_id = 7001,
    };
    const first_metadata: StartupCatchUpMetadata = .{
        .indexes_json = "{\"full_text\":{\"type\":\"full_text\",\"field\":\"body\"}}",
        .schema_json = "{\"version\":1}",
        .identity_namespace = namespace,
    };
    const second_metadata: StartupCatchUpMetadata = .{
        .indexes_json = first_metadata.indexes_json,
        .schema_json = "{\"version\":2}",
        .identity_namespace = namespace,
    };

    var write_cache = ProvisionedTableWriteCache.init(alloc);
    defer write_cache.deinit();
    var source = ProvisionedTableWriteSource.init(replica_root_dir, NoCatalog.iface());
    defer source.deinit();
    source.write_cache = &write_cache;

    var first = (try source.leaseCachedGroupWriterWithMetadata(
        alloc,
        7001,
        "docs",
        first_metadata,
    )) orelse return error.TestUnexpectedResult;
    var first_released = false;
    defer if (!first_released) first.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), write_cache.entries.items.len);
    try std.testing.expectEqualStrings(
        first_metadata.schema_json.?,
        first.schema_json.?,
    );

    try std.testing.expectError(
        error.LsmRootWriterAlreadyOpen,
        source.leaseCachedGroupWriterWithMetadata(
            alloc,
            7001,
            "docs",
            second_metadata,
        ),
    );
    try std.testing.expectEqual(@as(usize, 1), write_cache.entries.items.len);

    first.deinit(alloc);
    first_released = true;
    var second = (try source.leaseCachedGroupWriterWithMetadata(
        alloc,
        7001,
        "docs",
        second_metadata,
    )) orelse return error.TestUnexpectedResult;
    defer second.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), write_cache.entries.items.len);
    try std.testing.expectEqual(@as(usize, 0), write_cache.retired_entries.items.len);
    try std.testing.expectEqual(@as(usize, 0), write_cache.closing_entries.items.len);
    try std.testing.expectEqualStrings(
        second_metadata.schema_json.?,
        second.schema_json.?,
    );
}

test "provisioned transition identity reassignment opens only the same table" {
    const alloc = std.testing.allocator;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const replica_root_dir = try std.fmt.allocPrint(
        alloc,
        ".zig-cache/tmp/{s}/transition-writer-identity-reassignment",
        .{tmp.sub_path},
    );
    defer alloc.free(replica_root_dir);
    const db_path = try metadata_mod.groupDbPathFromReplicaRoot(
        alloc,
        replica_root_dir,
        7001,
    );
    defer alloc.free(db_path);

    const existing_namespace: doc_identity.Namespace = .{
        .table_id = 7,
        .shard_id = 7001,
        .range_id = 7101,
    };
    const target_namespace: doc_identity.Namespace = .{
        .table_id = 7,
        .shard_id = 7001,
        .range_id = 7102,
    };
    {
        var db = try db_mod.DB.open(alloc, db_path, .{
            .identity_namespace = existing_namespace,
            .start_index_workers = false,
        });
        try db.batch(.{
            .writes = &.{.{
                .key = "doc:a",
                .value = "{\"value\":1}",
            }},
        });
        db.close();
    }

    var source = ProvisionedTableWriteSource.init(
        replica_root_dir,
        table_catalog.emptyCatalogSource(),
    );
    defer source.deinit();
    var activity = source.beginGroupTransitionActivity("docs", 7001);
    defer activity.deinit();

    const reassignment_metadata: StartupCatchUpMetadata = .{
        .indexes_json = "{}",
        .schema_json = "",
        .identity_namespace = target_namespace,
        .identity_validation = .reassign_same_table,
    };
    {
        var db = try activity.openOwnedWriter(alloc, reassignment_metadata);
        defer db.close();
        try std.testing.expect(db.core.identity_namespace.eql(existing_namespace));
    }

    var wrong_table_metadata = reassignment_metadata;
    wrong_table_metadata.identity_namespace.?.table_id = 8;
    try std.testing.expectError(
        error.DocIdentityNamespaceMismatch,
        activity.openOwnedWriter(alloc, wrong_table_metadata),
    );
    var exact_metadata = reassignment_metadata;
    exact_metadata.identity_validation = .exact;
    try std.testing.expectError(
        error.DocIdentityNamespaceMismatch,
        activity.openOwnedWriter(alloc, exact_metadata),
    );
}

test "provisioned create index updates cached writer in place" {
    const alloc = std.testing.allocator;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const replica_root_dir = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/provisioned-create-index-cached-writer", .{tmp.sub_path});
    defer alloc.free(replica_root_dir);

    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), replica_root_dir) catch {};
    defer std.Io.Dir.cwd().deleteTree(io_impl.io(), replica_root_dir) catch {};

    const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, replica_root_dir, 7001);
    defer alloc.free(path);

    const Catalog = struct {
        var indexes_json_buf: []const u8 = "{}";
        var table_records = [_]metadata_table_manager.TableRecord{.{
            .table_id = 7,
            .name = "docs",
            .placement_role = "data",
        }};
        var range_records = [_]metadata_table_manager.RangeRecord{
            .{ .group_id = 7001, .table_id = 7, .start_key = "", .end_key = null },
        };

        fn iface() table_catalog.CatalogSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            table_records[0].indexes_json = indexes_json_buf;
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = table_records[0..],
                .ranges = range_records[0..],
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var write_cache = ProvisionedTableWriteCache.init(alloc);
    defer write_cache.deinit();
    var status_cache = runtime_status.TableRuntimeSnapshotCache.init(alloc);
    defer status_cache.deinit();
    var source = ProvisionedTableWriteSource.init(replica_root_dir, Catalog.iface());
    defer source.deinit();
    source.write_cache = &write_cache;
    source.runtime_status_cache = &status_cache;

    var cached = try source.getOrOpenCachedDbMode(alloc, &write_cache, path, 7001, "docs", .default_async, null, null);
    defer cached.deinit(alloc);
    const original_entry = cached.entry.?;
    try std.testing.expect(cached.db.core.index_manager.denseIndex("semantic_idx") == null);

    Catalog.indexes_json_buf = "{\"semantic_idx\":{\"type\":\"embeddings\",\"dimension\":3,\"external\":true,\"_coverage_incarnation\":42}}";
    const Fence = struct {
        cache: *runtime_status.TableRuntimeSnapshotCache,
        calls: usize = 0,
        structural_calls: usize = 0,
        publication_attempted_before_structural: bool = false,

        fn run(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.calls += 1;
            if (self.calls == 1) self.cache.invalidateTable("docs");
        }

        fn onChange(ptr: *anyopaque, _: []const u8, kind: ProvisionedTableWriteSource.LocalChangeKind) void {
            if (kind != .structural) return;
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.structural_calls += 1;
            self.publication_attempted_before_structural = self.calls != 0;
        }
    };
    var fence = Fence{ .cache = &status_cache };
    {
        const previous_hook = test_before_runtime_status_publish_hook;
        test_before_runtime_status_publish_hook = .{ .ptr = &fence, .run = Fence.run };
        defer test_before_runtime_status_publish_hook = previous_hook;
        source.setLocalChangeHook(.{ .ptr = &fence, .on_change = Fence.onChange });
        defer source.setLocalChangeHook(null);
        _ = try source.source().createIndex(alloc, "docs", "semantic_idx", "{\"type\":\"embeddings\",\"dimension\":3,\"external\":true}");
    }

    // Status is sampled only after releasing structural/cache admission. A
    // concurrent invalidation can fence that observation without retrying or
    // rolling back the already-committed index admission.
    try std.testing.expectEqual(@as(usize, 1), fence.calls);
    try std.testing.expectEqual(@as(usize, 1), fence.structural_calls);
    try std.testing.expect(fence.publication_attempted_before_structural);
    source.publishWriteCacheRuntimeStatusesForTableBestEffort(alloc, "docs");
    var published_status = (try status_cache.snapshotGroupStatus(alloc, "docs", 7001)) orelse
        return error.TestUnexpectedResult;
    defer published_status.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), write_cache.entries.items.len);
    try std.testing.expectEqual(@as(usize, 0), write_cache.retired_entries.items.len);
    try std.testing.expect(write_cache.entries.items[0] == original_entry);
    try std.testing.expect(cached.db.core.index_manager.denseIndex("semantic_idx") != null);
    try std.testing.expectEqual(@as(?u64, 42), cached.db.core.index_manager.coverageGenerationForIndex("semantic_idx"));

    var outer_cache = ProvisionedTableWriteCache.init(alloc);
    defer outer_cache.deinit();
    var outer_source = ProvisionedTableWriteSource.init(replica_root_dir, Catalog.iface());
    outer_source.write_cache = &outer_cache;
    _ = outer_source.withLocalWriteOwner(&source);

    Catalog.indexes_json_buf =
        \\{"semantic_idx":{"type":"embeddings","dimension":3,"external":true,"_coverage_incarnation":42},"owner_forwarded_idx":{"type":"embeddings","dimension":3,"external":true,"_coverage_incarnation":43}}
    ;
    _ = try outer_source.source().createIndex(alloc, "docs", "owner_forwarded_idx", "{\"type\":\"embeddings\",\"dimension\":3,\"external\":true}");

    try std.testing.expectEqual(@as(usize, 0), outer_cache.entries.items.len);
    try std.testing.expectEqual(@as(usize, 1), write_cache.entries.items.len);
    try std.testing.expect(write_cache.entries.items[0] == original_entry);
    try std.testing.expect(cached.db.core.index_manager.denseIndex("owner_forwarded_idx") != null);
    try std.testing.expectEqual(@as(?u64, 43), cached.db.core.index_manager.coverageGenerationForIndex("owner_forwarded_idx"));

    Catalog.indexes_json_buf = "{\"semantic_idx\":{\"type\":\"embeddings\",\"dimension\":3,\"external\":true,\"_coverage_incarnation\":42}}";
    _ = try source.source().dropIndex(alloc, "docs", "owner_forwarded_idx");

    try std.testing.expectEqual(@as(usize, 1), write_cache.entries.items.len);
    try std.testing.expectEqual(@as(usize, 0), write_cache.retired_entries.items.len);
    try std.testing.expect(write_cache.entries.items[0] == original_entry);
    try std.testing.expect(cached.db.core.index_manager.denseIndex("owner_forwarded_idx") == null);

    _ = try outer_source.source().batch(alloc, "docs", .{
        .writes = &.{.{ .key = "doc:owner-forwarded", .value = "{\"body\":\"owner forwarded batch\"}" }},
        .sync_level = .write,
    });
    try std.testing.expectEqual(@as(usize, 0), outer_cache.entries.items.len);
    try std.testing.expectEqual(@as(usize, 1), write_cache.entries.items.len);

    const RaftCapture = struct {
        const State = struct {
            batch_count: usize = 0,
            local_count: usize = 0,
            last_group_id: u64 = 0,
            last_write_count: usize = 0,
            last_timestamp_ns: u64 = 0,
        };

        fn batchGroup(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            group_id: u64,
            table_name: []const u8,
            req: db_mod.types.BatchRequest,
        ) !void {
            const state: *State = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            state.batch_count += 1;
            state.last_group_id = group_id;
            state.last_write_count = req.writes.len;
            state.last_timestamp_ns = req.timestamp_ns;
        }

        fn batchGroupLocal(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            group_id: u64,
            table_name: []const u8,
            req: db_mod.types.BatchRequest,
        ) !void {
            const state: *State = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            state.local_count += 1;
            state.last_group_id = group_id;
            state.last_write_count = req.writes.len;
        }
    };

    var raft_capture = RaftCapture.State{};
    _ = outer_source.withRaftBatcher(.{
        .ptr = &raft_capture,
        .vtable = &.{
            .batch_group = RaftCapture.batchGroup,
            .batch_group_local = RaftCapture.batchGroupLocal,
        },
    });
    _ = try outer_source.source().batch(alloc, "docs", .{
        .writes = &.{.{ .key = "doc:raft-batch", .value = "{\"body\":\"raft batch\"}" }},
        .timestamp_ns = 456,
        .sync_level = .write,
    });
    try std.testing.expectEqual(@as(usize, 1), raft_capture.batch_count);
    try std.testing.expectEqual(@as(usize, 0), raft_capture.local_count);
    try std.testing.expectEqual(@as(u64, 7001), raft_capture.last_group_id);
    try std.testing.expectEqual(@as(usize, 1), raft_capture.last_write_count);
    try std.testing.expectEqual(@as(u64, 456), raft_capture.last_timestamp_ns);
    try std.testing.expectEqual(@as(usize, 0), outer_cache.entries.items.len);

    _ = try outer_source.source().batchGroupLocal(alloc, 7001, "docs", .{
        .writes = &.{.{ .key = "doc:raft-group-local", .value = "{\"body\":\"raft group\"}" }},
        .sync_level = .write,
    });
    try std.testing.expectEqual(@as(usize, 1), raft_capture.batch_count);
    try std.testing.expectEqual(@as(usize, 1), raft_capture.local_count);
    try std.testing.expectEqual(@as(u64, 7001), raft_capture.last_group_id);
    try std.testing.expectEqual(@as(usize, 1), raft_capture.last_write_count);
    try std.testing.expectEqual(@as(usize, 0), outer_cache.entries.items.len);
}

test "raft batch aggregation makes failures after an accepted group non-retryable" {
    const Catalog = struct {
        var tables = [_]metadata_table_manager.TableRecord{.{
            .table_id = 7,
            .name = "docs",
            .placement_role = "data",
        }};
        var ranges = [_]metadata_table_manager.RangeRecord{
            .{ .group_id = 7001, .table_id = 7, .start_key = "", .end_key = "m" },
            .{ .group_id = 7002, .table_id = 7, .start_key = "m", .end_key = null },
        };

        fn iface() table_catalog.CatalogSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = tables[0..],
                .ranges = ranges[0..],
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    const Capture = struct {
        failed_group_id: u64,
        failure: anyerror,
        attempts: usize = 0,
        accepted: usize = 0,

        fn batchGroup(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            group_id: u64,
            _: []const u8,
            _: db_mod.types.BatchRequest,
        ) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.attempts += 1;
            if (group_id == self.failed_group_id) return self.failure;
            self.accepted += 1;
        }

        fn batchGroupLocal(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: u64,
            _: []const u8,
            _: db_mod.types.BatchRequest,
        ) !void {
            return error.TestUnexpectedResult;
        }
    };

    var source = ProvisionedTableWriteSource.init("unused", Catalog.iface());
    defer source.deinit();
    var capture = Capture{
        .failed_group_id = 7002,
        .failure = error.LeaderUnavailable,
    };
    _ = source.withRaftBatcher(.{
        .ptr = &capture,
        .vtable = &.{
            .batch_group = Capture.batchGroup,
            .batch_group_local = Capture.batchGroupLocal,
        },
    });
    const transforms = [_]db_mod.types.DocumentTransform{
        .{ .key = "a", .operations = &.{.{ .op = .inc, .path = "count", .value_json = "1" }} },
        .{ .key = "z", .operations = &.{.{ .op = .inc, .path = "count", .value_json = "1" }} },
    };

    try std.testing.expectError(error.RaftBatchWritePartialOutcome, source.source().batch(std.testing.allocator, "docs", .{
        .transforms = &transforms,
        .sync_level = .write,
    }));
    try std.testing.expectEqual(@as(usize, 2), capture.attempts);
    try std.testing.expectEqual(@as(usize, 1), capture.accepted);

    // A failure before any group is accepted retains its precise classification.
    capture = .{ .failed_group_id = 7001, .failure = error.LeaderUnavailable };
    try std.testing.expectError(error.LeaderUnavailable, source.source().batch(std.testing.allocator, "docs", .{
        .transforms = &transforms,
        .sync_level = .write,
    }));
    try std.testing.expectEqual(@as(usize, 1), capture.attempts);
    try std.testing.expectEqual(@as(usize, 0), capture.accepted);
}

