            self.source.beginTableRequest("docs");
            self.entered.store(true, .release);
            self.source.endTableRequest("docs");
        }
    };

    const ReadWorker = struct {
        source: *ProvisionedTableWriteSource,
        entered: std.atomic.Value(bool) = .init(false),

