    defer source.deinit();
    source.write_cache = &write_cache;
    source.runtime_status_cache = &status_cache;

    const Fence = struct {
        cache: *runtime_status.TableRuntimeSnapshotCache,
        calls: usize = 0,

        fn run(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.calls += 1;
