    var shared_state_mutex: std.atomic.Mutex = .unlocked;
    source.bindWriteCachesWithStateMutex(&source_cache, null, &shared_state_mutex);
    apply_source.bindWriteCachesWithStateMutex(&apply_cache, null, &shared_state_mutex);
